	private static void setSlotSuffix(Connection conn, String slot, String suffix, String value) throws SQLException {
		String prefix = normalizeStrategySlot(slot) + ".";
		try (PreparedStatement update = conn.prepareStatement("UPDATE FuturesStrategySettings SET settingValue = ? WHERE settingKey LIKE ?")) {
			update.setString(1, value);
			update.setString(2, prefix + "%." + suffix);
			update.executeUpdate();
		}
	}

	private static void insertSlotSuffixForSymbols(Connection conn, String slot, String suffix, String value) throws SQLException {
		String prefix = normalizeStrategySlot(slot) + ".";
		try (PreparedStatement stmt = conn.prepareStatement("INSERT OR REPLACE INTO FuturesStrategySettings (settingKey, settingValue) SELECT ? || symbol || ? AS settingKey, ? FROM (SELECT DISTINCT substr(settingKey, ?, instr(substr(settingKey, ?), '.') - 1) AS symbol FROM FuturesStrategySettings WHERE settingKey LIKE ?)")) {
			stmt.setString(1, prefix);
			stmt.setString(2, "." + suffix);
			stmt.setString(3, value);
			stmt.setInt(4, prefix.length() + 1);
			stmt.setInt(5, prefix.length() + 1);
			stmt.setString(6, prefix + "%");
			stmt.executeUpdate();
		}
	}

	private static void setSlotSymbolSetting(Connection conn, String slot, String symbol, String suffix, String value) throws SQLException {
		String key = normalizeStrategySlot(slot) + "." + normalizeSymbol(symbol) + "." + suffix;
		try (PreparedStatement stmt = conn.prepareStatement("INSERT OR REPLACE INTO FuturesStrategySettings (settingKey, settingValue) VALUES (?, ?)")) {
			stmt.setString(1, key);
			stmt.setString(2, value);
			stmt.executeUpdate();
		}
	}

	private static String settingValue(Connection conn, String key) throws SQLException {
		try (PreparedStatement stmt = conn.prepareStatement("SELECT settingValue FROM FuturesStrategySettings WHERE settingKey = ? LIMIT 1")) {
			stmt.setString(1, key);
			try (ResultSet rs = stmt.executeQuery()) {
				return rs.next() ? cleanOrDefault(rs.getString(1), "") : "";
			}
		}
	}

	private static boolean settingPrefixExists(Connection conn, String prefix) throws SQLException {
		try (PreparedStatement stmt = conn.prepareStatement("SELECT 1 FROM FuturesStrategySettings WHERE settingKey LIKE ? LIMIT 1")) {
			stmt.setString(1, cleanOrDefault(prefix, "") + "%");
			try (ResultSet rs = stmt.executeQuery()) {
				return rs.next();
			}
		}
	}

	private static int copyStrategySlotRows(Connection conn, String symbol, String fromSlot, String toSlot) throws SQLException {
		String normalizedSymbol = normalizeSymbol(symbol);
		String fromPrefix = strategySettingPrefix(fromSlot, normalizedSymbol);
		String toPrefix = strategySettingPrefix(toSlot, normalizedSymbol);
		List<String[]> values = new ArrayList<String[]>();
		try (PreparedStatement select = conn.prepareStatement("SELECT settingKey, settingValue FROM FuturesStrategySettings WHERE settingKey LIKE ?")) {
			select.setString(1, fromPrefix + "%");
			try (ResultSet rs = select.executeQuery()) {
				while (rs.next()) {
					String settingKey = rs.getString("settingKey");
					String unprefixed = settingKey.substring(fromPrefix.length());
					values.add(new String[] { toPrefix + unprefixed, rs.getString("settingValue") });
				}
			}
		}
		if (values.isEmpty()) {
			return 0;
		}
		try (PreparedStatement delete = conn.prepareStatement("DELETE FROM FuturesStrategySettings WHERE settingKey LIKE ?")) {
			delete.setString(1, toPrefix + "%");
			delete.executeUpdate();
		}
		try (PreparedStatement insert = conn.prepareStatement("INSERT OR REPLACE INTO FuturesStrategySettings (settingKey, settingValue) VALUES (?, ?)")) {
			for (int index = 0; index < values.size(); index++) {
				insert.setString(1, values.get(index)[0]);
				insert.setString(2, values.get(index)[1]);
				insert.addBatch();
			}
			insert.executeBatch();
		}
		return values.size();
	}

	private static void ensureColumn(Statement stmt, String tableName, String columnName, String definition) {
		try {
			stmt.execute("ALTER TABLE " + tableName + " ADD COLUMN " + columnName + " " + definition);
		} catch (SQLException e) {
			String message = e.getMessage() == null ? "" : e.getMessage().toLowerCase();
			if (!message.contains("duplicate column")) {
				e.printStackTrace();
			}
		}
	}

	private static void ensureTradeDetailColumns(Statement stmt, String tableName) {
		ensureColumn(stmt, tableName, "sourceStrategyCode", "TEXT DEFAULT ''");
		ensureColumn(stmt, tableName, "sourceStrategyName", "TEXT DEFAULT ''");
		ensureColumn(stmt, tableName, "originalContracts", "INTEGER DEFAULT 0");
		ensureColumn(stmt, tableName, "dtmPartialContractsClosed", "INTEGER DEFAULT 0");
		ensureColumn(stmt, tableName, "dtmRealizedPnl", "REAL DEFAULT 0");
		ensureColumn(stmt, tableName, "finalLegPnl", "REAL DEFAULT 0");
	}

	public static String getInstrumentJson() {
		List<InstrumentSpec> specs = supportedInstruments();
		StringBuilder json = new StringBuilder("[");
		for (int index = 0; index < specs.size(); index++) {
			if (index > 0) {
				json.append(",");
			}
			InstrumentSpec spec = specs.get(index);
			json.append("{")
				.append("\"symbol\":").append(jsonString(spec.symbol)).append(",")
				.append("\"name\":").append(jsonString(spec.name)).append(",")
				.append("\"exchange\":").append(jsonString(spec.exchange)).append(",")
				.append("\"tickSize\":").append(spec.tickSize).append(",")
				.append("\"tickValue\":").append(spec.tickValue).append(",")
				.append("\"pointValue\":").append(spec.pointValue).append(",")
				.append("\"defaultMaxContracts\":").append(spec.defaultMaxContracts).append(",")
				.append("\"defaultStopTicks\":").append(spec.defaultStopTicks).append(",")
				.append("\"defaultTargetR\":").append(spec.defaultTargetR)
				.append("}");
		}
		json.append("]");
		return json.toString();
	}

	public static String getMarketDataStatusJson() {
		List<InstrumentSpec> specs = supportedInstruments();
		Map<String, DataBundle> bundles = new HashMap<String, DataBundle>();
		Map<String, LocalDate> firstDates = new HashMap<String, LocalDate>();
		Map<String, LocalDate> lastDates = new HashMap<String, LocalDate>();
		LocalDate overallStartDate = null;
		LocalDate overallEndDate = null;
		LocalDate commonStartDate = null;
		LocalDate commonEndDate = null;
		for (int index = 0; index < specs.size(); index++) {
			InstrumentSpec spec = specs.get(index);
			DataBundle bundle = loadNativeFuturesBars(spec.symbol, LocalDate.now().minusYears(2), LocalDate.now(), TIMEFRAME_FOLDER);
			bundles.put(spec.symbol, bundle);
			if (!bundle.bars.isEmpty()) {
				LocalDate firstDate = bundle.bars.get(0).marketDate;
				LocalDate lastDate = bundle.bars.get(bundle.bars.size() - 1).marketDate;
				firstDates.put(spec.symbol, firstDate);
				lastDates.put(spec.symbol, lastDate);
				if (overallStartDate == null || firstDate.isBefore(overallStartDate)) {
					overallStartDate = firstDate;
				}
				if (overallEndDate == null || lastDate.isAfter(overallEndDate)) {
					overallEndDate = lastDate;
				}
				if (commonStartDate == null || firstDate.isAfter(commonStartDate)) {
					commonStartDate = firstDate;
				}
				if (commonEndDate == null || lastDate.isBefore(commonEndDate)) {
					commonEndDate = lastDate;
				}
			}
		}
		String dataDir = futuresDataDir();
		StringBuilder json = new StringBuilder("{\"storagePath\":\"")
			.append(dataDir)
			.append("\",\"timeframe\":\"1Min + derived 5Min/15Min/1Hour\",")
			.append("\"fields\":\"timestamp,open,high,low,close,volume,vwap,ema9,ema20,ema50,atr14,rsi14,volume_sma20,range_ticks,body_pct\",")
			.append("\"timeframes\":[\"1min\",\"5min\",\"15min\",\"1hour\"],\"symbols\":[");
		for (int index = 0; index < specs.size(); index++) {
			if (index > 0) {
				json.append(",");
			}
			json.append(jsonString(specs.get(index).symbol));
		}
		json.append("],\"rowsBySymbol\":{");
		for (int index = 0; index < specs.size(); index++) {
			if (index > 0) {
				json.append(",");
			}
			InstrumentSpec spec = specs.get(index);
			DataBundle bundle = bundles.get(spec.symbol);
			json.append(jsonString(spec.symbol)).append(":").append(bundle.bars.size());
		}
		json.append("},\"rawRowsBySymbol\":{");
		for (int index = 0; index < specs.size(); index++) {
			if (index > 0) {
				json.append(",");
			}
			InstrumentSpec spec = specs.get(index);
			json.append(jsonString(spec.symbol)).append(":")
				.append(countCsvDataRows(new File(dataDir + "/" + TIMEFRAME_FOLDER + "/" + spec.symbol + ".csv")));
		}
		json.append("},\"firstDateBySymbol\":{");
		for (int index = 0; index < specs.size(); index++) {
			if (index > 0) {
				json.append(",");
			}
			InstrumentSpec spec = specs.get(index);
			json.append(jsonString(spec.symbol)).append(":").append(jsonDate(firstDates.get(spec.symbol)));
		}
		json.append("},\"lastDateBySymbol\":{");
		for (int index = 0; index < specs.size(); index++) {
			if (index > 0) {
				json.append(",");
			}
			InstrumentSpec spec = specs.get(index);
			json.append(jsonString(spec.symbol)).append(":").append(jsonDate(lastDates.get(spec.symbol)));
		}
		json.append("},")
			.append("\"level2StatsBySymbol\":").append(FuturesMarketDataStore.level2StatsBySymbolJson(supportedInstrumentSymbols())).append(",")
			.append("\"liveCapturedRowsBySymbol\":").append(FuturesMarketDataStore.liveCapturedRowsBySymbolJson(supportedInstrumentSymbols())).append(",")
			.append("\"latestReconciliation\":").append(FuturesMarketDataStore.latestReconciliationSummaryJson()).append(",")
			.append("\"overallStartDate\":").append(jsonDate(overallStartDate)).append(",")
			.append("\"overallEndDate\":").append(jsonDate(overallEndDate)).append(",")
			.append("\"commonStartDate\":").append(jsonDate(commonStartDate)).append(",")
			.append("\"commonEndDate\":").append(jsonDate(commonEndDate)).append(",")
			.append("\"message\":")
			.append(jsonString("Futures data lives under " + dataDir + ". Production backtests use native 1-minute bars plus derived 5-minute, 15-minute, and 1-hour context."))
			.append("}");
		return json.toString();
	}

	public static int generateBacktest(
		String symbol,
		String startDate,
		String endDate,
		double accountSize,
		double maxTrailingDrawdown,
		double dailyLossLimit,
		double maxRiskPerTrade,
		int maxContracts,
		double commissionPerContract,
		double slippageTicks,
		double profitTarget
	) {
		return generateBacktest(
			symbol,
			startDate,
			endDate,
			accountSize,
			maxTrailingDrawdown,
			dailyLossLimit,
			maxRiskPerTrade,
			maxContracts,
			commissionPerContract,
			slippageTicks,
			profitTarget,
			"CUSTOM"
		);
	}

	public static int generateBacktest(
		String symbol,
		String startDate,
		String endDate,
		double accountSize,
		double maxTrailingDrawdown,
		double dailyLossLimit,
		double maxRiskPerTrade,
		int maxContracts,
		double commissionPerContract,
		double slippageTicks,
		double profitTarget,
		String fundedProfile
	) {
		initializeStore();
		BacktestConfig config = new BacktestConfig();
		config.symbol = normalizeSymbol(symbol);
		FuturesRiskSettings riskSettings = loadFuturesRiskSettings(config.symbol);
		FundedRuleProfile profile = fundedRuleProfileFor(fundedProfile);
		config.startDate = parseDate(startDate, LocalDate.now().minusYears(1));
		config.endDate = parseDate(endDate, LocalDate.now());
		config.accountSize = positiveOrDefault(accountSize, riskSettings.accountSize);
		config.maxTrailingDrawdown = positiveOrDefault(maxTrailingDrawdown, riskSettings.maxTrailingDrawdown);
		config.dailyLossLimit = positiveOrDefault(dailyLossLimit, riskSettings.dailyLossLimit);
		config.maxRiskPerTrade = positiveOrDefault(maxRiskPerTrade, riskSettings.maxRiskPerTrade);
		config.maxContracts = boundedInt(maxContracts, riskSettings.maxContracts, 1, 50);
		config.commissionPerContract = commissionPerContract >= 0.0 ? commissionPerContract : riskSettings.commissionPerContract;
		config.slippageTicks = slippageTicks >= 0.0 ? slippageTicks : riskSettings.slippageTicks;
		config.profitTarget = profitTarget >= 0.0 ? profitTarget : riskSettings.profitTarget;
		config.fundedProfile = profile.code;
		config.trailingDrawdownMode = profile.trailingDrawdownMode;
		config.strategySettings = loadFuturesStrategySettings(config.symbol);
		applyFundedProfile(config, profile);

		BacktestResult result = runBacktest(config);
		if (result == null) {
			return -1;
		}
		return saveBacktest(result, config);
	}

