	public static String getStrategyPresetsJson() {
		initializeStore();
		List<String> presetNames = savedStrategyPresetNames();
		StringBuilder json = new StringBuilder("[");
		for (int index = 0; index < presetNames.size(); index++) {
			if (index > 0) {
				json.append(",");
			}
			String name = normalizeStrategyPresetName(presetNames.get(index));
				json.append("{")
					.append("\"name\":").append(jsonString(name)).append(",")
					.append("\"label\":").append(jsonString(strategyPresetLabel(name))).append(",")
					.append("\"slot\":").append(jsonString(strategyPresetSlot(name))).append(",")
					.append("\"default\":").append(BEST_BIAS_FREE_STRATEGY_PRESET.equals(name))
				.append("}");
		}
		json.append("]");
		return json.toString();
	}

	public static String getStrategyWindowPolicyJson() {
		return "{"
			+ "\"controlPreset\":" + jsonString(DEFAULT_STRATEGY_PRESET) + ","
			+ "\"windowedPreset\":" + jsonString(WINDOWED_94K_STRATEGY_PRESET) + ","
			+ "\"biasFreePreset\":" + jsonString(BIAS_FREE_94K_STRATEGY_PRESET) + ","
			+ "\"bestBiasFreePreset\":" + jsonString(BEST_BIAS_FREE_STRATEGY_PRESET) + ","
			+ "\"editablePreset\":" + jsonString(BEST_BIAS_FREE_STRATEGY_PRESET) + ","
			+ "\"visiblePresets\":" + jsonStringArray(Arrays.asList(VISIBLE_STRATEGY_PRESETS)) + ","
			+ "\"timeNativeStrategies\":" + jsonStringArray(Arrays.asList(TIME_NATIVE_STRATEGY_CODES)) + ","
			+ "\"patternLevelStrategies\":" + jsonStringArray(Arrays.asList(PATTERN_LEVEL_STRATEGY_CODES)) + ","
			+ "\"disabledResearchStrategies\":" + jsonStringArray(Arrays.asList(DISABLED_RESEARCH_STRATEGY_CODES)) + ","
				+ "\"rule\":" + jsonString("backtestbias92k is the frozen windowed control. biasfree92k is the broad comparison preset with fitted windows removed. bestbiasfree is the main best strategy config. Level 2 infrastructure remains available for DTM and synthetic research.")
				+ "}";
	}

	private static String strategyPresetLabel(String presetName) {
		String normalized = normalizeStrategyPresetName(presetName);
		if (WINDOWED_94K_STRATEGY_PRESET.equals(normalized)) return "Backtest Bias 92k";
		if (BIAS_FREE_94K_STRATEGY_PRESET.equals(normalized)) return "Bias-Free 92k";
		if (BEST_BIAS_FREE_STRATEGY_PRESET.equals(normalized)) return "Best Bias-Free";
		return normalized;
	}

	private static List<String> savedStrategyPresetNames() {
		List<String> names = new ArrayList<String>();
		for (int index = 0; index < VISIBLE_STRATEGY_PRESETS.length; index++) {
			names.add(normalizeStrategyPresetName(VISIBLE_STRATEGY_PRESETS[index]));
		}
		return names;
	}

	public static String createStrategyPreset(String presetName, String sourcePreset) {
		initializeStore();
		String targetName = normalizeStrategyPresetName(presetName);
		String sourceName = normalizeStrategyPresetName(sourcePreset);
		String targetSlot = strategyPresetSlot(targetName);
		String sourceSlot = strategyPresetSlot(sourceName);
		if (targetName.length() == 0) {
			return "{\"success\":false,\"message\":\"Preset name is required.\"}";
		}
		if (!isSeededStrategyPresetName(targetName)) {
			return "{\"success\":false,\"message\":\"Strategy Configs are locked to the approved dev presets: backtestbias92k, biasfree92k, and bestbiasfree.\"}";
		}
		if (WIP_STRATEGY_PRESET.equals(sourceName)) {
			sourceName = DEFAULT_STRATEGY_PRESET;
			sourceSlot = strategyPresetSlot(sourceName);
		}
		try (Connection conn = DatabaseManager.getConnection()) {
			for (String symbol : supportedInstrumentSymbols()) {
				if (!settingPrefixExists(conn, strategySettingPrefix(sourceSlot, symbol))) {
					return "{\"success\":false,\"message\":" + jsonString("Source preset " + sourceName + " is missing settings for " + symbol + ".") + "}";
				}
			}
			for (String symbol : supportedInstrumentSymbols()) {
				copyStrategySlotRows(conn, symbol, sourceSlot, targetSlot);
			}
			return "{"
				+ "\"success\":true,"
				+ "\"message\":" + jsonString("Strategy preset " + targetName + " created from " + sourceName + ".") + ","
				+ "\"preset\":{\"name\":" + jsonString(targetName) + ",\"label\":" + jsonString(targetName) + ",\"slot\":" + jsonString(targetSlot) + "},"
				+ "\"presets\":" + getStrategyPresetsJson()
				+ "}";
		} catch (SQLException e) {
			e.printStackTrace();
			return "{\"success\":false,\"message\":\"Failed to create strategy preset.\"}";
		}
	}

	public static String validateStrategyPresetForSymbols(String presetName, String symbols) {
		String normalizedPreset = normalizeStrategyPresetName(presetName);
		String presetSlot = strategyPresetSlot(normalizedPreset);
		List<String> symbolList = parseSymbols(symbols);
		List<String> missing = new ArrayList<String>();
		try (Connection conn = DatabaseManager.getConnection()) {
			for (String symbol : symbolList) {
				if (!settingPrefixExists(conn, strategySettingPrefix(presetSlot, symbol))) {
					missing.add(symbol);
				}
			}
		} catch (SQLException e) {
			return "Strategy preset validation failed: " + cleanOrDefault(e.getMessage(), "database error");
		}
		if (!missing.isEmpty()) {
			return "Strategy preset " + normalizedPreset + " is missing settings for " + String.join(", ", missing) + ".";
		}
		return "";
	}

	public static String copyBacktestStrategyToLive(String symbols) {
		initializeStore();
		List<String> symbolList = parseSymbols(cleanOrDefault(symbols, DEFAULT_LIVE_SYMBOLS));
		if (symbolList.isEmpty()) {
			return "{\"success\":false,\"message\":\"Choose at least one futures symbol.\"}";
		}
		try (Connection conn = DatabaseManager.getConnection()) {
			conn.setAutoCommit(false);
			try {
				for (int index = 0; index < symbolList.size(); index++) {
					copyStrategySlotForSymbol(conn, symbolList.get(index), STRATEGY_SLOT_BACKTEST, STRATEGY_SLOT_LIVE);
				}
				conn.commit();
			} catch (SQLException e) {
				conn.rollback();
				throw e;
			} finally {
				conn.setAutoCommit(true);
			}
			return "{"
				+ "\"success\":true,"
				+ "\"message\":\"Live strategy configuration updated from the backtest strategy configuration.\","
				+ "\"symbols\":" + jsonStringArray(symbolList)
				+ "}";
		} catch (SQLException e) {
			e.printStackTrace();
			return "{\"success\":false,\"message\":\"Failed to copy backtest strategy into live strategy.\"}";
		}
	}

	private static void copyStrategySlotForSymbol(Connection conn, String symbol, String fromSlot, String toSlot) throws SQLException {
		int copied = copyStrategySlotRows(conn, symbol, fromSlot, toSlot);
		if (copied <= 0) {
			FuturesStrategySettings settings = loadFuturesStrategySettings(symbol, fromSlot);
			saveFuturesStrategySettings(symbol, toSlot, settings);
		}
	}

	public static FuturesRiskSettings loadFuturesRiskSettings() {
		return loadFuturesRiskSettings("MNQ");
	}

	public static FuturesRiskSettings loadFuturesRiskSettings(String symbol) {
		initializeStore();
		String normalizedSymbol = normalizeSymbol(symbol);
		FuturesRiskSettings settings = defaultFuturesRiskSettings(normalizedSymbol);
		String sql = "SELECT settingKey, settingValue FROM FuturesStrategySettings";
		try (Connection conn = DatabaseManager.getConnection();
			 Statement stmt = conn.createStatement();
			 ResultSet rs = stmt.executeQuery(sql)) {
			while (rs.next()) {
				String key = rs.getString("settingKey");
				if (!isSymbolScopedSettingKey(key)) {
					applyFuturesRiskSetting(settings, key, rs.getString("settingValue"));
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		try (Connection conn = DatabaseManager.getConnection();
			 Statement stmt = conn.createStatement();
			 ResultSet rs = stmt.executeQuery(sql)) {
			while (rs.next()) {
				String unprefixedKey = unprefixedSymbolSettingKey(normalizedSymbol, rs.getString("settingKey"));
				if (unprefixedKey != null) {
					applyFuturesRiskSetting(settings, unprefixedKey, rs.getString("settingValue"));
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		clampFuturesRiskSettings(settings);
		return settings;
	}

	public static FuturesRiskSettings loadFuturesRiskSettings(String symbol, String slot) {
		String normalizedSlot = normalizeStrategySlot(slot);
		if (STRATEGY_SLOT_BACKTEST.equals(normalizedSlot)) {
			return loadFuturesRiskSettings(symbol);
		}
		initializeStore();
		String normalizedSymbol = normalizeSymbol(symbol);
		FuturesRiskSettings settings = defaultFuturesRiskSettings(normalizedSymbol);
		boolean hasSlotSettings = false;
		String sql = "SELECT settingKey, settingValue FROM FuturesStrategySettings";
		try (Connection conn = DatabaseManager.getConnection();
			 Statement stmt = conn.createStatement();
			 ResultSet rs = stmt.executeQuery(sql)) {
			while (rs.next()) {
				String unprefixedKey = unprefixedSlotSymbolSettingKey(normalizedSlot, normalizedSymbol, rs.getString("settingKey"));
				if (unprefixedKey != null) {
					hasSlotSettings = true;
					applyFuturesRiskSetting(settings, unprefixedKey, rs.getString("settingValue"));
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
			if (!hasSlotSettings) {
				if (!isStrategyPresetSlot(normalizedSlot)) {
					return loadFuturesRiskSettings(symbol);
				}
				return defaultFuturesRiskSettings(normalizedSymbol);
			}
		clampFuturesRiskSettings(settings);
		return settings;
	}

	public static boolean saveFuturesRiskSettings(FuturesRiskSettings settings) {
		return saveFuturesRiskSettings("MNQ", settings);
	}

	public static boolean saveFuturesRiskSettings(String symbol, FuturesRiskSettings settings) {
		initializeStore();
		String normalizedSymbol = normalizeSymbol(symbol);
		FuturesRiskSettings safeSettings = settings == null ? defaultFuturesRiskSettings() : settings;
		clampFuturesRiskSettings(safeSettings);
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement("INSERT OR REPLACE INTO FuturesStrategySettings (settingKey, settingValue) VALUES (?, ?)")) {
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.accountSize"), safeSettings.accountSize);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.maxTrailingDrawdown"), safeSettings.maxTrailingDrawdown);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.dailyLossLimit"), safeSettings.dailyLossLimit);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.maxRiskPerTrade"), safeSettings.maxRiskPerTrade);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.maxContracts"), safeSettings.maxContracts);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.commissionPerContract"), safeSettings.commissionPerContract);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.slippageTicks"), safeSettings.slippageTicks);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.profitTarget"), safeSettings.profitTarget);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.maxInitialRiskTicks"), safeSettings.maxInitialRiskTicks);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.orbCompressedMaxRiskTicks"), safeSettings.orbCompressedMaxRiskTicks);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.orbRetestMaxRiskTicks"), safeSettings.orbRetestMaxRiskTicks);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.openingMomentumMaxRiskTicks"), safeSettings.openingMomentumMaxRiskTicks);
			saveSetting(pstmt, symbolSettingKey(normalizedSymbol, "risk.lateOrbContinuationMaxRiskTicks"), safeSettings.lateOrbContinuationMaxRiskTicks);
			pstmt.executeBatch();
			return true;
		} catch (SQLException e) {
			e.printStackTrace();
			return false;
		}
	}

	public static boolean saveFuturesRiskSettings(String symbol, String slot, FuturesRiskSettings settings) {
		String normalizedSlot = normalizeStrategySlot(slot);
		if (STRATEGY_SLOT_BACKTEST.equals(normalizedSlot)) {
			return saveFuturesRiskSettings(symbol, settings);
		}
		STRATEGY_SETTING_SAVE_SLOT.set(normalizedSlot);
		try {
			return saveFuturesRiskSettings(symbol, settings);
		} finally {
			STRATEGY_SETTING_SAVE_SLOT.remove();
		}
	}

