	private static String symbolSettingKey(String symbol, String key) {
		String normalizedSymbol = normalizeSymbol(symbol);
		String activeSlot = STRATEGY_SETTING_SAVE_SLOT.get();
		if (activeSlot != null && !STRATEGY_SLOT_BACKTEST.equals(activeSlot)) {
			return normalizeStrategySlot(activeSlot) + "." + normalizedSymbol + "." + key;
		}
		return normalizedSymbol + "." + key;
	}

	private static String slotSymbolSettingKey(String slot, String symbol, String key) {
		String normalizedSlot = normalizeStrategySlot(slot);
		String symbolKey = normalizeSymbol(symbol) + "." + key;
		return STRATEGY_SLOT_BACKTEST.equals(normalizedSlot) ? symbolKey : normalizedSlot + "." + symbolKey;
	}

	private static String strategySettingPrefix(String slot, String symbol) {
		String normalizedSlot = normalizeStrategySlot(slot);
		String normalizedSymbol = normalizeSymbol(symbol);
		return STRATEGY_SLOT_BACKTEST.equals(normalizedSlot)
			? normalizedSymbol + "."
			: normalizedSlot + "." + normalizedSymbol + ".";
	}

	private static String normalizeStrategySlot(String slot) {
		String normalized = slot == null ? "" : slot.trim().toUpperCase();
		if (STRATEGY_SLOT_LIVE.equals(normalized)) {
			return STRATEGY_SLOT_LIVE;
		}
		if (STRATEGY_SLOT_BACKTEST.equals(normalized)) {
			return STRATEGY_SLOT_BACKTEST;
		}
		if (normalized.startsWith(STRATEGY_PRESET_PREFIX) && normalized.length() > STRATEGY_PRESET_PREFIX.length()) {
			return STRATEGY_PRESET_PREFIX + normalized.substring(STRATEGY_PRESET_PREFIX.length()).replaceAll("[^A-Z0-9_\\-]", "");
		}
		for (int index = 0; index < SEEDED_STRATEGY_PRESETS.length; index++) {
			String preset = normalizeStrategyPresetName(SEEDED_STRATEGY_PRESETS[index]);
			if (preset.equalsIgnoreCase(slot == null ? "" : slot.trim())) {
				return strategyPresetSlot(preset);
			}
		}
		return STRATEGY_SLOT_BACKTEST;
	}

	private static boolean isSeededStrategyPresetName(String presetName) {
		String normalized = normalizeStrategyPresetName(presetName);
		for (int index = 0; index < SEEDED_STRATEGY_PRESETS.length; index++) {
			if (normalized.equals(normalizeStrategyPresetName(SEEDED_STRATEGY_PRESETS[index]))) {
				return true;
			}
		}
		return false;
	}

	private static boolean isStrategyPresetSlot(String slot) {
		return normalizeStrategySlot(slot).startsWith(STRATEGY_PRESET_PREFIX);
	}

	private static String normalizeStrategyPresetName(String presetName) {
		String cleaned = cleanOrDefault(presetName, DEFAULT_STRATEGY_PRESET).trim().toLowerCase(Locale.US).replaceAll("[^a-z0-9_\\-]", "");
		return cleaned.length() == 0 ? DEFAULT_STRATEGY_PRESET : cleaned;
	}

	public static String strategyPresetSlot(String presetName) {
		String normalized = normalizeStrategyPresetName(presetName);
		return STRATEGY_PRESET_PREFIX + normalized.toUpperCase(Locale.US).replace('-', '_');
	}

	private static String strategyPresetNameFromSlot(String slot) {
		String normalizedSlot = normalizeStrategySlot(slot);
		if (!normalizedSlot.startsWith(STRATEGY_PRESET_PREFIX)) {
			return DEFAULT_STRATEGY_PRESET;
		}
		String raw = normalizedSlot.substring(STRATEGY_PRESET_PREFIX.length()).toLowerCase(Locale.US);
		return raw.length() == 0 ? DEFAULT_STRATEGY_PRESET : raw;
	}

	private static boolean isSymbolScopedSettingKey(String key) {
		if (key == null) {
			return false;
		}
		int dot = key.indexOf(".");
		if (dot <= 0) {
			return false;
		}
		String prefix = key.substring(0, dot);
		return supportedInstrumentSymbols().contains(prefix);
	}

	private static String unprefixedSymbolSettingKey(String symbol, String key) {
		if (key == null) {
			return null;
		}
		String prefix = normalizeSymbol(symbol) + ".";
		return key.startsWith(prefix) ? key.substring(prefix.length()) : null;
	}

	private static String unprefixedSlotSymbolSettingKey(String slot, String symbol, String key) {
		if (key == null) {
			return null;
		}
		String prefix = normalizeStrategySlot(slot) + "." + normalizeSymbol(symbol) + ".";
		return key.startsWith(prefix) ? key.substring(prefix.length()) : null;
	}

	private static void saveSetting(PreparedStatement pstmt, String key, boolean value) throws SQLException {
		saveSetting(pstmt, key, String.valueOf(value));
	}

	private static void saveSetting(PreparedStatement pstmt, String key, int value) throws SQLException {
		saveSetting(pstmt, key, String.valueOf(value));
	}

	private static void saveSetting(PreparedStatement pstmt, String key, double value) throws SQLException {
		saveSetting(pstmt, key, String.valueOf(value));
	}

	private static void saveSetting(PreparedStatement pstmt, String key, String value) throws SQLException {
		pstmt.setString(1, key);
		pstmt.setString(2, value);
		pstmt.addBatch();
	}

