	private static LiveStrategySnapshotRow ensureLiveStrategySnapshotForPreset(
		String symbols,
		FundedRuleProfile profile,
		String strategyPreset,
		String strategySlot,
		String topstepAccountId
	) {
		String cleanSymbols = cleanSymbolsCsv(symbols);
		String presetName = normalizeStrategyPresetName(strategyPreset);
		String normalizedSlot = normalizeStrategySlot(strategySlot);
		String accountId = cleanOrDefault(topstepAccountId, accountIdForFundedProfile(profile.code));
		String accountMode = accountModeForTopstepAccountId(accountId, profile.code);
		LiveStrategySnapshotRow activeSnapshot = loadActiveLiveStrategySnapshot();
		if (liveSourceSnapshotMatchesPreset(activeSnapshot, cleanSymbols, profile.code, presetName, normalizedSlot, accountId)
			&& liveSnapshotIntegrityMessage(activeSnapshot).length() == 0) {
			return activeSnapshot;
		}
		String strategySettingsJson = strategySettingsBySymbolJson(cleanSymbols, normalizedSlot);
		String riskSettingsJson = riskSettingsBySymbolJson(cleanSymbols, normalizedSlot);
		String portfolioSettingsJson = livePortfolioSettingsJson(cleanSymbols, profile, accountId, accountMode, presetName, normalizedSlot);
		String sourceMetricsJson = liveSourceMetricsConfigJson(cleanSymbols, profile, presetName, normalizedSlot);
		String now = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
		String codeVersion = "local-worktree-" + now.replace(" ", "T");
		try (Connection conn = DatabaseManager.getConnection()) {
			saveActiveLiveStrategySlot(
				conn,
				null,
				cleanSymbols,
				profile.code,
				accountMode,
				accountId,
				Math.max(1, profile.maxOpenPositions),
				Math.max(1, profile.maxAggregateContracts),
				profile.maxAggregateMiniUnits,
				strategySettingsJson,
				riskSettingsJson,
				portfolioSettingsJson,
				sourceMetricsJson,
				codeVersion,
				now
			);
			return loadActiveLiveStrategySnapshot();
		} catch (SQLException e) {
			e.printStackTrace();
			return null;
		}
	}

	private static boolean liveSourceSnapshotMatchesPreset(
		LiveStrategySnapshotRow snapshot,
		String symbols,
		String fundedProfileCode,
		String strategyPreset,
		String strategySlot,
		String topstepAccountId
	) {
		if (snapshot == null || snapshot.sourcePortfolioBacktestId <= 0) {
			return false;
		}
		String requestedSymbols = cleanSymbolsCsv(symbols);
		if (requestedSymbols.length() == 0 || !requestedSymbols.equals(cleanSymbolsCsv(snapshot.symbols))) {
			return false;
		}
		String profileCode = normalizeFundedProfileCode(fundedProfileCode);
		if (!profileCode.equals(normalizeFundedProfileCode(snapshot.fundedProfile))) {
			return false;
		}
		String requestedAccountId = cleanOrDefault(topstepAccountId, accountIdForFundedProfile(profileCode));
		String snapshotAccountId = cleanOrDefault(snapshot.practiceAccountId, accountIdForFundedProfile(profileCode));
		if (requestedAccountId.length() > 0 && !requestedAccountId.equals(snapshotAccountId)) {
			return false;
		}
		String requestedPreset = normalizeStrategyPresetName(strategyPreset);
		String requestedSlot = normalizeStrategySlot(strategySlot);
		String snapshotPreset = normalizeStrategyPresetName(jsonText(snapshot.portfolioSettingsJson, "strategyPreset", requestedPreset));
		String snapshotSlot = normalizeStrategySlot(jsonText(snapshot.portfolioSettingsJson, "strategySlot", strategyPresetSlot(snapshotPreset)));
		return requestedPreset.equals(snapshotPreset) && requestedSlot.equals(snapshotSlot);
	}

	public static String dryRunTopstepxOrder(
		String symbol,
		String side,
		int contracts,
		double entryPrice,
		double stopPrice,
		double targetPrice,
		String reason
	) {
		initializeStore();
		LiveStrategySnapshotRow snapshot = loadActiveLiveStrategySnapshot();
		if (snapshot == null) {
			return "{\"success\":false,\"message\":\"Promote a live strategy snapshot before constructing dry-run orders.\"}";
		}
		String normalizedSymbol = normalizeSymbol(symbol);
		if (!csvContainsSymbol(snapshot.symbols, normalizedSymbol)) {
			return "{\"success\":false,\"message\":" + jsonString(normalizedSymbol + " is not part of the active live strategy snapshot.") + "}";
		}
		String normalizedSide = normalizeOrderSide(side);
		if (normalizedSide.length() == 0) {
			return "{\"success\":false,\"message\":\"Dry-run order side must be LONG, SHORT, BUY, or SELL.\"}";
		}
		FuturesLiveSession session = currentLiveSessionCopy();
		String profileCode = activeLiveFundedProfileCode(session, snapshot);
		FundedRuleProfile profile = fundedRuleProfileFor(profileCode);
		String requiredAccountId = selectedTopstepAccountId(snapshot, profile.code);
		int requestedContracts = boundedInt(contracts, 1, 1, profileMaxContractsForSymbol(profile, normalizedSymbol));
		double requestedMiniUnits = round(fundedMiniUnitsPerContract(normalizedSymbol) * requestedContracts);
		if (snapshot.maxAggregateMiniUnits > 0.0 && requestedMiniUnits > snapshot.maxAggregateMiniUnits + 0.000001) {
			return "{\"success\":false,\"message\":\"Dry-run order exceeds the active snapshot's funded unit limit.\"}";
		}

		String configuredAccountId = FuturesConnectionManager.getTopstepxConfiguredAccountId();
		String blockReason = "";
		if (requiredAccountId.length() == 0) {
			blockReason = profile.name + " does not have a configured Topstep account ID yet.";
		} else if (!requiredAccountId.equals(configuredAccountId)) {
			blockReason = "TopstepX selected account must be the " + profile.name + " account " + requiredAccountId + ".";
		}
		String orderType = entryPrice > 0.0 ? "LIMIT" : "MARKET";
		InstrumentSpec spec = instrumentFor(normalizedSymbol);
		double safeEntry = entryPrice > 0.0 ? roundToTick(spec, entryPrice) : 0.0;
		double safeStop = stopPrice > 0.0 ? roundToTick(spec, stopPrice) : 0.0;
		double safeTarget = targetPrice > 0.0 ? roundToTick(spec, targetPrice) : 0.0;
		String createdAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
		String cleanStrategyCode = strategyCodeFromOrderReason(reason);
		String cleanStrategyName = liveStrategyNameForCode(cleanStrategyCode);
		String requestJson = "{"
			+ "\"provider\":\"TOPSTEPX\","
			+ "\"accountId\":" + jsonString(configuredAccountId) + ","
			+ "\"requiredAccountId\":" + jsonString(requiredAccountId) + ","
			+ "\"symbol\":" + jsonString(normalizedSymbol) + ","
			+ "\"strategyCode\":" + jsonString(cleanStrategyCode) + ","
			+ "\"strategyName\":" + jsonString(cleanStrategyName) + ","
			+ "\"side\":" + jsonString(normalizedSide) + ","
			+ "\"orderType\":" + jsonString(orderType) + ","
			+ "\"contracts\":" + requestedContracts + ","
			+ "\"fundedMiniUnits\":" + requestedMiniUnits + ","
			+ "\"entryPrice\":" + safeEntry + ","
			+ "\"stopPrice\":" + safeStop + ","
			+ "\"targetPrice\":" + safeTarget + ","
			+ "\"reason\":" + jsonString(cleanOrDefault(reason, "manual dry-run")) + ","
			+ "\"willSubmit\":false"
			+ "}";
		String responseJson = "{"
			+ "\"acceptedForSubmission\":false,"
			+ "\"dryRun\":true,"
			+ "\"blockReason\":" + jsonString(blockReason.length() == 0 ? "Order submission is disabled; this endpoint only records intent." : blockReason)
			+ "}";
		String status = blockReason.length() == 0 ? "DRY_RUN_RECORDED" : "DRY_RUN_BLOCKED";
		int ledgerId = insertLiveOrderLedger(snapshot.snapshotId, configuredAccountId, normalizedSymbol, normalizedSide, orderType, requestedContracts, safeEntry, safeStop, safeTarget, status, requestJson, responseJson, createdAt);
		recordLiveAudit(status, "INFO", "TopstepX dry-run order intent recorded for " + normalizedSymbol, requestJson);
		return "{"
			+ "\"success\":" + (blockReason.length() == 0) + ","
			+ "\"message\":" + jsonString(blockReason.length() == 0
				? "Dry-run order intent recorded. No broker order was submitted."
				: blockReason) + ","
			+ "\"ledgerId\":" + ledgerId + ","
			+ "\"request\":" + requestJson + ","
			+ "\"response\":" + responseJson
			+ "}";
	}

