	public static String getLiveThinkingJson(int sessionId, int limit) {
		int safeLimit = boundedInt(limit, 80, 1, LIVE_THINKING_LOG_LIMIT);
		List<LiveThinkingEntry> entries = new ArrayList<LiveThinkingEntry>();
		entries.addAll(persistedLiveThinkingEntries(sessionId, safeLimit));
		entries.addAll(persistedPotentialSignalThinkingEntries(sessionId, safeLimit));
		if (entries.isEmpty()) {
			synchronized (FuturesManager.class) {
				for (int index = liveThinkingLog.size() - 1; index >= 0 && entries.size() < safeLimit; index--) {
					LiveThinkingEntry entry = liveThinkingLog.get(index);
					if (sessionId > 0 && entry.sessionId != sessionId) {
						continue;
					}
					entries.add(entry);
				}
			}
		}
		Collections.sort(entries, new Comparator<LiveThinkingEntry>() {
			@Override
			public int compare(LiveThinkingEntry first, LiveThinkingEntry second) {
				int timeCompare = cleanOrDefault(second.createdAt, "").compareTo(cleanOrDefault(first.createdAt, ""));
				if (timeCompare != 0) {
					return timeCompare;
				}
				return Long.compare(second.id, first.id);
			}
		});
		entries = coalesceLiveThinkingEntries(entries, safeLimit);
		if (entries.size() > safeLimit) {
			entries = new ArrayList<LiveThinkingEntry>(entries.subList(0, safeLimit));
		}
		StringBuilder json = new StringBuilder("[");
		for (int index = 0; index < entries.size(); index++) {
			LiveThinkingEntry entry = entries.get(index);
			if (index > 0) {
				json.append(",");
			}
			json.append("{")
				.append("\"id\":").append(entry.id).append(",")
				.append("\"sessionId\":").append(entry.sessionId).append(",")
				.append("\"createdAt\":").append(jsonString(entry.createdAt)).append(",")
				.append("\"eventType\":").append(jsonString(entry.eventType)).append(",")
				.append("\"phase\":").append(jsonString(entry.phase)).append(",")
				.append("\"tone\":").append(jsonString(entry.tone)).append(",")
				.append("\"symbol\":").append(jsonString(entry.symbol)).append(",")
				.append("\"barTime\":").append(jsonString(entry.barTime)).append(",")
				.append("\"title\":").append(jsonString(entry.summary)).append(",")
				.append("\"subtext\":").append(jsonString(entry.detail)).append(",")
				.append("\"summary\":").append(jsonString(entry.summary)).append(",")
				.append("\"detail\":").append(jsonString(entry.detail)).append(",")
				.append("\"coalescedCount\":").append(Math.max(1, entry.coalescedCount)).append(",")
				.append("\"details\":").append(jsonObjectOrDefault(entry.detailsJson, "{}"))
				.append("}");
		}
		json.append("]");
		return json.toString();
	}

