	private static List<LiveThinkingEntry> coalesceLiveThinkingEntries(List<LiveThinkingEntry> entries, int limit) {
		LinkedHashMap<String, LiveThinkingEntry> grouped = new LinkedHashMap<String, LiveThinkingEntry>();
		if (entries == null) {
			return new ArrayList<LiveThinkingEntry>();
		}
		for (int index = 0; index < entries.size(); index++) {
			LiveThinkingEntry entry = entries.get(index);
			String key = liveThinkingCoalesceKey(entry);
			LiveThinkingEntry existing = grouped.get(key);
			if (existing == null) {
				grouped.put(key, copyLiveThinkingEntry(entry));
			} else {
				existing.coalescedCount = Math.max(1, existing.coalescedCount) + 1;
			}
			if (grouped.size() >= limit && index >= limit) {
				break;
			}
		}
		return new ArrayList<LiveThinkingEntry>(grouped.values());
	}

	private static LiveThinkingEntry copyLiveThinkingEntry(LiveThinkingEntry source) {
		LiveThinkingEntry copy = new LiveThinkingEntry();
		if (source == null) {
			return copy;
		}
		copy.id = source.id;
		copy.sessionId = source.sessionId;
		copy.createdAt = source.createdAt;
		copy.eventType = source.eventType;
		copy.phase = source.phase;
		copy.tone = source.tone;
		copy.symbol = source.symbol;
		copy.barTime = source.barTime;
		copy.summary = source.summary;
		copy.detail = source.detail;
		copy.detailsJson = source.detailsJson;
		copy.coalescedCount = Math.max(1, source.coalescedCount);
		return copy;
	}

	private static String liveThinkingCoalesceKey(LiveThinkingEntry entry) {
		if (entry == null) {
			return "empty";
		}
		String eventType = cleanOrDefault(entry.eventType, eventTypeFromPhase(entry.phase));
		String normalizedEvent = eventType.toUpperCase(Locale.US);
		if ("BACKEND_RESTARTED".equals(normalizedEvent)
			|| "BOT_STARTED".equals(normalizedEvent)
			|| "BOT_STOPPED".equals(normalizedEvent)
			|| "BOT_START_BLOCKED".equals(normalizedEvent)
			|| "STOP_FLATTEN_SWEEP".equals(normalizedEvent)) {
			return entry.sessionId + "|" + normalizedEvent + "|" + cleanOrDefault(entry.createdAt, "") + "|" + entry.id;
		}
		if ("SESSION_PREP".equals(normalizedEvent)
			|| "ENTRY_GATE_CLOSED".equals(normalizedEvent)
			|| "ENTRY_GATE_OPENED".equals(normalizedEvent)
			|| "TRADING_ENABLED".equals(normalizedEvent)) {
			return entry.sessionId + "|" + normalizedEvent + "|" + jsonText(entry.detailsJson, "marketDate", "");
		}
		if ("MARKET_DATA_STOPPED".equals(normalizedEvent)
			|| "MARKET_DATA_RESUMED".equals(normalizedEvent)) {
			return entry.sessionId + "|" + normalizedEvent + "|" + cleanOrDefault(entry.createdAt, "") + "|" + entry.id;
		}
		if ("POST_CLOSE_CLEANUP".equals(normalizedEvent)) {
			return entry.sessionId + "|" + normalizedEvent + "|" + jsonText(entry.detailsJson, "marketDate", "") + "|" + jsonText(entry.detailsJson, "code", "") + "|" + jsonText(entry.detailsJson, "gate", "") + "|" + jsonText(entry.detailsJson, "action", "");
		}
		return entry.sessionId
			+ "|" + normalizedEvent
			+ "|" + cleanOrDefault(entry.phase, "")
			+ "|" + cleanOrDefault(entry.symbol, "")
			+ "|" + cleanOrDefault(entry.barTime, "")
			+ "|" + cleanOrDefault(entry.summary, "");
	}

