	private static List<LiveThinkingEntry> persistedPotentialSignalThinkingEntries(int sessionId, int limit) {
		initializeStore();
		int safeLimit = boundedInt(limit, 80, 1, LIVE_THINKING_LOG_LIMIT);
		List<LiveThinkingEntry> entries = new ArrayList<LiveThinkingEntry>();
		String sql = sessionId > 0
			? "SELECT * FROM FuturesLiveRiskEvents WHERE sessionID = ? AND eventType IN ('POTENTIAL_SIGNAL_BLOCKED', 'POTENTIAL_SIGNAL_REJECTED') ORDER BY riskEventID DESC LIMIT ?"
			: "SELECT * FROM FuturesLiveRiskEvents WHERE eventType IN ('POTENTIAL_SIGNAL_BLOCKED', 'POTENTIAL_SIGNAL_REJECTED') ORDER BY riskEventID DESC LIMIT ?";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			if (sessionId > 0) {
				pstmt.setInt(1, sessionId);
				pstmt.setInt(2, safeLimit);
			} else {
				pstmt.setInt(1, safeLimit);
			}
			try (ResultSet rs = pstmt.executeQuery()) {
				while (rs.next()) {
					String payload = cleanOrDefault(rs.getString("payloadJson"), "{}");
					String validationReason = jsonText(payload, "validationReason", "");
					String marketDetail = jsonText(payload, "marketSessionDetail", "");
					String symbol = normalizeSymbol(jsonText(payload, "symbol", ""));
					String strategyCode = cleanOrDefault(jsonText(payload, "strategyCode", ""), "LIVE");
					String side = cleanOrDefault(jsonText(payload, "side", ""), "");
					LiveThinkingEntry entry = new LiveThinkingEntry();
					entry.id = 1000000000L + rs.getInt("riskEventID");
					entry.sessionId = rs.getInt("sessionID");
					entry.createdAt = cleanOrDefault(rs.getString("createdAt"), "");
					entry.eventType = "TRADE_BLOCKED";
					entry.phase = "Trade Blocked";
					entry.tone = "blocked";
					entry.symbol = symbol;
					entry.barTime = firstNonBlank(jsonText(payload, "entryTime", ""), jsonText(payload, "signalTime", ""));
					entry.summary = symbol + " " + strategyCode + " " + side + " blocked before order submit.";
					entry.detail = firstNonBlank(
						jsonText(payload, "detail", ""),
						validationReason.length() > 0
							? validationReason
							: marketDetail
					);
					entry.detailsJson = "{"
						+ "\"symbol\":" + jsonString(symbol) + ","
						+ "\"strategy\":" + jsonString(strategyCode) + ","
						+ "\"side\":" + jsonString(side) + ","
						+ "\"entry\":" + round(jsonNumber(payload, "entryPrice", 0.0)) + ","
						+ "\"stop\":" + round(jsonNumber(payload, "stopPrice", 0.0)) + ","
						+ "\"target\":" + round(jsonNumber(payload, "targetPrice", 0.0)) + ","
						+ "\"gate\":" + jsonString(jsonText(payload, "marketSessionLabel", "")) + ","
						+ "\"reason\":" + jsonString(cleanOrDefault(validationReason, marketDetail))
						+ "}";
					entries.add(entry);
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return entries;
	}

	private static void resetLiveThinkingLog(int sessionId) {
		synchronized (FuturesManager.class) {
			for (int index = liveThinkingLog.size() - 1; index >= 0; index--) {
				if (liveThinkingLog.get(index).sessionId == sessionId) {
					liveThinkingLog.remove(index);
				}
			}
		}
	}

	private static void pushLiveThinking(
		int sessionId,
		String phase,
		String tone,
		String symbol,
		String barTime,
		String summary,
		String detail
	) {
		pushLiveEvent(sessionId, eventTypeFromPhase(phase), phase, tone, symbol, barTime, summary, detail, "{}");
	}

	private static void pushLiveEvent(
		int sessionId,
		String eventType,
		String phase,
		String tone,
		String symbol,
		String barTime,
		String title,
		String subtext,
		String detailsJson
	) {
		String cleanEventType = cleanEventType(eventType);
		String cleanPhase = cleanOrDefault(phase, "Live Bot");
		String cleanTone = cleanOrDefault(tone, "info");
		String cleanSymbol = cleanOrDefault(symbol, "");
		String cleanBarTime = cleanOrDefault(barTime, "");
		String cleanSummary = cleanOrDefault(title, "");
		String cleanDetail = cleanOrDefault(subtext, "");
		String cleanDetailsJson = jsonObjectOrDefault(detailsJson, "{}");
		if (cleanSummary.length() == 0 && cleanDetail.length() == 0) {
			return;
		}
		LiveThinkingEntry entry = null;
			synchronized (FuturesManager.class) {
				if (!liveThinkingLog.isEmpty()) {
					LiveThinkingEntry last = liveThinkingLog.get(liveThinkingLog.size() - 1);
					if (last.sessionId == sessionId
						&& cleanEventType.equals(last.eventType)
					&& cleanPhase.equals(last.phase)
					&& cleanSymbol.equals(last.symbol)
					&& cleanBarTime.equals(last.barTime)
						&& cleanSummary.equals(last.summary)
						&& cleanDetail.equals(last.detail)
						&& cleanDetailsJson.equals(last.detailsJson)) {
						return;
					}
				}
				entry = new LiveThinkingEntry();
				entry.id = ++liveThinkingSequence;
				entry.sessionId = sessionId;
				entry.createdAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
				entry.eventType = cleanEventType;
				entry.phase = cleanPhase;
				entry.tone = cleanTone;
				entry.symbol = cleanSymbol;
			entry.barTime = cleanBarTime;
				entry.summary = cleanSummary;
				entry.detail = cleanDetail;
				entry.detailsJson = cleanDetailsJson;
				liveThinkingLog.add(entry);
				while (liveThinkingLog.size() > LIVE_THINKING_LOG_LIMIT) {
					liveThinkingLog.remove(0);
				}
			}
			if (entry != null) {
				persistLiveThinkingEntry(entry);
			}
	}

	private static void pushLiveDtmDecisionEvent(
		int sessionId,
		FuturesTrade trade,
		String actionCode,
		String title,
		String reason,
		String detailsJson
	) {
		FuturesTrade safeTrade = trade == null ? new FuturesTrade() : trade;
		String cleanAction = cleanOrDefault(actionCode, "DTM_HOLD_THESIS_INTACT");
		String detailPayload = jsonObjectOrDefault(detailsJson, "{}");
		pushLiveEvent(
			sessionId,
			"DTM_DECISION",
			"DTM Decision",
			"warn",
			cleanOrDefault(safeTrade.symbol, ""),
			cleanOrDefault(safeTrade.closedAt, ""),
			cleanOrDefault(title, "DTM trade decision recorded."),
			cleanOrDefault(reason, "DTM action reason not available."),
			"{"
				+ "\"symbol\":" + jsonString(cleanOrDefault(safeTrade.symbol, "")) + ","
				+ "\"strategy\":" + jsonString(cleanOrDefault(safeTrade.strategyCode, "")) + ","
				+ "\"side\":" + jsonString(cleanOrDefault(safeTrade.side, "")) + ","
				+ "\"contracts\":" + safeTrade.contracts + ","
				+ "\"action\":" + jsonString(cleanAction) + ","
				+ "\"reason\":" + jsonString(cleanOrDefault(reason, "")) + ","
				+ "\"dtmDetails\":" + detailPayload
				+ "}"
		);
	}

	private static void persistLiveThinkingEntry(LiveThinkingEntry entry) {
		if (entry == null) {
			return;
		}
		String sql = "INSERT INTO FuturesLiveThinkingLog (sessionID, eventType, phase, tone, symbol, barTime, summary, detail, detailsJson, createdAt) "
			+ "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setInt(1, entry.sessionId);
			pstmt.setString(2, cleanOrDefault(entry.eventType, ""));
			pstmt.setString(3, cleanOrDefault(entry.phase, ""));
			pstmt.setString(4, cleanOrDefault(entry.tone, "info"));
			pstmt.setString(5, cleanOrDefault(entry.symbol, ""));
			pstmt.setString(6, cleanOrDefault(entry.barTime, ""));
			pstmt.setString(7, cleanOrDefault(entry.summary, ""));
			pstmt.setString(8, cleanOrDefault(entry.detail, ""));
			pstmt.setString(9, jsonObjectOrDefault(entry.detailsJson, "{}"));
			pstmt.setString(10, cleanOrDefault(entry.createdAt, LocalDateTime.now().format(DISPLAY_TIME_FORMAT)));
			pstmt.executeUpdate();
		} catch (SQLException e) {
			e.printStackTrace();
		}
	}

	private static String cleanEventType(String eventType) {
		String normalized = cleanOrDefault(eventType, "STATUS").toUpperCase(Locale.US).replaceAll("[^A-Z0-9_]+", "_");
		while (normalized.contains("__")) {
			normalized = normalized.replace("__", "_");
		}
		normalized = normalized.replaceAll("^_+", "").replaceAll("_+$", "");
		return normalized.length() == 0 ? "STATUS" : normalized;
	}

	private static String eventTypeFromPhase(String phase) {
		String normalized = cleanOrDefault(phase, "STATUS").toUpperCase(Locale.US);
		if (normalized.contains("START")) return "BOT_STARTED";
		if (normalized.contains("STOP")) return "BOT_STOPPED";
		if (normalized.contains("MARKET")) return "MARKET_DATA";
		if (normalized.contains("ENTRY")) return "ENTRY_GATE";
		if (normalized.contains("CANDIDATE")) return "TRADE_CANDIDATE";
		if (normalized.contains("RISK")) return "TRADE_BLOCKED";
		if (normalized.contains("TOPSTEP") || normalized.contains("ORDER")) return "ORDER_EVENT";
		if (normalized.contains("EXIT")) return "POSITION_EXITED";
		if (normalized.contains("POST CLOSE")) return "POST_CLOSE_CLEANUP";
		return normalized.replaceAll("[^A-Z0-9_]+", "_");
	}

