		public static String getLiveMetricsJson(String accountId) {
			initializeStore();
			int sessionId = currentLiveSessionId();
			LiveStrategySnapshotRow snapshot = loadActiveLiveStrategySnapshot();
			FuturesLiveSession session = currentLiveSessionCopy();
			String profileCode = activeLiveFundedProfileCode(session, snapshot);
			String requestedAccountId = cleanOrDefault(accountId, "");
			String snapshotAccountId = snapshot == null
				? accountIdForFundedProfile(profileCode)
				: cleanOrDefault(snapshot.practiceAccountId, accountIdForFundedProfile(profileCode));
			String brokerAccountId = requestedAccountId.length() > 0 ? requestedAccountId : snapshotAccountId;
			FundedRuleProfile profile = fundedRuleProfileFor(profileCode);
			double configuredAccountSize = jsonNumber(snapshot == null ? "" : snapshot.portfolioSettingsJson, "accountSize", liveSession.accountSize > 0.0 ? liveSession.accountSize : 50000.0);
			double accountSize = accountSizeForBrokerProfile(brokerAccountId, profileCode, configuredAccountSize);
			double trailingDrawdownLimit = positiveOrDefault(profile.maxTrailingDrawdown, liveSession.maxTrailingDrawdown);
		int totalDecisions = 0;
		int accepted = 0;
		int rejected = 0;
		int exitTrades = 0;
		int winners = 0;
		double pnl = 0.0;
		double peakPnl = 0.0;
		double maxDrawdown = 0.0;
		String lastUpdated = "";
		String sql = sessionId > 0
			? "SELECT * FROM FuturesLiveSignalDecisions WHERE sessionID = ? ORDER BY decisionID ASC"
			: "SELECT * FROM FuturesLiveSignalDecisions ORDER BY decisionID ASC";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			if (sessionId > 0) {
				pstmt.setInt(1, sessionId);
			}
			try (ResultSet rs = pstmt.executeQuery()) {
				while (rs.next()) {
					totalDecisions++;
					String status = cleanOrDefault(rs.getString("status"), "");
						if (status.contains("ACCEPTED") || status.contains("SUBMITTED")) {
							accepted++;
						}
						if (status.contains("REJECTED")) {
							rejected++;
						}
						String payload = rs.getString("payloadJson");
						if (liveDecisionExitStatus(status) && liveDecisionPnlAuthoritative(status, payload)) {
							double tradePnl = liveDecisionRealizedPnl(status, payload);
							pnl = round(pnl + tradePnl);
							exitTrades++;
							if (tradePnl > 0.0) {
								winners++;
							}
							peakPnl = Math.max(peakPnl, pnl);
							maxDrawdown = Math.max(maxDrawdown, peakPnl - pnl);
						}
					lastUpdated = cleanOrDefault(rs.getString("createdAt"), lastUpdated);
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		double returnPct = accountSize <= 0.0 ? 0.0 : (pnl / accountSize) * 100.0;
			double winRate = exitTrades <= 0 ? 0.0 : (winners * 100.0) / exitTrades;
			int openTrades = Math.max(0, accepted - exitTrades);
				String brokerSymbols = snapshot == null ? liveSession.symbols : snapshot.symbols;
			String brokerMetricsJson = FuturesConnectionManager.getTopstepxAccountMetrics(brokerAccountId, brokerSymbols, accountSize, liveBrokerTradeHistoryDays());
			LiveRuntimeState.updateBrokerMetricsJson(brokerMetricsJson);
			boolean brokerMetricsReady = brokerMetricsJson.contains("\"success\":true");
			if (brokerMetricsReady && sessionId > 0 && snapshot != null) {
				reconcileBrokerFlatLiveEntries(sessionId, snapshot.snapshotId, brokerMetricsJson);
			}
			double currentPnl = pnl;
			double currentBalance = accountSize + pnl;
			double displayDrawdown = maxDrawdown;
			double displayReturnPct = returnPct;
			int displayTrades = exitTrades;
			int displayOpenTrades = openTrades;
			double totalFees = 0.0;
			String dataSource = "LOCAL_DECISIONS";
			boolean brokerBalanceTracksPnl = false;
			String brokerBalanceMode = "EQUITY";
			double riskCurrentBalance = currentBalance;
			if (brokerMetricsReady) {
				double brokerPnl = jsonFirstNumber(brokerMetricsJson, new String[] { "currentPnl", "closedTradePnl", "realizedPnl" }, Double.NaN);
				double brokerBalance = jsonFirstNumber(brokerMetricsJson, new String[] { "currentBalance", "balance", "cashBalance" }, Double.NaN);
				double brokerRiskBalance = jsonFirstNumber(brokerMetricsJson, new String[] { "riskCurrentBalance", "equityBalance" }, Double.NaN);
				double brokerReturnPct = jsonFirstNumber(brokerMetricsJson, new String[] { "returnPct" }, Double.NaN);
				double brokerDrawdown = jsonFirstNumber(brokerMetricsJson, new String[] { "drawdown" }, Double.NaN);
				double brokerTotalFees = jsonFirstNumber(brokerMetricsJson, new String[] { "totalFees" }, Double.NaN);
			double brokerTrades = jsonFirstNumber(brokerMetricsJson, new String[] { "numberOfTrades" }, Double.NaN);
			double brokerOpenTrades = jsonFirstNumber(brokerMetricsJson, new String[] { "openTrades" }, Double.NaN);
			brokerBalanceTracksPnl = jsonBoolean(brokerMetricsJson, "balanceTracksPnl");
			brokerBalanceMode = brokerBalanceTracksPnl ? "PNL" : "EQUITY";
			if (!Double.isNaN(brokerPnl)) {
				currentPnl = brokerPnl;
			}
				if (!Double.isNaN(brokerBalance) && (brokerBalance > 0.0 || brokerBalanceTracksPnl)) {
					currentBalance = brokerBalance;
				}
				if (!Double.isNaN(brokerRiskBalance) && brokerRiskBalance > 0.0) {
					riskCurrentBalance = brokerRiskBalance;
				} else if (brokerBalanceTracksPnl && !Double.isNaN(brokerPnl)) {
					riskCurrentBalance = Math.max(0.0, accountSize + brokerPnl);
				} else {
					riskCurrentBalance = currentBalance;
				}
				if (!Double.isNaN(brokerReturnPct)) {
					displayReturnPct = brokerReturnPct;
				}
				if (!Double.isNaN(brokerDrawdown)) {
					displayDrawdown = brokerDrawdown;
				}
				if (!Double.isNaN(brokerTotalFees)) {
					totalFees = brokerTotalFees;
				}
			if (!Double.isNaN(brokerTrades)) {
				displayTrades = (int) Math.round(brokerTrades);
			}
			if (!Double.isNaN(brokerOpenTrades)) {
				displayOpenTrades = (int) Math.round(brokerOpenTrades);
				}
				dataSource = "TOPSTEPX";
			}
			double drawdownFloor = liveTrailingDrawdownFloor(accountSize, riskCurrentBalance, trailingDrawdownLimit);
			double drawdownCushion = trailingDrawdownLimit > 0.0 ? Math.max(0.0, riskCurrentBalance - drawdownFloor) : 0.0;
			double drawdownUsed = trailingDrawdownLimit > 0.0 ? Math.max(0.0, trailingDrawdownLimit - drawdownCushion) : Math.max(0.0, accountSize - riskCurrentBalance);
			if (displayDrawdown <= 0.0 && drawdownUsed > 0.0) {
				displayDrawdown = drawdownUsed;
			}
			return "{"
				+ "\"success\":true,"
			+ "\"sessionId\":" + sessionId + ","
			+ "\"snapshotId\":" + (snapshot == null ? 0 : snapshot.snapshotId) + ","
			+ "\"symbols\":" + jsonString(snapshot == null ? liveSession.symbols : snapshot.symbols) + ","
			+ "\"dataSource\":" + jsonString(dataSource) + ","
				+ "\"brokerMetricsReady\":" + brokerMetricsReady + ","
				+ "\"currentPnl\":" + round(currentPnl) + ","
				+ "\"currentBalance\":" + round(currentBalance) + ","
				+ "\"riskCurrentBalance\":" + round(riskCurrentBalance) + ","
				+ "\"equityBalance\":" + round(riskCurrentBalance) + ","
				+ "\"balanceMode\":" + jsonString(brokerBalanceMode) + ","
				+ "\"balanceTracksPnl\":" + brokerBalanceTracksPnl + ","
				+ "\"totalFees\":" + round(totalFees) + ","
				+ "\"returnPct\":" + round(displayReturnPct) + ","
				+ "\"winRate\":" + round(winRate) + ","
				+ "\"numberOfTrades\":" + displayTrades + ","
				+ "\"openTrades\":" + displayOpenTrades + ","
				+ "\"drawdown\":" + round(displayDrawdown) + ","
				+ "\"drawdownUsed\":" + round(drawdownUsed) + ","
				+ "\"drawdownCushion\":" + round(drawdownCushion) + ","
				+ "\"trailingDrawdownLimit\":" + round(trailingDrawdownLimit) + ","
				+ "\"trailingDrawdownFloor\":" + round(drawdownFloor) + ","
				+ "\"drawdownSource\":" + jsonString(displayDrawdown > 0.0 ? dataSource : "TRAILING_CUSHION") + ","
			+ "\"accepted\":" + accepted + ","
			+ "\"rejected\":" + rejected + ","
			+ "\"decisions\":" + totalDecisions + ","
			+ "\"accountSize\":" + round(accountSize) + ","
				+ "\"broker\":" + jsonObjectOrDefault(brokerMetricsJson, "{}") + ","
				+ "\"lastUpdated\":" + jsonString(lastUpdated)
				+ "}";
		}

	private static double liveDecisionRealizedPnl(String status, String payloadJson) {
		if (!liveDecisionExitStatus(status) || !liveDecisionPnlAuthoritative(status, payloadJson)) {
			return 0.0;
		}
		return round(jsonNumber(payloadJson, "pnl", 0.0));
	}

	private static boolean liveDecisionExitStatus(String status) {
		String cleanStatus = cleanOrDefault(status, "").toUpperCase(Locale.US);
		return cleanStatus.startsWith("SIMULATED")
			|| cleanStatus.contains("EXIT")
			|| cleanStatus.contains("CLOSED")
			|| cleanStatus.contains("FLAT")
			|| cleanStatus.contains("SOLD");
	}

	private static boolean liveDecisionPnlAuthoritative(String status, String payloadJson) {
		String cleanStatus = cleanOrDefault(status, "").toUpperCase(Locale.US);
		if (!liveDecisionExitStatus(cleanStatus)) {
			return false;
		}
		if (cleanStatus.startsWith("SIMULATED") || !cleanStatus.contains("TOPSTEPX")) {
			return true;
		}
		String payload = cleanOrDefault(payloadJson, "");
		return payload.contains("\"authoritative\":true")
			|| payload.contains("\"source\":\"TOPSTEPX_METRICS_RECONCILE\"")
			|| payload.contains("\"finalRealizedPnlSource\":\"BROKER_FILL\"");
	}

