	private static double liveTrailingDrawdownFloor(double accountSize, double currentBalance, double trailingDrawdownLimit) {
		if (trailingDrawdownLimit <= 0.0) {
			return Math.max(0.0, accountSize);
		}
		double staticFloor = accountSize - trailingDrawdownLimit;
		double trailingFloor = currentBalance - trailingDrawdownLimit;
		return Math.max(staticFloor, Math.min(accountSize, trailingFloor));
	}

