	private static void alignSyntheticPositionToBar(PortfolioSymbolContext context, PortfolioPosition position, Bar bar) {
		if (context == null || position == null || bar == null || bar.marketDate == null || bar.marketTime == null) {
			return;
		}
		Integer index = barIndex(context, bar.marketDate, bar.marketTime);
		if (index != null) {
			position.entryIndex = index.intValue();
			position.openedMarketTime = bar.marketTime;
		}
	}

	private static Bar selfTestDtmBar(PortfolioSymbolContext context, PortfolioPosition position, int index, double rMultiple, boolean targetTouch, boolean trendAgainst) {
		List<Bar> bars = context.byDay.get(LocalDate.of(2026, 5, 14));
		Bar template = bars.get(Math.min(Math.max(index, 0), bars.size() - 1));
		Bar bar = new Bar();
		bar.displayTime = template.displayTime;
		bar.marketDate = template.marketDate;
		bar.marketTime = template.marketTime;
		double tickSize = Math.max(context.spec.tickSize, 0.01);
		double move = position.initialRisk * rMultiple;
		double close = "SHORT".equals(position.side) ? position.entryPrice - move : position.entryPrice + move;
		if (targetTouch) {
			close = position.targetPrice;
		}
		close = roundToTick(context.spec, close);
		bar.close = close;
		bar.open = roundToTick(context.spec, position.entryPrice);
		if ("SHORT".equals(position.side)) {
			bar.high = targetTouch
				? roundToTick(context.spec, Math.min(position.entryPrice, (position.activeStopPrice > 0.0 ? position.activeStopPrice - tickSize : position.entryPrice)))
				: roundToTick(context.spec, close + tickSize);
			bar.low = targetTouch ? roundToTick(context.spec, position.targetPrice - tickSize) : roundToTick(context.spec, close - tickSize);
		} else {
			bar.high = targetTouch ? roundToTick(context.spec, position.targetPrice + tickSize) : roundToTick(context.spec, close + tickSize);
			bar.low = targetTouch
				? roundToTick(context.spec, Math.max(position.entryPrice, (position.activeStopPrice > 0.0 ? position.activeStopPrice + tickSize : position.entryPrice)))
				: roundToTick(context.spec, close - tickSize);
		}
		bar.volume = Math.max(1.0, template.volume);
		if (trendAgainst) {
			bar.vwap = "SHORT".equals(position.side) ? close - (tickSize * 4.0) : close + (tickSize * 4.0);
			bar.ema20 = bar.vwap;
			bar.ema9 = bar.vwap;
			bar.ema50 = bar.vwap;
		} else {
			bar.vwap = "SHORT".equals(position.side) ? close + tickSize : close - tickSize;
			bar.ema20 = bar.vwap;
			bar.ema9 = bar.vwap;
			bar.ema50 = bar.vwap;
		}
		bar.atr14 = Math.max(template.atr14, tickSize * 4.0);
		bar.rsi14 = "SHORT".equals(position.side) ? 45.0 : 55.0;
		bar.volumeSma20 = Math.max(1.0, template.volumeSma20);
		bar.rangeTicks = tickSize <= 0.0 ? 0.0 : Math.abs(bar.high - bar.low) / tickSize;
		bar.bodyPct = 80.0;
		return bar;
	}

	private static int countSessionRows(String tableName, String columnName, int sessionId) {
		String cleanTable = cleanOrDefault(tableName, "");
		String cleanColumn = cleanOrDefault(columnName, "");
		if (!"FuturesLiveSignalDecisions".equals(cleanTable) && !"FuturesLiveThinkingLog".equals(cleanTable)) {
			return 0;
		}
		if (!"sessionID".equals(cleanColumn)) {
			return 0;
		}
		String sql = "SELECT COUNT(*) FROM " + cleanTable + " WHERE " + cleanColumn + " = ?";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setInt(1, sessionId);
			try (ResultSet rs = pstmt.executeQuery()) {
				return rs.next() ? rs.getInt(1) : 0;
			}
		} catch (SQLException e) {
			e.printStackTrace();
			return 0;
		}
	}

	private static int countThinkingEvents(int sessionId, String eventType) {
		String sql = "SELECT COUNT(*) FROM FuturesLiveThinkingLog WHERE sessionID = ? AND eventType = ?";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setInt(1, sessionId);
			pstmt.setString(2, cleanEventType(eventType));
			try (ResultSet rs = pstmt.executeQuery()) {
				return rs.next() ? rs.getInt(1) : 0;
			}
		} catch (SQLException e) {
			e.printStackTrace();
			return 0;
		}
	}

	private static List<String> selfTestSymbols(LiveStrategySnapshotRow snapshot) {
		List<String> symbols = parseSymbols(snapshot == null ? DEFAULT_LIVE_SYMBOLS : snapshot.symbols);
		Set<String> seen = new HashSet<String>(symbols);
		List<String> supported = supportedInstrumentSymbols();
		for (int index = 0; index < supported.size(); index++) {
			String symbol = normalizeSymbol(supported.get(index));
			if (!seen.contains(symbol)) {
				symbols.add(symbol);
				seen.add(symbol);
			}
		}
		if (symbols.isEmpty()) {
			symbols.addAll(supported);
		}
		return symbols;
	}

	private static PortfolioSymbolContext selfTestContext(String symbol) {
		String normalizedSymbol = normalizeSymbol(symbol);
		PortfolioSymbolContext context = new PortfolioSymbolContext();
		context.symbol = normalizedSymbol;
		context.spec = instrumentFor(normalizedSymbol);
		context.config = new BacktestConfig();
		context.config.symbol = normalizedSymbol;
		context.config.accountSize = 50000.0;
		context.config.maxTrailingDrawdown = 2000.0;
		context.config.dailyLossLimit = 5000.0;
		context.config.maxRiskPerTrade = 5000.0;
		context.config.maxContracts = topstepMaxContractsForSymbol(normalizedSymbol);
		context.config.commissionPerContract = 1.24;
		context.config.slippageTicks = 0.0;
		context.config.strategySettings = selfTestStrategySettings();
		LocalDate day = LocalDate.of(2026, 5, 14);
		List<Bar> bars = new ArrayList<Bar>();
		for (int index = 0; index < 12; index++) {
			LocalTime time = LocalTime.of(9, 35).plusMinutes(index);
			Bar bar = new Bar();
			bar.displayTime = day + " " + time;
			bar.marketDate = day;
			bar.marketTime = time;
			bar.open = 100.0 + (index * 0.25);
			bar.high = bar.open + 1.0;
			bar.low = bar.open - 1.0;
			bar.close = bar.open + 0.65;
			bar.volume = 1000.0 + (index * 10.0);
			bar.volumeSma20 = 800.0;
			bar.ema9 = bar.close - 0.10;
			bar.ema20 = bar.close - 0.20;
			bar.ema50 = bar.close - 0.30;
			bar.vwap = bar.close - 0.15;
			bar.rsi14 = 55.0;
			bar.rangeTicks = context.spec.tickSize <= 0.0 ? 0.0 : Math.abs(bar.high - bar.low) / context.spec.tickSize;
			bar.bodyPct = 45.0;
			bars.add(bar);
		}
		context.byDay.put(day, bars);
		Map<LocalTime, Integer> indexByTime = new HashMap<LocalTime, Integer>();
		for (int index = 0; index < bars.size(); index++) {
			indexByTime.put(bars.get(index).marketTime, Integer.valueOf(index));
		}
		context.indexByDayTime.put(day, indexByTime);
		return context;
	}

