	private static LivePortfolioSignalCandidate selfTestCandidateWithFlatStop(String symbol, String strategyCode) {
		return selfTestCandidate(symbol, strategyCode, "LONG", true);
	}

	private static LivePortfolioSignalCandidate selfTestCandidate(String symbol, String strategyCode, String side, boolean flatStop) {
		PortfolioSymbolContext context = selfTestContext(symbol);
		LocalDate day = LocalDate.of(2026, 5, 14);
		List<Bar> bars = context.byDay.get(day);
		Bar entryBar = bars.get(6);
		Signal signal = new Signal();
		signal.strategyCode = strategyCode;
		signal.strategyName = selfTestStrategyName(strategyCode);
		signal.side = "SHORT".equals(side) ? "SHORT" : "LONG";
		signal.entryIndex = 5;
		double executableEntry = entryBar.close > 0.0 ? entryBar.close : entryBar.open;
		signal.entryPrice = roundToTick(context.spec, executableEntry);
		double riskDistance = Math.max(context.spec.tickSize * 8.0, context.spec.tickSize);
		double rewardDistance = riskDistance * 2.0;
		if (flatStop) {
			signal.stopPrice = signal.entryPrice;
			signal.targetPrice = signal.entryPrice;
		} else if ("SHORT".equals(signal.side)) {
			signal.stopPrice = roundToTick(context.spec, signal.entryPrice + riskDistance);
			signal.targetPrice = roundToTick(context.spec, signal.entryPrice - rewardDistance);
		} else {
			signal.stopPrice = roundToTick(context.spec, signal.entryPrice - riskDistance);
			signal.targetPrice = roundToTick(context.spec, signal.entryPrice + rewardDistance);
		}
		signal.maxHoldBars = 30;
		Bar syntheticEntryBar = copyBar(entryBar);
		syntheticEntryBar.open = signal.entryPrice;
		syntheticEntryBar.close = signal.entryPrice;
		syntheticEntryBar.high = roundToTick(context.spec, signal.entryPrice + (riskDistance * 0.25));
		syntheticEntryBar.low = roundToTick(context.spec, signal.entryPrice - (riskDistance * 0.25));
		SignalEvent event = new SignalEvent();
		event.symbol = normalizeSymbol(symbol);
		event.signal = signal;
		event.day = day;
		event.entryTime = syntheticEntryBar.marketTime;
		event.executionIndex = 6;
		LivePortfolioSignalCandidate candidate = new LivePortfolioSignalCandidate();
		candidate.symbol = event.symbol;
		candidate.context = context;
		candidate.event = event;
		candidate.entryBar = syntheticEntryBar;
		candidate.signalTime = bars.get(5).displayTime;
		candidate.entryTime = syntheticEntryBar.displayTime;
		candidate.syntheticSelfTest = true;
		return candidate;
	}

	private static Bar selfTestExitBar(PortfolioSymbolContext context, LivePortfolioSignalCandidate candidate, PortfolioPosition position) {
		LocalDate day = candidate.event.day;
		List<Bar> bars = context.byDay.get(day);
		int exitIndex = Math.min(Math.max(candidate.event.executionIndex + 1, 0), bars.size() - 1);
		Bar template = bars.get(exitIndex);
		Bar bar = new Bar();
		bar.displayTime = template.displayTime;
		bar.marketDate = template.marketDate;
		bar.marketTime = template.marketTime;
		double tickSize = Math.max(context.spec.tickSize, 0.01);
		double entryPrice = roundToTick(context.spec, position.entryPrice);
		double targetPrice = roundToTick(context.spec, position.targetPrice);
		if ("SHORT".equals(position.side)) {
			bar.open = entryPrice;
			bar.high = entryPrice;
			bar.low = roundToTick(context.spec, targetPrice - tickSize);
			bar.close = targetPrice;
		} else {
			bar.open = entryPrice;
			bar.high = roundToTick(context.spec, targetPrice + tickSize);
			bar.low = entryPrice;
			bar.close = targetPrice;
		}
		bar.volume = Math.max(1.0, template.volume);
		bar.vwap = bar.close;
		bar.ema9 = bar.close;
		bar.ema20 = bar.close;
		bar.ema50 = bar.close;
		bar.atr14 = Math.max(template.atr14, tickSize * 4.0);
		bar.rsi14 = "SHORT".equals(position.side) ? 45.0 : 55.0;
		bar.volumeSma20 = Math.max(1.0, template.volumeSma20);
		bar.rangeTicks = tickSize <= 0.0 ? 0.0 : Math.abs(bar.high - bar.low) / tickSize;
		bar.bodyPct = 100.0;
		return bar;
	}

	private static PortfolioPosition selfTestOpenPosition(String symbol) {
		String normalizedSymbol = normalizeSymbol(symbol);
		InstrumentSpec spec = instrumentFor(normalizedSymbol);
		PortfolioPosition position = new PortfolioPosition();
		position.symbol = normalizedSymbol;
		position.spec = spec;
		position.signal = new Signal();
		position.signal.strategyCode = "ORB";
		position.signal.strategyName = "Opening Range";
		position.side = "LONG";
		position.contracts = 1;
		position.entryPrice = 100.0;
		position.stopPrice = 98.0;
		position.targetPrice = 104.0;
		position.activeStopPrice = position.activeStopPrice > 0.0 ? position.activeStopPrice : position.stopPrice;
		position.initialRisk = 2.0;
		position.riskPerContract = ((position.initialRisk / spec.tickSize) * spec.tickValue) + 2.48;
		position.commissionPerContract = 1.24;
		position.openedAt = "2026-05-14 09:35";
		position.openedMarketTime = LocalTime.of(9, 35);
		return position;
	}

