		if ("ORB".equals(strategyCode)) return "Opening Range";
		if ("ORB2".equals(strategyCode)) return "Opening Range Retest";
		if ("ORBX".equals(strategyCode)) return "ORB Event Pack";
		if ("LORB".equals(strategyCode)) return "Late ORB Continuation";
		if ("OMOM".equals(strategyCode)) return "Opening Momentum";
		if ("SWEEP".equals(strategyCode)) return "Liquidity Sweep";
		if ("SWEEP2".equals(strategyCode)) return "Confirmed Prior-Day Sweep";
		if ("PDB".equals(strategyCode)) return "Prior-Day Breakout";
		if ("VWAP".equals(strategyCode)) return "VWAP Pullback";
		if ("VRCL".equals(strategyCode)) return "VWAP Reclaim";
		if ("MRVWAP".equals(strategyCode)) return "VWAP Reversion";
		if ("FVG".equals(strategyCode)) return "Fair Value Gap";
		if ("IFVG".equals(strategyCode)) return "Inversion Fair Value Gap";
		if ("CMOM".equals(strategyCode)) return "Close Momentum";
		if ("AFT".equals(strategyCode)) return "Afternoon Continuation";
		if ("MIM".equals(strategyCode)) return "Market Momentum";
		if ("IPB".equals(strategyCode)) return "Impulse Pullback";
		if ("KELT".equals(strategyCode)) return "Keltner Scalp";
		if ("KREV".equals(strategyCode)) return "Keltner Reversion";
		if ("MSCALP".equals(strategyCode)) return "Micro Scalp";
		if ("SHDW".equals(strategyCode)) return "Mini Shadow";
		if ("ECHO".equals(strategyCode)) return "Micro Echo";
		if ("WFT".equals(strategyCode)) return "Winner Follow-Through";
		if ("TLAD".equals(strategyCode)) return "Trend Ladder";
		if ("RCB".equals(strategyCode)) return "Compression Breakout";
		if ("VPB".equals(strategyCode)) return "Value Area Reclaim";
		if ("VABS".equals(strategyCode)) return "Volume Absorption Reversal";
		if ("EIA".equals(strategyCode)) return "MCL EIA Continuation";
		if ("COPEN".equals(strategyCode)) return "MCL Crude Session Open";
		if ("IDXCONF".equals(strategyCode)) return "MYM Index Confirmation";
		if ("MYMORB2".equals(strategyCode)) return "MYM ORB Retest";
