	private static PortfolioBacktestConfig livePortfolioConfigFromSnapshot(LiveStrategySnapshotRow snapshot, LocalDate startDate, LocalDate endDate) {
		String portfolioSettings = snapshot == null ? "{}" : snapshot.portfolioSettingsJson;
		FuturesLiveSession session;
		synchronized (FuturesManager.class) {
			session = copyLiveSession(liveSession);
		}
		boolean useSessionRisk = session.running && session.sessionId > 0;
		String configSymbols = useSessionRisk ? activeLiveSymbols(session, snapshot) : cleanSymbolsCsv(snapshot == null ? "MNQ" : snapshot.symbols);
		String profileCode = useSessionRisk
			? cleanOrDefault(session.fundedProfile, snapshot == null ? TOPSTEPX_DEFAULT_LIVE_PROFILE : snapshot.fundedProfile)
			: cleanOrDefault(snapshot == null ? "" : snapshot.fundedProfile, TOPSTEPX_DEFAULT_LIVE_PROFILE);
		double accountSize = useSessionRisk ? session.accountSize : jsonNumber(portfolioSettings, "accountSize", 50000.0);
		double maxTrailingDrawdown = useSessionRisk ? session.maxTrailingDrawdown : jsonNumber(portfolioSettings, "maxTrailingDrawdown", 2000.0);
		double dailyLossLimit = useSessionRisk ? session.dailyLossLimit : jsonNumber(portfolioSettings, "dailyLossLimit", 1000.0);
		double maxRiskPerTrade = useSessionRisk ? session.maxRiskPerTrade : jsonNumber(portfolioSettings, "maxRiskPerTrade", 400.0);
		int maxContracts = useSessionRisk ? session.maxContracts : (int) jsonNumber(portfolioSettings, "maxContracts", 50.0);
		double commissionPerContract = useSessionRisk ? session.commissionPerContract : jsonNumber(portfolioSettings, "commissionPerContract", 1.24);
		double slippageTicks = useSessionRisk ? session.slippageTicks : jsonNumber(portfolioSettings, "slippageTicks", 1.0);
		double profitTarget = useSessionRisk ? session.profitTarget : jsonNumber(portfolioSettings, "profitTarget", 0.0);
		int maxOpenPositions = useSessionRisk ? session.maxOpenPositions : Math.max(1, snapshot == null ? 1 : snapshot.maxOpenPositions);
		int maxAggregateContracts = useSessionRisk ? session.maxAggregateContracts : Math.max(1, snapshot == null ? maxContracts : snapshot.maxAggregateContracts);
		double maxAggregateMiniUnits = useSessionRisk ? session.maxAggregateMiniUnits : (snapshot == null ? 5.0 : snapshot.maxAggregateMiniUnits);
		boolean useSavedRisk = riskProfileUsesSavedRisk(profileCode);
		PortfolioBacktestConfig config = buildPortfolioBacktestConfig(
			configSymbols,
			startDate.toString(),
			endDate.toString(),
			accountSize,
			maxTrailingDrawdown,
			dailyLossLimit,
			maxRiskPerTrade,
			maxContracts,
			commissionPerContract,
			slippageTicks,
			maxOpenPositions,
			maxAggregateContracts,
			maxAggregateMiniUnits,
			useSavedRisk,
			profitTarget,
			profileCode
		);
		config.strategySlot = activeLiveStrategySlot(session, snapshot);
		config.strategyPreset = activeLiveStrategyPreset(session, snapshot);
		config.sourcePortfolioBacktestId = snapshot == null ? 0 : snapshot.sourcePortfolioBacktestId;
		if (useSessionRisk) {
			FundedRuleProfile profile = fundedRuleProfileFor(profileCode);
			config.accountSize = positiveOrDefault(accountSize, config.accountSize);
			config.maxTrailingDrawdown = positiveOrDefault(maxTrailingDrawdown, config.maxTrailingDrawdown);
			config.dailyLossLimit = positiveOrDefault(dailyLossLimit, config.dailyLossLimit);
			config.maxRiskPerTrade = Math.min(positiveOrDefault(maxRiskPerTrade, config.maxRiskPerTrade), profile.maxRiskPerTrade);
			config.maxContracts = Math.min(Math.max(1, maxContracts), profile.maxMicroContracts);
			config.commissionPerContract = commissionPerContract >= 0.0 ? commissionPerContract : config.commissionPerContract;
			config.slippageTicks = slippageTicks >= 0.0 ? slippageTicks : config.slippageTicks;
			config.profitTarget = profitTarget >= 0.0 ? profitTarget : config.profitTarget;
			config.maxOpenPositions = Math.min(Math.max(1, maxOpenPositions), profile.maxOpenPositions);
			config.maxAggregateContracts = Math.min(Math.max(1, maxAggregateContracts), profile.maxAggregateContracts);
			config.maxAggregateMiniUnits = clamp(maxAggregateMiniUnits, 0.1, Math.max(0.1, profile.maxAggregateMiniUnits));
		}
		config.dayStartBalance = config.accountSize;
		config.currentBalance = config.accountSize;
		return config;
	}

	private static int createLiveEngineSession(LiveStrategySnapshotRow snapshot, String executionMode, String dataMode, String status, String lastBarTime, String startedAt) {
		String sql = "INSERT INTO FuturesLiveEngineSessions (snapshotID, sourcePortfolioBacktestID, executionMode, status, symbols, dataMode, startedAt, lastUpdatedAt, lastBarTime, message) "
			+ "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
			pstmt.setInt(1, snapshot.snapshotId);
			if (snapshot.sourcePortfolioBacktestId > 0) {
				pstmt.setInt(2, snapshot.sourcePortfolioBacktestId);
			} else {
				pstmt.setNull(2, Types.INTEGER);
			}
			pstmt.setString(3, cleanOrDefault(executionMode, "DRY_RUN"));
			pstmt.setString(4, cleanOrDefault(status, "RUNNING"));
			pstmt.setString(5, cleanOrDefault(snapshot.symbols, ""));
			pstmt.setString(6, cleanOrDefault(dataMode, "LOCAL_REPLAY"));
			pstmt.setString(7, startedAt);
			pstmt.setString(8, startedAt);
			pstmt.setString(9, cleanOrDefault(lastBarTime, ""));
			pstmt.setString(10, "Live dry-run engine session started.");
			pstmt.executeUpdate();
			try (ResultSet keys = pstmt.getGeneratedKeys()) {
				return keys.next() ? keys.getInt(1) : -1;
			}
		} catch (SQLException e) {
			e.printStackTrace();
			return -1;
		}
	}

	private static void updateLiveEngineSession(int sessionId, String status, String lastBarTime, int decisionCount, int acceptedCount, int rejectedCount, String message) {
		String sql = "UPDATE FuturesLiveEngineSessions SET status = ?, lastUpdatedAt = ?, lastBarTime = ?, decisionCount = ?, acceptedDecisionCount = ?, rejectedDecisionCount = ?, message = ? WHERE sessionID = ?";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setString(1, cleanOrDefault(status, "COMPLETED"));
			pstmt.setString(2, LocalDateTime.now().format(DISPLAY_TIME_FORMAT));
			pstmt.setString(3, cleanOrDefault(lastBarTime, ""));
			pstmt.setInt(4, decisionCount);
			pstmt.setInt(5, acceptedCount);
			pstmt.setInt(6, rejectedCount);
			pstmt.setString(7, cleanOrDefault(message, ""));
			pstmt.setInt(8, sessionId);
			pstmt.executeUpdate();
		} catch (SQLException e) {
			e.printStackTrace();
		}
	}

	private static void insertLiveSignalDecision(int sessionId, int snapshotId, SignalEvent event, PortfolioPosition position, String status, String reason) {
		int contracts = position == null ? 0 : position.contracts;
		double entryPrice = position == null ? 0.0 : position.entryPrice;
		double stopPrice = position == null ? event.signal.stopPrice : position.stopPrice;
		double targetPrice = position == null ? event.signal.targetPrice : position.targetPrice;
		double miniUnits = position == null ? 0.0 : round(fundedMiniUnitsPerContract(position.symbol) * position.contracts);
		String signalTime = event.day + " " + event.entryTime;
		String entryTime = position == null ? signalTime : cleanOrDefault(position.openedAt, signalTime);
		insertLiveDecision(
			sessionId,
			snapshotId,
			event.symbol,
			event.signal.strategyCode,
			event.signal.strategyName,
			event.signal.side,
			signalTime,
			entryTime,
			contracts,
			entryPrice,
			stopPrice,
			targetPrice,
			miniUnits,
			status,
			reason,
			decisionPayloadJson(event, position, reason)
		);
	}

	private static void insertLiveExitDecision(int sessionId, int snapshotId, FuturesTrade trade, String status, String reason) {
		insertLiveExitDecision(sessionId, snapshotId, trade, status, reason, "");
	}

	private static void insertLiveExitDecision(int sessionId, int snapshotId, FuturesTrade trade, String status, String reason, String brokerCloseJson) {
		insertLiveDecision(
			sessionId,
			snapshotId,
			trade.symbol,
			trade.strategyCode,
			trade.strategyName,
			trade.side,
			trade.openedAt,
			trade.closedAt,
			trade.contracts,
			trade.entryPrice,
			trade.stopPrice,
			trade.targetPrice,
			round(fundedMiniUnitsPerContract(trade.symbol) * trade.contracts),
			status,
			reason,
			liveExitPayloadJson(trade, status, reason, brokerCloseJson)
		);
	}

	private static String liveExitPayloadJson(FuturesTrade trade, String status, String reason, String brokerCloseJson) {
		String brokerPayload = cleanOrDefault(brokerCloseJson, "").length() == 0
			? ""
			: ",\"brokerClose\":" + jsonObjectOrDefault(brokerCloseJson, "{}");
		String tradeReasonJson = liveExitTradeReasoningJson(trade, status, reason, brokerCloseJson);
			return "{"
				+ "\"openedAt\":" + jsonString(trade.openedAt) + ","
				+ "\"closedAt\":" + jsonString(trade.closedAt) + ","
				+ "\"sourceStrategyCode\":" + jsonString(cleanOrDefault(trade.sourceStrategyCode, "")) + ","
				+ "\"sourceStrategyName\":" + jsonString(cleanOrDefault(trade.sourceStrategyName, "")) + ","
				+ "\"entryPrice\":" + round(trade.entryPrice) + ","
				+ "\"exitPrice\":" + round(trade.exitPrice) + ","
				+ "\"pnl\":" + round(trade.pnl) + ","
				+ "\"finalLegPnl\":" + round(trade.finalLegPnl) + ","
				+ "\"dtmRealizedPnl\":" + round(trade.dtmRealizedPnl) + ","
				+ "\"dtmPartialContractsClosed\":" + trade.dtmPartialContractsClosed + ","
				+ "\"mfe\":" + round(trade.mfe) + ","
			+ "\"mae\":" + round(trade.mae) + ","
			+ "\"exitReason\":" + jsonString(trade.exitReason)
			+ ",\"tradeReason\":" + tradeReasonJson
			+ brokerPayload
			+ "}";
	}

	private static boolean updateLiveExitDecision(int sessionId, int snapshotId, FuturesTrade trade, String status, String reason, String brokerCloseJson) {
		if (trade == null) {
			return false;
		}
		String findSql = "SELECT decisionID FROM FuturesLiveSignalDecisions "
			+ "WHERE sessionID = ? AND snapshotID = ? AND symbol = ? AND strategyCode = ? AND signalTime = ? "
			+ "AND (status LIKE '%EXIT%' OR status LIKE '%CLOSED%' OR status LIKE '%FLAT%') "
			+ "ORDER BY decisionID DESC LIMIT 1";
		String updateSql = "UPDATE FuturesLiveSignalDecisions SET entryTime = ?, contracts = ?, entryPrice = ?, stopPrice = ?, targetPrice = ?, "
			+ "fundedMiniUnits = ?, status = ?, reason = ?, payloadJson = ?, createdAt = ? WHERE decisionID = ?";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement find = conn.prepareStatement(findSql)) {
			find.setInt(1, sessionId);
			find.setInt(2, snapshotId);
			find.setString(3, normalizeSymbol(trade.symbol));
			find.setString(4, cleanOrDefault(trade.strategyCode, ""));
			find.setString(5, cleanOrDefault(trade.openedAt, ""));
			try (ResultSet rs = find.executeQuery()) {
				if (!rs.next()) {
					return false;
				}
				int decisionId = rs.getInt("decisionID");
				try (PreparedStatement update = conn.prepareStatement(updateSql)) {
					update.setString(1, cleanOrDefault(trade.closedAt, ""));
					update.setInt(2, trade.contracts);
					update.setDouble(3, trade.entryPrice);
					update.setDouble(4, trade.stopPrice);
					update.setDouble(5, trade.targetPrice);
					update.setDouble(6, round(fundedMiniUnitsPerContract(trade.symbol) * trade.contracts));
					update.setString(7, cleanOrDefault(status, ""));
					update.setString(8, cleanOrDefault(reason, ""));
					update.setString(9, jsonObjectOrDefault(liveExitPayloadJson(trade, status, reason, brokerCloseJson), "{}"));
					update.setString(10, LocalDateTime.now().format(DISPLAY_TIME_FORMAT));
					update.setInt(11, decisionId);
					return update.executeUpdate() > 0;
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
			return false;
		}
	}

	private static String liveEntryTradeReasoningJson(
		String symbol,
		Signal signal,
		String side,
		int contracts,
		double entryPrice,
		double stopPrice,
		double targetPrice,
		double fundedMiniUnits,
		String status,
		String reason,
		String diagnosticsJson
	) {
		String cleanSymbol = normalizeSymbol(symbol);
		Signal safeSignal = signal == null ? signal("LIVE", "Live Strategy", cleanOrDefault(side, "LONG"), -1, entryPrice, stopPrice, targetPrice, 0, "") : signal;
		String strategyCode = cleanOrDefault(safeSignal.strategyCode, "LIVE");
		String strategyName = cleanOrDefault(safeSignal.strategyName, strategyCode);
		String cleanSide = cleanOrDefault(side, safeSignal.side).toUpperCase(Locale.US);
		String direction = "SHORT".equals(cleanSide) ? "short" : "long";
		InstrumentSpec spec = instrumentFor(cleanSymbol);
		double riskTicks = spec.tickSize <= 0.0 ? 0.0 : Math.abs(entryPrice - stopPrice) / spec.tickSize;
		double rewardTicks = spec.tickSize <= 0.0 ? 0.0 : Math.abs(targetPrice - entryPrice) / spec.tickSize;
		double diagnosticsRiskPerContract = jsonNumber(jsonObjectOrDefault(diagnosticsJson, "{}"), "riskPerContract", 0.0);
		double estimatedMaxLoss = diagnosticsRiskPerContract > 0.0
			? diagnosticsRiskPerContract * Math.max(0, contracts)
			: riskTicks * spec.tickValue * Math.max(0, contracts);
		double estimatedReward = rewardTicks * spec.tickValue * Math.max(0, contracts);
		double aggregateGuardBudget = jsonNumber(jsonObjectOrDefault(diagnosticsJson, "{}"), "aggregateGuardBudget", 0.0);
		boolean compressedRiskPlan = jsonBoolean(jsonObjectOrDefault(diagnosticsJson, "{}"), "compressedRiskPlan");
		String firstFailingRule = jsonText(jsonObjectOrDefault(diagnosticsJson, "{}"), "firstFailingRule", "");
		String orderFlowAction = jsonText(jsonObjectOrDefault(diagnosticsJson, "{}"), "orderFlowAction", "");
		String orderFlowReason = jsonText(jsonObjectOrDefault(diagnosticsJson, "{}"), "orderFlowReason", "");
		String orderFlowJson = jsonObjectForKey(jsonObjectOrDefault(diagnosticsJson, "{}"), "orderFlow");
		boolean accepted = statusAcceptsLiveTrade(status);
		FuturesLiveSession session = currentLiveSessionCopy();
		FundedRuleProfile profile = fundedRuleProfileFor(cleanOrDefault(session.fundedProfile, "CUSTOM"));
		String riskProfile = firstNonBlank(profile.name, session.fundedProfile, "selected Risk Config");
		String pattern = firstNonBlank(safeSignal.notes, liveStrategyPatternFor(strategyCode, direction));
		String invalidation = liveStrategyInvalidationText(cleanSide, stopPrice);
		String confirmation = "configured " + strategyCode + " filters passed; next-bar signal fired";
		if (orderFlowAction.length() > 0) {
			confirmation += "; " + liveReasonCodeText(orderFlowAction);
		}
		String riskCode = accepted
			? (compressedRiskPlan ? "RISK_CONTRACT_CAP_APPLIED" : "RISK_PORTFOLIO_APPROVED")
			: "RISK_REJECTED";
		String strategyText = strategyCode + " wanted a " + direction + " because " + compactReasonPhrase(pattern)
			+ ". Confirmations: " + confirmation
			+ ". Invalidation: " + compactReasonPhrase(invalidation) + ".";
		String riskText;
		String guardText = accepted ? "exposure, daily loss, trailing drawdown" : "not available";
		if (accepted) {
			String compressionText = compressedRiskPlan ? "; Adjust: stop compressed before sizing" : "";
			riskText = "Size: " + liveContractText(contracts)
				+ "; Entry: " + livePriceText(entryPrice)
				+ "; Stop: " + livePriceText(stopPrice)
				+ "; Target: " + livePriceText(targetPrice)
				+ "; Risk: " + liveNumberText(riskTicks) + "t / " + liveDollarText(estimatedMaxLoss)
				+ "; Guards: " + guardText + " passed"
				+ compressionText + ".";
		} else {
			riskText = "Status: rejected"
				+ (firstFailingRule.length() > 0 ? "; Rule: " + compactReasonPhrase(firstFailingRule) : "")
				+ "; Note: " + compactReasonPhrase(cleanOrDefault(reason, "Sizing details were not available."))
				+ ".";
		}
		return "{"
			+ "\"schemaVersion\":1,"
			+ "\"entryReasonText\":" + jsonString("Strategy: " + strategyText + " Risk: " + riskText) + ","
			+ "\"entry\":{"
					+ "\"strategyReasonCode\":" + jsonString(liveEntryReasonCode(strategyCode)) + ","
					+ "\"strategyCode\":" + jsonString(strategyCode) + ","
					+ "\"strategyName\":" + jsonString(strategyName) + ","
					+ "\"sourceStrategyCode\":" + jsonString(cleanOrDefault(safeSignal.sourceStrategyCode, "")) + ","
					+ "\"sourceStrategyName\":" + jsonString(cleanOrDefault(safeSignal.sourceStrategyName, "")) + ","
					+ "\"strategyThesis\":" + jsonString(pattern) + ","
				+ "\"strategyPattern\":" + jsonString(liveStrategyPatternFor(strategyCode, direction)) + ","
				+ "\"strategyConfirmations\":" + jsonString(confirmation) + ","
				+ "\"orderFlowAction\":" + jsonString(orderFlowAction) + ","
				+ "\"orderFlowReason\":" + jsonString(orderFlowReason) + ","
				+ "\"orderFlow\":" + jsonObjectOrDefault(orderFlowJson, "{}") + ","
				+ "\"strategyInvalidation\":" + jsonString(invalidation) + ","
				+ "\"strategyText\":" + jsonString(strategyText) + ","
				+ "\"riskReasonCode\":" + jsonString(riskCode) + ","
				+ "\"riskSizingExplanation\":" + jsonString(riskText) + ","
				+ "\"riskProfile\":" + jsonString(riskProfile) + ","
				+ "\"contracts\":" + contracts + ","
				+ "\"entryPrice\":" + round(entryPrice) + ","
				+ "\"initialStop\":" + round(stopPrice) + ","
				+ "\"initialTarget\":" + round(targetPrice) + ","
				+ "\"riskTicks\":" + round(riskTicks) + ","
				+ "\"estimatedMaxLoss\":" + round(estimatedMaxLoss) + ","
				+ "\"estimatedReward\":" + round(estimatedReward) + ","
				+ "\"fundedMiniUnits\":" + round(fundedMiniUnits) + ","
				+ "\"aggregateGuardBudget\":" + round(aggregateGuardBudget) + ","
				+ "\"sizingDiagnostics\":" + jsonObjectOrDefault(diagnosticsJson, "{}") + ","
				+ "\"limitingCap\":" + jsonString(jsonText(jsonObjectOrDefault(diagnosticsJson, "{}"), "limitingCap", "")) + ","
				+ "\"limitingCapLabel\":" + jsonString(jsonText(jsonObjectOrDefault(diagnosticsJson, "{}"), "limitingCapLabel", "")) + ","
				+ "\"portfolioGuardsPassed\":" + jsonString(guardText) + ","
				+ "\"compressedRiskPlan\":" + compressedRiskPlan
			+ "}"
		+ "}";
	}

	private static String liveExitTradeReasoningJson(FuturesTrade trade, String status, String reason, String brokerCloseJson) {
		FuturesTrade safeTrade = trade == null ? new FuturesTrade() : trade;
		String finalCode = liveExitReasonCode(status, safeTrade.exitReason, brokerCloseJson);
		String dtmAction = firstNonBlank(safeTrade.dtmFinalAction, liveDtmActionForExitReason(safeTrade.exitReason));
		String dtmSummary = liveDtmSummaryForTrade(safeTrade, dtmAction);
		String trigger = compactExitTrigger(firstNonBlank(safeTrade.exitReason, reason, "Close reason not available."), finalCode, safeTrade);
		String exitPriceText = safeTrade.exitPrice > 0.0 ? livePriceText(safeTrade.exitPrice) : "not available";
		String review = liveExitReview(safeTrade);
		String reviewFacts = liveExitReviewFactsJson(safeTrade, brokerCloseJson);
		String exitText = "DTM: " + dtmSummary
			+ " Exit: " + trigger
			+ "; Price: " + exitPriceText
			+ "; Contracts: " + liveContractText(safeTrade.contracts) + ".";
		if (review.length() > 0) {
			exitText += " Review: " + review;
		}
		return "{"
			+ "\"schemaVersion\":1,"
			+ "\"exitReasonText\":" + jsonString(exitText) + ","
			+ "\"exit\":{"
				+ "\"dtmSummary\":" + jsonString(dtmSummary) + ","
				+ "\"dtmDecisionTimeline\":" + jsonObjectOrDefault(safeTrade.dtmTimelineJson, "[]") + ","
				+ "\"dtmFinalAction\":" + jsonString(dtmAction) + ","
				+ "\"finalExitReasonCode\":" + jsonString(finalCode) + ","
				+ "\"finalExitTrigger\":" + jsonString(trigger) + ","
				+ "\"exitPrice\":" + round(safeTrade.exitPrice) + ","
				+ "\"exitContracts\":" + safeTrade.contracts + ","
				+ "\"exitReview\":" + jsonString(review) + ","
				+ "\"reviewFacts\":" + reviewFacts + ","
				+ "\"mfe\":" + round(safeTrade.mfe) + ","
				+ "\"mae\":" + round(safeTrade.mae) + ","
				+ "\"runnerDecision\":" + jsonString(firstNonBlank(safeTrade.dtmRunnerDecision, "not available")) + ","
				+ "\"partialDecision\":" + jsonString(firstNonBlank(safeTrade.dtmPartialDecision, "not available")) + ","
				+ "\"exitText\":" + jsonString(exitText)
			+ "}"
		+ "}";
	}

	private static String liveExitReviewFactsJson(FuturesTrade trade, String brokerCloseJson) {
		FuturesTrade safeTrade = trade == null ? new FuturesTrade() : trade;
		String broker = jsonObjectOrDefault(brokerCloseJson, "{}");
		boolean brokerAuthoritative = broker.contains("\"status\":\"FLAT_SYNC_TOPSTEPX\"")
			|| broker.contains("\"source\":\"TOPSTEPX")
			|| jsonBoolean(broker, "authoritative");
		double brokerExitPrice = jsonNumber(broker, "exitPrice", jsonNumber(broker, "fillPrice", 0.0));
		double brokerPnl = jsonNumber(broker, "pnl", 0.0);
		String priceSource = brokerAuthoritative && brokerExitPrice > 0.0 ? "BROKER_FILL" : "LOCAL_ESTIMATE";
		return "{"
			+ "\"priceSource\":" + jsonString(priceSource) + ","
			+ "\"finalRealizedPnlSource\":" + jsonString(brokerAuthoritative ? "BROKER_FILL" : "LOCAL_ESTIMATE") + ","
			+ "\"plannedEntryPrice\":" + round(safeTrade.entryPrice) + ","
			+ "\"plannedStopPrice\":" + round(safeTrade.stopPrice) + ","
			+ "\"plannedTargetPrice\":" + round(safeTrade.targetPrice) + ","
			+ "\"estimatedExitPrice\":" + round(safeTrade.exitPrice) + ","
			+ "\"brokerFillPrice\":" + round(brokerExitPrice > 0.0 ? brokerExitPrice : safeTrade.exitPrice) + ","
			+ "\"brokerRealizedPnl\":" + round(brokerPnl) + ","
			+ "\"finalRealizedPnl\":" + round(brokerAuthoritative && Math.abs(brokerPnl) > 0.0 ? brokerPnl : safeTrade.pnl) + ","
			+ "\"brokerClose\":" + broker
			+ "}";
	}

	private static boolean statusAcceptsLiveTrade(String status) {
		String normalized = cleanOrDefault(status, "").toUpperCase(Locale.US);
		return normalized.contains("SUBMITTED")
			|| normalized.contains("ACCEPTED")
			|| normalized.contains("LIVE_TOPSTEP")
			|| normalized.contains("TOPSTEPX");
	}

	private static String liveEntryReasonCode(String strategyCode) {
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		if ("ORB".equals(code)) return "ENTRY_ORB_BREAKOUT";
		if ("ORB2".equals(code)) return "ENTRY_ORB_RETEST";
		if ("ORBX".equals(code)) return "ENTRY_ORB_EVENT_PACK";
		if ("OMOM".equals(code)) return "ENTRY_OPENING_MOMENTUM";
		if ("LORB".equals(code)) return "ENTRY_LATE_ORB_CONTINUATION";
		if ("VWAP".equals(code)) return "ENTRY_VWAP_PULLBACK";
		if ("VRCL".equals(code)) return "ENTRY_VWAP_RECLAIM";
		if ("VPB".equals(code)) return "ENTRY_VALUE_AREA_RECLAIM";
		if ("SWEEP".equals(code) || "SWEEP2".equals(code)) return "ENTRY_LIQUIDITY_SWEEP";
		if ("PDB".equals(code)) return "ENTRY_PRIOR_DAY_BREAKOUT";
		if ("FVG".equals(code)) return "ENTRY_FAIR_VALUE_GAP";
		if ("IFVG".equals(code)) return "ENTRY_INVERSION_FAIR_VALUE_GAP";
		if ("AFT".equals(code)) return "ENTRY_AFTERNOON_CONTINUATION";
		if ("CMOM".equals(code)) return "ENTRY_CLOSE_MOMENTUM";
		if ("KELT".equals(code)) return "ENTRY_KELTNER_BREAKOUT";
		if ("KREV".equals(code) || "MRVWAP".equals(code)) return "ENTRY_KELTNER_REVERSION";
		if ("EIA".equals(code)) return "ENTRY_MCL_EIA_CONTINUATION";
		if ("COPEN".equals(code)) return "ENTRY_MCL_CRUDE_OPEN";
		if ("IDXCONF".equals(code)) return "ENTRY_MYM_INDEX_CONFIRMATION";
		if ("MYMORB2".equals(code)) return "ENTRY_MYM_ORB_RETEST";
		if ("MYMBR".equals(code)) return "ENTRY_MYM_BREADTH_CONFIRMATION";
		if ("MCLTC".equals(code)) return "ENTRY_MCL_TREND_CONTINUATION";
		if ("LIQREC".equals(code)) return "ENTRY_LIQUIDITY_RECLAIM";
		if ("VABS".equals(code)) return "ENTRY_VOLUME_ABSORPTION_REVERSAL";
		if ("OFLOW_EQ".equals(code)) return "ENTRY_ORDER_FLOW_EQUILIBRIUM";
		if (code.contains("OFLOW")) return "ENTRY_ORDER_FLOW_CONTINUATION";
		return "ENTRY_CONFIGURED_STRATEGY";
	}

	private static String liveStrategyPatternFor(String strategyCode, String direction) {
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		String dir = "short".equals(direction) ? "downside" : "upside";
		if ("ORB".equals(code)) return "the opening range broke in the trade direction after ORB filters passed.";
		if ("ORB2".equals(code)) return "the opening range breakout retested and held before continuation.";
		if ("ORBX".equals(code)) return "the 1-minute opening-range event pack detected a mined retest, reclaim, or continuation structure.";
		if ("OMOM".equals(code)) return "compressed opening momentum broke in the trade direction with volume/range filters aligned.";
		if ("LORB".equals(code)) return "opening-range structure stayed valid into a later continuation window.";
		if ("VWAP".equals(code)) return "a trend-side VWAP/EMA pullback held and resumed.";
		if ("VRCL".equals(code)) return "price reclaimed or rejected VWAP with continuation confirmation.";
		if ("VPB".equals(code)) return "the prior/session value-area reference held or rejected with confirmation.";
		if ("SWEEP".equals(code) || "SWEEP2".equals(code)) return "a prior-day liquidity sweep reclaimed and triggered continuation.";
		if ("PDB".equals(code)) return "a prior-day high/low breakout or retest continued.";
		if ("FVG".equals(code)) return "a fair-value-gap reclaim/retest setup triggered.";
		if ("IFVG".equals(code)) return "an inverted fair-value-gap retest triggered after a displacement through the prior gap.";
		if ("AFT".equals(code)) return "an afternoon local-range continuation setup triggered.";
		if ("CMOM".equals(code)) return "late-session momentum stayed aligned near the close.";
		if ("KELT".equals(code)) return "Keltner/ATR volatility expanded in the trade direction.";
		if ("KREV".equals(code)) return "a Keltner band stretch reclaimed into a mean-reversion setup.";
		if ("MRVWAP".equals(code)) return "price stretched away from VWAP and reverted toward fair value.";
		if ("MSCALP".equals(code)) return "a micro trend scalp setup aligned VWAP/EMA continuation filters.";
		if ("MIM".equals(code)) return "intraday futures momentum aligned with VWAP/EMA confirmation.";
		if ("IPB".equals(code)) return "an opening impulse pulled back and resumed in the original direction.";
		if ("RCB".equals(code)) return "a tight intraday range compressed and resolved with " + dir + " pressure.";
		if ("TLAD".equals(code)) return "a repeated trend-ladder pullback resumed with " + dir + " pressure.";
		if ("EIA".equals(code)) return "MCL broke and continued after the Wednesday inventory-release range.";
		if ("COPEN".equals(code)) return "MCL expanded from its crude-specific morning session range.";
		if ("IDXCONF".equals(code)) return "MYM confirmed trend-side continuation through VWAP, EMA, session-open, and range structure.";
		if ("MYMORB2".equals(code)) return "MYM retested the opening range after a confirmed break and resumed.";
		if ("MYMBR".equals(code)) return "MYM faded an index-breadth stretch after the Dow contract reached a structured breakout/breakdown zone.";
		if ("MCLTC".equals(code)) return "MCL faded an extended crude trend push after price stretched away from the session open with bounded reversal risk.";
		if ("LIQREC".equals(code)) return "a first-class Liquidity Reclaim source-stack setup triggered with reclaim structure and executable risk geometry.";
		if ("VABS".equals(code)) return "a high-volume absorption candle rejected an attempted sweep and the next candle reclaimed the failure level.";
		if ("OFLOW_EQ".equals(code)) return "order-flow equilibrium logic confirmed a dislocation reversion setup.";
		return "the configured strategy filters passed for " + dir + " expectancy.";
	}

	private static String liveStrategyInvalidationText(String side, double stopPrice) {
		if (stopPrice <= 0.0) {
			return "not available";
		}
		return "SHORT".equals(cleanOrDefault(side, "").toUpperCase(Locale.US))
			? "a reclaim through " + livePriceText(stopPrice)
			: "a break below " + livePriceText(stopPrice);
	}

	private static String liveExitReasonCode(String status, String exitReason, String brokerCloseJson) {
		String normalizedStatus = cleanOrDefault(status, "").toUpperCase(Locale.US);
		String normalizedReason = cleanOrDefault(exitReason, "").toUpperCase(Locale.US);
		String brokerCode = jsonText(jsonObjectOrDefault(brokerCloseJson, "{}"), "finalExitReasonCode", "");
		if (brokerCode.length() > 0) {
			return brokerCode;
		}
		if (normalizedReason.contains("TARGET")) return "EXIT_BROKER_TARGET_FILL";
		if (normalizedReason.contains("STOP")) return "EXIT_BROKER_STOP_FILL";
		if (normalizedReason.contains("ADAPTIVE LOSS")) return "DTM_CUT_EARLY_THESIS_FAILED";
		if (normalizedReason.contains("MANAGED STOP")) return "DTM_TRAIL_STOP";
		if (normalizedStatus.contains("FLAT_SYNC")) return "EXIT_BROKER_FLAT_SYNC";
		if (normalizedReason.contains("MANUAL")) return "EXIT_MANUAL_FLATTEN";
		if (jsonObjectOrDefault(brokerCloseJson, "{}").contains("\"status\":\"FLAT_SYNC_TOPSTEPX\"")) return "EXIT_BROKER_FLAT_SYNC";
		return "EXIT_UNMATCHED_BROKER_CLOSE";
	}

	private static String liveDtmActionForExitReason(String exitReason) {
		String normalized = cleanOrDefault(exitReason, "").toUpperCase(Locale.US);
		if (normalized.contains("ADAPTIVE LOSS")) return "DTM_CUT_EARLY_THESIS_FAILED";
		if (normalized.contains("MANAGED STOP")) return "DTM_TRAIL_STOP";
		return "DTM_NO_OVERRIDE";
	}

	private static String liveDtmSummaryForExit(String exitReason) {
		String normalized = cleanOrDefault(exitReason, "").toUpperCase(Locale.US);
		if (normalized.contains("ADAPTIVE LOSS")) {
			return "Early loss cut before the hard stop.";
		}
		if (normalized.contains("MANAGED STOP")) {
			return "Managed stop protected the trade after favorable movement.";
		}
		return "No DTM decisions.";
	}

	private static String liveDtmSummaryForTrade(FuturesTrade trade, String dtmAction) {
		FuturesTrade safeTrade = trade == null ? new FuturesTrade() : trade;
		List<String> timeline = jsonArrayObjects("{\"events\":" + jsonObjectOrDefault(safeTrade.dtmTimelineJson, "[]") + "}", "events");
		if (!timeline.isEmpty()) {
			String lastEvent = timeline.get(timeline.size() - 1);
			String actionCode = firstNonBlank(jsonText(lastEvent, "actionCode", ""), dtmAction);
			String reason = jsonText(lastEvent, "reason", "");
			String details = jsonObjectForKey(lastEvent, "details");
			double favorableR = jsonNumber(details, "favorableR", 0.0);
			double adverseR = jsonNumber(details, "adverseR", 0.0);
			StringBuilder summary = new StringBuilder();
			summary.append("DTM recorded ").append(liveReasonCodeText(actionCode));
			if (reason.length() > 0) {
				summary.append(": ").append(compactReasonPhrase(reason));
			}
			if (favorableR > 0.0 || adverseR > 0.0) {
				summary.append(" Movement: +").append(liveNumberText(favorableR)).append("R / -").append(liveNumberText(adverseR)).append("R.");
			}
			if (safeTrade.dtmPartialDecision != null && safeTrade.dtmPartialDecision.trim().length() > 0) {
				summary.append(" Partial: ").append(compactReasonPhrase(safeTrade.dtmPartialDecision)).append(".");
			}
			if (safeTrade.dtmRunnerDecision != null && safeTrade.dtmRunnerDecision.trim().length() > 0) {
				summary.append(" Runner: ").append(compactReasonPhrase(safeTrade.dtmRunnerDecision)).append(".");
			}
			return summary.toString();
		}
		return liveDtmSummaryForExit(safeTrade.exitReason);
	}

	private static String liveExitReview(FuturesTrade trade) {
		if (trade == null) {
			return "";
		}
		if (Math.abs(trade.mfe) <= 0.0 && Math.abs(trade.mae) <= 0.0) {
			return "";
		}
		return "MFE: " + liveDollarText(trade.mfe) + "; MAE: " + liveDollarText(trade.mae) + "; saved for DTM review.";
	}

	private static String compactExitTrigger(String value, String finalCode, FuturesTrade trade) {
		String cleaned = compactReasonPhrase(value);
		String prefix = liveExitHitPrefix(finalCode, trade, cleaned);
		String brokerPrefix = "Broker TP/SL fill reconciled from TopstepX Trade/search order ";
		if (cleaned.startsWith(brokerPrefix)) {
			return prefix + "broker TP/SL fill; order " + compactReasonPhrase(cleaned.substring(brokerPrefix.length()));
		}
		if ("Broker flat sync from TopstepX Position/searchOpen".equals(cleaned)) {
			return prefix + "broker flat sync; no open Topstep position";
		}
		if (cleaned.startsWith("Broker TP/SL fill; Topstep order ")) {
			return prefix + "broker TP/SL fill; order " + compactReasonPhrase(cleaned.substring("Broker TP/SL fill; Topstep order ".length()));
		}
		if (cleaned.startsWith("Broker flat sync; no open Topstep position")) {
			return prefix + "broker flat sync; no open Topstep position";
		}
		return prefix + cleaned;
	}

	private static String liveExitHitPrefix(String finalCode, FuturesTrade trade, String trigger) {
		String normalizedCode = cleanOrDefault(finalCode, "").toUpperCase(Locale.US);
		String normalizedTrigger = cleanOrDefault(trigger, "").toUpperCase(Locale.US);
		if (normalizedCode.contains("TARGET") || normalizedTrigger.contains("TARGET")) {
			return "target hit; ";
		}
		if (normalizedCode.contains("STOP") || normalizedTrigger.contains("STOP")) {
			return "stop hit; ";
		}
		if (trade != null && trade.exitPrice > 0.0) {
			InstrumentSpec spec = instrumentFor(trade.symbol);
			double tolerance = Math.max(spec.tickSize, 0.01) * 1.5;
			if (trade.targetPrice > 0.0 && Math.abs(trade.exitPrice - trade.targetPrice) <= tolerance) {
				return "target hit; ";
			}
			if (trade.stopPrice > 0.0 && Math.abs(trade.exitPrice - trade.stopPrice) <= tolerance) {
				return "stop hit; ";
			}
			if (normalizedTrigger.contains("TP/SL FILL") || normalizedTrigger.contains("BRACKET")) {
				if (trade.pnl > 0.0) {
					return "take-profit fill; ";
				}
				if (trade.pnl < 0.0) {
					return "stop-loss fill; ";
				}
			}
		}
		return "";
	}

	private static String compactReasonPhrase(String value) {
		String cleaned = cleanOrDefault(value, "").replaceAll("\\s+", " ").trim();
		while (cleaned.endsWith(".")) {
			cleaned = cleaned.substring(0, cleaned.length() - 1).trim();
		}
		return cleaned;
	}

	private static String liveReasonCodeText(String value) {
		return compactReasonPhrase(value).replace("_", " ").toLowerCase(Locale.US);
	}

	private static String liveContractText(int contracts) {
		return contracts + " contract" + (contracts == 1 ? "" : "s");
	}

	private static String lowerFirstSentence(String value) {
		String cleaned = cleanOrDefault(value, "");
		if (cleaned.length() == 0) {
			return "the configured setup triggered.";
		}
		String sentence = cleaned.endsWith(".") ? cleaned : cleaned + ".";
		return sentence.substring(0, 1).toLowerCase(Locale.US) + sentence.substring(1);
	}

	private static String livePriceText(double value) {
		if (value <= 0.0 || Double.isNaN(value) || Double.isInfinite(value)) {
			return "not available";
		}
		return String.format(Locale.US, "%.2f", round(value));
	}

	private static String liveNumberText(double value) {
		if (Double.isNaN(value) || Double.isInfinite(value) || value <= 0.0) {
			return "not available";
		}
		return String.format(Locale.US, "%.1f", round(value));
	}

	private static String liveDollarText(double value) {
		if (Double.isNaN(value) || Double.isInfinite(value)) {
			return "not available";
		}
		return "$" + String.format(Locale.US, "%.2f", Math.abs(round(value)));
	}

