	private static boolean insertLiveRiskEventOnce(int sessionId, int snapshotId, String eventType, String severity, String message, String payloadJson, String dedupeKey) {
		String cleanDedupeKey = cleanOrDefault(dedupeKey, "");
		if (cleanDedupeKey.length() == 0) {
			insertLiveRiskEvent(sessionId, snapshotId, eventType, severity, message, payloadJson);
			return true;
		}
		String existsSql = "SELECT 1 FROM FuturesLiveRiskEvents WHERE dedupeKey = ? LIMIT 1";
		String insertSql = "INSERT INTO FuturesLiveRiskEvents (sessionID, snapshotID, eventType, severity, message, payloadJson, createdAt, dedupeKey) VALUES (?, ?, ?, ?, ?, ?, ?, ?)";
		try (Connection conn = DatabaseManager.getConnection()) {
			try (PreparedStatement exists = conn.prepareStatement(existsSql)) {
				exists.setString(1, cleanDedupeKey);
				try (ResultSet rs = exists.executeQuery()) {
					if (rs.next()) {
						return false;
					}
				}
			}
			try (PreparedStatement pstmt = conn.prepareStatement(insertSql)) {
				pstmt.setInt(1, sessionId);
				pstmt.setInt(2, snapshotId);
				pstmt.setString(3, cleanOrDefault(eventType, "RISK"));
				pstmt.setString(4, cleanOrDefault(severity, "INFO"));
				pstmt.setString(5, cleanOrDefault(message, ""));
				pstmt.setString(6, jsonObjectOrDefault(payloadJson, "{}"));
				pstmt.setString(7, LocalDateTime.now().format(DISPLAY_TIME_FORMAT));
				pstmt.setString(8, cleanDedupeKey);
				pstmt.executeUpdate();
				return true;
			}
		} catch (SQLException e) {
			e.printStackTrace();
			return false;
		}
	}

