	private static LiveStrategySnapshotRow loadActiveLiveStrategySnapshot() {
		initializeStore();
		String sql = "SELECT * FROM FuturesLiveStrategySnapshots WHERE active = 1 ORDER BY snapshotID DESC LIMIT 1";
		try (Connection conn = DatabaseManager.getConnection();
			 Statement stmt = conn.createStatement();
			 ResultSet rs = stmt.executeQuery(sql)) {
			if (rs.next()) {
				return liveStrategySnapshotRow(rs);
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return null;
	}

	private static LiveStrategySnapshotRow liveStrategySnapshotRow(ResultSet rs) throws SQLException {
		LiveStrategySnapshotRow row = new LiveStrategySnapshotRow();
		row.snapshotId = rs.getInt("snapshotID");
		row.sourcePortfolioBacktestId = rs.getInt("sourcePortfolioBacktestID");
		if (rs.wasNull()) {
			row.sourcePortfolioBacktestId = 0;
		}
		row.symbols = cleanSymbolsCsv(rs.getString("symbols"));
		row.fundedProfile = cleanOrDefault(rs.getString("fundedProfile"), "CUSTOM");
		row.accountMode = cleanOrDefault(rs.getString("accountMode"), accountModeForFundedProfile(row.fundedProfile));
		row.practiceAccountId = cleanOrDefault(rs.getString("practiceAccountId"), accountIdForFundedProfile(row.fundedProfile));
		row.maxOpenPositions = rs.getInt("maxOpenPositions");
		row.maxAggregateContracts = rs.getInt("maxAggregateContracts");
		row.maxAggregateMiniUnits = rs.getDouble("maxAggregateMiniUnits");
		row.strategySettingsJson = rs.getString("strategySettingsJson");
		row.riskSettingsJson = rs.getString("riskSettingsJson");
		row.portfolioSettingsJson = rs.getString("portfolioSettingsJson");
		row.sourceMetricsJson = rs.getString("sourceMetricsJson");
		row.codeVersion = cleanOrDefault(rs.getString("codeVersion"), "local-worktree");
		row.createdAt = cleanOrDefault(rs.getString("createdAt"), "");
		row.updatedAt = cleanOrDefault(rs.getString("updatedAt"), "");
		return row;
	}

	private static String liveStrategySnapshotJson(LiveStrategySnapshotRow snapshot) {
		if (snapshot == null) {
			return "null";
		}
		String label = snapshot.sourcePortfolioBacktestId > 0
			? "Portfolio Backtest #" + snapshot.sourcePortfolioBacktestId
			: "Live Strategy Slot";
		String displaySlot = jsonText(snapshot.portfolioSettingsJson, "strategySlot", "");
		if (displaySlot.length() == 0) {
			displaySlot = strategyPresetSlot(visibleStrategyPresetName(jsonText(snapshot.portfolioSettingsJson, "strategyPreset", WINDOWED_94K_STRATEGY_PRESET)));
		}
		String settingsJson = strategySettingsBySymbolJson(snapshot.symbols, displaySlot);
		String riskJson = riskSettingsBySymbolJson(snapshot.symbols, displaySlot);
		return "{"
			+ "\"snapshotId\":" + snapshot.snapshotId + ","
			+ "\"sourcePortfolioBacktestId\":" + snapshot.sourcePortfolioBacktestId + ","
			+ "\"label\":" + jsonString(label) + ","
			+ "\"symbols\":" + jsonString(snapshot.symbols) + ","
			+ "\"symbolList\":" + jsonStringArray(parseSymbols(snapshot.symbols)) + ","
			+ "\"fundedProfile\":" + jsonString(snapshot.fundedProfile) + ","
			+ "\"accountMode\":" + jsonString(snapshot.accountMode) + ","
			+ "\"practiceAccountId\":" + jsonString(snapshot.practiceAccountId) + ","
			+ "\"maxOpenPositions\":" + snapshot.maxOpenPositions + ","
			+ "\"maxAggregateContracts\":" + snapshot.maxAggregateContracts + ","
			+ "\"maxAggregateMiniUnits\":" + round(snapshot.maxAggregateMiniUnits) + ","
			+ "\"strategySettings\":" + jsonObjectOrDefault(settingsJson, jsonObjectOrDefault(snapshot.strategySettingsJson, "{}")) + ","
			+ "\"riskSettings\":" + jsonObjectOrDefault(riskJson, jsonObjectOrDefault(snapshot.riskSettingsJson, "{}")) + ","
			+ "\"portfolioSettings\":" + jsonObjectOrDefault(snapshot.portfolioSettingsJson, "{}") + ","
			+ "\"sourceMetrics\":" + jsonObjectOrDefault(snapshot.sourceMetricsJson, "{}") + ","
			+ "\"codeVersion\":" + jsonString(snapshot.codeVersion) + ","
			+ "\"createdAt\":" + jsonString(snapshot.createdAt) + ","
			+ "\"updatedAt\":" + jsonString(snapshot.updatedAt)
			+ "}";
	}

	private static int recommendedLiveSnapshotSourceId() {
		int preferredId = parseInt(DEFAULT_LIVE_SNAPSHOT_SOURCE_ID, 242);
		if (portfolioBacktestExists(preferredId)) {
			return preferredId;
		}
		String sql = "SELECT portfolioBacktestID FROM FuturesPortfolioBacktests WHERE ruleViolation = 0 ORDER BY portfolioBacktestID DESC LIMIT 1";
		try (Connection conn = DatabaseManager.getConnection();
			 Statement stmt = conn.createStatement();
			 ResultSet rs = stmt.executeQuery(sql)) {
			if (rs.next()) {
				return rs.getInt(1);
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return 0;
	}

	private static boolean portfolioBacktestExists(int portfolioBacktestId) {
		String sql = "SELECT 1 FROM FuturesPortfolioBacktests WHERE portfolioBacktestID = ? LIMIT 1";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setInt(1, portfolioBacktestId);
			try (ResultSet rs = pstmt.executeQuery()) {
				return rs.next();
			}
		} catch (SQLException e) {
			e.printStackTrace();
			return false;
		}
	}

	private static void backfillActiveSnapshotPortfolioSettings() {
		String sql = "SELECT sourcePortfolioBacktestID, symbols FROM FuturesLiveStrategySnapshots WHERE active = 1 AND sourcePortfolioBacktestID IS NOT NULL ORDER BY snapshotID DESC LIMIT 1";
		try (Connection conn = DatabaseManager.getConnection();
			 Statement stmt = conn.createStatement();
			 ResultSet rs = stmt.executeQuery(sql)) {
			if (!rs.next()) {
				return;
			}
			int portfolioBacktestId = rs.getInt("sourcePortfolioBacktestID");
			if (portfolioBacktestId <= 0 || portfolioSettingRowCount(conn, portfolioBacktestId) > 0) {
				return;
			}
			capturePortfolioBacktestSettingRows(conn, portfolioBacktestId, parseSymbols(rs.getString("symbols")), STRATEGY_SLOT_BACKTEST);
		} catch (SQLException e) {
			e.printStackTrace();
		}
	}

	private static void capturePortfolioBacktestConfiguration(Connection conn, int portfolioBacktestId, PortfolioBacktestConfig config, PortfolioBacktestResult result) throws SQLException {
		if (portfolioBacktestId <= 0 || config == null) {
			return;
		}
		List<String> symbols = config.symbols == null ? new ArrayList<String>() : config.symbols;
		boolean copiedSourceSettings = false;
		if (config.sourcePortfolioBacktestId > 0 && portfolioSettingRowCount(conn, config.sourcePortfolioBacktestId) > 0) {
			copiedSourceSettings = copyPortfolioBacktestSettingRows(conn, config.sourcePortfolioBacktestId, portfolioBacktestId, symbols);
		}
		if (!copiedSourceSettings) {
			capturePortfolioBacktestSettingRows(conn, portfolioBacktestId, symbols, config.strategySlot);
		}
		normalizePortfolioBacktestRiskRowsForProfile(conn, portfolioBacktestId, symbols, config);
		String symbolsCsv = symbols.isEmpty() ? "" : String.join(",", symbols);
		String strategySettingsJson = strategySettingsBySymbolJson(symbolsCsv, config.strategySlot);
		String riskSettingsJson = riskSettingsBySymbolJson(symbolsCsv, config.strategySlot);
		String portfolioSettingsJson = portfolioSettingsJson(result, config);
		String codeVersion = "local-worktree-" + LocalDateTime.now().format(DISPLAY_TIME_FORMAT).replace(" ", "T");
		try (PreparedStatement update = conn.prepareStatement(
				"UPDATE FuturesPortfolioBacktests SET strategySettingsJson = ?, riskSettingsJson = ?, portfolioSettingsJson = ?, codeVersion = ? WHERE portfolioBacktestID = ?")) {
			update.setString(1, strategySettingsJson);
			update.setString(2, riskSettingsJson);
			update.setString(3, portfolioSettingsJson);
			update.setString(4, codeVersion);
			update.setInt(5, portfolioBacktestId);
			update.executeUpdate();
		}
	}

	private static boolean copyPortfolioBacktestSettingRows(Connection conn, int sourcePortfolioBacktestId, int targetPortfolioBacktestId, List<String> symbols) throws SQLException {
		if (sourcePortfolioBacktestId <= 0 || targetPortfolioBacktestId <= 0 || symbols == null || symbols.isEmpty()) {
			return false;
		}
		Map<String, String> rows = loadPortfolioBacktestSettingRows(conn, sourcePortfolioBacktestId, symbols);
		if (rows.isEmpty()) {
			return false;
		}
		try (PreparedStatement delete = conn.prepareStatement("DELETE FROM FuturesPortfolioBacktestSettings WHERE portfolioBacktestID = ?")) {
			delete.setInt(1, targetPortfolioBacktestId);
			delete.executeUpdate();
		}
		try (PreparedStatement insert = conn.prepareStatement("INSERT OR REPLACE INTO FuturesPortfolioBacktestSettings (portfolioBacktestID, settingKey, settingValue) VALUES (?, ?, ?)")) {
			for (Map.Entry<String, String> entry : rows.entrySet()) {
				insert.setInt(1, targetPortfolioBacktestId);
				insert.setString(2, entry.getKey());
				insert.setString(3, entry.getValue());
				insert.addBatch();
			}
			insert.executeBatch();
		}
		return true;
	}

	private static void capturePortfolioBacktestSettingRows(Connection conn, int portfolioBacktestId, List<String> symbols, String slot) throws SQLException {
		if (portfolioBacktestId <= 0 || symbols == null || symbols.isEmpty()) {
			return;
		}
		Map<String, String> rows = new TreeMap<String, String>();
		String normalizedSlot = normalizeStrategySlot(slot);
		for (int index = 0; index < symbols.size(); index++) {
			String symbol = normalizeSymbol(symbols.get(index));
			String fromPrefix = STRATEGY_SLOT_BACKTEST.equals(normalizedSlot)
				? symbol + "."
				: normalizedSlot + "." + symbol + ".";
			try (PreparedStatement select = conn.prepareStatement("SELECT settingKey, settingValue FROM FuturesStrategySettings WHERE settingKey LIKE ?")) {
				select.setString(1, fromPrefix + "%");
				try (ResultSet rs = select.executeQuery()) {
					while (rs.next()) {
						String unprefixed = rs.getString("settingKey").substring(fromPrefix.length());
						rows.put(symbol + "." + unprefixed, rs.getString("settingValue"));
					}
				}
			}
		}
		try (PreparedStatement delete = conn.prepareStatement("DELETE FROM FuturesPortfolioBacktestSettings WHERE portfolioBacktestID = ?")) {
			delete.setInt(1, portfolioBacktestId);
			delete.executeUpdate();
		}
		try (PreparedStatement insert = conn.prepareStatement("INSERT OR REPLACE INTO FuturesPortfolioBacktestSettings (portfolioBacktestID, settingKey, settingValue) VALUES (?, ?, ?)")) {
			for (Map.Entry<String, String> entry : rows.entrySet()) {
				insert.setInt(1, portfolioBacktestId);
				insert.setString(2, entry.getKey());
				insert.setString(3, entry.getValue());
				insert.addBatch();
			}
			insert.executeBatch();
		}
	}

	private static void normalizePortfolioBacktestRiskRowsForProfile(Connection conn, int portfolioBacktestId, List<String> symbols, PortfolioBacktestConfig config) throws SQLException {
		if (portfolioBacktestId <= 0 || symbols == null || symbols.isEmpty() || config == null || !scalesSavedSizingForProfile(config.fundedProfile)) {
			return;
		}
		FundedRuleProfile profile = fundedRuleProfileFor(config.fundedProfile);
		try (PreparedStatement upsert = conn.prepareStatement("INSERT OR REPLACE INTO FuturesPortfolioBacktestSettings (portfolioBacktestID, settingKey, settingValue) VALUES (?, ?, ?)")) {
			for (int index = 0; index < symbols.size(); index++) {
				String symbol = normalizeSymbol(symbols.get(index));
				FuturesRiskSettings sourceRisk = loadPortfolioBacktestRiskSettings(portfolioBacktestId, symbol);
				if (sourceRisk == null) {
					sourceRisk = loadFuturesRiskSettings(symbol, config.strategySlot);
				}
				double scale = savedSizingScale(sourceRisk, profile);
				double scaledRisk = Math.min(profile.maxRiskPerTrade, Math.max(1.0, sourceRisk.maxRiskPerTrade * scale));
				int scaledContracts = Math.min(
					Math.max(1, (int) Math.floor(Math.max(1.0, sourceRisk.maxContracts * scale))),
					profileMaxContractsForSymbol(profile, symbol)
				);
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.accountSize", round(profile.accountSize));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.maxTrailingDrawdown", round(profile.maxTrailingDrawdown));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.dailyLossLimit", round(profile.dailyLossLimit));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.maxRiskPerTrade", round(scaledRisk));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.maxContracts", scaledContracts);
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.commissionPerContract", round(config.commissionPerContract));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.slippageTicks", round(config.slippageTicks));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.profitTarget", round(profile.profitTarget));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.maxInitialRiskTicks", round(sourceRisk.maxInitialRiskTicks));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.orbCompressedMaxRiskTicks", round(sourceRisk.orbCompressedMaxRiskTicks));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.orbRetestMaxRiskTicks", round(sourceRisk.orbRetestMaxRiskTicks));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.openingMomentumMaxRiskTicks", round(sourceRisk.openingMomentumMaxRiskTicks));
				upsertPortfolioRiskSetting(upsert, portfolioBacktestId, symbol, "risk.lateOrbContinuationMaxRiskTicks", round(sourceRisk.lateOrbContinuationMaxRiskTicks));
			}
			upsert.executeBatch();
		}
	}

	private static void upsertPortfolioRiskSetting(PreparedStatement upsert, int portfolioBacktestId, String symbol, String key, double value) throws SQLException {
		upsert.setInt(1, portfolioBacktestId);
		upsert.setString(2, normalizeSymbol(symbol) + "." + key);
		upsert.setString(3, String.valueOf(value));
		upsert.addBatch();
	}

	private static void copyPortfolioBacktestSettingsToLiveSlot(Connection conn, int portfolioBacktestId, String symbols) throws SQLException {
		List<String> symbolList = parseSymbols(symbols);
		if (portfolioBacktestId <= 0 || symbolList.isEmpty()) {
			return;
		}
		if (portfolioSettingRowCount(conn, portfolioBacktestId) <= 0) {
			capturePortfolioBacktestSettingRows(conn, portfolioBacktestId, symbolList, STRATEGY_SLOT_BACKTEST);
		}
		Map<String, String> rows = loadPortfolioBacktestSettingRows(conn, portfolioBacktestId, symbolList);
		if (rows.isEmpty()) {
			throw new SQLException("Portfolio backtest #" + portfolioBacktestId + " has no captured strategy settings.");
		}
		for (int index = 0; index < symbolList.size(); index++) {
			String symbol = normalizeSymbol(symbolList.get(index));
			try (PreparedStatement delete = conn.prepareStatement("DELETE FROM FuturesStrategySettings WHERE settingKey LIKE ?")) {
				delete.setString(1, STRATEGY_SLOT_LIVE + "." + symbol + ".%");
				delete.executeUpdate();
			}
		}
		try (PreparedStatement insert = conn.prepareStatement("INSERT OR REPLACE INTO FuturesStrategySettings (settingKey, settingValue) VALUES (?, ?)")) {
			for (Map.Entry<String, String> entry : rows.entrySet()) {
				insert.setString(1, STRATEGY_SLOT_LIVE + "." + entry.getKey());
				insert.setString(2, entry.getValue());
				insert.addBatch();
			}
			insert.executeBatch();
		}
	}

	private static int portfolioSettingRowCount(Connection conn, int portfolioBacktestId) throws SQLException {
		try (PreparedStatement count = conn.prepareStatement("SELECT COUNT(*) FROM FuturesPortfolioBacktestSettings WHERE portfolioBacktestID = ?")) {
			count.setInt(1, portfolioBacktestId);
			try (ResultSet rs = count.executeQuery()) {
				return rs.next() ? rs.getInt(1) : 0;
			}
		}
	}

	private static Map<String, String> loadPortfolioBacktestSettingRows(Connection conn, int portfolioBacktestId, List<String> symbols) throws SQLException {
		Set<String> prefixes = new HashSet<String>();
		for (int index = 0; index < symbols.size(); index++) {
			prefixes.add(normalizeSymbol(symbols.get(index)) + ".");
		}
		Map<String, String> rows = new TreeMap<String, String>();
		try (PreparedStatement select = conn.prepareStatement("SELECT settingKey, settingValue FROM FuturesPortfolioBacktestSettings WHERE portfolioBacktestID = ?")) {
			select.setInt(1, portfolioBacktestId);
			try (ResultSet rs = select.executeQuery()) {
				while (rs.next()) {
					String key = rs.getString("settingKey");
					if (hasAnyPrefix(key, prefixes)) {
						rows.put(key, rs.getString("settingValue"));
					}
				}
			}
		}
		return rows;
	}

	private static FuturesStrategySettings loadPortfolioBacktestStrategySettings(int portfolioBacktestId, String symbol) {
		if (portfolioBacktestId <= 0) {
			return null;
		}
		initializeStore();
		String normalizedSymbol = normalizeSymbol(symbol);
		FuturesStrategySettings settings = defaultFuturesStrategySettings();
		boolean found = false;
		try (Connection conn = DatabaseManager.getConnection()) {
			Map<String, String> rows = loadPortfolioBacktestSettingRows(conn, portfolioBacktestId, java.util.Arrays.asList(normalizedSymbol));
			String prefix = normalizedSymbol + ".";
			for (Map.Entry<String, String> entry : rows.entrySet()) {
				if (!entry.getKey().startsWith(prefix)) {
					continue;
				}
				found = true;
				applyFuturesSetting(settings, entry.getKey().substring(prefix.length()), entry.getValue());
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		if (!found) {
			return null;
		}
		clampFuturesStrategySettings(settings);
		return settings;
	}

	private static FuturesRiskSettings loadPortfolioBacktestRiskSettings(int portfolioBacktestId, String symbol) {
		if (portfolioBacktestId <= 0) {
			return null;
		}
		initializeStore();
		String normalizedSymbol = normalizeSymbol(symbol);
		FuturesRiskSettings settings = defaultFuturesRiskSettings(normalizedSymbol);
		boolean found = false;
		try (Connection conn = DatabaseManager.getConnection()) {
			Map<String, String> rows = loadPortfolioBacktestSettingRows(conn, portfolioBacktestId, java.util.Arrays.asList(normalizedSymbol));
			String prefix = normalizedSymbol + ".";
			for (Map.Entry<String, String> entry : rows.entrySet()) {
				if (!entry.getKey().startsWith(prefix)) {
					continue;
				}
				found = true;
				applyFuturesRiskSetting(settings, entry.getKey().substring(prefix.length()), entry.getValue());
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		if (!found) {
			return null;
		}
		clampFuturesRiskSettings(settings);
		return settings;
	}

	private static Map<String, String> loadLiveSlotSettingRows(Connection conn, List<String> symbols) throws SQLException {
		Map<String, String> rows = new TreeMap<String, String>();
		for (int index = 0; index < symbols.size(); index++) {
			String symbol = normalizeSymbol(symbols.get(index));
			String prefix = STRATEGY_SLOT_LIVE + "." + symbol + ".";
			try (PreparedStatement select = conn.prepareStatement("SELECT settingKey, settingValue FROM FuturesStrategySettings WHERE settingKey LIKE ?")) {
				select.setString(1, prefix + "%");
				try (ResultSet rs = select.executeQuery()) {
					while (rs.next()) {
						rows.put(symbol + "." + rs.getString("settingKey").substring(prefix.length()), rs.getString("settingValue"));
					}
				}
			}
		}
		return rows;
	}

	private static boolean hasAnyPrefix(String value, Set<String> prefixes) {
		if (value == null || prefixes == null) {
			return false;
		}
		for (String prefix : prefixes) {
			if (value.startsWith(prefix)) {
				return true;
			}
		}
		return false;
	}

	private static String liveSnapshotIntegrityMessage(LiveStrategySnapshotRow snapshot) {
		if (snapshot == null || snapshot.sourcePortfolioBacktestId <= 0) {
			return "";
		}
		List<String> diffs = liveSnapshotSettingDifferences(snapshot, 3);
		if (diffs.isEmpty()) {
			return "";
		}
		return "Stored live preset snapshot does not match portfolio backtest #" + snapshot.sourcePortfolioBacktestId
			+ " (" + diffs.get(0) + "). Select and start from a Strategy Config preset instead.";
	}

	private static List<String> liveSnapshotSettingDifferences(LiveStrategySnapshotRow snapshot, int limit) {
		List<String> diffs = new ArrayList<String>();
		if (snapshot == null || snapshot.sourcePortfolioBacktestId <= 0) {
			return diffs;
		}
		List<String> symbols = parseSymbols(snapshot.symbols);
		if (symbols.isEmpty()) {
			diffs.add("snapshot has no symbols");
			return diffs;
		}
		try (Connection conn = DatabaseManager.getConnection()) {
			if (portfolioSettingRowCount(conn, snapshot.sourcePortfolioBacktestId) <= 0) {
				diffs.add("no captured settings are stored for the source run");
				return diffs;
			}
			Map<String, String> expected = loadPortfolioBacktestSettingRows(conn, snapshot.sourcePortfolioBacktestId, symbols);
			Map<String, String> actual = loadLiveSlotSettingRows(conn, symbols);
			for (Map.Entry<String, String> entry : expected.entrySet()) {
				if (!liveStrategyComparableSettingKey(entry.getKey())) {
					continue;
				}
				String actualValue = actual.get(entry.getKey());
				if (actualValue == null) {
					diffs.add(entry.getKey() + " missing from LIVE slot");
				} else if (!actualValue.equals(entry.getValue())) {
					diffs.add(entry.getKey() + " expected " + entry.getValue() + " but LIVE has " + actualValue);
				}
				if (diffs.size() >= limit) {
					return diffs;
				}
			}
			for (String key : actual.keySet()) {
				if (!liveStrategyComparableSettingKey(key)) {
					continue;
				}
				if (!expected.containsKey(key)) {
					diffs.add(key + " exists in LIVE slot but not in source run");
				}
				if (diffs.size() >= limit) {
					return diffs;
				}
			}
		} catch (SQLException e) {
			diffs.add("integrity query failed: " + cleanOrDefault(e.getMessage(), "unknown database error"));
		}
		return diffs;
	}

	private static boolean liveStrategyComparableSettingKey(String key) {
		String lower = cleanOrDefault(key, "").toLowerCase(Locale.US);
		return lower.length() > 0 && !lower.contains(".risk.");
	}

