	private static String cleanSymbolsCsv(String symbols) {
		List<String> symbolList = parseSymbols(symbols);
		StringBuilder value = new StringBuilder();
		for (int index = 0; index < symbolList.size(); index++) {
			if (index > 0) {
				value.append(",");
			}
			value.append(symbolList.get(index));
		}
		return value.toString();
	}

	private static boolean csvContainsSymbol(String symbols, String symbol) {
		String normalized = normalizeSymbol(symbol);
		List<String> symbolList = parseSymbols(symbols);
		return symbolList.contains(normalized);
	}

	private static boolean explicitCsvContainsSymbol(String symbols, String symbol) {
		if (symbols == null || symbols.trim().isEmpty()) {
			return false;
		}
		String normalized = normalizeSymbol(symbol);
		String[] parts = symbols.split(",");
		for (int index = 0; index < parts.length; index++) {
			if (normalized.equals(normalizeSymbol(parts[index]))) {
				return true;
			}
		}
		return false;
	}

	private static MarketSessionStatus currentMarketSessionStatus() {
		ZonedDateTime now = ZonedDateTime.now(NEW_YORK_ZONE);
		LocalDate date = now.toLocalDate();
		LocalTime time = now.toLocalTime();
		DayOfWeek day = now.getDayOfWeek();
		boolean weekday = day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY;
		String holidayName = weekday ? marketHolidayName(date) : "";
		boolean holiday = holidayName.length() > 0;
		boolean tradingDay = weekday && !holiday;
		MarketSessionStatus status = new MarketSessionStatus();
		status.tradingDay = tradingDay;
		status.holiday = holiday;
		status.rthOpen = tradingDay && !time.isBefore(RTH_START) && time.isBefore(RTH_END);
		status.entryWindowOpen = tradingDay && !time.isBefore(LIVE_ENTRY_WINDOW_START) && time.isBefore(LIVE_ENTRY_WINDOW_END);
		status.tradingEnabled = status.entryWindowOpen;
		status.closeGuard = tradingDay && !time.isBefore(LIVE_ENTRY_WINDOW_END) && time.isBefore(LIVE_CANCEL_RESTING_ORDERS_TIME);
		status.cancelRestingOrders = tradingDay && !time.isBefore(LIVE_CANCEL_RESTING_ORDERS_TIME) && time.isBefore(LIVE_FLATTEN_POSITIONS_TIME);
		status.flattenPositions = tradingDay && !time.isBefore(LIVE_FLATTEN_POSITIONS_TIME) && time.isBefore(LIVE_VERIFY_FLAT_TIME);
		status.verifyFlat = tradingDay && !time.isBefore(LIVE_VERIFY_FLAT_TIME) && time.isBefore(LIVE_FULLY_DISABLED_TIME);
		status.now = now.toLocalDateTime().format(DISPLAY_TIME_FORMAT);
		status.marketDate = date.toString();
		status.holidayName = holidayName;
		if (!weekday) {
			status.code = "WEEKEND_CLOSED";
			status.label = "Market Closed";
			status.detail = "Regular strategy session is closed for the weekend.";
			status.nextAction = "Wait for the next weekday regular session.";
		} else if (holiday) {
			status.code = "HOLIDAY_CLOSED";
			status.label = "Market Closed";
			status.detail = "Regular strategy session is closed for " + holidayName + ".";
			status.nextAction = "Wait for the next non-holiday regular session.";
		} else if (time.isBefore(LIVE_PREP_START)) {
			status.code = "OVERNIGHT_IDLE";
			status.label = "Market Closed";
			status.detail = "The backend may stay online overnight, but strategy entries are disabled until the NY session.";
			status.nextAction = "Start bot prep at 9:00 AM ET.";
		} else if (time.isBefore(LIVE_DATA_CONNECT_START)) {
			status.code = "BOT_PREP";
			status.label = "Bot Prep";
			status.detail = "Load live config and keep trading disabled.";
			status.nextAction = "Connect ProjectX streams at 9:15 AM ET.";
		} else if (time.isBefore(LIVE_DATA_VERIFY_START)) {
			status.code = "DATA_CONNECT";
			status.label = "Data Connect";
			status.detail = "Authenticate and connect user, order, position, quote, and trade streams while entries stay disabled.";
			status.nextAction = "Verify fresh market data at 9:25 AM ET.";
		} else if (time.isBefore(RTH_START)) {
			status.code = "PREMARKET_WAIT";
			status.label = "Pre-Market";
			status.detail = "Fresh market data and flat account checks should pass before the regular session opens.";
			status.nextAction = "Keep entries disabled until 9:35 AM ET.";
		} else if (time.isBefore(LIVE_ENTRY_WINDOW_START)) {
			status.code = "RTH_ARMING";
			status.label = "Market Open";
			status.detail = "Regular session is open, but new entries stay disabled for the first five minutes.";
			status.nextAction = "Enable entries at 9:35 AM ET if health checks pass.";
		} else if (time.isBefore(LIVE_ENTRY_WINDOW_END)) {
			status.code = "RTH_OPEN";
			status.label = "Market Open";
			status.detail = "Strategy entries are enabled only while live data and risk checks pass.";
			status.nextAction = "Analyze live candles.";
		} else if (time.isBefore(LIVE_CANCEL_RESTING_ORDERS_TIME)) {
			status.code = "CLOSING_GUARD";
			status.label = "Closing Guard";
			status.detail = "New entries are blocked ahead of the close.";
			status.nextAction = "Block new entries.";
		} else if (time.isBefore(LIVE_FLATTEN_POSITIONS_TIME)) {
			status.code = "CANCEL_RESTING_ORDERS";
			status.label = "Cancel Orders";
			status.detail = "Resting entry orders should be canceled while protective orders are preserved.";
			status.nextAction = "Cancel stale entry orders.";
		} else if (time.isBefore(LIVE_VERIFY_FLAT_TIME)) {
			status.code = "FLATTEN_WINDOW";
			status.label = "Flatten Window";
			status.detail = "Open positions should be flattened and remaining orders canceled.";
			status.nextAction = "Flatten open positions.";
		} else if (time.isBefore(LIVE_FULLY_DISABLED_TIME)) {
			status.code = "POST_CLOSE_VERIFY";
			status.label = "Verify Flat";
			status.detail = "Verify the account is flat and no open orders remain.";
			status.nextAction = "Verify flat account state.";
		} else {
			status.code = "RTH_CLOSED";
			status.label = "Market Closed";
			status.detail = "Trading is fully disabled after the regular-session close sequence.";
			status.nextAction = "Wait for the next regular session.";
		}
		return status;
	}

	private static boolean isLiveEntryWindowTime(LocalTime time) {
		return time != null && !time.isBefore(LIVE_ENTRY_WINDOW_START) && time.isBefore(LIVE_ENTRY_WINDOW_END);
	}

