	private static String marketHolidayName(LocalDate date) {
		if (date == null) {
			return "";
		}
		Map<LocalDate, String> holidays = new HashMap<LocalDate, String>();
		for (int year = date.getYear() - 1; year <= date.getYear() + 1; year++) {
			addMarketHoliday(holidays, observedFixedHoliday(year, Month.JANUARY, 1), "New Year's Day");
			addMarketHoliday(holidays, nthWeekday(year, Month.JANUARY, DayOfWeek.MONDAY, 3), "Martin Luther King Jr. Day");
			addMarketHoliday(holidays, nthWeekday(year, Month.FEBRUARY, DayOfWeek.MONDAY, 3), "Presidents' Day");
			addMarketHoliday(holidays, easterSunday(year).minusDays(2), "Good Friday");
			addMarketHoliday(holidays, lastWeekday(year, Month.MAY, DayOfWeek.MONDAY), "Memorial Day");
			if (year >= 2022) {
				addMarketHoliday(holidays, observedFixedHoliday(year, Month.JUNE, 19), "Juneteenth");
			}
			addMarketHoliday(holidays, observedFixedHoliday(year, Month.JULY, 4), "Independence Day");
			addMarketHoliday(holidays, nthWeekday(year, Month.SEPTEMBER, DayOfWeek.MONDAY, 1), "Labor Day");
			addMarketHoliday(holidays, nthWeekday(year, Month.NOVEMBER, DayOfWeek.THURSDAY, 4), "Thanksgiving Day");
			addMarketHoliday(holidays, observedFixedHoliday(year, Month.DECEMBER, 25), "Christmas Day");
		}
		return cleanOrDefault(holidays.get(date), "");
	}

	private static void addMarketHoliday(Map<LocalDate, String> holidays, LocalDate date, String name) {
		if (date != null) {
			holidays.put(date, name);
		}
	}

	private static LocalDate observedFixedHoliday(int year, Month month, int day) {
		LocalDate date = LocalDate.of(year, month, day);
		if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
			return date.minusDays(1);
		}
		if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
			return date.plusDays(1);
		}
		return date;
	}

	private static LocalDate nthWeekday(int year, Month month, DayOfWeek dayOfWeek, int nth) {
		return LocalDate.of(year, month, 1)
			.with(TemporalAdjusters.dayOfWeekInMonth(nth, dayOfWeek));
	}

	private static LocalDate lastWeekday(int year, Month month, DayOfWeek dayOfWeek) {
		return LocalDate.of(year, month, 1)
			.with(TemporalAdjusters.lastInMonth(dayOfWeek));
	}

	private static LocalDate easterSunday(int year) {
		int a = year % 19;
		int b = year / 100;
		int c = year % 100;
		int d = b / 4;
		int e = b % 4;
		int f = (b + 8) / 25;
		int g = (b - f + 1) / 3;
		int h = (19 * a + b - d - g + 15) % 30;
		int i = c / 4;
		int k = c % 4;
		int l = (32 + 2 * e + 2 * i - h - k) % 7;
		int m = (a + 11 * h + 22 * l) / 451;
		int month = (h + l - 7 * m + 114) / 31;
		int day = ((h + l - 7 * m + 114) % 31) + 1;
		return LocalDate.of(year, month, day);
	}

	private static String normalizeOrderSide(String side) {
		if (side == null) {
			return "";
		}
		String normalized = side.trim().toUpperCase();
		if ("LONG".equals(normalized) || "BUY".equals(normalized)) {
			return "BUY";
		}
		if ("SHORT".equals(normalized) || "SELL".equals(normalized)) {
			return "SELL";
		}
		return "";
	}

	private static int insertLiveOrderLedger(
		int snapshotId,
		String accountId,
		String symbol,
		String side,
		String orderType,
		int contracts,
		double entryPrice,
		double stopPrice,
		double targetPrice,
		String status,
		String requestJson,
		String responseJson,
		String createdAt
	) {
		String cleanStrategyCode = firstNonBlank(jsonText(requestJson, "strategyCode", ""), strategyCodeFromOrderReason(jsonText(requestJson, "reason", "")));
		String cleanStrategyName = firstNonBlank(jsonText(requestJson, "strategyName", ""), liveStrategyNameForCode(cleanStrategyCode));
		String cleanBrokerOrderId = brokerOrderIdFromJson(responseJson);
		String cleanCustomTag = jsonText(requestJson, "customTag", "");
		String cleanSignalTime = jsonText(requestJson, "signalTime", "");
		String cleanEntryTime = firstNonBlank(jsonText(requestJson, "entryTime", ""), createdAt);
		String sql = "INSERT INTO FuturesLiveOrderLedger (snapshotID, accountId, symbol, side, orderType, contracts, entryPrice, stopPrice, targetPrice, status, requestJson, responseJson, strategyCode, strategyName, brokerOrderId, customTag, signalTime, entryTime, createdAt, updatedAt) "
			+ "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
			pstmt.setInt(1, snapshotId);
			pstmt.setString(2, cleanOrDefault(accountId, ""));
			pstmt.setString(3, symbol);
			pstmt.setString(4, side);
			pstmt.setString(5, orderType);
			pstmt.setInt(6, contracts);
			pstmt.setDouble(7, entryPrice);
			pstmt.setDouble(8, stopPrice);
			pstmt.setDouble(9, targetPrice);
			pstmt.setString(10, status);
			pstmt.setString(11, requestJson);
			pstmt.setString(12, responseJson);
			pstmt.setString(13, cleanStrategyCode);
			pstmt.setString(14, cleanStrategyName);
			pstmt.setString(15, cleanBrokerOrderId);
			pstmt.setString(16, cleanCustomTag);
			pstmt.setString(17, cleanSignalTime);
			pstmt.setString(18, cleanEntryTime);
			pstmt.setString(19, createdAt);
			pstmt.setString(20, createdAt);
			pstmt.executeUpdate();
			try (ResultSet keys = pstmt.getGeneratedKeys()) {
				return keys.next() ? keys.getInt(1) : -1;
			}
		} catch (SQLException e) {
			e.printStackTrace();
			return -1;
		}
	}

	private static void recordLiveAudit(String eventType, String severity, String message, String payloadJson) {
		String sql = "INSERT INTO FuturesLiveAuditLog (eventType, severity, message, payloadJson, createdAt) VALUES (?, ?, ?, ?, ?)";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setString(1, cleanOrDefault(eventType, "EVENT"));
			pstmt.setString(2, cleanOrDefault(severity, "INFO"));
			pstmt.setString(3, cleanOrDefault(message, ""));
			pstmt.setString(4, jsonObjectOrDefault(payloadJson, "{}"));
			pstmt.setString(5, LocalDateTime.now().format(DISPLAY_TIME_FORMAT));
			pstmt.executeUpdate();
		} catch (SQLException e) {
			e.printStackTrace();
		}
	}

	private static synchronized void startLiveAutomationLoop() {
		if (liveAutomationTask != null && !liveAutomationTask.isDone()) {
			return;
		}
		liveAutomationTask = LIVE_AUTOMATION_EXECUTOR.scheduleWithFixedDelay(new Runnable() {
			@Override
			public void run() {
				try {
					runLiveRealtimeCycle();
				} catch (Exception e) {
					e.printStackTrace();
					synchronized (FuturesManager.class) {
						liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
						liveSession.lastDecision = "Live automation cycle failed: " + cleanOrDefault(e.getMessage(), "unknown error");
					}
					recordLiveAudit("LIVE_AUTOMATION_ERROR", "ERROR", "Live automation cycle failed.", "{\"error\":" + jsonString(cleanOrDefault(e.getMessage(), "")) + "}");
				}
			}
		}, LIVE_AUTOMATION_INITIAL_DELAY_SECONDS, LIVE_AUTOMATION_CYCLE_DELAY_SECONDS, TimeUnit.SECONDS);
	}

	private static synchronized void stopLiveAutomationLoop() {
		if (liveAutomationTask != null) {
			liveAutomationTask.cancel(false);
			liveAutomationTask = null;
		}
	}

