	private static double liveSelectedAccountSize(String accountId, String profileCode, String symbols, double fallbackAccountSize) {
		String cleanAccountId = cleanOrDefault(accountId, "");
		double brokerFallback = accountSizeForBrokerProfile(cleanAccountId, profileCode, fallbackAccountSize);
		if (cleanAccountId.length() == 0) {
			return positiveOrDefault(brokerFallback, fallbackAccountSize);
		}
		String brokerMetricsJson = FuturesConnectionManager.getTopstepxAccountMetrics(
			cleanAccountId,
			cleanSymbolsCsv(symbols),
			brokerFallback,
			3
		);
		if (jsonBoolean(brokerMetricsJson, "success")) {
			LiveRuntimeState.updateBrokerMetricsJson(brokerMetricsJson);
			double brokerBalance = jsonFirstNumber(brokerMetricsJson, new String[] { "riskCurrentBalance", "equityBalance", "currentBalance", "balance", "cashBalance" }, Double.NaN);
			if (!Double.isNaN(brokerBalance) && brokerBalance > 0.0) {
				return brokerBalance;
			}
			double brokerAccountSize = jsonFirstNumber(brokerMetricsJson, new String[] { "accountSize" }, Double.NaN);
			if (!Double.isNaN(brokerAccountSize) && brokerAccountSize > 0.0) {
				return brokerAccountSize;
			}
		}
		return positiveOrDefault(brokerFallback, fallbackAccountSize);
	}

	private static LiveAccountSizing liveAccountSizingFor(FuturesLiveSession session, LiveStrategySnapshotRow snapshot) {
		LiveAccountSizing sizing = new LiveAccountSizing();
		String profileCode = cleanOrDefault(session == null ? "" : session.fundedProfile, "");
		if (profileCode.length() == 0) {
			profileCode = snapshot == null ? TOPSTEPX_DEFAULT_LIVE_PROFILE : snapshot.fundedProfile;
		}
		sizing.profile = fundedRuleProfileFor(profileCode);
		sizing.accountId = selectedTopstepAccountId(snapshot, sizing.profile.code);
		double configuredAccountSize = positiveOrDefault(session == null ? 0.0 : session.accountSize, sizing.profile.accountSize);
		if (isTopstep50KProfile(sizing.profile.code)) {
			configuredAccountSize = sizing.profile.accountSize;
		}
		double configuredDrawdown = positiveOrDefault(session == null ? 0.0 : session.maxTrailingDrawdown, sizing.profile.maxTrailingDrawdown);
		double configuredDailyLossLimit = positiveOrDefault(session == null ? 0.0 : session.dailyLossLimit, sizing.profile.dailyLossLimit);
		double configuredMaxRisk = Math.min(
			positiveOrDefault(session == null ? 0.0 : session.maxRiskPerTrade, sizing.profile.maxRiskPerTrade),
			positiveOrDefault(sizing.profile.maxRiskPerTrade, session == null ? 0.0 : session.maxRiskPerTrade)
		);
		double profileSize = Math.max(1.0, configuredAccountSize);
		double fallbackBalance = positiveOrDefault(session == null ? 0.0 : session.accountSize, profileSize);
		sizing.currentBalance = fallbackBalance;
		if (sizing.accountId.length() > 0) {
			String symbols = activeLiveSymbols(session, snapshot);
			String brokerMetricsJson = FuturesConnectionManager.getTopstepxAccountMetrics(sizing.accountId, symbols, profileSize, 3);
			if (brokerMetricsJson.contains("\"success\":true")) {
				LiveRuntimeState.updateBrokerMetricsJson(brokerMetricsJson);
				if (session != null && session.sessionId > 0 && snapshot != null) {
					reconcileBrokerFlatLiveEntries(session.sessionId, snapshot.snapshotId, brokerMetricsJson);
				}
				double brokerBalance = jsonFirstNumber(brokerMetricsJson, new String[] { "riskCurrentBalance", "equityBalance", "currentBalance", "balance", "cashBalance" }, Double.NaN);
				if (!Double.isNaN(brokerBalance) && brokerBalance > 0.0) {
					sizing.currentBalance = brokerBalance;
				}
				sizing.dayStartBalance = brokerDayStartBalanceForLiveRisk(brokerMetricsJson, sizing.currentBalance, LocalDate.now(NEW_YORK_ZONE));
			}
		}
		if (sizing.dayStartBalance <= 0.0) {
			sizing.dayStartBalance = sizing.currentBalance;
		}
		double drawdownFloor = Math.max(profileSize - configuredDrawdown, Math.min(profileSize, sizing.currentBalance - configuredDrawdown));
		sizing.trailingCushion = Math.max(0.0, sizing.currentBalance - drawdownFloor);
		double baseCushion = Math.max(1.0, configuredDrawdown);
		double rawRatio = sizing.trailingCushion / baseCushion;
		sizing.sizingRatio = clamp(rawRatio, 0.25, Math.max(1.0, configuredDailyLossLimit / Math.max(1.0, configuredMaxRisk)));
		double dailyRiskCap = Math.max(1.0, Math.abs(configuredDailyLossLimit) * 0.70);
		sizing.maxRiskPerTrade = Math.min(dailyRiskCap, Math.max(1.0, configuredMaxRisk * sizing.sizingRatio));
		sizing.maxContracts = Math.max(1, session == null || session.maxContracts <= 0 ? sizing.profile.maxMicroContracts : session.maxContracts);
		sizing.maxOpenPositions = Math.max(1, session == null || session.maxOpenPositions <= 0 ? sizing.profile.maxOpenPositions : session.maxOpenPositions);
		sizing.maxAggregateContracts = Math.max(1, session == null || session.maxAggregateContracts <= 0 ? sizing.profile.maxAggregateContracts : session.maxAggregateContracts);
		double configuredMiniUnits = positiveOrDefault(session == null ? 0.0 : session.maxAggregateMiniUnits, sizing.profile.maxAggregateMiniUnits);
		double scaledMiniUnits = configuredMiniUnits * Math.min(1.0, sizing.sizingRatio);
		sizing.maxAggregateMiniUnits = clamp(scaledMiniUnits, 0.1, Math.max(0.1, configuredMiniUnits));
		return sizing;
	}

	private static void applyLiveAccountSizingToPortfolioConfig(PortfolioBacktestConfig portfolioConfig, FuturesLiveSession session, LiveAccountSizing accountSizing) {
		if (portfolioConfig == null || accountSizing == null) {
			return;
		}
		double configuredAccountSize = positiveOrDefault(session == null ? 0.0 : session.accountSize, portfolioConfig.accountSize);
		if (isTopstep50KProfile(portfolioConfig.fundedProfile)) {
			configuredAccountSize = fundedRuleProfileFor(portfolioConfig.fundedProfile).accountSize;
		}
		portfolioConfig.accountSize = positiveOrDefault(configuredAccountSize, portfolioConfig.accountSize);
		portfolioConfig.dayStartBalance = positiveOrDefault(accountSizing.dayStartBalance, portfolioConfig.accountSize);
		portfolioConfig.currentBalance = positiveOrDefault(accountSizing.currentBalance, portfolioConfig.accountSize);
		portfolioConfig.maxTrailingDrawdown = positiveOrDefault(session == null ? 0.0 : session.maxTrailingDrawdown, portfolioConfig.maxTrailingDrawdown);
		portfolioConfig.dailyLossLimit = positiveOrDefault(session == null ? 0.0 : session.dailyLossLimit, portfolioConfig.dailyLossLimit);
		portfolioConfig.maxRiskPerTrade = positiveOrDefault(accountSizing.maxRiskPerTrade, portfolioConfig.maxRiskPerTrade);
		portfolioConfig.maxContracts = Math.max(1, accountSizing.maxContracts);
		portfolioConfig.maxOpenPositions = Math.max(1, accountSizing.maxOpenPositions);
		portfolioConfig.maxAggregateContracts = Math.max(1, accountSizing.maxAggregateContracts);
		portfolioConfig.maxAggregateMiniUnits = accountSizing.maxAggregateMiniUnits;
	}

	static double brokerDayStartBalanceForLiveRiskForTest(String brokerMetricsJson, double currentBalance, LocalDate marketDate) {
		return brokerDayStartBalanceForLiveRisk(brokerMetricsJson, currentBalance, marketDate);
	}

	private static double brokerDayStartBalanceForLiveRisk(String brokerMetricsJson, double currentBalance, LocalDate marketDate) {
		if (currentBalance <= 0.0 || marketDate == null || !jsonBoolean(brokerMetricsJson, "success")) {
			return currentBalance;
		}
		double currentDayClosedPnl = 0.0;
		List<String> trades = jsonArrayObjects(brokerMetricsJson, "trades");
		for (int index = 0; index < trades.size(); index++) {
			String trade = trades.get(index);
			if (!jsonBoolean(trade, "closed")) {
				continue;
			}
			ZonedDateTime tradeTime = parseMarketTimestamp(firstNonBlank(jsonText(trade, "createdAt", ""), jsonText(trade, "closedAt", "")));
			if (tradeTime == null || !marketDate.equals(tradeTime.toLocalDate())) {
				continue;
			}
			currentDayClosedPnl += jsonNumber(trade, "pnl", 0.0);
		}
		return round(currentBalance - currentDayClosedPnl);
	}

	private static boolean ensureTopstepxRealtimeFeedFresh(FuturesLiveSession session, LiveStrategySnapshotRow snapshot) {
		MarketFeedFreshness feed = currentMarketFeedFreshness();
		recordLiveMarketDataTransition(session, feed);
		if (feed.fresh || feed.warming) {
			return true;
		}
		String message = "Market data stopped; live bot remains running and will resume strategy evaluation after fresh ProjectX events return.";
		synchronized (FuturesManager.class) {
			liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
			liveSession.lastDecision = message;
		}
		updateLiveEngineSession(session.sessionId, "RUNNING", session.lastBarTime, session.decisionCount, session.acceptedDecisionCount, session.rejectedDecisionCount, message);
		return false;
	}

	private static MarketFeedFreshness currentMarketFeedFreshness() {
		MarketFeedFreshness feed = new MarketFeedFreshness();
		feed.running = ProjectXRealtimeManager.isRunning();
		feed.lastMarketEventAt = LiveRuntimeState.currentLatestMarketEventAt();
		feed.eventAgeSeconds = secondsSinceDisplayTime(feed.lastMarketEventAt);
		feed.startedAgeSeconds = secondsSinceDisplayTime(ProjectXRealtimeManager.currentStartedAt());
		feed.staleSeconds = feed.eventAgeSeconds >= 0L ? feed.eventAgeSeconds : feed.startedAgeSeconds;
		feed.fresh = feed.running && feed.eventAgeSeconds >= 0L && feed.eventAgeSeconds <= LIVE_REALTIME_FRESH_SECONDS;
		feed.warming = feed.running && feed.eventAgeSeconds < 0L && feed.startedAgeSeconds >= 0L && feed.startedAgeSeconds <= LIVE_REALTIME_FRESH_SECONDS;
		if (!feed.running) {
			feed.reason = "ProjectX realtime feed is disconnected.";
		} else if (feed.eventAgeSeconds >= 0L) {
			feed.reason = "ProjectX market data feed is stale (" + feed.eventAgeSeconds + " seconds since last market event).";
		} else {
			feed.reason = "ProjectX market data feed has not delivered a market event since realtime start.";
		}
		return feed;
	}

	private static void recordLiveMarketDataTransition(FuturesLiveSession session, MarketFeedFreshness feed) {
		if (session == null || session.sessionId <= 0 || feed == null) {
			return;
		}
		if (feed.fresh) {
			String stoppedAt;
			String stoppedLastEventAt;
			boolean shouldLogResume = false;
			String resumedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
			synchronized (FuturesManager.class) {
				if (liveMarketDataStoppedActive) {
					shouldLogResume = true;
					stoppedAt = liveMarketDataStoppedDetectedAt;
					stoppedLastEventAt = liveMarketDataStoppedLastEventAt;
					liveMarketDataStoppedActive = false;
					liveMarketDataStoppedDetectedAt = "";
					liveMarketDataStoppedLastEventAt = "";
				} else {
					stoppedAt = "";
					stoppedLastEventAt = "";
				}
			}
			if (shouldLogResume) {
				long detectedDowntimeSeconds = secondsBetweenDisplayTimes(stoppedAt, resumedAt);
				long marketEventGapSeconds = secondsBetweenDisplayTimes(stoppedLastEventAt, feed.lastMarketEventAt);
				String message = "Market data resumed; live bot will resume strategy evaluation on fresh ProjectX events.";
				String payload = "{"
					+ "\"stoppedDetectedAt\":" + jsonString(stoppedAt) + ","
					+ "\"resumedAt\":" + jsonString(resumedAt) + ","
					+ "\"lastStoppedMarketEventAt\":" + jsonString(stoppedLastEventAt) + ","
					+ "\"resumeMarketEventAt\":" + jsonString(feed.lastMarketEventAt) + ","
					+ "\"detectedDowntimeSeconds\":" + detectedDowntimeSeconds + ","
					+ "\"marketEventGapSeconds\":" + marketEventGapSeconds
					+ "}";
				recordLiveAudit("MARKET_DATA_RESUMED", "INFO", message, payload);
				pushLiveEvent(
					session.sessionId,
					"MARKET_DATA_RESUMED",
					"Market Data",
					"active",
					"",
					feed.lastMarketEventAt,
					"Market data resumed.",
					"Fresh ProjectX market events returned. Strategy scans are active again.",
					"{"
						+ "\"downtime\":" + jsonString(formatDurationForLog(detectedDowntimeSeconds)) + ","
						+ "\"marketEventGap\":" + jsonString(formatDurationForLog(marketEventGapSeconds)) + ","
						+ "\"lastEvent\":" + jsonString(feed.lastMarketEventAt) + ","
						+ "\"resumedAt\":" + jsonString(resumedAt)
						+ "}"
				);
			}
			return;
		}
		if (feed.warming) {
			return;
		}
		boolean shouldLogStop = false;
		String stoppedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
		synchronized (FuturesManager.class) {
			if (!liveMarketDataStoppedActive) {
				shouldLogStop = true;
				liveMarketDataStoppedActive = true;
				liveMarketDataStoppedDetectedAt = stoppedAt;
				liveMarketDataStoppedLastEventAt = cleanOrDefault(feed.lastMarketEventAt, "");
			}
		}
		if (shouldLogStop) {
			String message = "Market data stopped; live bot remains running and will resume strategy evaluation after fresh ProjectX events return.";
			String payload = "{"
				+ "\"stoppedDetectedAt\":" + jsonString(stoppedAt) + ","
				+ "\"lastMarketEventAt\":" + jsonString(feed.lastMarketEventAt) + ","
				+ "\"staleSeconds\":" + feed.staleSeconds + ","
				+ "\"running\":" + feed.running + ","
				+ "\"reason\":" + jsonString(feed.reason)
				+ "}";
			recordLiveAudit("MARKET_DATA_STOPPED", "ERROR", message, payload);
			pushLiveEvent(
				session.sessionId,
				"MARKET_DATA_STOPPED",
				"Market Data",
				"error",
				"",
				feed.lastMarketEventAt,
				"Market data stopped.",
				"Strategy scans and Topstep entries are paused until fresh data resumes.",
				"{"
					+ "\"seconds\":" + Math.max(0L, feed.staleSeconds) + ","
					+ "\"lastEvent\":" + jsonString(feed.lastMarketEventAt) + ","
					+ "\"running\":" + feed.running + ","
					+ "\"reason\":" + jsonString(feed.reason)
					+ "}"
			);
		}
	}

	private static void resetLiveMarketDataTransitionState() {
		synchronized (FuturesManager.class) {
			liveMarketDataStoppedActive = false;
			liveMarketDataStoppedDetectedAt = "";
			liveMarketDataStoppedLastEventAt = "";
			liveSessionPrepLoggedDate = "";
			liveEntryGateOpenedLoggedDate = "";
			liveEntryGateClosedLoggedDate = "";
		}
	}

	private static void recordLiveEntryGateTransition(FuturesLiveSession session, MarketSessionStatus marketStatus) {
		if (session == null || session.sessionId <= 0 || marketStatus == null) {
			return;
		}
		String code = cleanOrDefault(marketStatus.code, "");
		String marketDate = cleanOrDefault(marketStatus.marketDate, "");
		if (!marketStatus.tradingDay || marketDate.length() == 0) {
			return;
		}
		if (marketStatus.entryWindowOpen) {
			boolean shouldLogOpen = false;
			synchronized (FuturesManager.class) {
				if (!marketDate.equals(liveEntryGateOpenedLoggedDate)) {
					shouldLogOpen = true;
					liveEntryGateOpenedLoggedDate = marketDate;
				}
			}
			if (shouldLogOpen) {
				pushLiveEvent(
					session.sessionId,
					"TRADING_ENABLED",
					"Trading Enabled",
					"active",
					"",
					"",
					"Trading Enabled",
					"Market window, realtime data, strategy config, and risk config are ready for live entries.",
					"{"
						+ "\"gate\":" + jsonString(cleanOrDefault(marketStatus.label, "")) + ","
						+ "\"code\":" + jsonString(code) + ","
						+ "\"marketDate\":" + jsonString(marketDate) + ","
						+ "\"entriesEnabled\":true,"
						+ "\"strategyConfig\":" + jsonString(activeLiveStrategyPreset(session, null)) + ","
						+ "\"riskConfig\":" + jsonString(fundedRuleProfileFor(cleanOrDefault(session.fundedProfile, "CUSTOM")).name) + ","
						+ "\"marketData\":" + jsonString(cleanOrDefault(session.dataMode, ProjectXRealtimeManager.currentDataMode()))
						+ "}"
				);
			}
			return;
		}
		if (!shouldLogLiveEntryClosed(marketStatus)) {
			return;
		}
		boolean shouldLogClosed = false;
		synchronized (FuturesManager.class) {
			if (!marketDate.equals(liveEntryGateClosedLoggedDate)) {
				shouldLogClosed = true;
				liveEntryGateClosedLoggedDate = marketDate;
			}
		}
		if (!shouldLogClosed) {
			return;
		}
		pushLiveEvent(
			session.sessionId,
			"ENTRY_GATE_CLOSED",
			"Entry Gate",
			"closed",
			"",
			"",
			"Trading entries disabled.",
			"",
			"{"
				+ "\"gate\":" + jsonString(cleanOrDefault(marketStatus.label, "")) + ","
				+ "\"code\":" + jsonString(code) + ","
				+ "\"marketDate\":" + jsonString(marketDate) + ","
				+ "\"entriesEnabled\":false"
				+ "}"
		);
	}

	private static boolean shouldLogLiveSessionPrep(MarketSessionStatus status) {
		if (status == null || !status.tradingDay || status.entryWindowOpen) {
			return false;
		}
		String code = cleanOrDefault(status.code, "");
		return "BOT_PREP".equals(code)
			|| "DATA_CONNECT".equals(code)
			|| "PREMARKET_WAIT".equals(code)
			|| "RTH_ARMING".equals(code);
	}

	private static boolean shouldLogLiveEntryClosed(MarketSessionStatus status) {
		if (status == null || !status.tradingDay || status.entryWindowOpen) {
			return false;
		}
		String code = cleanOrDefault(status.code, "");
		return status.closeGuard
			|| status.cancelRestingOrders
			|| status.flattenPositions
			|| status.verifyFlat
			|| "RTH_CLOSED".equals(code);
	}

	private static String formatDurationForLog(long seconds) {
		if (seconds < 0L) {
			return "unknown";
		}
		if (seconds < 60L) {
			return seconds + "s";
		}
		long minutes = seconds / 60L;
		long remainder = seconds % 60L;
		if (minutes < 60L) {
			return remainder == 0L ? minutes + "m" : minutes + "m " + remainder + "s";
		}
		long hours = minutes / 60L;
		long minuteRemainder = minutes % 60L;
		return minuteRemainder == 0L ? hours + "h" : hours + "h " + minuteRemainder + "m";
	}

	private static boolean shouldRunLivePotentialSignalScan() {
		long now = System.currentTimeMillis();
		synchronized (FuturesManager.class) {
			if (now - livePotentialSignalScanAttemptAtMillis < LIVE_POTENTIAL_SIGNAL_SCAN_INTERVAL_MS) {
				return false;
			}
			livePotentialSignalScanAttemptAtMillis = now;
			return true;
		}
	}

	private static LivePotentialSignalScan scanLivePotentialSignals(FuturesLiveSession session, LiveStrategySnapshotRow snapshot) {
		LivePotentialSignalScan scan = new LivePotentialSignalScan();
		List<String> symbols = parseSymbols(activeLiveSymbols(session, snapshot));
		for (int index = 0; index < symbols.size(); index++) {
			String symbol = symbols.get(index);
			scan.symbolsChecked++;
			List<Bar> bars = realtimeBarsForSymbol(symbol, "1m", LIVE_STRATEGY_ONE_MINUTE_BAR_LIMIT);
			if (bars.size() < 6) {
				scan.symbolsWaitingForBars++;
				continue;
			}
			scan.symbolsWithBars++;
			Bar entryBar = bars.get(bars.size() - 1);
			Bar signalBar = bars.get(bars.size() - 2);
			scan.currentBarsBySymbol.put(symbol, entryBar);
			scan.lastProcessed = entryBar.displayTime;

			InstrumentSpec spec = instrumentFor(symbol);
			BacktestConfig config = liveSignalConfigFor(symbol, session, snapshot);
			PortfolioSymbolContext context = livePortfolioContext(symbol, spec, config, bars);
			prepareLivePortfolioSignalEvents(
				context,
				previousLocalDayBarsForLive(symbol, signalBar.marketDate),
				liveHigherTimeframeBarsFromMinuteBars(bars, spec, "15m", 96),
				liveHigherTimeframeBarsFromMinuteBars(bars, spec, "1h", 48)
			);
			List<SignalEvent> todaysEvents = context.eventsByDay.get(entryBar.marketDate);
			scan.daySignalEvents += todaysEvents == null ? 0 : todaysEvents.size();
			scan.contexts.put(symbol, context);
		}
		addMymBreadthConfirmationSignalEvents(scan.contexts);
		addMicroShadowSignalEvents(scan.contexts);
		addMicroEchoSignalEvents(scan.contexts);
		scan.candidates.addAll(currentLiveSignalCandidates(session.sessionId, snapshot.snapshotId, scan.contexts, scan.currentBarsBySymbol, false));
		rankLivePortfolioSignalCandidates(scan.candidates, scan.contexts);
		return scan;
	}

	private static void recordOffSessionPotentialSignals(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		MarketSessionStatus marketStatus,
		LivePotentialSignalScan scan
	) {
		if (scan == null || scan.candidates.isEmpty()) {
			return;
		}
		LocalDate scanDate = LocalDate.now(NEW_YORK_ZONE);
		PortfolioBacktestConfig portfolioConfig = livePortfolioConfigFromSnapshot(snapshot, scanDate, scanDate);
		LiveAccountSizing accountSizing = liveAccountSizingFor(session, snapshot);
		applyLiveAccountSizingToPortfolioConfig(portfolioConfig, session, accountSizing);

		List<PortfolioPosition> trackedOpenPositions = liveOpenPositionsForSession(session.sessionId, snapshot.snapshotId);
		List<PortfolioPosition> openPositions = "TOPSTEPX".equals(session.executionMode)
			? new ArrayList<PortfolioPosition>()
			: trackedOpenPositions;
		Map<String, Integer> takenByStrategy = liveTakenByStrategyForSession(session.sessionId, snapshot.snapshotId);
		LiveBrokerExposure brokerExposure = "TOPSTEPX".equals(session.executionMode)
			? liveBrokerExposureForSnapshot(session, snapshot)
			: new LiveBrokerExposure();

		for (int index = 0; index < scan.candidates.size(); index++) {
			LivePortfolioSignalCandidate candidate = scan.candidates.get(index);
			if (candidate == null || candidate.event == null || candidate.event.signal == null) {
				continue;
			}
			Signal signal = candidate.event.signal;
			LiveSignalOrder validation = validateLivePortfolioSignal(session, portfolioConfig, scan.contexts, candidate, openPositions, takenByStrategy, brokerExposure);
			boolean wouldPassRisk = validation.accepted;
			String strategyCode = cleanOrDefault(signal.strategyCode, "LIVE");
			String side = cleanOrDefault(signal.side, "");
			String symbol = normalizeSymbol(candidate.symbol);
			String statusText = wouldPassRisk ? "would pass read-only validation" : "did not pass read-only validation";
			String eventType = wouldPassRisk ? "POTENTIAL_SIGNAL_BLOCKED" : "POTENTIAL_SIGNAL_REJECTED";
			String severity = wouldPassRisk ? "INFO" : "BLOCK";
			String message = symbol + " " + strategyCode + " " + side + " potential live entry " + statusText + " while " + marketStatus.label + ".";
			String detail = wouldPassRisk
				? "No order was submitted because the entry gate is closed: " + marketStatus.detail
				: "No order was submitted. " + cleanOrDefault(validation.reason, "Read-only validation rejected this signal.") + " Entry gate state: " + marketStatus.detail;
			String dedupeKey = "potential|" + session.sessionId + "|" + snapshot.snapshotId + "|" + symbol + "|" + strategyCode + "|" + side + "|" + candidate.signalTime + "|" + candidate.entryTime + "|" + marketStatus.code;
			String payload = potentialSignalPayloadJson(candidate, validation, marketStatus, wouldPassRisk, detail);
			boolean inserted = insertLiveRiskEventOnce(session.sessionId, snapshot.snapshotId, eventType, severity, message, payload, dedupeKey);
			if (inserted) {
				recordLiveAudit(eventType, severity, message, payload);
			}
			if (wouldPassRisk) {
				if (validation.position != null) {
					openPositions.add(validation.position);
				}
				String strategyKey = strategyDailyLimitKey(symbol, strategyCode);
				takenByStrategy.put(strategyKey, countFor(takenByStrategy, strategyKey) + 1);
			}
		}
	}

	private static String potentialSignalPayloadJson(
		LivePortfolioSignalCandidate candidate,
		LiveSignalOrder validation,
		MarketSessionStatus marketStatus,
		boolean wouldPassRisk,
		String detail
	) {
		Signal signal = candidate.event.signal;
		double entryPrice = validation.accepted && validation.entryPrice > 0.0 ? validation.entryPrice : signal.entryPrice;
		double stopPrice = validation.accepted && validation.stopPrice > 0.0 ? validation.stopPrice : signal.stopPrice;
		double targetPrice = validation.accepted && validation.targetPrice > 0.0 ? validation.targetPrice : signal.targetPrice;
		return "{"
			+ "\"symbol\":" + jsonString(candidate.symbol) + ","
			+ "\"strategyCode\":" + jsonString(signal.strategyCode) + ","
			+ "\"strategyName\":" + jsonString(signal.strategyName) + ","
			+ "\"side\":" + jsonString(signal.side) + ","
			+ "\"signalTime\":" + jsonString(candidate.signalTime) + ","
			+ "\"entryTime\":" + jsonString(candidate.entryTime) + ","
			+ "\"entryPrice\":" + round(entryPrice) + ","
			+ "\"stopPrice\":" + round(stopPrice) + ","
			+ "\"targetPrice\":" + round(targetPrice) + ","
			+ "\"contracts\":" + Math.max(0, validation.contracts) + ","
			+ "\"fundedMiniUnits\":" + round(validation.fundedMiniUnits) + ","
			+ "\"wouldPassRisk\":" + wouldPassRisk + ","
			+ "\"validationReason\":" + jsonString(cleanOrDefault(validation.reason, "")) + ","
			+ "\"marketSessionCode\":" + jsonString(marketStatus.code) + ","
			+ "\"marketSessionLabel\":" + jsonString(marketStatus.label) + ","
			+ "\"marketSessionDetail\":" + jsonString(marketStatus.detail) + ","
			+ "\"detail\":" + jsonString(detail)
			+ "}";
	}

	private static void runLiveRealtimeCycle() {
		long cycleStartedAtMillis = System.currentTimeMillis();
		FuturesLiveSession session;
		synchronized (FuturesManager.class) {
			if (!liveSession.running) {
				return;
			}
			session = copyLiveSession(liveSession);
			liveSession.automationCycles++;
			}
				LiveStrategySnapshotRow snapshot = loadActiveLiveStrategySnapshot();
				if (snapshot == null || session.sessionId <= 0) {
					pushLiveEvent(
						session.sessionId,
						"BROKER_SYNC_ERROR",
						"Setup",
						"error",
						"",
						"",
						"Live strategy config missing.",
						"Selected Strategy Config preset could not be prepared for live evaluation.",
						"{}"
					);
					return;
				}
			MarketSessionStatus marketStatus = currentMarketSessionStatus();
			recordLiveEntryGateTransition(session, marketStatus);
			if ("TOPSTEPX".equals(session.executionMode)) {
				recordLiveMarketDataTransition(session, currentMarketFeedFreshness());
			}
		if (marketStatus.tradingDay && !marketStatus.marketDate.equals(session.closeActionDate)) {
			synchronized (FuturesManager.class) {
				liveSession.closeActionDate = marketStatus.marketDate;
				liveSession.flattenAttempted = false;
				liveSession.restingOrdersCancelAttempted = false;
				liveSession.postCloseVerified = false;
				session = copyLiveSession(liveSession);
			}
		}
		if (!marketStatus.entryWindowOpen) {
			String message = marketStatus.label + ": " + marketStatus.detail;
			if ("TOPSTEPX".equals(session.executionMode)) {
				String activeAccountId = activeLiveTopstepAccountId(session, snapshot);
				if (marketStatus.cancelRestingOrders && !session.restingOrdersCancelAttempted) {
					String cancelResponse = activeAccountId.length() == 0
						? "{\"success\":false,\"message\":\"Selected Topstep account has no account ID configured.\"}"
						: FuturesConnectionManager.cancelTopstepxPracticeRestingEntryOrders(activeAccountId);
					boolean canceled = jsonBoolean(cancelResponse, "success");
					message = marketStatus.label + ": " + marketStatus.detail + " "
						+ (canceled ? "Resting-order cancel sweep completed." : "Resting-order cancel sweep needs attention: " + jsonStringSummary(cancelResponse));
						recordLiveAudit(canceled ? "PRACTICE_RESTING_ORDER_CANCEL" : "PRACTICE_RESTING_ORDER_CANCEL_FAILED", canceled ? "WARN" : "ERROR", message, cancelResponse);
						pushLiveEvent(
							session.sessionId,
							"POST_CLOSE_CLEANUP",
							"Post Close",
							canceled ? "warn" : "error",
							"",
							"",
							canceled ? "Post-close account cleanup completed." : "Post-close account cleanup needs attention.",
							canceled ? "Canceled resting practice entry orders." : "Resting-order cancel sweep needs attention.",
							"{"
								+ "\"action\":\"cancel_resting_orders\","
								+ "\"status\":" + jsonString(canceled ? "completed" : "needs_attention") + ","
								+ "\"summary\":" + jsonString(jsonStringSummary(cancelResponse))
								+ "}"
						);
						synchronized (FuturesManager.class) {
							liveSession.restingOrdersCancelAttempted = true;
							session = copyLiveSession(liveSession);
					}
				}
				if ((marketStatus.flattenPositions || marketStatus.verifyFlat || "RTH_CLOSED".equals(marketStatus.code)) && !session.flattenAttempted) {
					String flattenResponse = activeAccountId.length() == 0
						? "{\"success\":false,\"message\":\"Selected Topstep account has no account ID configured.\"}"
						: FuturesConnectionManager.flattenTopstepxPracticeAccount(activeAccountId);
					boolean flattened = jsonBoolean(flattenResponse, "success");
					message = marketStatus.label + ": " + marketStatus.detail + " "
						+ (flattened ? "Topstep flatten/cancel sweep completed." : "Topstep flatten/cancel sweep needs attention: " + jsonStringSummary(flattenResponse));
						recordLiveAudit(flattened ? "PRACTICE_FLATTEN_SWEEP" : "PRACTICE_FLATTEN_SWEEP_FAILED", flattened ? "WARN" : "ERROR", message, flattenResponse);
						pushLiveEvent(
							session.sessionId,
							"POST_CLOSE_CLEANUP",
							"Post Close",
							flattened ? "warn" : "error",
							"",
							"",
							flattened ? "Account flattened." : "Flatten sweep needs attention.",
							flattened ? "" : "Topstep flatten sweep needs attention.",
							"{"
								+ "\"action\":\"flatten_positions\","
								+ "\"status\":" + jsonString(flattened ? "completed" : "needs_attention") + ","
								+ "\"summary\":" + jsonString(jsonStringSummary(flattenResponse))
								+ "}"
						);
						synchronized (FuturesManager.class) {
							liveSession.flattenAttempted = true;
							session = copyLiveSession(liveSession);
					}
					}
					if ((marketStatus.verifyFlat || "RTH_CLOSED".equals(marketStatus.code)) && !session.postCloseVerified) {
						String verifyResponse = FuturesConnectionManager.syncTopstepxReadOnly();
						boolean verified = jsonBoolean(verifyResponse, "success");
						message = marketStatus.label + ": " + marketStatus.detail + " "
							+ (verified ? "Flat/order verification sync completed." : "Flat/order verification needs attention: " + jsonStringSummary(verifyResponse));
						recordLiveAudit(verified ? "PRACTICE_POST_CLOSE_VERIFY" : "PRACTICE_POST_CLOSE_VERIFY_FAILED", verified ? "INFO" : "ERROR", message, verifyResponse);
						if (!verified) {
							pushLiveEvent(
								session.sessionId,
								"POST_CLOSE_CLEANUP",
								"Post Close",
								"error",
								"",
								"",
								"Post-close account cleanup needs attention.",
								"Flat/order verification needs attention.",
								"{"
									+ "\"action\":\"verify_flat\","
									+ "\"status\":\"needs_attention\","
									+ "\"summary\":" + jsonString(jsonStringSummary(verifyResponse))
									+ "}"
							);
						}
						synchronized (FuturesManager.class) {
							liveSession.postCloseVerified = true;
							session = copyLiveSession(liveSession);
						}
					}
				}
			synchronized (FuturesManager.class) {
					liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
					liveSession.lastDecision = message;
				}
				if (shouldRunLivePotentialSignalScan()) {
					boolean feedFreshForPotentialScan = !"TOPSTEPX".equals(session.executionMode);
					if ("TOPSTEPX".equals(session.executionMode)) {
						MarketFeedFreshness feed = currentMarketFeedFreshness();
						feedFreshForPotentialScan = feed.fresh;
					}
					if (feedFreshForPotentialScan) {
						LivePotentialSignalScan potentialScan = scanLivePotentialSignals(session, snapshot);
						recordOffSessionPotentialSignals(session, snapshot, marketStatus, potentialScan);
					}
				}
				updateLiveEngineSession(session.sessionId, "RUNNING", session.lastBarTime, session.decisionCount, session.acceptedDecisionCount, session.rejectedDecisionCount, message);
				return;
			}

		if ("TOPSTEPX".equals(session.executionMode) && !ensureTopstepxRealtimeFeedFresh(session, snapshot)) {
			MarketFeedFreshness staleFeed = currentMarketFeedFreshness();
			insertLiveCycleAudit(
				session.sessionId,
				snapshot.snapshotId,
				marketStatus,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				"",
				false,
				"Live cycle skipped because Topstep realtime feed was not fresh.",
				liveCycleAuditPayloadJson(
					session,
					snapshot,
					marketStatus,
					staleFeed,
					new ArrayList<String>(),
					new ArrayList<String>(),
					System.currentTimeMillis() - cycleStartedAtMillis,
					-1L,
					0L,
					0L
				)
			);
			return;
		}

		long strategyScanStartedAtMillis = System.currentTimeMillis();
			List<String> symbols = parseSymbols(activeLiveSymbols(session, snapshot));
		Map<String, PortfolioSymbolContext> liveContexts = new HashMap<String, PortfolioSymbolContext>();
		Map<String, Bar> currentBarsBySymbol = new HashMap<String, Bar>();
			List<LivePortfolioSignalCandidate> candidates = new ArrayList<LivePortfolioSignalCandidate>();
			String lastProcessed = "";
			int symbolsChecked = 0;
			int symbolsWithBars = 0;
			int symbolsWaitingForBars = 0;
			int daySignalEvents = 0;
			List<String> symbolAuditParts = new ArrayList<String>();
			LocalDate today = LocalDate.now(NEW_YORK_ZONE);
		PortfolioBacktestConfig portfolioConfig = livePortfolioConfigFromSnapshot(snapshot, today, today);
		LiveAccountSizing accountSizing = liveAccountSizingFor(session, snapshot);
		applyLiveAccountSizingToPortfolioConfig(portfolioConfig, session, accountSizing);
			for (int index = 0; index < symbols.size(); index++) {
				String symbol = symbols.get(index);
				symbolsChecked++;
				List<Bar> bars = realtimeBarsForSymbol(symbol, "1m", LIVE_STRATEGY_ONE_MINUTE_BAR_LIMIT);
				if (bars.size() < 6) {
					symbolsWaitingForBars++;
					symbolAuditParts.add(liveCycleSymbolAuditJson(symbol, bars, 0, "", "", "WAITING_FOR_BARS"));
					continue;
				}
				symbolsWithBars++;
				Bar entryBar = bars.get(bars.size() - 1);
				Bar signalBar = bars.get(bars.size() - 2);
				currentBarsBySymbol.put(symbol, entryBar);
			lastProcessed = entryBar.displayTime;

			InstrumentSpec spec = instrumentFor(symbol);
			BacktestConfig config = liveSignalConfigFor(symbol, session, snapshot);
			config.maxRiskPerTrade = Math.min(config.maxRiskPerTrade, portfolioConfig.maxRiskPerTrade);
			config.maxContracts = Math.min(config.maxContracts, profileMaxContractsForSymbol(accountSizing.profile, symbol));
			PortfolioSymbolContext context = livePortfolioContext(symbol, spec, config, bars);
			prepareLivePortfolioSignalEvents(
				context,
				previousLocalDayBarsForLive(symbol, signalBar.marketDate),
					liveHigherTimeframeBarsFromMinuteBars(bars, spec, "15m", 96),
					liveHigherTimeframeBarsFromMinuteBars(bars, spec, "1h", 48)
				);
				List<SignalEvent> todaysEvents = context.eventsByDay.get(entryBar.marketDate);
				daySignalEvents += todaysEvents == null ? 0 : todaysEvents.size();
				symbolAuditParts.add(liveCycleSymbolAuditJson(
					symbol,
					bars,
					todaysEvents == null ? 0 : todaysEvents.size(),
					signalBar.displayTime,
					entryBar.displayTime,
					!isLiveEntryWindowTime(entryBar.marketTime) ? "OUTSIDE_LIVE_ENTRY_WINDOW" : "READY"
				));
				liveContexts.put(symbol, context);
				if (!isLiveEntryWindowTime(entryBar.marketTime)) {
					continue;
				}
			}
			addMymBreadthConfirmationSignalEvents(liveContexts);
			addMicroShadowSignalEvents(liveContexts);
			addMicroEchoSignalEvents(liveContexts);
			candidates.addAll(currentLiveSignalCandidates(session.sessionId, snapshot.snapshotId, liveContexts, currentBarsBySymbol));
		long strategyScanDurationMs = System.currentTimeMillis() - strategyScanStartedAtMillis;
			List<PortfolioPosition> trackedOpenPositions = liveOpenPositionsForSession(session.sessionId, snapshot.snapshotId);
			int exitsProcessed = 0;
			if ("TOPSTEPX".equals(session.executionMode)) {
				exitsProcessed = processTopstepxLiveExitSignals(session, snapshot, liveContexts, currentBarsBySymbol, trackedOpenPositions);
			}
			rankLivePortfolioSignalCandidates(candidates, liveContexts);
		List<PortfolioPosition> openPositions = "TOPSTEPX".equals(session.executionMode)
			? new ArrayList<PortfolioPosition>()
			: trackedOpenPositions;
		Map<String, Integer> takenByStrategy = liveTakenByStrategyForSession(session.sessionId, snapshot.snapshotId);
		long brokerExposureDurationMs = 0L;
		LiveBrokerExposure brokerExposure = new LiveBrokerExposure();
		if ("TOPSTEPX".equals(session.executionMode) && !candidates.isEmpty()) {
			long brokerExposureStartedAtMillis = System.currentTimeMillis();
			brokerExposure = liveBrokerExposureForSnapshot(session, snapshot);
			brokerExposureDurationMs = System.currentTimeMillis() - brokerExposureStartedAtMillis;
		}
		int acceptedThisCycle = 0;
		int rejectedThisCycle = 0;
		List<String> candidateAuditParts = new ArrayList<String>();
			for (int candidateIndex = 0; candidateIndex < candidates.size(); candidateIndex++) {
				LivePortfolioSignalCandidate candidate = candidates.get(candidateIndex);
				Signal signal = candidate.event.signal;
				if (liveDecisionExists(session.sessionId, candidate.symbol, signal.strategyCode, candidate.signalTime)) {
					continue;
				}
				pushLiveEvent(
					session.sessionId,
					"TRADE_CANDIDATE",
					"Trade Candidate",
					"active",
					candidate.symbol,
					candidate.entryTime,
					normalizeSymbol(candidate.symbol) + " " + cleanOrDefault(signal.strategyCode, "LIVE") + " " + cleanOrDefault(signal.side, "") + " candidate found.",
					"Validating risk limits, exposure, and Topstep order room.",
					"{"
						+ "\"symbol\":" + jsonString(normalizeSymbol(candidate.symbol)) + ","
						+ "\"strategy\":" + jsonString(cleanOrDefault(signal.strategyCode, "LIVE")) + ","
						+ "\"side\":" + jsonString(cleanOrDefault(signal.side, "")) + ","
						+ "\"signalTime\":" + jsonString(candidate.signalTime) + ","
						+ "\"barTime\":" + jsonString(candidate.entryTime) + ","
						+ "\"entry\":" + round(signal.entryPrice) + ","
						+ "\"stop\":" + round(signal.stopPrice) + ","
					+ "\"target\":" + round(signal.targetPrice)
						+ "}"
				);
				LiveSignalOrder order = validateLivePortfolioSignal(session, portfolioConfig, liveContexts, candidate, openPositions, takenByStrategy, brokerExposure);
				if (!order.accepted) {
					candidateAuditParts.add(liveCycleCandidateAuditJson(candidate, "REJECTED", order.reason, 0, 0.0, signal.stopPrice, signal.targetPrice, order.diagnosticsJson, ""));
					insertLiveSignalDecisionFromSignal(session.sessionId, snapshot.snapshotId, candidate.symbol, signal, candidate.signalTime, candidate.entryTime, 0, 0.0, signal.stopPrice, signal.targetPrice, 0.0, "REJECTED", order.reason, "", order.diagnosticsJson);
					pushLiveEvent(
						session.sessionId,
						"TRADE_BLOCKED",
						"Risk Gate",
						"blocked",
						candidate.symbol,
						candidate.entryTime,
						normalizeSymbol(candidate.symbol) + " " + cleanOrDefault(signal.strategyCode, "LIVE") + " " + cleanOrDefault(signal.side, "") + " blocked before order submit.",
						cleanOrDefault(order.reason, "Risk validation rejected this trade."),
						"{"
							+ "\"symbol\":" + jsonString(normalizeSymbol(candidate.symbol)) + ","
							+ "\"strategy\":" + jsonString(cleanOrDefault(signal.strategyCode, "LIVE")) + ","
							+ "\"side\":" + jsonString(cleanOrDefault(signal.side, "")) + ","
							+ "\"entry\":" + round(signal.entryPrice) + ","
							+ "\"stop\":" + round(signal.stopPrice) + ","
							+ "\"target\":" + round(signal.targetPrice) + ","
							+ "\"reason\":" + jsonString(cleanOrDefault(order.reason, "Risk validation rejected this trade.")) + ","
							+ "\"sizingDiagnostics\":" + jsonObjectOrDefault(order.diagnosticsJson, "{}")
							+ "}"
					);
					rejectedThisCycle++;
					continue;
				}
			String status;
					String reason;
					String brokerSubmitJson = "";
					if ("TOPSTEPX".equals(session.executionMode)) {
						if (!liveSessionStillRunning(session.sessionId)) {
							brokerSubmitJson = "{\"success\":false,\"message\":\"Live bot stopped before broker submission.\"}";
						} else {
							brokerSubmitJson = submitTopstepxPracticeOrderViaAdapter(
								snapshot.snapshotId,
								"LIVE_SIGNAL",
								candidate.symbol,
								signal.side,
								order.contracts,
								order.entryPrice,
								order.stopPrice,
								order.targetPrice,
								signal.strategyCode + " live signal",
								"SUBMITTED_TOPSTEPX",
								"SUBMIT_BLOCKED",
								signal.strategyCode,
								signal.strategyName,
								candidate.signalTime,
								candidate.entryTime
							);
						}
					boolean submitted = jsonBoolean(brokerSubmitJson, "success");
					boolean requiresAutoOcoBrackets = !submitted && jsonBoolean(brokerSubmitJson, "requiresAutoOcoBrackets");
					status = submitted ? "SUBMITTED_TOPSTEPX" : "SUBMIT_BLOCKED";
					String orderId = jsonText(brokerSubmitJson, "orderId", "");
					if (orderId.length() == 0) {
						double numericOrderId = jsonNumber(brokerSubmitJson, "orderId", 0.0);
						orderId = numericOrderId > 0.0 ? String.valueOf((long) numericOrderId) : "";
					}
					reason = submitted
						? "TopstepX order submitted from live signal" + (orderId.length() == 0 ? "." : " (order " + orderId + ").")
						: (requiresAutoOcoBrackets ? TOPSTEPX_AUTO_OCO_REQUIRED_MESSAGE : "TopstepX order was blocked: " + jsonStringSummary(brokerSubmitJson));
				} else {
				status = "ACCEPTED_SIMULATED_LIVE";
				reason = "Live signal accepted in simulated mode.";
			}
				insertLiveSignalDecisionFromSignal(session.sessionId, snapshot.snapshotId, candidate.symbol, signal, candidate.signalTime, candidate.entryTime, order.contracts, order.entryPrice, order.stopPrice, order.targetPrice, order.fundedMiniUnits, status, reason, brokerSubmitJson, order.diagnosticsJson);
				candidateAuditParts.add(liveCycleCandidateAuditJson(candidate, status, reason, order.contracts, order.entryPrice, order.stopPrice, order.targetPrice, order.diagnosticsJson, brokerSubmitJson));
				if (status.startsWith("SUBMIT_BLOCKED")) {
					pushLiveEvent(
						session.sessionId,
						"ORDER_REJECTED",
						"TopstepX",
						"blocked",
						candidate.symbol,
						candidate.entryTime,
						normalizeSymbol(candidate.symbol) + " " + cleanOrDefault(signal.strategyCode, "LIVE") + " " + cleanOrDefault(signal.side, "") + " rejected by Topstep.",
						cleanOrDefault(reason, "Topstep rejected the order."),
						"{"
							+ "\"symbol\":" + jsonString(normalizeSymbol(candidate.symbol)) + ","
							+ "\"strategy\":" + jsonString(cleanOrDefault(signal.strategyCode, "LIVE")) + ","
							+ "\"side\":" + jsonString(cleanOrDefault(signal.side, "")) + ","
							+ "\"contracts\":" + order.contracts + ","
							+ "\"entry\":" + round(order.entryPrice) + ","
							+ "\"stop\":" + round(order.stopPrice) + ","
							+ "\"target\":" + round(order.targetPrice) + ","
							+ "\"reason\":" + jsonString(cleanOrDefault(reason, "Topstep rejected the order."))
							+ "}"
					);
					rejectedThisCycle++;
				} else {
					String submittedOrderId = jsonText(brokerSubmitJson, "orderId", "");
					if (submittedOrderId.length() == 0) {
						double numericSubmittedOrderId = jsonNumber(brokerSubmitJson, "orderId", 0.0);
						submittedOrderId = numericSubmittedOrderId > 0.0 ? String.valueOf((long) numericSubmittedOrderId) : "";
					}
					String entryReasonJson = liveEntryTradeReasoningJson(candidate.symbol, signal, signal.side, order.contracts, order.entryPrice, order.stopPrice, order.targetPrice, order.fundedMiniUnits, status, reason, order.diagnosticsJson);
					String entryReasonText = jsonText(entryReasonJson, "entryReasonText", "Order submitted from a validated live strategy signal.");
					pushLiveEvent(
						session.sessionId,
						"ORDER_SUBMITTED",
						"TopstepX",
						"accepted",
						candidate.symbol,
						candidate.entryTime,
						normalizeSymbol(candidate.symbol) + " " + cleanOrDefault(signal.strategyCode, "LIVE") + " " + cleanOrDefault(signal.side, "") + " submitted to Topstep.",
						entryReasonText,
						"{"
							+ "\"symbol\":" + jsonString(normalizeSymbol(candidate.symbol)) + ","
							+ "\"strategy\":" + jsonString(cleanOrDefault(signal.strategyCode, "LIVE")) + ","
							+ "\"side\":" + jsonString(cleanOrDefault(signal.side, "")) + ","
							+ "\"contracts\":" + order.contracts + ","
							+ "\"entry\":" + round(order.entryPrice) + ","
							+ "\"stop\":" + round(order.stopPrice) + ","
							+ "\"target\":" + round(order.targetPrice) + ","
							+ "\"orderId\":" + jsonString(submittedOrderId) + ","
							+ "\"entryReason\":" + jsonString(entryReasonText) + ","
							+ "\"tradeReason\":" + entryReasonJson
							+ "}"
					);
					if (order.position != null) {
						openPositions.add(order.position);
					}
				String strategyKey = strategyDailyLimitKey(candidate.symbol, signal.strategyCode);
				takenByStrategy.put(strategyKey, countFor(takenByStrategy, strategyKey) + 1);
				acceptedThisCycle++;
			}
		}

		if (acceptedThisCycle > 0 || rejectedThisCycle > 0 || lastProcessed.length() > 0) {
			String message = acceptedThisCycle > 0
				? "Live strategy processed and submitted " + acceptedThisCycle + " Topstep order signal(s)."
				: "Live strategy processed latest candles; no new accepted order signal.";
			synchronized (FuturesManager.class) {
				liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
				if (lastProcessed.length() > 0) {
					liveSession.lastBarTime = lastProcessed;
					liveSession.lastProcessedLiveBarTime = lastProcessed;
				}
				liveSession.decisionCount += acceptedThisCycle + rejectedThisCycle;
				liveSession.acceptedDecisionCount += acceptedThisCycle;
				liveSession.rejectedDecisionCount += rejectedThisCycle;
				liveSession.lastDecision = message;
				session = copyLiveSession(liveSession);
			}
			updateLiveEngineSession(session.sessionId, "RUNNING", session.lastBarTime, session.decisionCount, session.acceptedDecisionCount, session.rejectedDecisionCount, message);
		}
		MarketFeedFreshness cycleFeedFreshness = "TOPSTEPX".equals(session.executionMode) ? currentMarketFeedFreshness() : new MarketFeedFreshness();
		boolean cycleFeedFresh = !"TOPSTEPX".equals(session.executionMode) || cycleFeedFreshness.fresh;
		String cycleAuditMessage = acceptedThisCycle > 0
			? "Live cycle submitted " + acceptedThisCycle + " order signal(s)."
			: (rejectedThisCycle > 0
				? "Live cycle rejected " + rejectedThisCycle + " candidate signal(s)."
				: "Live cycle processed without accepted candidates.");
		insertLiveCycleAudit(
			session.sessionId,
			snapshot.snapshotId,
			marketStatus,
			symbolsChecked,
			symbolsWithBars,
			symbolsWaitingForBars,
			daySignalEvents,
			candidates.size(),
			acceptedThisCycle,
			rejectedThisCycle,
			exitsProcessed,
			lastProcessed,
			cycleFeedFresh,
			cycleAuditMessage,
			liveCycleAuditPayloadJson(
				session,
				snapshot,
				marketStatus,
				cycleFeedFreshness,
				symbolAuditParts,
				candidateAuditParts,
				System.currentTimeMillis() - cycleStartedAtMillis,
				lastProcessed.length() == 0 ? -1L : secondsSinceDisplayTime(lastProcessed),
				brokerExposureDurationMs,
				strategyScanDurationMs
			)
		);
	}

	private static int processTopstepxLiveExitSignals(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBars,
		List<PortfolioPosition> openPositions
	) {
		if (session == null || snapshot == null || openPositions == null || openPositions.isEmpty()) {
			return 0;
		}
		List<FuturesTrade> exitTrades = closeTriggeredLivePositions(session, snapshot, openPositions, contexts, currentBars);
		int completed = 0;
		for (int index = 0; index < exitTrades.size(); index++) {
			FuturesTrade trade = exitTrades.get(index);
			if (liveExitDecisionExists(session.sessionId, snapshot.snapshotId, trade)) {
				continue;
			}
			String closeJson = closeTopstepxPracticePositionViaAdapter(snapshot.snapshotId, "LIVE_EXIT", trade, trade.exitReason);
			boolean closed = jsonBoolean(closeJson, "success");
			String closeStatus = jsonText(closeJson, "status", closed ? "CLOSED_TOPSTEPX" : "CLOSE_REJECTED_TOPSTEPX");
			boolean alreadyFlat = "FLAT_SYNC_TOPSTEPX".equals(closeStatus);
			String reason = alreadyFlat
				? "TopstepX already reported no open position; local live trade state marked flat."
				: (closed
					? "TopstepX practice exit sent from live signal: " + trade.exitReason
					: "TopstepX practice exit was blocked: " + jsonStringSummary(closeJson));
			if (closed) {
				if (alreadyFlat) {
					trade.exitReason = "Broker flat sync; close fill reconciles from Topstep trades.";
					if (!brokerCloseHasAuthoritativeFill(closeJson)) {
						String pendingReason = "TopstepX already reported no open position for " + trade.symbol
							+ "; waiting for broker trade metrics before writing the final exit price and PnL.";
						String pendingJson = "{"
							+ "\"status\":\"PENDING_BROKER_RECONCILE\","
							+ "\"source\":\"TOPSTEPX_CLOSE_ADAPTER\","
							+ "\"symbol\":" + jsonString(trade.symbol) + ","
							+ "\"strategyCode\":" + jsonString(cleanOrDefault(trade.strategyCode, "")) + ","
							+ "\"entryTime\":" + jsonString(cleanOrDefault(trade.openedAt, "")) + ","
							+ "\"adapterClose\":" + jsonObjectOrDefault(closeJson, "{}") + ","
							+ "\"reason\":" + jsonString(pendingReason)
							+ "}";
						recordLiveAudit("PENDING_BROKER_RECONCILE", "WARN", pendingReason, pendingJson);
						continue;
					}
				}
				insertLiveExitDecision(session.sessionId, snapshot.snapshotId, trade, closeStatus, reason, closeJson);
				String exitReasonJson = liveExitTradeReasoningJson(trade, closeStatus, reason, closeJson);
				String exitReasonDetailsJson = jsonObjectForKey(exitReasonJson, "exit");
				String exitReasonText = jsonText(exitReasonJson, "exitReasonText", cleanOrDefault(reason, trade.exitReason));
				pushLiveEvent(
					session.sessionId,
					"POSITION_EXITED",
					"Position Exit",
					"closed",
					trade.symbol,
					trade.closedAt,
					normalizeSymbol(trade.symbol) + " " + cleanOrDefault(trade.strategyCode, "") + " " + cleanOrDefault(trade.side, "") + " exited.",
					exitReasonText,
					"{"
						+ "\"symbol\":" + jsonString(normalizeSymbol(trade.symbol)) + ","
						+ "\"strategy\":" + jsonString(cleanOrDefault(trade.strategyCode, "")) + ","
						+ "\"side\":" + jsonString(cleanOrDefault(trade.side, "")) + ","
						+ "\"contracts\":" + trade.contracts + ","
						+ "\"exitPrice\":" + round(trade.exitPrice) + ","
						+ "\"pnl\":" + round(trade.pnl) + ","
						+ "\"exitReason\":" + jsonString(exitReasonText) + ","
						+ "\"dtmAction\":" + jsonString(jsonText(exitReasonDetailsJson, "dtmFinalAction", "DTM_NO_OVERRIDE")) + ","
						+ "\"reason\":" + jsonString(cleanOrDefault(trade.exitReason, reason)) + ","
						+ "\"tradeReason\":" + exitReasonJson
						+ "}"
				);
				completed++;
			} else {
				recordLiveAudit(closeStatus, "ERROR", reason, closeJson);
				pushLiveEvent(
					session.sessionId,
					"BROKER_SYNC_ERROR",
					"Broker Sync",
					"error",
					trade.symbol,
					trade.closedAt,
					"Topstep position exit needs attention.",
					cleanOrDefault(reason, "Topstep rejected the exit request."),
					"{"
						+ "\"symbol\":" + jsonString(normalizeSymbol(trade.symbol)) + ","
						+ "\"strategy\":" + jsonString(cleanOrDefault(trade.strategyCode, "")) + ","
						+ "\"side\":" + jsonString(cleanOrDefault(trade.side, "")) + ","
						+ "\"reason\":" + jsonString(cleanOrDefault(reason, "Topstep rejected the exit request."))
						+ "}"
				);
			}
		}
		return completed;
	}

	private static int reconcileBrokerFlatLiveEntries(int sessionId, int snapshotId, String brokerMetricsJson) {
		if (sessionId <= 0 || snapshotId <= 0 || !brokerMetricsJson.contains("\"success\":true") || !brokerMetricsJson.contains("\"source\":\"TOPSTEPX\"")) {
			return 0;
		}
		List<PortfolioPosition> openPositions = liveReconcilePositionsForSession(sessionId, snapshotId);
		if (openPositions.isEmpty()) {
			return 0;
		}
		List<String> brokerPositions = jsonArrayObjects(brokerMetricsJson, "positions");
		List<String> brokerTrades = jsonArrayObjects(brokerMetricsJson, "trades");
		int reconciled = 0;
		for (int index = 0; index < openPositions.size(); index++) {
			PortfolioPosition position = openPositions.get(index);
			if (!"SUBMITTED_TOPSTEPX".equals(cleanOrDefault(position.sourceStatus, ""))) {
				continue;
			}
			if (brokerPositionExistsFor(position, brokerPositions)) {
				continue;
			}
			BrokerCloseFill closeFill = matchingBrokerCloseFill(position, brokerTrades);
			if (closeFill == null || !closeFill.matched) {
				if (!pendingBrokerReconcileExists(sessionId, snapshotId, position)) {
					String pendingReason = "TopstepX reports no open broker position for " + position.symbol
						+ ", but no matching broker close fill was found yet for order "
						+ cleanOrDefault(position.brokerOrderId, "unknown") + ".";
					String pendingJson = "{"
						+ "\"status\":\"PENDING_BROKER_RECONCILE\","
						+ "\"symbol\":" + jsonString(position.symbol) + ","
						+ "\"strategyCode\":" + jsonString(position.signal == null ? "" : position.signal.strategyCode) + ","
						+ "\"entryTime\":" + jsonString(position.openedAt) + ","
						+ "\"brokerOrderId\":" + jsonString(cleanOrDefault(position.brokerOrderId, "")) + ","
						+ "\"customTag\":" + jsonString(cleanOrDefault(position.customTag, "")) + ","
						+ "\"reason\":" + jsonString(pendingReason)
						+ "}";
					insertPendingBrokerReconcileDecision(sessionId, snapshotId, position, pendingReason, pendingJson);
					recordLiveAudit("PENDING_BROKER_RECONCILE", "WARN", pendingReason, pendingJson);
				}
				continue;
			}
			FuturesTrade trade = liveFlatSyncTrade(position, closeFill);
			if (liveAuthoritativeBrokerExitDecisionExists(sessionId, snapshotId, trade)) {
				continue;
			}
			String reason = "TopstepX matched broker close fill " + cleanOrDefault(closeFill.orderId, "unknown")
				+ " to local order " + cleanOrDefault(position.brokerOrderId, "unknown") + "; local live entry marked flat.";
			String brokerCloseJson = "{"
				+ "\"success\":true,"
				+ "\"status\":\"FLAT_SYNC_TOPSTEPX\","
				+ "\"authoritative\":true,"
				+ "\"source\":\"TOPSTEPX_METRICS_RECONCILE\","
				+ "\"transport\":\"topstepx-broker-metrics-v1\","
				+ "\"symbol\":" + jsonString(position.symbol) + ","
				+ "\"strategyCode\":" + jsonString(position.signal == null ? "" : position.signal.strategyCode) + ","
				+ "\"entryTime\":" + jsonString(position.openedAt) + ","
				+ "\"brokerOrderId\":" + jsonString(cleanOrDefault(position.brokerOrderId, "")) + ","
				+ "\"closeOrderId\":" + jsonString(cleanOrDefault(closeFill.orderId, "")) + ","
				+ "\"matchQuality\":" + jsonString(cleanOrDefault(closeFill.matchQuality, "")) + ","
				+ "\"exitPrice\":" + round(trade.exitPrice) + ","
				+ "\"fillPrice\":" + round(trade.exitPrice) + ","
				+ "\"fillTime\":" + jsonString(trade.closedAt) + ","
				+ "\"finalExitReasonCode\":" + jsonString(liveExitReasonCode("FLAT_SYNC_TOPSTEPX", trade.exitReason, "{}")) + ","
				+ "\"pnl\":" + round(trade.pnl) + ","
				+ "\"fees\":" + round(closeFill.fees)
				+ "}";
			if (!updateLiveExitDecision(sessionId, snapshotId, trade, "FLAT_SYNC_TOPSTEPX", reason, brokerCloseJson)) {
				insertLiveExitDecision(sessionId, snapshotId, trade, "FLAT_SYNC_TOPSTEPX", reason, brokerCloseJson);
			}
			recordLiveAudit("FLAT_SYNC_TOPSTEPX", "WARN", reason, brokerCloseJson);
			String exitReasonJson = liveExitTradeReasoningJson(trade, "FLAT_SYNC_TOPSTEPX", reason, brokerCloseJson);
			String exitReasonDetailsJson = jsonObjectForKey(exitReasonJson, "exit");
			String exitReasonText = jsonText(exitReasonJson, "exitReasonText", reason);
			pushLiveEvent(
				sessionId,
				"POSITION_EXITED",
				"Position Exit",
				"closed",
				trade.symbol,
				trade.closedAt,
				normalizeSymbol(trade.symbol) + " " + cleanOrDefault(trade.strategyCode, "") + " " + cleanOrDefault(trade.side, "") + " exited.",
				exitReasonText,
				"{"
					+ "\"symbol\":" + jsonString(normalizeSymbol(trade.symbol)) + ","
					+ "\"strategy\":" + jsonString(cleanOrDefault(trade.strategyCode, "")) + ","
					+ "\"side\":" + jsonString(cleanOrDefault(trade.side, "")) + ","
					+ "\"contracts\":" + trade.contracts + ","
					+ "\"exitPrice\":" + round(trade.exitPrice) + ","
					+ "\"pnl\":" + round(trade.pnl) + ","
					+ "\"exitReason\":" + jsonString(exitReasonText) + ","
					+ "\"dtmAction\":" + jsonString(jsonText(exitReasonDetailsJson, "dtmFinalAction", "DTM_NO_OVERRIDE")) + ","
					+ "\"reason\":" + jsonString(reason) + ","
					+ "\"tradeReason\":" + exitReasonJson
					+ "}"
			);
			reconciled++;
		}
		return reconciled;
	}

	private static boolean brokerPositionExistsFor(PortfolioPosition position, List<String> brokerPositions) {
		if (position == null) {
			return false;
		}
		String symbol = normalizeSymbol(position.symbol);
		for (int index = 0; index < brokerPositions.size(); index++) {
			String brokerPosition = brokerPositions.get(index);
			String brokerSymbol = normalizeSymbol(jsonText(brokerPosition, "symbol", ""));
			int contracts = (int) Math.round(jsonNumber(brokerPosition, "contracts", 0.0));
			if (symbol.equals(brokerSymbol) && contracts > 0) {
				return true;
			}
		}
		return false;
	}

	private static boolean brokerCloseHasAuthoritativeFill(String brokerCloseJson) {
		String broker = jsonObjectOrDefault(brokerCloseJson, "{}");
		if (jsonBoolean(broker, "authoritative") || broker.contains("\"source\":\"TOPSTEPX_METRICS_RECONCILE\"")) {
			return true;
		}
		double exitPrice = jsonNumber(broker, "exitPrice", jsonNumber(broker, "fillPrice", 0.0));
		String fillTime = firstNonBlank(jsonText(broker, "fillTime", ""), jsonText(broker, "closedAt", ""));
		return exitPrice > 0.0 && fillTime.length() > 0;
	}

	private static FuturesTrade liveFlatSyncTrade(PortfolioPosition position, BrokerCloseFill closeFill) {
		FuturesTrade trade = new FuturesTrade();
			trade.symbol = normalizeSymbol(position.symbol);
			trade.strategyCode = position.signal == null ? "" : cleanOrDefault(position.signal.strategyCode, "");
			trade.strategyName = position.signal == null ? "" : cleanOrDefault(position.signal.strategyName, "");
			trade.sourceStrategyCode = position.signal == null ? "" : cleanOrDefault(position.signal.sourceStrategyCode, "");
			trade.sourceStrategyName = position.signal == null ? "" : cleanOrDefault(position.signal.sourceStrategyName, "");
			trade.side = cleanOrDefault(position.side, "LONG");
			trade.contracts = position.contracts;
			trade.originalContracts = position.originalContracts <= 0 ? position.contracts + position.dtmPartialContractsClosed : position.originalContracts;
			trade.entryPrice = position.entryPrice;
		trade.exitPrice = closeFill != null && closeFill.price > 0.0 ? closeFill.price : position.entryPrice;
		trade.stopPrice = position.stopPrice;
		trade.targetPrice = position.targetPrice;
		trade.openedAt = cleanOrDefault(position.openedAt, "");
			trade.closedAt = closeFill != null && closeFill.createdAt.length() > 0 ? closeFill.createdAt : LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
			trade.pnl = closeFill == null ? 0.0 : closeFill.pnl;
			trade.finalLegPnl = trade.pnl;
			trade.mfe = 0.0;
		trade.mae = 0.0;
		trade.exitReason = brokerFlatSyncExitReason(position, closeFill, trade.exitPrice);
		trade.dtmTimelineJson = position.dtmTimelineJson;
		trade.dtmFinalAction = position.dtmFinalAction;
		trade.dtmPartialDecision = position.dtmPartialDecision;
		trade.dtmRunnerDecision = position.dtmRunnerDecision;
		trade.dtmPartialContractsClosed = position.dtmPartialContractsClosed;
		trade.dtmRealizedPnl = position.dtmRealizedPnl;
		trade.openedMarketTime = position.openedMarketTime;
		LocalDateTime closedAt = parseDisplayLocalDateTime(trade.closedAt);
		trade.closedMarketTime = closedAt == null ? null : closedAt.toLocalTime();
		return trade;
	}

	private static String brokerFlatSyncExitReason(PortfolioPosition position, BrokerCloseFill closeFill, double exitPrice) {
		if (closeFill == null || cleanOrDefault(closeFill.orderId, "").length() == 0) {
			return "Broker flat sync; no open Topstep position.";
		}
		double targetDistance = Math.abs(exitPrice - position.targetPrice);
		double stopDistance = Math.abs(exitPrice - position.stopPrice);
		String fillType = targetDistance <= stopDistance ? "target" : "stop-loss";
		return "Broker " + fillType + " fill; Topstep order " + closeFill.orderId + ".";
	}

	private static BrokerCloseFill matchingBrokerCloseFill(PortfolioPosition position, List<String> brokerTrades) {
		BrokerCloseFill bestLineage = null;
		BrokerCloseFill bestFallback = null;
		long bestFallbackMillis = Long.MAX_VALUE;
		if (position == null || brokerTrades == null || brokerTrades.isEmpty()) {
			return null;
		}
		String symbol = normalizeSymbol(position.symbol);
		String expectedClosingSide = "SHORT".equalsIgnoreCase(position.side) ? "BUY" : "SELL";
		long openedMillis = parseChartComparableTime(position.openedAt);
		for (int index = 0; index < brokerTrades.size(); index++) {
			String trade = brokerTrades.get(index);
			if (!brokerTradeAccountMatches(position, trade)) {
				continue;
			}
			if (!symbol.equals(normalizeSymbol(jsonText(trade, "symbol", "")))) {
				continue;
			}
			String side = cleanOrDefault(jsonText(trade, "side", ""), "").toUpperCase(Locale.US);
			if (expectedClosingSide.length() > 0 && side.length() > 0 && !expectedClosingSide.equals(side)) {
				continue;
			}
			if (!jsonBoolean(trade, "closed")) {
				continue;
			}
			String createdAt = firstNonBlank(jsonText(trade, "createdAt", ""), jsonText(trade, "closedAt", ""));
			long createdMillis = parseChartComparableTime(createdAt);
			if (openedMillis > 0L && createdMillis > 0L && createdMillis < openedMillis) {
				continue;
			}
			BrokerCloseFill candidate = brokerCloseFillFromTrade(trade, createdAt);
				if (brokerCloseBelongsToEntry(position, candidate)) {
					if (bestLineage == null || createdMillis >= parseChartComparableTime(bestLineage.createdAt)) {
						candidate.matched = true;
						candidate.matchQuality = "ORDER_LINEAGE";
						bestLineage = candidate;
					}
					continue;
				}
				if (brokerCloseFallbackEligible(position, candidate, createdMillis, openedMillis)) {
					long comparableMillis = createdMillis > 0L ? createdMillis : Long.MAX_VALUE - index;
					if (bestFallback == null || comparableMillis < bestFallbackMillis) {
						candidate.matched = true;
						candidate.matchQuality = "ACCOUNT_SYMBOL_SIDE_AFTER_ENTRY";
						bestFallback = candidate;
						bestFallbackMillis = comparableMillis;
					}
				}
			}
			return bestLineage != null ? bestLineage : bestFallback;
		}

	private static BrokerCloseFill brokerCloseFillFromTrade(String trade, String createdAt) {
		BrokerCloseFill fill = new BrokerCloseFill();
		fill.orderId = brokerOrderIdFromJson(trade);
		fill.createdAt = createdAt;
		fill.price = jsonNumber(trade, "price", jsonNumber(trade, "exitPrice", 0.0));
		fill.pnl = jsonNumber(trade, "pnl", 0.0);
		fill.fees = jsonNumber(trade, "fees", jsonNumber(trade, "commission", 0.0));
		return fill;
	}

	private static boolean brokerTradeAccountMatches(PortfolioPosition position, String trade) {
		String expected = cleanOrDefault(position == null ? "" : position.accountId, "");
		if (expected.length() == 0) {
			return true;
		}
		String actual = cleanOrDefault(jsonText(trade, "accountId", ""), "");
		return actual.length() == 0 || expected.equals(actual);
	}

	private static boolean brokerCloseBelongsToEntry(PortfolioPosition position, BrokerCloseFill closeFill) {
		if (position == null || closeFill == null) {
			return false;
		}
		String closeOrderId = cleanOrderId(closeFill.orderId);
		String entryOrderId = cleanOrderId(position.brokerOrderId);
		if (closeOrderId.length() == 0) {
			return false;
		}
		if (entryOrderId.length() > 0 && closeOrderId.equals(entryOrderId)) {
			return true;
		}
		if (position.customTag != null && position.customTag.trim().length() > 0 && realtimeOrderHasCustomTag(closeOrderId, position.customTag)) {
			return true;
		}
		return bracketChildOrderIdLooksRelated(entryOrderId, closeOrderId);
	}

	private static boolean brokerCloseFallbackEligible(PortfolioPosition position, BrokerCloseFill closeFill, long closeMillis, long openedMillis) {
		if (position == null || closeFill == null) {
			return false;
		}
		if (openedMillis > 0L && closeMillis > 0L && closeMillis < openedMillis) {
			return false;
		}
		double entryDistance = Math.abs(closeFill.price - position.entryPrice);
		double targetDistance = position.targetPrice > 0.0 ? Math.abs(closeFill.price - position.targetPrice) : Double.MAX_VALUE;
		double stopDistance = position.stopPrice > 0.0 ? Math.abs(closeFill.price - position.stopPrice) : Double.MAX_VALUE;
		double risk = position.initialRisk > 0.0 ? position.initialRisk : Math.abs(position.entryPrice - position.stopPrice);
		boolean priceLooksRelevant = closeFill.price <= 0.0
			|| risk <= 0.0
			|| entryDistance <= risk * 4.0
			|| targetDistance <= risk * 1.5
			|| stopDistance <= risk * 1.5;
		return priceLooksRelevant;
	}

	private static boolean bracketChildOrderIdLooksRelated(String entryOrderId, String closeOrderId) {
		long entry = parseOrderIdLong(entryOrderId);
		long close = parseOrderIdLong(closeOrderId);
		return entry > 0L && close > entry && close <= entry + 4L;
	}

	private static boolean realtimeOrderHasCustomTag(String orderId, String baseCustomTag) {
		String cleanOrderId = cleanOrderId(orderId);
		String cleanTag = cleanOrDefault(baseCustomTag, "");
		if (cleanOrderId.length() == 0 || cleanTag.length() == 0) {
			return false;
		}
		String sql = "SELECT payloadJson FROM FuturesLiveRealtimeEvents "
			+ "WHERE hub = 'user' AND eventType = 'GatewayUserOrder' AND payloadJson LIKE ? "
			+ "ORDER BY realtimeEventID DESC LIMIT 50";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setString(1, "%" + cleanTag + "%");
			try (ResultSet rs = pstmt.executeQuery()) {
				while (rs.next()) {
					String payload = cleanOrDefault(rs.getString("payloadJson"), "{}");
					String eventOrderId = cleanOrderId(String.valueOf((long) jsonFirstNumber(payload, new String[] { "id" }, 0.0)));
					String eventTag = jsonText(payload, "customTag", "");
					if (cleanOrderId.equals(eventOrderId) && (eventTag.equals(cleanTag) || eventTag.startsWith(cleanTag + "-"))) {
						return true;
					}
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return false;
	}

	private static String cleanOrderId(String value) {
		String clean = cleanOrDefault(value, "").trim();
		if (clean.length() == 0) {
			return "";
		}
		double numeric = parseDouble(clean, Double.NaN);
		if (!Double.isNaN(numeric) && numeric > 0.0) {
			return String.valueOf((long) numeric);
		}
		return clean;
	}

	private static long parseOrderIdLong(String value) {
		String clean = cleanOrderId(value);
		if (clean.length() == 0) {
			return 0L;
		}
		try {
			return Long.parseLong(clean);
		} catch (Exception ignored) {
			return 0L;
		}
	}

	private static long parseChartComparableTime(String value) {
		String clean = cleanOrDefault(value, "").trim();
		if (clean.length() == 0) {
			return 0L;
		}
		try {
			return OffsetDateTime.parse(clean).toInstant().toEpochMilli();
		} catch (Exception ignored) {
		}
		try {
			return ZonedDateTime.parse(clean).toInstant().toEpochMilli();
		} catch (Exception ignored) {
		}
		try {
			return LocalDateTime.parse(clean, DateTimeFormatter.ISO_LOCAL_DATE_TIME)
				.atZone(NEW_YORK_ZONE)
				.toInstant()
				.toEpochMilli();
		} catch (Exception ignored) {
		}
		LocalDateTime parsed = parseDisplayLocalDateTime(clean);
		if (parsed == null) {
			return 0L;
		}
		return parsed.atZone(NEW_YORK_ZONE).toInstant().toEpochMilli();
	}

	private static List<FuturesTrade> closeTriggeredLivePositions(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		List<PortfolioPosition> positions,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBars
	) {
		List<FuturesTrade> trades = new ArrayList<FuturesTrade>();
		if (positions == null || positions.isEmpty() || contexts == null || currentBars == null) {
			return trades;
		}
		for (int index = positions.size() - 1; index >= 0; index--) {
			PortfolioPosition position = positions.get(index);
			PortfolioSymbolContext context = contexts.get(position.symbol);
			Bar bar = currentBars.get(position.symbol);
			if (context == null || bar == null || bar.marketDate == null || bar.marketTime == null) {
				continue;
			}
			hydrateLivePositionState(position, context, bar);
			applyDynamicTradeStateToPosition(session == null ? 0 : session.sessionId, snapshot == null ? 0 : snapshot.snapshotId, position);
			boolean dtmActive = session != null && session.dtmEnabled;
			FuturesTrade triggeredTrade = dtmActive
				? closePortfolioPositionIfStopTriggered(position, context, bar, bar.marketDate, bar.marketTime)
				: closePortfolioPositionIfTriggered(position, context, bar, bar.marketDate, bar.marketTime);
			if (triggeredTrade != null) {
				applyDynamicTradeStateToTrade(session == null ? 0 : session.sessionId, snapshot == null ? 0 : snapshot.snapshotId, position, triggeredTrade, "");
				trades.add(0, triggeredTrade);
				positions.remove(index);
				continue;
			}
			if (dtmActive) {
				double preDtmTargetPrice = position.targetPrice;
				DynamicTradeDecision dtmDecision = evaluateDynamicTradeManager(session, snapshot, position, context, bar);
				if (dtmDecision != null && dtmDecision.finalExit) {
					FuturesTrade dtmTrade = buildPortfolioTrade(position, context, bar, currentIndexOrEntry(position, context, bar), bar.close, dtmDecision.exitReason);
					applyDynamicTradeStateToTrade(session.sessionId, snapshot == null ? 0 : snapshot.snapshotId, position, dtmTrade, dtmDecision.actionCode);
					trades.add(0, dtmTrade);
					positions.remove(index);
					continue;
				}
				FuturesTrade postDtmTrade = closePortfolioPositionAfterDtmDecision(position, context, bar, bar.marketDate, bar.marketTime, dtmDecision, preDtmTargetPrice);
				if (postDtmTrade != null) {
					applyDynamicTradeStateToTrade(session.sessionId, snapshot == null ? 0 : snapshot.snapshotId, position, postDtmTrade, "");
					trades.add(0, postDtmTrade);
					positions.remove(index);
				}
			}
		}
		return trades;
	}

	private static DynamicTradeDecision evaluateDynamicTradeManager(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		PortfolioPosition position,
		PortfolioSymbolContext context,
		Bar bar
	) {
		return evaluateDynamicTradeManager(session, snapshot, position, context, bar, null, true);
	}

	private static DynamicTradeDecision evaluateDynamicTradeManager(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		PortfolioPosition position,
		PortfolioSymbolContext context,
		Bar bar,
		LiveRuntimeState.OrderFlowSnapshot orderFlow,
		boolean publishLiveEvent
	) {
		if (session == null || snapshot == null || position == null || context == null || bar == null || position.initialRisk <= 0.0) {
			return null;
		}
		DynamicTradeState state = dynamicTradeState(session.sessionId, snapshot.snapshotId, position, true);
		if (state == null) {
			return null;
		}
		if (state.remainingContracts <= 0) {
			state.remainingContracts = Math.max(1, position.contracts);
		}
		position.contracts = Math.max(1, state.remainingContracts);
		double favorableMove = favorableMovePoints(position, favorableExtremePrice(position, bar));
		double adverseMove = adverseMovePoints(position, adverseExtremePrice(position, bar));
		double favorableR = favorableMove / position.initialRisk;
		double adverseR = adverseMove / position.initialRisk;
		double favorableCloseR = favorableMovePoints(position, bar.close) / position.initialRisk;
		double adverseCloseR = adverseMovePoints(position, bar.close) / position.initialRisk;
		double targetR = dtmTargetR(position);
		int currentIndex = currentIndexOrEntry(position, context, bar);
		int barsHeld = Math.max(0, currentIndex - Math.max(0, position.entryIndex));
		double breakevenTriggerR = dtmTargetAwareTrigger(DTM_BREAKEVEN_TRIGGER_R, targetR, DTM_BREAKEVEN_TARGET_FRACTION, 1.35);
		double partialTriggerR = dtmTargetAwareTrigger(DTM_PARTIAL_TRIGGER_R, targetR, DTM_PARTIAL_TARGET_FRACTION, 2.50);
		double trailTriggerR = dtmTargetAwareTrigger(DTM_TRAIL_TRIGGER_R, targetR, DTM_TRAIL_TARGET_FRACTION, 2.00);
		LiveRuntimeState.OrderFlowSnapshot flow = orderFlow == null ? LiveRuntimeState.orderFlowSnapshot(position.symbol) : orderFlow;
		boolean flowAgainst = orderFlowAgainstPosition(position.side, flow);
		boolean strongFlowAgainst = strongOrderFlowAgainstPosition(position.side, flow);
		boolean trendAgainst = trendAgainstPosition(position.side, bar);
		boolean continuationAligned = dtmContinuationAligned(position, bar, flow, trendAgainst, strongFlowAgainst);
		double extensionTriggerR = dtmExtensionTriggerR(targetR);
		double extensionAcceptanceR = dtmExtensionAcceptanceR(targetR);
		String dtmState = dtmStateName(position, state, favorableCloseR, adverseCloseR, flowAgainst, trendAgainst, breakevenTriggerR, partialTriggerR);
		state.stateName = dtmState;
		boolean thesisInvalidated = dtmThesisInvalidated(position, context, bar, strongFlowAgainst, trendAgainst, adverseCloseR);
		boolean earlyCutMature = barsHeld >= dtmMinimumBarsBeforeEarlyCut(position);
		boolean exitEvidence = earlyCutMature
			&& adverseCloseR >= DTM_EARLY_CUT_CLOSE_ADVERSE_R
			&& thesisInvalidated
			&& (trendAgainst || strongFlowAgainst);
		if (exitEvidence) {
			if (state.lastExitEvidenceIndex != currentIndex) {
				state.exitEvidenceCount++;
				state.lastExitEvidenceIndex = currentIndex;
			}
		} else {
			state.exitEvidenceCount = 0;
			state.lastExitEvidenceIndex = -1;
		}
		boolean emergencyExit = earlyCutMature && adverseCloseR >= DTM_EMERGENCY_CUT_ADVERSE_R && thesisInvalidated && (trendAgainst || strongFlowAgainst);
		boolean normalExitArmed = exitEvidence && state.exitEvidenceCount >= DTM_EXIT_EVIDENCE_BARS_REQUIRED;
		if ((emergencyExit || normalExitArmed) && !state.exitRequested) {
			DynamicTradeDecision decision = new DynamicTradeDecision();
			decision.actionCode = "DTM_CUT_EARLY_THESIS_FAILED";
			decision.exitReason = "DTM early cut: thesis failed before hard stop";
			decision.stateName = "EXIT_ARMED";
			decision.normalizedAction = "CUT_EARLY";
			decision.reason = "DTM cut early because the trade held for " + barsHeld + " bars, closed " + liveNumberText(adverseCloseR) + "R adverse, and structure plus strong market/order-flow evidence confirmed thesis failure.";
			decision.finalExit = true;
			decision.detailsJson = dtmDetailsJson(position, bar, flow, favorableR, adverseR, favorableCloseR, adverseCloseR, targetR, barsHeld, 0, 0.0, 0.0, true, decision.stateName, decision.normalizedAction, state.exitEvidenceCount);
			state.exitRequested = true;
			recordDynamicTradeDecision(session, snapshot, position, state, decision, bar, publishLiveEvent);
			return decision;
		}
		if (dtmOneContractExtensionEnabled()
			&& position.contracts == 1
			&& !state.partialTaken
			&& !state.targetExtended
			&& barsHeld >= dtmMinimumBarsBeforeTargetManagement(position)
			&& favorableCloseR >= extensionAcceptanceR
			&& continuationAligned) {
			DynamicTradeDecision extensionDecision = dtmTargetExtensionDecision(
				session,
				snapshot,
				position,
				state,
				bar,
				flow,
				favorableR,
				adverseR,
				favorableCloseR,
				adverseCloseR,
				targetR,
				barsHeld,
				true,
				publishLiveEvent
			);
			if (extensionDecision != null) {
				return extensionDecision;
			}
		}
		if (barsHeld >= dtmMinimumBarsBeforeProtect(position) && favorableCloseR >= breakevenTriggerR && !state.breakevenMoved) {
			double stop = "LONG".equals(position.side)
				? roundToTick(position.spec, position.entryPrice + position.spec.tickSize)
				: roundToTick(position.spec, position.entryPrice - position.spec.tickSize);
			if (stopImprovesRisk(position, stop)) {
				DynamicTradeDecision decision = new DynamicTradeDecision();
				decision.actionCode = "DTM_MOVE_STOP_BREAKEVEN";
				decision.stateName = "PROTECT";
				decision.normalizedAction = "MOVE_STOP_BREAKEVEN";
				decision.stopPrice = stop;
				decision.reason = "DTM moved stop to breakeven after the trade closed " + liveNumberText(favorableCloseR) + "R favorable against a " + liveNumberText(targetR) + "R target.";
				decision.detailsJson = dtmDetailsJson(position, bar, flow, favorableR, adverseR, favorableCloseR, adverseCloseR, targetR, barsHeld, 0, stop, 0.0, false, decision.stateName, decision.normalizedAction, state.exitEvidenceCount);
				String brokerJson = dynamicBrokerModifyProtectiveOrdersJson(session, snapshot, position, stop, 0.0, position.contracts);
				decision.brokerAction = jsonBoolean(brokerJson, "success");
				decision.detailsJson = mergeSimpleJson(decision.detailsJson, "\"brokerModify\":" + jsonObjectOrDefault(brokerJson, "{}"));
				if (decision.brokerAction) {
					position.activeStopPrice = stop;
					state.lastStopPrice = stop;
				}
				state.breakevenMoved = true;
				recordDynamicTradeDecision(session, snapshot, position, state, decision, bar, publishLiveEvent);
				return decision;
			}
			state.breakevenMoved = true;
		}
		if (position.contracts > 1 && barsHeld >= dtmMinimumBarsBeforeTargetManagement(position) && favorableCloseR >= partialTriggerR && !state.partialTaken && !state.partialCloseBlocked) {
			boolean experimentalHalfRunner = dtmExperimentalHalfRunnerEnabled() && dtmExperimentalHalfRunnerQualified(position, targetR);
			int closeContracts = Math.max(1, position.contracts / 2);
			int remaining = Math.max(1, position.contracts - closeContracts);
			double experimentalExtensionTriggerR = experimentalHalfRunner
				? dtmExperimentalHalfRunnerTriggerR(partialTriggerR, targetR, extensionAcceptanceR)
				: extensionAcceptanceR;
			boolean extendRunner = dtmDynamicProtectiveOrdersEnabled()
				&& !state.targetExtended
				&& favorableCloseR >= experimentalExtensionTriggerR
				&& (experimentalHalfRunner ? dtmExperimentalRunnerAligned(position, bar, flow, trendAgainst, strongFlowAgainst) : continuationAligned);
			double runnerStop = extendRunner
				? (experimentalHalfRunner ? dtmExperimentalRunnerStop(position, favorableCloseR) : dtmProfitLockStop(position, favorableCloseR, targetR, false))
				: 0.0;
			double runnerTarget = extendRunner ? dtmExtendedTargetPrice(position, targetR) : 0.0;
			if (extendRunner && (!stopImprovesRisk(position, runnerStop) || !targetImprovesReward(position, runnerTarget))) {
				extendRunner = false;
				runnerStop = 0.0;
				runnerTarget = 0.0;
			}
			if (experimentalHalfRunner && !extendRunner) {
				return null;
			}
			DynamicTradeDecision decision = new DynamicTradeDecision();
			decision.actionCode = experimentalHalfRunner ? "DTM_PARTIAL_HALF_RUNNER_EXTENDED" : "DTM_PARTIAL_TARGET";
			decision.stateName = "TARGET_DECISION";
			decision.normalizedAction = "PARTIAL_EXIT";
			decision.partialContracts = closeContracts;
			decision.reason = experimentalHalfRunner
				? "DTM partially sold half the position, kept " + remaining + " runner contract" + (remaining == 1 ? "" : "s") + ", raised the runner target, and locked a profitable stop because continuation stayed aligned."
				: "DTM partially sold " + closeContracts + " contract" + (closeContracts == 1 ? "" : "s") + " near the original target zone and kept " + remaining + " runner contract" + (remaining == 1 ? "" : "s") + ".";
			if (extendRunner) {
				decision.stopPrice = runnerStop;
				decision.targetPrice = runnerTarget;
				if (!experimentalHalfRunner) {
					decision.reason += " DTM also extended the runner target and locked a profitable stop because continuation stayed aligned.";
				}
			}
			decision.detailsJson = dtmDetailsJson(position, bar, flow, favorableR, adverseR, favorableCloseR, adverseCloseR, targetR, barsHeld, closeContracts, runnerStop, runnerTarget, false, decision.stateName, decision.normalizedAction, state.exitEvidenceCount);
			String brokerJson = dynamicBrokerPartialCloseJson(session, snapshot, position, closeContracts);
			decision.brokerAction = jsonBoolean(brokerJson, "success");
			decision.detailsJson = mergeSimpleJson(decision.detailsJson, "\"brokerPartialClose\":" + jsonObjectOrDefault(brokerJson, "{}"));
			if (decision.brokerAction) {
				double partialPnl = pnlForPrice(position.spec, position.side, position.entryPrice, bar.close, closeContracts)
					- (position.commissionPerContract * closeContracts * 2.0);
				state.realizedPnl += round(partialPnl);
				state.partialContractsClosed += closeContracts;
				state.remainingContracts = remaining;
				state.partialTaken = true;
				state.partialDecision = decision.reason;
				state.runnerDecision = experimentalHalfRunner
					? "Runner held after a single half-partial with an extended target and profitable stop lock."
					: "Runner held after partial using the original target and current protective stop.";
				position.contracts = remaining;
				position.dtmRealizedPnl = state.realizedPnl;
				position.dtmPartialContractsClosed = state.partialContractsClosed;
				position.dtmPartialDecision = state.partialDecision;
				position.dtmRunnerDecision = state.runnerDecision;
				String modifyJson = dynamicBrokerModifyProtectiveOrdersJson(
					session,
					snapshot,
					position,
					extendRunner ? runnerStop : (state.lastStopPrice > 0.0 ? state.lastStopPrice : position.activeStopPrice),
					extendRunner ? runnerTarget : position.targetPrice,
					remaining
				);
				decision.detailsJson = mergeSimpleJson(decision.detailsJson, "\"brokerModify\":" + jsonObjectOrDefault(modifyJson, "{}"));
				if (extendRunner && jsonBoolean(modifyJson, "success")) {
					position.activeStopPrice = runnerStop;
					position.targetPrice = runnerTarget;
					state.lastStopPrice = runnerStop;
					state.lastTargetPrice = runnerTarget;
					state.targetExtended = true;
					state.runnerDecision = experimentalHalfRunner
						? "Runner target extended with profit lock immediately after the single half-partial."
						: "Runner target extended with profit lock after partial because continuation evidence stayed aligned.";
					position.dtmRunnerDecision = state.runnerDecision;
				}
			} else {
				state.partialCloseBlocked = true;
				state.remainingContracts = Math.max(1, position.contracts);
				decision.actionCode = "DTM_PARTIAL_BLOCKED";
				decision.normalizedAction = "HOLD_STATIC";
				decision.reason = "DTM attempted a partial close, but broker confirmation failed; DTM kept managing the full position and did not assume a runner.";
				state.partialDecision = decision.reason;
			}
			recordDynamicTradeDecision(session, snapshot, position, state, decision, bar, publishLiveEvent);
			return decision;
		}
		if (dtmDynamicProtectiveOrdersEnabled()
			&& state.partialTaken
			&& !state.targetExtended
			&& barsHeld >= dtmMinimumBarsBeforeTargetManagement(position)
			&& favorableCloseR >= extensionAcceptanceR
			&& continuationAligned) {
			DynamicTradeDecision extensionDecision = dtmTargetExtensionDecision(
				session,
				snapshot,
				position,
				state,
				bar,
				flow,
				favorableR,
				adverseR,
				favorableCloseR,
				adverseCloseR,
				targetR,
				barsHeld,
				false,
				publishLiveEvent
			);
			if (extensionDecision != null) {
				return extensionDecision;
			}
		}
		if (barsHeld >= dtmMinimumBarsBeforeTargetManagement(position) && favorableCloseR >= trailTriggerR) {
			double trail = updateManagedStop(position.spec, position.side, position.entryPrice, position.activeStopPrice, bar.close, position.initialRisk, position.minTrailDistance);
			if (stopImprovesRisk(position, trail) && Math.abs(trail - state.lastStopPrice) >= position.spec.tickSize - 0.000001) {
				DynamicTradeDecision decision = new DynamicTradeDecision();
				decision.actionCode = "DTM_TRAIL_STOP";
				decision.stateName = "PROTECT";
				decision.normalizedAction = "TRAIL_STOP";
				decision.stopPrice = trail;
				decision.reason = "DTM trailed the protective stop after the trade closed " + liveNumberText(favorableCloseR) + "R favorable against a " + liveNumberText(targetR) + "R target.";
				decision.detailsJson = dtmDetailsJson(position, bar, flow, favorableR, adverseR, favorableCloseR, adverseCloseR, targetR, barsHeld, 0, trail, 0.0, false, decision.stateName, decision.normalizedAction, state.exitEvidenceCount);
				String brokerJson = dynamicBrokerModifyProtectiveOrdersJson(session, snapshot, position, trail, 0.0, position.contracts);
				decision.brokerAction = jsonBoolean(brokerJson, "success");
				decision.detailsJson = mergeSimpleJson(decision.detailsJson, "\"brokerModify\":" + jsonObjectOrDefault(brokerJson, "{}"));
				if (decision.brokerAction) {
					position.activeStopPrice = trail;
					state.lastStopPrice = trail;
				}
				recordDynamicTradeDecision(session, snapshot, position, state, decision, bar, publishLiveEvent);
				return decision;
			}
		}
		return null;
	}

	private static DynamicTradeDecision dtmTargetExtensionDecision(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		PortfolioPosition position,
		DynamicTradeState state,
		Bar bar,
		LiveRuntimeState.OrderFlowSnapshot flow,
		double favorableR,
		double adverseR,
		double favorableCloseR,
		double adverseCloseR,
		double targetR,
		int barsHeld,
		boolean oneContractRunner,
		boolean publishLiveEvent
	) {
		double stop = dtmProfitLockStop(position, favorableCloseR, targetR, oneContractRunner);
		double target = dtmExtendedTargetPrice(position, targetR);
		if (!stopImprovesRisk(position, stop) || !targetImprovesReward(position, target)) {
			return null;
		}
		DynamicTradeDecision decision = new DynamicTradeDecision();
		decision.actionCode = oneContractRunner ? "DTM_EXTEND_ONE_CONTRACT_RUNNER" : "DTM_EXTEND_TARGET_CONTINUATION";
		decision.stateName = "RUNNER";
		decision.normalizedAction = "EXTEND_TARGET";
		decision.stopPrice = stop;
		decision.targetPrice = target;
		decision.reason = oneContractRunner
			? "DTM converted the one-contract trade into a protected runner because price closed near the original target and continuation evidence stayed aligned."
			: "DTM extended the runner target and tightened the stop because price closed near the original target and continuation evidence stayed aligned.";
		decision.detailsJson = dtmDetailsJson(position, bar, flow, favorableR, adverseR, favorableCloseR, adverseCloseR, targetR, barsHeld, 0, stop, target, false, decision.stateName, decision.normalizedAction, state.exitEvidenceCount);
		String brokerJson = dynamicBrokerModifyProtectiveOrdersJson(session, snapshot, position, stop, target, position.contracts);
		decision.brokerAction = jsonBoolean(brokerJson, "success");
		decision.detailsJson = mergeSimpleJson(decision.detailsJson, "\"brokerModify\":" + jsonObjectOrDefault(brokerJson, "{}"));
		if (!decision.brokerAction) {
			return null;
		}
		position.activeStopPrice = stop;
		position.targetPrice = target;
		state.lastStopPrice = stop;
		state.lastTargetPrice = target;
		state.targetExtended = true;
		state.oneContractExtended = oneContractRunner;
		state.runnerDecision = decision.reason;
		position.dtmRunnerDecision = state.runnerDecision;
		recordDynamicTradeDecision(session, snapshot, position, state, decision, bar, publishLiveEvent);
		return decision;
	}

	private static String dynamicBrokerModifyProtectiveOrdersJson(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		PortfolioPosition position,
		double stopPrice,
		double targetPrice,
		int contracts
	) {
		if (session == null || !"TOPSTEPX".equals(cleanOrDefault(session.executionMode, ""))) {
			return "{"
				+ "\"success\":true,"
				+ "\"status\":\"SIMULATED_DTM_MODIFY\","
				+ "\"source\":\"LOCAL_DTM_SIMULATION\","
				+ "\"executionMode\":" + jsonString(session == null ? "" : cleanOrDefault(session.executionMode, "SIMULATED")) + ","
				+ "\"symbol\":" + jsonString(position == null ? "" : normalizeSymbol(position.symbol)) + ","
				+ "\"stopPrice\":" + round(stopPrice) + ","
				+ "\"targetPrice\":" + round(targetPrice) + ","
				+ "\"contracts\":" + Math.max(0, contracts) + ","
				+ "\"message\":\"DTM protective-order state updated locally because this session is not using TopstepX execution.\""
				+ "}";
		}
		return FuturesConnectionManager.modifyTopstepxPracticeProtectiveOrders(
			selectedTopstepAccountId(snapshot, session.fundedProfile),
			position == null ? "" : position.symbol,
			stopPrice,
			targetPrice,
			contracts
		);
	}

	private static String dynamicBrokerPartialCloseJson(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		PortfolioPosition position,
		int closeContracts
	) {
		if (session == null || !"TOPSTEPX".equals(cleanOrDefault(session.executionMode, ""))) {
			return "{"
				+ "\"success\":true,"
				+ "\"status\":\"SIMULATED_DTM_PARTIAL_CLOSE\","
				+ "\"source\":\"LOCAL_DTM_SIMULATION\","
				+ "\"executionMode\":" + jsonString(session == null ? "" : cleanOrDefault(session.executionMode, "SIMULATED")) + ","
				+ "\"symbol\":" + jsonString(position == null ? "" : normalizeSymbol(position.symbol)) + ","
				+ "\"contracts\":" + Math.max(0, closeContracts) + ","
				+ "\"message\":\"DTM partial-close state updated locally because this session is not using TopstepX execution.\""
				+ "}";
		}
		return FuturesConnectionManager.partialCloseTopstepxPracticeSymbolPosition(
			selectedTopstepAccountId(snapshot, session.fundedProfile),
			position == null ? "" : position.symbol,
			closeContracts
		);
	}

	private static void recordDynamicTradeDecision(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		PortfolioPosition position,
		DynamicTradeState state,
		DynamicTradeDecision decision,
		Bar bar
	) {
		recordDynamicTradeDecision(session, snapshot, position, state, decision, bar, true);
	}

	private static void recordDynamicTradeDecision(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		PortfolioPosition position,
		DynamicTradeState state,
		DynamicTradeDecision decision,
		Bar bar,
		boolean publishLiveEvent
	) {
		if (session == null || position == null || state == null || decision == null) {
			return;
		}
		String eventJson = "{"
			+ "\"time\":" + jsonString(bar == null ? LocalDateTime.now().format(DISPLAY_TIME_FORMAT) : cleanOrDefault(bar.displayTime, "")) + ","
			+ "\"actionCode\":" + jsonString(decision.actionCode) + ","
			+ "\"state\":" + jsonString(cleanOrDefault(decision.stateName, state.stateName)) + ","
			+ "\"normalizedAction\":" + jsonString(cleanOrDefault(decision.normalizedAction, "HOLD_STATIC")) + ","
			+ "\"reason\":" + jsonString(decision.reason) + ","
			+ "\"details\":" + jsonObjectOrDefault(decision.detailsJson, "{}")
			+ "}";
		state.timelineJson = appendJsonObjectToArray(state.timelineJson, eventJson);
		state.finalAction = decision.actionCode;
		position.dtmTimelineJson = state.timelineJson;
		position.dtmFinalAction = state.finalAction;
		position.dtmPartialDecision = state.partialDecision;
		position.dtmRunnerDecision = state.runnerDecision;
		if (!publishLiveEvent) {
			return;
		}
		FuturesTrade logTrade = liveTradeFromPositionForDtm(position, bar);
		pushLiveDtmDecisionEvent(
			session.sessionId,
			logTrade,
			decision.actionCode,
			dtmTitle(decision.actionCode),
			decision.reason,
			decision.detailsJson
		);
	}

	private static FuturesTrade liveTradeFromPositionForDtm(PortfolioPosition position, Bar bar) {
		FuturesTrade trade = new FuturesTrade();
		if (position == null) {
			return trade;
		}
			trade.symbol = position.symbol;
			trade.strategyCode = position.signal == null ? "" : position.signal.strategyCode;
			trade.strategyName = position.signal == null ? "" : position.signal.strategyName;
			trade.sourceStrategyCode = position.signal == null ? "" : cleanOrDefault(position.signal.sourceStrategyCode, "");
			trade.sourceStrategyName = position.signal == null ? "" : cleanOrDefault(position.signal.sourceStrategyName, "");
			trade.side = position.side;
			trade.contracts = position.contracts;
			trade.originalContracts = position.originalContracts <= 0 ? position.contracts + position.dtmPartialContractsClosed : position.originalContracts;
			trade.entryPrice = position.entryPrice;
			trade.exitPrice = bar == null ? 0.0 : bar.close;
		trade.stopPrice = position.stopPrice;
		trade.targetPrice = position.targetPrice;
		trade.openedAt = position.openedAt;
		trade.closedAt = bar == null ? "" : bar.displayTime;
		return trade;
	}

	private static void applyDynamicTradeStateToTrade(int sessionId, int snapshotId, PortfolioPosition position, FuturesTrade trade, String finalActionOverride) {
		if (position == null || trade == null) {
			return;
		}
		DynamicTradeState state = dynamicTradeState(sessionId, snapshotId, position, false);
			if (state == null) {
				trade.dtmTimelineJson = position.dtmTimelineJson;
				trade.dtmFinalAction = firstNonBlank(finalActionOverride, position.dtmFinalAction);
				trade.dtmPartialDecision = position.dtmPartialDecision;
				trade.dtmRunnerDecision = position.dtmRunnerDecision;
				trade.dtmPartialContractsClosed = position.dtmPartialContractsClosed;
				trade.dtmRealizedPnl = round(position.dtmRealizedPnl);
				return;
			}
		// Trade builders own PnL accounting, including realized DTM partial exits.
		// This method only attaches the final DTM timeline/action metadata.
		trade.dtmTimelineJson = state.timelineJson;
			trade.dtmFinalAction = firstNonBlank(finalActionOverride, state.finalAction);
			trade.dtmPartialDecision = state.partialDecision;
			trade.dtmRunnerDecision = state.runnerDecision;
			trade.dtmPartialContractsClosed = state.partialContractsClosed;
			trade.dtmRealizedPnl = round(state.realizedPnl);
		}

	private static int currentIndexOrEntry(PortfolioPosition position, PortfolioSymbolContext context, Bar bar) {
		if (position == null || context == null || bar == null || bar.marketDate == null || bar.marketTime == null) {
			return position == null ? 0 : Math.max(0, position.entryIndex);
		}
		Integer value = barIndex(context, bar.marketDate, bar.marketTime);
		return value == null ? Math.max(0, position.entryIndex) : value.intValue();
	}

	private static double favorableMovePoints(PortfolioPosition position, double price) {
		if (position == null) {
			return 0.0;
		}
		return "LONG".equals(position.side) ? price - position.entryPrice : position.entryPrice - price;
	}

	private static double favorableExtremePrice(PortfolioPosition position, Bar bar) {
		if (position == null || bar == null) {
			return 0.0;
		}
		return "LONG".equals(position.side) ? Math.max(bar.close, bar.high) : Math.min(bar.close, bar.low);
	}

	private static double adverseExtremePrice(PortfolioPosition position, Bar bar) {
		if (position == null || bar == null) {
			return 0.0;
		}
		return "LONG".equals(position.side) ? Math.min(bar.close, bar.low) : Math.max(bar.close, bar.high);
	}

	private static double adverseMovePoints(PortfolioPosition position, double price) {
		return Math.max(0.0, -favorableMovePoints(position, price));
	}

	private static boolean stopImprovesRisk(PortfolioPosition position, double stop) {
		if (position == null || stop <= 0.0) {
			return false;
		}
		if ("LONG".equals(position.side)) {
			return stop > position.activeStopPrice && stop >= position.stopPrice;
		}
		return stop < position.activeStopPrice && stop <= position.stopPrice;
	}

	private static boolean targetImprovesReward(PortfolioPosition position, double target) {
		if (position == null || target <= 0.0) {
			return false;
		}
		if ("LONG".equals(position.side)) {
			return target > position.targetPrice + (position.spec.tickSize - 0.000001);
		}
		return target < position.targetPrice - (position.spec.tickSize - 0.000001);
	}

	private static boolean orderFlowAgainstPosition(String side, LiveRuntimeState.OrderFlowSnapshot flow) {
		if (flow == null || !flow.available || !flow.fresh) {
			return false;
		}
		String cleanSide = cleanOrDefault(side, "").toUpperCase(Locale.US);
		if ("LONG".equals(cleanSide)) {
			return flow.depthImbalance5 <= -0.35 || flow.tapeDelta <= -ORDER_FLOW_HARD_OPPOSING_TAPE || "ASK_FLIP".equals(flow.bookFlip);
		}
		return flow.depthImbalance5 >= 0.35 || flow.tapeDelta >= ORDER_FLOW_HARD_OPPOSING_TAPE || "BID_FLIP".equals(flow.bookFlip);
	}

	private static boolean strongOrderFlowAgainstPosition(String side, LiveRuntimeState.OrderFlowSnapshot flow) {
		if (flow == null || !flow.available || !flow.fresh) {
			return false;
		}
		String cleanSide = cleanOrDefault(side, "").toUpperCase(Locale.US);
		if ("LONG".equals(cleanSide)) {
			return (flow.depthImbalance5 <= -ORDER_FLOW_HARD_OPPOSING_IMBALANCE && flow.tapeDelta <= -ORDER_FLOW_HARD_OPPOSING_TAPE)
				|| "ASK_FLIP".equals(flow.bookFlip);
		}
		return (flow.depthImbalance5 >= ORDER_FLOW_HARD_OPPOSING_IMBALANCE && flow.tapeDelta >= ORDER_FLOW_HARD_OPPOSING_TAPE)
			|| "BID_FLIP".equals(flow.bookFlip);
	}

	private static boolean orderFlowSupportsPosition(String side, LiveRuntimeState.OrderFlowSnapshot flow) {
		if (flow == null || !flow.available || !flow.fresh) {
			return true;
		}
		String cleanSide = cleanOrDefault(side, "").toUpperCase(Locale.US);
		if ("LONG".equals(cleanSide)) {
			return flow.depthImbalance5 >= 0.15 || flow.tapeDelta >= ORDER_FLOW_SOFT_CONFIRM_TAPE || "BID_FLIP".equals(flow.bookFlip);
		}
		return flow.depthImbalance5 <= -0.15 || flow.tapeDelta <= -ORDER_FLOW_SOFT_CONFIRM_TAPE || "ASK_FLIP".equals(flow.bookFlip);
	}

	private static boolean trendAgainstPosition(String side, Bar bar) {
		if (bar == null) {
			return false;
		}
		String cleanSide = cleanOrDefault(side, "").toUpperCase(Locale.US);
		boolean hasVwap = bar.vwap > 0.0;
		boolean hasEma20 = bar.ema20 > 0.0;
		if ("LONG".equals(cleanSide)) {
			return (hasVwap && bar.close < bar.vwap) && (hasEma20 && bar.close < bar.ema20);
		}
		return (hasVwap && bar.close > bar.vwap) && (hasEma20 && bar.close > bar.ema20);
	}

	private static boolean trendWithPosition(String side, Bar bar) {
		if (bar == null) {
			return false;
		}
		String cleanSide = cleanOrDefault(side, "").toUpperCase(Locale.US);
		boolean hasVwap = bar.vwap > 0.0;
		boolean hasEma20 = bar.ema20 > 0.0;
		if ("LONG".equals(cleanSide)) {
			return (hasVwap && bar.close > bar.vwap) && (hasEma20 && bar.close > bar.ema20);
		}
		return (hasVwap && bar.close < bar.vwap) && (hasEma20 && bar.close < bar.ema20);
	}

	private static boolean dtmContinuationAligned(PortfolioPosition position, Bar bar, LiveRuntimeState.OrderFlowSnapshot flow, boolean trendAgainst, boolean strongFlowAgainst) {
		if (position == null || bar == null || trendAgainst || strongFlowAgainst) {
			return false;
		}
		double location = closeLocation(bar);
		boolean closesStrong = "LONG".equals(position.side) ? location >= 0.58 : location <= 0.42;
		boolean structureWith = trendWithPosition(position.side, bar) || closesStrong;
		return structureWith && orderFlowSupportsPosition(position.side, flow);
	}

	private static boolean dtmExperimentalRunnerAligned(PortfolioPosition position, Bar bar, LiveRuntimeState.OrderFlowSnapshot flow, boolean trendAgainst, boolean strongFlowAgainst) {
		if (position == null || bar == null || trendAgainst || strongFlowAgainst) {
			return false;
		}
		double location = closeLocation(bar);
		boolean closesStrong = "LONG".equals(position.side) ? location >= 0.55 : location <= 0.45;
		boolean structureWith = trendWithPosition(position.side, bar) || closesStrong;
		boolean flowWith = orderFlowSupportsPosition(position.side, flow);
		return structureWith || flowWith;
	}

	private static double dtmExtensionTriggerR(double targetR) {
		return targetR > 0.0 ? Math.max(DTM_PARTIAL_TRIGGER_R, targetR * DTM_EXTENSION_TARGET_FRACTION) : 1.40;
	}

	private static double dtmExtensionAcceptanceR(double targetR) {
		return targetR > 0.0 ? Math.max(dtmExtensionTriggerR(targetR), targetR + DTM_EXTENSION_ACCEPTANCE_R) : 1.40;
	}

	private static double dtmExtendedTargetPrice(PortfolioPosition position, double targetR) {
		if (position == null || position.initialRisk <= 0.0 || targetR <= 0.0) {
			return 0.0;
		}
		double extendedR = Math.min(targetR + DTM_DYNAMIC_TARGET_EXTENSION_MAX_ADD_R, Math.max(targetR + 0.50, targetR * DTM_DYNAMIC_TARGET_EXTENSION_MULTIPLE));
		double target = "LONG".equals(position.side)
			? position.entryPrice + (position.initialRisk * extendedR)
			: position.entryPrice - (position.initialRisk * extendedR);
		return roundToTick(position.spec, target);
	}

	private static double dtmProfitLockStop(PortfolioPosition position, double favorableCloseR, double targetR, boolean oneContractRunner) {
		if (position == null || position.initialRisk <= 0.0 || favorableCloseR <= DTM_EXTENSION_PROFIT_LOCK_BUFFER_R) {
			return 0.0;
		}
		double minimumLockR = Math.max(oneContractRunner ? 0.70 : 0.45, targetR - DTM_EXTENSION_MAX_TARGET_GIVEBACK_R);
		double targetLockR = Math.max(minimumLockR, targetR);
		double lockR = Math.min(targetLockR, favorableCloseR - DTM_EXTENSION_PROFIT_LOCK_BUFFER_R);
		if (lockR < minimumLockR) {
			return 0.0;
		}
		double stop = "LONG".equals(position.side)
			? position.entryPrice + (position.initialRisk * lockR)
			: position.entryPrice - (position.initialRisk * lockR);
		return roundToTick(position.spec, stop);
	}

	private static double dtmExperimentalRunnerStop(PortfolioPosition position, double favorableCloseR) {
		if (position == null || position.initialRisk <= 0.0 || favorableCloseR <= DTM_EXTENSION_PROFIT_LOCK_BUFFER_R) {
			return 0.0;
		}
		String mode = dtmExperimentalHalfRunnerStopMode();
		double minimumLockR = 0.45;
		double givebackR = DTM_EXTENSION_PROFIT_LOCK_BUFFER_R;
		if ("balanced".equals(mode)) {
			minimumLockR = 0.35;
			givebackR = 0.45;
		} else if ("loose".equals(mode)) {
			minimumLockR = 0.25;
			givebackR = 0.60;
		}
		double lockR = Math.max(minimumLockR, favorableCloseR - givebackR);
		double stop = "LONG".equals(position.side)
			? position.entryPrice + (position.initialRisk * lockR)
			: position.entryPrice - (position.initialRisk * lockR);
		return roundToTick(position.spec, stop);
	}

	private static double dtmTargetR(PortfolioPosition position) {
		if (position == null || position.initialRisk <= 0.0) {
			return 0.0;
		}
		return Math.max(0.0, favorableMovePoints(position, position.targetPrice) / position.initialRisk);
	}

	private static double dtmTargetAwareTrigger(double baseTriggerR, double targetR, double targetFraction, double maxTriggerR) {
		double targetAware = targetR > 0.0 ? targetR * targetFraction : 0.0;
		return Math.min(Math.max(baseTriggerR, targetAware), Math.max(baseTriggerR, maxTriggerR));
	}

	private static boolean dtmDynamicProtectiveOrdersEnabled() {
		return !"false".equalsIgnoreCase(System.getProperty("tradingbot.dtm.dynamicProtectiveOrders", "true"));
	}

	private static boolean dtmOneContractExtensionEnabled() {
		return "true".equalsIgnoreCase(System.getProperty("tradingbot.dtm.oneContractExtension", "false"));
	}

	private static boolean dtmExperimentalHalfRunnerEnabled() {
		return !"false".equalsIgnoreCase(System.getProperty("tradingbot.dtm.experimentalHalfRunner", "true"));
	}

	private static double dtmExperimentalHalfRunnerTriggerR(double partialTriggerR, double targetR, double extensionAcceptanceR) {
		String mode = dtmExperimentalHalfRunnerTriggerMode();
		if ("acceptance".equals(mode)) {
			return extensionAcceptanceR;
		}
		if ("target".equals(mode)) {
			return targetR > 0.0 ? Math.max(partialTriggerR, targetR) : partialTriggerR;
		}
		return partialTriggerR;
	}

	private static boolean dtmExperimentalHalfRunnerQualified(PortfolioPosition position, double targetR) {
		int minContracts = dtmExperimentalHalfRunnerMinContracts();
		if (position == null || position.contracts < Math.max(2, minContracts)) {
			return false;
		}
		String targetMode = dtmExperimentalHalfRunnerTargetMode();
		if ("medium".equals(targetMode)) {
			return targetR >= 1.25 && targetR < 1.60;
		}
		return true;
	}

