	private static int dtmMinimumBarsBeforeProtect(PortfolioPosition position) {
		String code = dtmStrategyCode(position);
		if ("KREV".equals(code) || "LIQREC".equals(code) || "ORB".equals(code) || "ORB2".equals(code)) {
			return 2;
		}
		return 3;
	}

	private static int dtmMinimumBarsBeforeTargetManagement(PortfolioPosition position) {
		String code = dtmStrategyCode(position);
		if ("KREV".equals(code) || "LIQREC".equals(code) || "ORB".equals(code) || "ORB2".equals(code)) {
			return 3;
		}
		return 4;
	}

	private static int dtmMinimumBarsBeforeEarlyCut(PortfolioPosition position) {
		String code = dtmStrategyCode(position);
		if ("KREV".equals(code) || "LIQREC".equals(code)) {
			return 3;
		}
		if ("OMOM".equals(code) || "ORB".equals(code) || "ORB2".equals(code) || "SWEEP".equals(code)) {
			return 4;
		}
		return 6;
	}

	private static String dtmStateName(PortfolioPosition position, DynamicTradeState state, double favorableR, double adverseR, boolean flowAgainst, boolean trendAgainst, double breakevenTriggerR, double partialTriggerR) {
		if (state != null && state.partialTaken) {
			return "RUNNER";
		}
		if (adverseR >= DTM_EARLY_CUT_CLOSE_ADVERSE_R && (flowAgainst || trendAgainst)) {
			return "DEFEND";
		}
		if (favorableR >= partialTriggerR) {
			return "TARGET_DECISION";
		}
		if (favorableR >= breakevenTriggerR) {
			return "PROTECT";
		}
		return "PROBE";
	}

	private static boolean dtmThesisInvalidated(PortfolioPosition position, PortfolioSymbolContext context, Bar bar, boolean strongFlowAgainst, boolean trendAgainst, double adverseCloseR) {
		if (position == null || bar == null) {
			return false;
		}
		double risk = Math.max(position.initialRisk, Math.abs(position.entryPrice - position.stopPrice));
		if (risk <= 0.0) {
			return false;
		}
		double checkpoint = DTM_EARLY_CUT_CLOSE_ADVERSE_R * risk;
		boolean structureBreak = false;
		if ("LONG".equals(position.side)) {
			double adverseCheckpoint = position.entryPrice - checkpoint;
			structureBreak = bar.close <= adverseCheckpoint;
		} else {
			double adverseCheckpoint = position.entryPrice + checkpoint;
			structureBreak = bar.close >= adverseCheckpoint;
		}
		return structureBreak && (trendAgainst || (strongFlowAgainst && adverseCloseR >= 0.80));
	}

	private static String dtmDetailsJson(
		PortfolioPosition position,
		Bar bar,
		LiveRuntimeState.OrderFlowSnapshot flow,
		double favorableR,
		double adverseR,
		double favorableCloseR,
		double adverseCloseR,
		double targetR,
		int barsHeld,
		int partialContracts,
		double stopPrice,
		double targetPrice,
		boolean finalExit,
		String stateName,
		String normalizedAction,
		int exitEvidenceCount
	) {
		return "{"
			+ "\"state\":" + jsonString(cleanOrDefault(stateName, "PROBE")) + ","
			+ "\"action\":" + jsonString(cleanOrDefault(normalizedAction, "HOLD_STATIC")) + ","
			+ "\"exitEvidenceCount\":" + Math.max(0, exitEvidenceCount) + ","
			+ "\"favorableR\":" + round(favorableR) + ","
			+ "\"adverseR\":" + round(adverseR) + ","
			+ "\"favorableCloseR\":" + round(favorableCloseR) + ","
			+ "\"adverseCloseR\":" + round(adverseCloseR) + ","
			+ "\"targetR\":" + round(targetR) + ","
			+ "\"barsHeld\":" + Math.max(0, barsHeld) + ","
			+ "\"entryPrice\":" + round(position == null ? 0.0 : position.entryPrice) + ","
			+ "\"currentPrice\":" + round(bar == null ? 0.0 : bar.close) + ","
			+ "\"activeStop\":" + round(position == null ? 0.0 : position.activeStopPrice) + ","
			+ "\"newStop\":" + round(stopPrice) + ","
			+ "\"newTarget\":" + round(targetPrice) + ","
			+ "\"contracts\":" + (position == null ? 0 : position.contracts) + ","
			+ "\"partialContracts\":" + partialContracts + ","
			+ "\"riskEnvelopeOk\":true,"
			+ "\"finalExit\":" + finalExit + ","
			+ "\"orderFlow\":" + (flow == null ? "{}" : flow.toJson())
			+ "}";
	}

	private static String appendJsonObjectToArray(String arrayJson, String objectJson) {
		String object = jsonObjectOrDefault(objectJson, "{}");
		String clean = jsonObjectOrDefault(arrayJson, "[]");
		if (!clean.startsWith("[") || !clean.endsWith("]")) {
			return "[" + object + "]";
		}
		if (clean.length() <= 2) {
			return "[" + object + "]";
		}
		return clean.substring(0, clean.length() - 1) + "," + object + "]";
	}

	private static String mergeSimpleJson(String baseJson, String fieldJson) {
		String base = jsonObjectOrDefault(baseJson, "{}");
		String field = cleanOrDefault(fieldJson, "");
		if (field.length() == 0) {
			return base;
		}
		if (base.length() <= 2) {
			return "{" + field + "}";
		}
		return base.substring(0, base.length() - 1) + "," + field + "}";
	}

	private static String dtmTitle(String actionCode) {
		String code = cleanOrDefault(actionCode, "");
		if ("DTM_MOVE_STOP_BREAKEVEN".equals(code)) return "DTM moved stop to breakeven.";
		if ("DTM_TRAIL_STOP".equals(code)) return "DTM trailed the stop.";
		if ("DTM_PARTIAL_TARGET".equals(code)) return "DTM partially sold the position.";
		if ("DTM_PARTIAL_HALF_RUNNER_EXTENDED".equals(code)) return "DTM partially sold half and extended the runner.";
		if ("DTM_PARTIAL_BLOCKED".equals(code)) return "DTM partial close was blocked.";
		if ("DTM_EXTEND_TARGET_CONTINUATION".equals(code)) return "DTM extended the runner target.";
		if ("DTM_EXTEND_ONE_CONTRACT_RUNNER".equals(code)) return "DTM extended a one-contract runner.";
		if ("DTM_CUT_EARLY_THESIS_FAILED".equals(code)) return "DTM cut the trade early.";
		return "DTM trade decision recorded.";
	}

	private static void hydrateLivePositionState(PortfolioPosition position, PortfolioSymbolContext context, Bar currentBar) {
		if (position == null || context == null || currentBar == null || currentBar.marketDate == null || currentBar.marketTime == null) {
			return;
		}
		Integer currentIndexValue = barIndex(context, currentBar.marketDate, currentBar.marketTime);
		if (currentIndexValue == null) {
			return;
		}
		int currentIndex = currentIndexValue.intValue();
		if (position.entryIndex < 0 && position.openedAt != null && position.openedAt.trim().length() > 0) {
			LocalDateTime openedAt = parseDisplayLocalDateTime(position.openedAt);
			if (openedAt != null && openedAt.toLocalDate().equals(currentBar.marketDate)) {
				Integer entryIndexValue = barIndex(context, openedAt.toLocalDate(), openedAt.toLocalTime());
				if (entryIndexValue != null) {
					position.entryIndex = entryIndexValue.intValue();
					position.openedMarketTime = openedAt.toLocalTime();
				}
			}
		}
		if (position.entryIndex < 0 || position.entryIndex > currentIndex) {
			position.entryIndex = currentIndex;
			position.openedMarketTime = currentBar.marketTime;
			return;
		}
		List<Bar> dayBars = context.byDay.get(currentBar.marketDate);
		if (dayBars == null || dayBars.isEmpty()) {
			return;
		}
		position.activeStopPrice = position.stopPrice;
		position.maxFavorable = 0.0;
		position.maxAdverse = 0.0;
		for (int index = position.entryIndex; index < currentIndex && index >= 0 && index < dayBars.size(); index++) {
			Bar replayBar = dayBars.get(index);
			position.maxFavorable = Math.max(position.maxFavorable, favorablePnl(position.spec, position.side, position.entryPrice, replayBar, position.contracts));
			position.maxAdverse = Math.min(position.maxAdverse, adversePnl(position.spec, position.side, position.entryPrice, replayBar, position.contracts));
			position.activeStopPrice = updateManagedStop(position.spec, position.side, position.entryPrice, position.activeStopPrice, replayBar.close, position.initialRisk, position.minTrailDistance);
		}
		position.maxFavorable = Math.max(position.maxFavorable, favorablePnl(position.spec, position.side, position.entryPrice, currentBar, position.contracts));
		position.maxAdverse = Math.min(position.maxAdverse, adversePnl(position.spec, position.side, position.entryPrice, currentBar, position.contracts));
	}

