	private static PortfolioSymbolContext livePortfolioContext(String symbol, InstrumentSpec spec, BacktestConfig config, List<Bar> bars) {
		PortfolioSymbolContext context = new PortfolioSymbolContext();
		context.symbol = normalizeSymbol(symbol);
		context.spec = spec;
		context.config = config;
		if (bars == null || bars.isEmpty()) {
			return context;
		}
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketDate == null || bar.marketTime == null) {
				continue;
			}
			List<Bar> dayBars = context.byDay.get(bar.marketDate);
			if (dayBars == null) {
				dayBars = new ArrayList<Bar>();
				context.byDay.put(bar.marketDate, dayBars);
			}
			dayBars.add(bar);
			Map<LocalTime, Integer> indexByTime = context.indexByDayTime.get(bar.marketDate);
			if (indexByTime == null) {
				indexByTime = new HashMap<LocalTime, Integer>();
				context.indexByDayTime.put(bar.marketDate, indexByTime);
			}
			indexByTime.put(bar.marketTime, dayBars.size() - 1);
		}
		return context;
	}

	private static void prepareLivePortfolioSignalEvents(
		PortfolioSymbolContext context,
		List<Bar> previousBars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars
	) {
		if (context == null || context.byDay == null || context.byDay.isEmpty()) {
			return;
		}
		Map<LocalDate, List<Bar>> fifteenMinuteByDay = groupByDay(fifteenMinuteBars == null ? new ArrayList<Bar>() : fifteenMinuteBars);
		Map<LocalDate, List<Bar>> oneHourByDay = groupByDay(oneHourBars == null ? new ArrayList<Bar>() : oneHourBars);
		List<LocalDate> days = new ArrayList<LocalDate>(context.byDay.keySet());
		Collections.sort(days);
		for (int dayIndex = 0; dayIndex < days.size(); dayIndex++) {
			LocalDate day = days.get(dayIndex);
			List<Bar> bars = context.byDay.get(day);
			if (bars == null || bars.size() < 40) {
				continue;
			}
			List<Bar> priorBars = previousDayBars(context.byDay, days, dayIndex);
			if ((priorBars == null || priorBars.isEmpty()) && dayIndex == days.size() - 1 && previousBars != null && !previousBars.isEmpty()) {
				priorBars = previousBars;
			}
			List<Signal> signals = buildSignals(
				context.spec,
				bars,
				priorBars,
				fifteenMinuteByDay.get(day),
				oneHourByDay.get(day),
				context.config,
				liveOrderFlowMapForBars(context.symbol, bars)
			);
			List<SignalEvent> events = new ArrayList<SignalEvent>();
			for (int signalIndex = 0; signalIndex < signals.size(); signalIndex++) {
				Signal signal = signals.get(signalIndex);
				int executionIndex = signal.entryIndex + 1;
				if (executionIndex >= bars.size()) {
					continue;
				}
				Bar entryBar = bars.get(executionIndex);
				if (!isLiveEntryWindowTime(entryBar.marketTime)) {
					continue;
				}
				SignalEvent event = new SignalEvent();
				event.symbol = context.symbol;
				event.signal = signal;
				event.day = day;
				event.entryTime = entryBar.marketTime;
				event.executionIndex = executionIndex;
				events.add(event);
			}
			sortSignalEvents(events);
			context.eventsByDay.put(day, events);
		}
	}

	private static boolean strategyUsesRangeMidpointContinuation(FuturesStrategySettings settings) {
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		return safe.rangeMidpointContinuation != null && safe.rangeMidpointContinuation.enabled;
	}

	private static Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> liveOrderFlowMapForBars(String symbol, List<Bar> bars) {
		Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> map = new HashMap<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>>();
		if (bars == null || bars.isEmpty()) {
			return map;
		}
		Bar latest = null;
		for (int index = bars.size() - 1; index >= 0; index--) {
			Bar bar = bars.get(index);
			if (bar != null && bar.marketDate != null && bar.marketTime != null) {
				latest = bar;
				break;
			}
		}
		if (latest == null) {
			return map;
		}
		LiveRuntimeState.OrderFlowSnapshot snapshot = LiveRuntimeState.orderFlowSnapshot(symbol);
		if (snapshot == null || !snapshot.available || !snapshot.fresh) {
			return map;
		}
		if (cleanOrDefault(snapshot.source, "").length() == 0) {
			snapshot.source = "LIVE_RUNTIME_ORDER_FLOW";
		}
		if (snapshot.sourceConfidence <= 0.0) {
			snapshot.sourceConfidence = 1.0;
		}
		Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot> byTime = new HashMap<LocalTime, LiveRuntimeState.OrderFlowSnapshot>();
		byTime.put(latest.marketTime.withSecond(0).withNano(0), snapshot);
		map.put(latest.marketDate, byTime);
		return map;
	}

	private static List<LivePortfolioSignalCandidate> currentLiveSignalCandidates(
		int sessionId,
		int snapshotId,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBarsBySymbol
	) {
		return currentLiveSignalCandidates(sessionId, snapshotId, contexts, currentBarsBySymbol, true);
	}

	private static List<LivePortfolioSignalCandidate> currentLiveSignalCandidates(
		int sessionId,
		int snapshotId,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBarsBySymbol,
		boolean enforceForcedExitCutoff
	) {
		List<LivePortfolioSignalCandidate> candidates = new ArrayList<LivePortfolioSignalCandidate>();
		if (contexts == null || contexts.isEmpty() || currentBarsBySymbol == null || currentBarsBySymbol.isEmpty()) {
			return candidates;
		}
		for (PortfolioSymbolContext context : contexts.values()) {
			if (context == null || context.eventsByDay == null) {
				continue;
			}
			Bar entryBar = currentBarsBySymbol.get(context.symbol);
			if (entryBar == null || entryBar.marketDate == null || entryBar.marketTime == null) {
				continue;
			}
			if (enforceForcedExitCutoff && !isLiveEntryWindowTime(entryBar.marketTime)) {
				continue;
			}
			Integer currentIndex = barIndex(context, entryBar.marketDate, entryBar.marketTime);
			if (currentIndex == null) {
				continue;
			}
			List<SignalEvent> events = context.eventsByDay.get(entryBar.marketDate);
				if (events == null || events.isEmpty()) {
					continue;
				}
				for (int eventIndex = 0; eventIndex < events.size(); eventIndex++) {
					SignalEvent event = events.get(eventIndex);
					if (event == null || event.signal == null) {
						continue;
					}
					Bar signalBar = signalBarForEvent(context, event);
					String signalTime = signalBar == null ? entryBar.displayTime : signalBar.displayTime;
					if (event.executionIndex < currentIndex.intValue()) {
						auditStaleLiveSignalCandidate(sessionId, snapshotId, context, event, signalTime, entryBar, currentIndex.intValue());
						continue;
					}
					if (event.executionIndex != currentIndex.intValue() || !entryBar.marketTime.equals(event.entryTime)) {
						continue;
					}
					if (liveDecisionExists(sessionId, context.symbol, event.signal.strategyCode, signalTime)) {
						continue;
					}
		LivePortfolioSignalCandidate candidate = new LivePortfolioSignalCandidate();
				candidate.symbol = context.symbol;
				candidate.context = context;
				candidate.event = event;
				candidate.entryBar = entryBar;
				candidate.signalTime = signalTime;
				candidate.entryTime = entryBar.displayTime;
				candidates.add(candidate);
			}
		}
			return candidates;
		}

	private static void auditStaleLiveSignalCandidate(
		int sessionId,
		int snapshotId,
		PortfolioSymbolContext context,
		SignalEvent event,
		String signalTime,
		Bar currentBar,
		int currentIndex
	) {
		if (sessionId <= 0 || snapshotId <= 0 || context == null || event == null || event.signal == null || currentBar == null) {
			return;
		}
		int skippedBars = currentIndex - event.executionIndex;
		if (skippedBars < 1 || skippedBars > LIVE_STALE_SIGNAL_AUDIT_LOOKBACK_BARS) {
			return;
		}
		if (event.entryTime == null || event.entryTime.isBefore(LIVE_ENTRY_WINDOW_START) || !event.entryTime.isBefore(LIVE_ENTRY_WINDOW_END)) {
			return;
		}
		Signal signal = event.signal;
		if (liveDecisionExists(sessionId, context.symbol, signal.strategyCode, signalTime)) {
			return;
		}
		Bar plannedEntryBar = barForEventIndex(context, event);
		String entryTime = plannedEntryBar == null ? displayTime(event.day, event.entryTime) : cleanOrDefault(plannedEntryBar.displayTime, "");
		String reason = staleSignalSkippedReason(false);
		String payload = "{"
			+ "\"symbol\":" + jsonString(normalizeSymbol(context.symbol)) + ","
			+ "\"strategyCode\":" + jsonString(cleanOrDefault(signal.strategyCode, "")) + ","
			+ "\"strategyName\":" + jsonString(cleanOrDefault(signal.strategyName, "")) + ","
			+ "\"side\":" + jsonString(cleanOrDefault(signal.side, "")) + ","
			+ "\"diagnosticStage\":\"RAW_PRE_SIZING\","
			+ "\"signalTime\":" + jsonString(cleanOrDefault(signalTime, "")) + ","
			+ "\"entryTime\":" + jsonString(entryTime) + ","
			+ "\"currentBarTime\":" + jsonString(cleanOrDefault(currentBar.displayTime, "")) + ","
			+ "\"skippedBars\":" + skippedBars + ","
			+ "\"catchUpOrdersEnabled\":false,"
			+ "\"entryPrice\":" + round(signal.entryPrice) + ","
			+ "\"stopPrice\":" + round(signal.stopPrice) + ","
			+ "\"targetPrice\":" + round(signal.targetPrice) + ","
			+ "\"reason\":" + jsonString(reason)
			+ "}";
		insertLiveSignalDecisionFromSignal(
			sessionId,
			snapshotId,
			context.symbol,
			signal,
			signalTime,
			entryTime,
			0,
			0.0,
			signal.stopPrice,
			signal.targetPrice,
			0.0,
			"REJECTED_STALE_SIGNAL",
			reason,
			"",
			payload
		);
		pushLiveEvent(
			sessionId,
			"STALE_SIGNAL_SKIPPED",
			"Signal Audit",
			"blocked",
			context.symbol,
			entryTime,
			normalizeSymbol(context.symbol) + " " + cleanOrDefault(signal.strategyCode, "LIVE") + " " + cleanOrDefault(signal.side, "") + " stale signal skipped.",
			reason,
			payload
		);
	}

	private static String staleSignalSkippedReason(boolean validated) {
		if (validated) {
			return "Validated live signal execution bar passed without an order submission; catch-up orders are disabled.";
		}
		return "Diagnostics-only: raw strategy signal execution bar passed before live sizing could validate it; this has not yet passed live sizing, exposure, or broker checks; catch-up orders are disabled.";
	}

	private static Bar barForEventIndex(PortfolioSymbolContext context, SignalEvent event) {
		if (context == null || event == null || event.day == null || event.executionIndex < 0) {
			return null;
		}
		List<Bar> dayBars = context.byDay.get(event.day);
		if (dayBars == null || event.executionIndex >= dayBars.size()) {
			return null;
		}
		return dayBars.get(event.executionIndex);
	}

	private static String displayTime(LocalDate day, LocalTime time) {
		if (day == null || time == null) {
			return "";
		}
		return day.toString() + " " + time.format(DateTimeFormatter.ofPattern("HH:mm"));
	}

	private static void rankLivePortfolioSignalCandidates(final List<LivePortfolioSignalCandidate> candidates, final Map<String, PortfolioSymbolContext> contexts) {
		Collections.sort(candidates, new Comparator<LivePortfolioSignalCandidate>() {
			@Override
			public int compare(LivePortfolioSignalCandidate first, LivePortfolioSignalCandidate second) {
				double firstScore = portfolioEventScore(contexts.get(first.symbol), first.event);
				double secondScore = portfolioEventScore(contexts.get(second.symbol), second.event);
				int scoreCompare = Double.compare(secondScore, firstScore);
				if (scoreCompare != 0) {
					return scoreCompare;
				}
				int timeCompare = first.event.entryTime.compareTo(second.event.entryTime);
				if (timeCompare != 0) {
					return timeCompare;
				}
				return first.symbol.compareTo(second.symbol);
			}
		});
	}

	private static Bar liveExecutionBarForCandidate(LivePortfolioSignalCandidate candidate) {
		if (candidate == null || candidate.event == null || candidate.event.signal == null || candidate.entryBar == null || candidate.context == null) {
			return null;
		}
		LiveRuntimeState.OrderFlowSnapshot flow = candidate.syntheticSelfTest ? null : LiveRuntimeState.orderFlowSnapshot(candidate.symbol);
		return executionBarForOrderFlow(candidate, flow);
	}

	private static Bar executionBarForOrderFlow(LivePortfolioSignalCandidate candidate, LiveRuntimeState.OrderFlowSnapshot flow) {
		if (candidate == null || candidate.event == null || candidate.event.signal == null || candidate.entryBar == null || candidate.context == null) {
			return null;
		}
		Bar source = candidate.entryBar;
		Bar execution = copyBar(source);
		Signal signal = candidate.event.signal;
		double executablePrice = 0.0;
		if (flow != null && flow.available && flow.fresh) {
			if ("LONG".equals(signal.side)) {
				executablePrice = flow.bestAsk > 0.0 ? flow.bestAsk : flow.bestBid;
			} else {
				executablePrice = flow.bestBid > 0.0 ? flow.bestBid : flow.bestAsk;
			}
		}
		if (executablePrice <= 0.0) {
			executablePrice = source.close > 0.0 ? source.close : source.open;
		}
		if (executablePrice <= 0.0) {
			return null;
		}
		execution.open = roundToTick(candidate.context.spec, executablePrice);
		execution.high = Math.max(execution.high, execution.open);
		execution.low = execution.low <= 0.0 ? execution.open : Math.min(execution.low, execution.open);
		execution.close = execution.open;
		return execution;
	}

	private static LocalTime signalBarTime(PortfolioSymbolContext context, SignalEvent event) {
		Bar signalBar = signalBarForEvent(context, event);
		return signalBar == null ? (event == null ? null : event.entryTime) : signalBar.marketTime;
	}

	private static String liveEntryDecayRejectReason(PortfolioSymbolContext context, SignalEvent event, Bar executionBar) {
		return liveEntryDecayRejectReason(context, event, executionBar, PORTFOLIO_VALIDATION_LIVE_STRICT);
	}

	private static final String PORTFOLIO_VALIDATION_BACKTEST_PARITY = "BACKTEST_PARITY";
	private static final String PORTFOLIO_VALIDATION_LIVE_STRICT = "LIVE_STRICT";

	private static String activeLivePortfolioValidationPolicy(FuturesLiveSession session, LiveStrategySnapshotRow snapshot) {
		return PORTFOLIO_VALIDATION_BACKTEST_PARITY;
	}

	private static boolean portfolioPolicyBlocksEntryDecay(String policyName) {
		return PORTFOLIO_VALIDATION_LIVE_STRICT.equals(cleanOrDefault(policyName, "").toUpperCase(Locale.US));
	}

	private static boolean portfolioPolicyUsesLiveExecutableEntry(String policyName) {
		return PORTFOLIO_VALIDATION_LIVE_STRICT.equals(cleanOrDefault(policyName, "").toUpperCase(Locale.US));
	}

	private static String liveValidationDiagnosticsJson(String sizingDiagnosticsJson, String validationPolicy, String liveDecayWarning) {
		return mergeSimpleJson(
			sizingDiagnosticsJson,
			"\"validationPolicy\":" + jsonString(cleanOrDefault(validationPolicy, PORTFOLIO_VALIDATION_BACKTEST_PARITY))
				+ ",\"liveEntryDecayWarning\":" + jsonString(cleanOrDefault(liveDecayWarning, ""))
		);
	}

	private static String liveEntryDecayRejectReason(PortfolioSymbolContext context, SignalEvent event, Bar executionBar, String policyName) {
		if (!portfolioPolicyBlocksEntryDecay(policyName)) {
			return "";
		}
		if (context == null || context.spec == null || event == null || event.signal == null || executionBar == null) {
			return "Rejected: live signal could not be checked for entry decay.";
		}
		Signal signal = event.signal;
		String code = cleanOrDefault(signal.strategyCode, "").toUpperCase(Locale.US);
		double tick = Math.max(0.000001, context.spec.tickSize);
		double minimumLiveRewardRisk = liveEntryDecayMinimumRewardRisk(code);
		double liveRisk = Math.abs(executionBar.open - signal.stopPrice);
		double remainingReward = "LONG".equals(signal.side)
			? signal.targetPrice - executionBar.open
			: executionBar.open - signal.targetPrice;
		if (liveRisk <= 0.0) {
			return "Rejected: live entry decayed because the executable price crossed the original invalidation/stop.";
		}
		if ("LONG".equals(signal.side)) {
			if (executionBar.open >= signal.targetPrice - tick || executionBar.high >= signal.targetPrice - tick) {
				return "Rejected: " + code + " live entry decayed because the first target zone already traded before a fresh executable entry was available.";
			}
		} else if ("SHORT".equals(signal.side)) {
			if (executionBar.open <= signal.targetPrice + tick || executionBar.low <= signal.targetPrice + tick) {
				return "Rejected: " + code + " live entry decayed because the first target zone already traded before a fresh executable entry was available.";
			}
		}
		double liveRewardRisk = remainingReward / liveRisk;
		if (liveRewardRisk < minimumLiveRewardRisk) {
			return "Rejected: " + code + " live entry decayed because the executable price consumed too much reward versus the original stop/target plan.";
		}
		return "";
	}

	private static double liveEntryDecayMinimumRewardRisk(String strategyCode) {
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		if ("LIQREC".equals(code)) {
			return 0.65;
		}
		if ("KREV".equals(code) || "MRVWAP".equals(code)) {
			return 0.70;
		}
		if ("RMC".equals(code)) {
			return 0.60;
		}
		if ("BOSRT".equals(code)) {
			return 1.25;
		}
		if ("FVG".equals(code) || "IFVG".equals(code) || "VWAP".equals(code) || "VRCL".equals(code) || "SWEEP".equals(code) || "PDB".equals(code)) {
			return 0.60;
		}
		return 0.50;
	}

	private static LiveSignalOrder validateLivePortfolioSignal(
		FuturesLiveSession session,
		PortfolioBacktestConfig portfolioConfig,
		Map<String, PortfolioSymbolContext> contexts,
		LivePortfolioSignalCandidate candidate,
		List<PortfolioPosition> openPositions,
		Map<String, Integer> takenByStrategy,
		LiveBrokerExposure brokerExposure
	) {
		LiveSignalOrder order = new LiveSignalOrder();
		if (candidate == null || candidate.event == null || candidate.event.signal == null || candidate.context == null || candidate.entryBar == null) {
			order.reason = "Rejected: live portfolio signal was incomplete.";
			order.diagnosticsJson = "{\"firstFailingRule\":\"INCOMPLETE_SIGNAL\"}";
			return order;
		}
		LiveBrokerExposure exposure = brokerExposure == null ? new LiveBrokerExposure() : brokerExposure;
		if (!exposure.verified) {
			order.reason = "Rejected: live portfolio exposure could not be verified: " + exposure.message;
			order.diagnosticsJson = "{\"firstFailingRule\":\"BROKER_EXPOSURE_UNVERIFIED\",\"message\":" + jsonString(exposure.message) + "}";
			return order;
		}
			SignalEvent event = candidate.event;
			Signal signal = event.signal;
			PortfolioSymbolContext context = candidate.context;
			Bar liveExecutionBar = liveExecutionBarForCandidate(candidate);
			String validationPolicy = activeLivePortfolioValidationPolicy(session, null);
			if (liveExecutionBar == null) {
				order.reason = "Rejected: live portfolio signal had no executable live price.";
				order.diagnosticsJson = "{\"firstFailingRule\":\"NO_EXECUTABLE_LIVE_PRICE\"}";
				return order;
			}
			String liveDecayWarning = liveEntryDecayRejectReason(context, event, liveExecutionBar, PORTFOLIO_VALIDATION_LIVE_STRICT);
			String liveDecayReject = liveEntryDecayRejectReason(context, event, liveExecutionBar, validationPolicy);
			if (liveDecayReject.length() > 0) {
				order.reason = liveDecayReject;
				order.diagnosticsJson = liveValidationDiagnosticsJson(
					liveSizingDiagnosticsJson(context, event, liveExecutionBar, 0.0, 0, 0.0, openPositions.size() + exposure.positionSlots, openContractCount(openPositions) + exposure.totalContracts, openMiniUnitCount(openPositions) + exposure.totalMiniUnits, "LIVE_ENTRY_DECAY", null),
					validationPolicy,
					liveDecayWarning
				);
				return order;
			}
			if (portfolioPolicyUsesLiveExecutableEntry(validationPolicy)) {
				candidate.entryBar = liveExecutionBar;
			}
			if (hasOpenCorrelatedSymbol(exposure.symbols, event.symbol) || hasOpenCorrelatedPosition(openPositions, event.symbol)) {
				order.reason = "Rejected: a correlated live portfolio position is already open for the same futures family.";
				order.diagnosticsJson = liveValidationDiagnosticsJson(
					liveSizingDiagnosticsJson(context, event, candidate.entryBar, 0.0, 0, 0.0, openPositions.size() + exposure.positionSlots, openContractCount(openPositions) + exposure.totalContracts, openMiniUnitCount(openPositions) + exposure.totalMiniUnits, "CORRELATED_SYMBOL_ALREADY_OPEN", null),
					validationPolicy,
					liveDecayWarning
				);
				return order;
			}
			if (explicitCsvContainsSymbol(exposure.symbols, event.symbol) || hasOpenSymbol(openPositions, event.symbol)) {
				order.reason = "Rejected: symbol already has an open live portfolio position.";
				order.diagnosticsJson = liveValidationDiagnosticsJson(
					liveSizingDiagnosticsJson(context, event, candidate.entryBar, 0.0, 0, 0.0, openPositions.size() + exposure.positionSlots, openContractCount(openPositions) + exposure.totalContracts, openMiniUnitCount(openPositions) + exposure.totalMiniUnits, "SYMBOL_ALREADY_OPEN", null),
					validationPolicy,
					liveDecayWarning
				);
				return order;
		}
		int openPositionCount = openPositions.size() + exposure.positionSlots;
		if (openPositionCount >= portfolioConfig.maxOpenPositions) {
			order.reason = "Rejected: live portfolio max open positions reached.";
			order.diagnosticsJson = liveValidationDiagnosticsJson(
				liveSizingDiagnosticsJson(context, event, candidate.entryBar, 0.0, 0, 0.0, openPositionCount, openContractCount(openPositions) + exposure.totalContracts, openMiniUnitCount(openPositions) + exposure.totalMiniUnits, "MAX_OPEN_POSITIONS", null),
				validationPolicy,
				liveDecayWarning
			);
			return order;
		}
		int openContracts = openContractCount(openPositions) + exposure.totalContracts;
		double openMiniUnits = openMiniUnitCount(openPositions) + exposure.totalMiniUnits;
		if (openContracts >= portfolioConfig.maxAggregateContracts || fundedMiniUnitLimitReached(portfolioConfig, openMiniUnits)) {
			order.reason = "Rejected: live portfolio aggregate contract or funded-unit limit reached.";
			order.diagnosticsJson = liveValidationDiagnosticsJson(
				liveSizingDiagnosticsJson(context, event, candidate.entryBar, 0.0, 0, 0.0, openPositionCount, openContracts, openMiniUnits, "AGGREGATE_LIMIT", null),
				validationPolicy,
				liveDecayWarning
			);
			return order;
		}
		String strategyKey = strategyDailyLimitKey(event.symbol, signal.strategyCode);
		int taken = countFor(takenByStrategy, strategyKey);
		if (taken >= maxTradesPerDay(signal.strategyCode, context.config.strategySettings)) {
			order.reason = "Rejected: live portfolio per-strategy daily limit reached.";
			order.diagnosticsJson = liveValidationDiagnosticsJson(
				liveSizingDiagnosticsJson(context, event, candidate.entryBar, 0.0, 0, 0.0, openPositionCount, openContracts, openMiniUnits, "PER_STRATEGY_DAILY_LIMIT", null),
				validationPolicy,
				liveDecayWarning
			);
			return order;
		}

		Map<String, Bar> currentBars = barsAt(contexts, event.day, event.entryTime);
		if (currentBars.isEmpty()) {
			currentBars.put(event.symbol, candidate.entryBar);
		}
		double dayStartBalance = positiveOrDefault(portfolioConfig.dayStartBalance, portfolioConfig.accountSize);
		double balance = positiveOrDefault(portfolioConfig.currentBalance, dayStartBalance);
		double equityAtOpen = balance + aggregateOpenPnl(openPositions, currentBars, "open");
		double accountBase = positiveOrDefault(portfolioConfig.accountSize, dayStartBalance);
		double trailingThreshold = liveTrailingDrawdownFloor(accountBase, equityAtOpen, Math.abs(portfolioConfig.maxTrailingDrawdown));
		if (equityAtOpen - dayStartBalance <= -Math.abs(portfolioConfig.dailyLossLimit)) {
			order.reason = "Rejected: live portfolio daily loss guard blocked new entries.";
			order.diagnosticsJson = liveValidationDiagnosticsJson(
				liveSizingDiagnosticsJson(context, event, candidate.entryBar, 0.0, 0, 0.0, openPositionCount, openContracts, openMiniUnits, "DAILY_LOSS_GUARD", null),
				validationPolicy,
				liveDecayWarning
			);
			return order;
		}
		if (equityAtOpen <= trailingThreshold) {
			order.reason = "Rejected: live portfolio trailing drawdown guard blocked new entries.";
			order.diagnosticsJson = liveValidationDiagnosticsJson(
				liveSizingDiagnosticsJson(context, event, candidate.entryBar, 0.0, 0, 0.0, openPositionCount, openContracts, openMiniUnits, "TRAILING_DRAWDOWN_GUARD", null),
				validationPolicy,
				liveDecayWarning
			);
			return order;
		}

		double reservedOpenRisk = aggregateOpenRisk(openPositions);
		double dailyRiskBudget = Math.abs(portfolioConfig.dailyLossLimit) + (equityAtOpen - dayStartBalance) - reservedOpenRisk;
		double trailingRiskBudget = equityAtOpen - trailingThreshold - reservedOpenRisk;
		double aggregateGuardBudget = Math.min(dailyRiskBudget, trailingRiskBudget);
		DynamicRiskPolicy liveRiskPolicy = dynamicRiskPolicyForMode(RISK_SIZING_STATIC_WITHDRAW_DAILY);
		DynamicRiskBudget liveRiskBudget = dynamicRiskBudget(
			liveRiskPolicy,
			context.config.maxRiskPerTrade,
			dailyRiskBudget,
			trailingRiskBudget,
			portfolioConfig.maxTrailingDrawdown
		);
		double riskBudgetMultiplier = context.config.qualitativeRiskEnabled ? portfolioRiskBudgetMultiplier(
			context,
			event,
			equityAtOpen - dayStartBalance,
			aggregateGuardBudget,
			openPositionCount
		) : 1.0;
		double symbolRiskBudget = liveRiskBudget.availableRiskBudget * riskBudgetMultiplier;
		double availableRiskBudget = Math.min(symbolRiskBudget, aggregateGuardBudget);
		int aggregateRoom = portfolioConfig.maxAggregateContracts - openContracts;
		if (portfolioConfig.maxAggregateMiniUnits > 0.0) {
			aggregateRoom = Math.min(aggregateRoom, contractsAllowedByMiniUnitRoom(event.symbol, portfolioConfig.maxAggregateMiniUnits - openMiniUnits));
		}
		if (availableRiskBudget <= 0.0 || aggregateRoom <= 0) {
			order.reason = "Rejected: live portfolio has no remaining risk or funded-unit room.";
			order.diagnosticsJson = liveValidationDiagnosticsJson(
				liveSizingDiagnosticsJson(context, event, candidate.entryBar, availableRiskBudget, aggregateRoom, aggregateGuardBudget, openPositionCount, openContracts, openMiniUnits, availableRiskBudget <= 0.0 ? "NO_RISK_BUDGET" : "NO_AGGREGATE_ROOM", null),
				validationPolicy,
				liveDecayWarning
			);
			return order;
		}

		PortfolioPosition position = openPortfolioPosition(context, event, candidate.entryBar, availableRiskBudget, aggregateRoom, aggregateGuardBudget, portfolioRiskCompressionAllowed(signal.strategyCode), liveRiskPolicy.stopRiskBufferMultiplier);
		if (position == null) {
			String failingRule = liveSizingFirstFailingRule(context, event, candidate.entryBar, availableRiskBudget, aggregateRoom, aggregateGuardBudget);
			order.reason = "Rejected: live signal failed portfolio sizing or risk validation (" + failingRule + ").";
			order.diagnosticsJson = liveValidationDiagnosticsJson(
				liveSizingDiagnosticsJson(context, event, candidate.entryBar, availableRiskBudget, aggregateRoom, aggregateGuardBudget, openPositionCount, openContracts, openMiniUnits, failingRule, null),
				validationPolicy,
				liveDecayWarning
			);
			return order;
		}
		position.concurrentPositionsAtEntry = openPositionCount + 1;
		position.concurrentContractsAtEntry = openContracts + position.contracts;
		order.contracts = position.contracts;
		order.entryPrice = position.entryPrice;
		order.stopPrice = position.stopPrice;
		order.targetPrice = position.targetPrice;
		order.fundedMiniUnits = round(fundedMiniUnitsPerContract(position.symbol) * position.contracts);
		order.position = position;
		order.accepted = true;
		order.reason = "Accepted live portfolio signal.";
		order.diagnosticsJson = liveValidationDiagnosticsJson(
			liveSizingDiagnosticsJson(context, event, candidate.entryBar, availableRiskBudget, aggregateRoom, aggregateGuardBudget, openPositionCount, openContracts, openMiniUnits, "ACCEPTED", position),
			validationPolicy,
			liveDecayWarning
		);
		return order;
	}

	private static String liveSizingFirstFailingRule(
		PortfolioSymbolContext context,
		SignalEvent event,
		Bar entryBar,
		double riskBudget,
		int aggregateRoom,
		double aggregateGuardBudget
	) {
		if (context == null || event == null || event.signal == null || entryBar == null) {
			return "INCOMPLETE_SIGNAL";
		}
		LiveSizingSnapshot sizing = liveSizingSnapshot(context, event, entryBar, riskBudget, aggregateRoom, aggregateGuardBudget, null);
		if (!sizing.validStopRelation) return "INVALID_STOP_RELATION";
		if (sizing.rawRiskTicks < 1.0) return "RISK_TOO_SMALL";
		if (sizing.rawRiskTicks > sizing.maxInitialRiskTicks) return "MAX_INITIAL_RISK_TICKS";
		if (sizing.effectiveRiskBudget <= 0.0) return "NO_RISK_BUDGET";
		if (sizing.aggregateRoom <= 0) return "NO_AGGREGATE_ROOM";
		if (sizing.contractsBeforeGuard < 1) return "RISK_BUDGET_CONTRACTS";
		if (sizing.finalContracts < 1) return "AGGREGATE_GUARD_BUDGET";
		return "UNKNOWN_SIZING_REJECTION";
	}

	private static String liveSizingDiagnosticsJson(
		PortfolioSymbolContext context,
		SignalEvent event,
		Bar entryBar,
		double riskBudget,
		int aggregateRoom,
		double aggregateGuardBudget,
		int openPositionCount,
		int openContracts,
		double openMiniUnits,
		String firstFailingRule,
		PortfolioPosition acceptedPosition
	) {
		LiveSizingSnapshot sizing = liveSizingSnapshot(context, event, entryBar, riskBudget, aggregateRoom, aggregateGuardBudget, acceptedPosition);
		return "{"
			+ "\"symbol\":" + jsonString(context == null ? "" : context.symbol) + ","
			+ "\"strategyCode\":" + jsonString(event == null || event.signal == null ? "" : event.signal.strategyCode) + ","
			+ "\"side\":" + jsonString(event == null || event.signal == null ? "" : event.signal.side) + ","
			+ "\"firstFailingRule\":" + jsonString(cleanOrDefault(firstFailingRule, "")) + ","
			+ "\"openPositionCount\":" + openPositionCount + ","
			+ "\"openContracts\":" + openContracts + ","
			+ "\"openMiniUnits\":" + round(openMiniUnits) + ","
			+ "\"entryPrice\":" + round(sizing.entryPrice) + ","
			+ "\"signalStopPrice\":" + round(sizing.signalStopPrice) + ","
			+ "\"stopPrice\":" + round(sizing.stopPrice) + ","
			+ "\"targetPrice\":" + round(sizing.targetPrice) + ","
			+ "\"compressedRiskPlan\":" + sizing.compressedRiskPlan + ","
			+ "\"rawRiskTicks\":" + round(sizing.rawRiskTicks) + ","
			+ "\"stopTicks\":" + round(sizing.rawRiskTicks) + ","
			+ "\"originalRiskTicks\":" + round(sizing.originalRiskTicks) + ","
			+ "\"maxInitialRiskTicks\":" + round(sizing.maxInitialRiskTicks) + ","
			+ "\"rewardRemainingTicks\":" + round(sizing.rewardRemainingTicks) + ","
			+ "\"rewardConsumedTicks\":" + round(sizing.rewardConsumedTicks) + ","
			+ "\"liveRewardRisk\":" + round(sizing.liveRewardRisk) + ","
			+ "\"minimumLiveRewardRisk\":" + round(sizing.minimumLiveRewardRisk) + ","
			+ "\"riskPerContract\":" + round(sizing.riskPerContract) + ","
			+ "\"sizingRiskPerContract\":" + round(sizing.sizingRiskPerContract) + ","
			+ "\"effectiveRiskBudget\":" + round(sizing.effectiveRiskBudget) + ","
			+ "\"maxRiskBudget\":" + round(sizing.effectiveRiskBudget) + ","
			+ "\"strategyRisk\":" + round(sizing.effectiveRiskBudget) + ","
			+ "\"aggregateGuardBudget\":" + round(sizing.aggregateGuardBudget) + ","
			+ "\"trailingDrawdownRoom\":" + round(sizing.aggregateGuardBudget) + ","
			+ "\"dailyLossRoom\":" + round(sizing.effectiveRiskBudget) + ","
			+ "\"aggregateRoom\":" + sizing.aggregateRoom + ","
			+ "\"maxContracts\":" + sizing.maxContracts + ","
			+ "\"perSymbolContractCap\":" + sizing.maxContracts + ","
			+ "\"aggregateExposureCap\":" + sizing.aggregateRoom + ","
			+ "\"fundedMiniUnitCap\":" + round(fundedMiniUnitsPerContract(context == null ? "" : context.symbol) * Math.max(0, sizing.aggregateRoom)) + ","
			+ "\"contractsBeforeGuard\":" + sizing.contractsBeforeGuard + ","
			+ "\"finalContracts\":" + sizing.finalContracts + ","
			+ "\"expectedTargetPnl\":" + round(sizing.expectedTargetPnl) + ","
			+ "\"expectedStopLoss\":" + round(sizing.expectedStopLoss) + ","
			+ "\"limitingCap\":" + jsonString(sizing.limitingCap) + ","
			+ "\"limitingCapLabel\":" + jsonString(limitingCapLabel(sizing.limitingCap)) + ","
			+ "\"selectedAccountProfile\":" + jsonString(context == null || context.config == null ? "" : context.config.fundedProfile)
			+ "}";
	}

	private static LiveSizingSnapshot liveSizingSnapshot(
		PortfolioSymbolContext context,
		SignalEvent event,
		Bar entryBar,
		double riskBudget,
		int aggregateRoom,
		double aggregateGuardBudget,
		PortfolioPosition acceptedPosition
	) {
		LiveSizingSnapshot snapshot = new LiveSizingSnapshot();
		snapshot.aggregateRoom = aggregateRoom;
		snapshot.aggregateGuardBudget = aggregateGuardBudget;
		snapshot.effectiveRiskBudget = Math.max(0.0, riskBudget);
		if (context == null || context.spec == null || event == null || event.signal == null || entryBar == null) {
			return snapshot;
			}
			Signal signal = event.signal;
			FuturesStrategySettings settings = context.config == null || context.config.strategySettings == null ? defaultFuturesStrategySettings() : context.config.strategySettings;
			snapshot.maxInitialRiskTicks = liveInitialRiskLimitTicks(settings, signal.strategyCode);
		snapshot.maxContracts = context.config == null ? 0 : strategySpecificMaxContracts(context.symbol, signal.strategyCode, settings, context.config.maxContracts);
		snapshot.entryPrice = acceptedPosition != null && acceptedPosition.entryPrice > 0.0
			? acceptedPosition.entryPrice
			: applySlippage(context.spec, entryBar.open > 0.0 ? entryBar.open : entryBar.close, signal.side, context.config.slippageTicks, true);
		snapshot.signalStopPrice = roundToTick(context.spec, signal.stopPrice);
		snapshot.stopPrice = acceptedPosition != null && acceptedPosition.stopPrice > 0.0 ? acceptedPosition.stopPrice : snapshot.signalStopPrice;
		snapshot.validStopRelation = ("LONG".equals(signal.side) && snapshot.entryPrice > snapshot.stopPrice)
			|| ("SHORT".equals(signal.side) && snapshot.entryPrice < snapshot.stopPrice);
		double originalRisk = Math.abs(snapshot.entryPrice - snapshot.signalStopPrice);
		snapshot.originalRiskTicks = context.spec.tickSize <= 0.0 ? 0.0 : originalRisk / context.spec.tickSize;
		if (acceptedPosition != null) {
			snapshot.compressedRiskPlan = acceptedPosition.compressedRiskPlan;
			snapshot.rawRiskTicks = acceptedPosition.rawRiskTicks;
			snapshot.stopPrice = acceptedPosition.stopPrice;
			snapshot.targetPrice = acceptedPosition.targetPrice;
			snapshot.finalContracts = acceptedPosition.contracts;
			snapshot.contractsBeforeGuard = acceptedPosition.contracts;
			snapshot.riskPerContract = acceptedPosition.riskPerContract;
			snapshot.sizingRiskPerContract = acceptedPosition.riskPerContract * settings.openMaeRiskMultiplier;
			double originalRewardTicks = context.spec.tickSize <= 0.0 ? 0.0 : Math.abs(signal.targetPrice - signal.entryPrice) / context.spec.tickSize;
			snapshot.rewardRemainingTicks = context.spec.tickSize <= 0.0 ? 0.0 : Math.max(0.0, ("LONG".equals(signal.side) ? signal.targetPrice - snapshot.entryPrice : snapshot.entryPrice - signal.targetPrice) / context.spec.tickSize);
			snapshot.rewardConsumedTicks = Math.max(0.0, originalRewardTicks - snapshot.rewardRemainingTicks);
			snapshot.liveRewardRisk = snapshot.rawRiskTicks <= 0.0 ? 0.0 : snapshot.rewardRemainingTicks / snapshot.rawRiskTicks;
			snapshot.minimumLiveRewardRisk = liveEntryDecayMinimumRewardRisk(signal.strategyCode);
			snapshot.expectedTargetPnl = targetPnlEstimate(context.spec, signal.side, snapshot.entryPrice, snapshot.targetPrice, snapshot.finalContracts);
			snapshot.expectedStopLoss = Math.abs(snapshot.riskPerContract * Math.max(0, snapshot.finalContracts));
			snapshot.limitingCap = liveSizingLimitingCap(snapshot);
			return snapshot;
		}
			if (snapshot.originalRiskTicks > snapshot.maxInitialRiskTicks && isLiveRiskCompressibleStrategy(signal.strategyCode)) {
				List<Bar> dayBars = context.byDay.get(event.day);
				double compressedStop = "LONG".equals(signal.side)
					? compressedLongStop(context.spec, dayBars, event.executionIndex, snapshot.entryPrice, snapshot.maxInitialRiskTicks)
					: compressedShortStop(context.spec, dayBars, event.executionIndex, snapshot.entryPrice, snapshot.maxInitialRiskTicks);
			boolean validCompressedStop = ("LONG".equals(signal.side) && snapshot.entryPrice > compressedStop)
				|| ("SHORT".equals(signal.side) && snapshot.entryPrice < compressedStop);
			if (validCompressedStop) {
				snapshot.stopPrice = compressedStop;
				snapshot.compressedRiskPlan = true;
			}
		}
		double initialRisk = Math.abs(snapshot.entryPrice - snapshot.stopPrice);
		snapshot.rawRiskTicks = context.spec.tickSize <= 0.0 ? 0.0 : initialRisk / context.spec.tickSize;
		double signalRisk = Math.abs(signal.entryPrice - signal.stopPrice);
		double rewardMultiple = signalRisk <= 0.0 ? context.spec.defaultTargetR : Math.abs(signal.targetPrice - signal.entryPrice) / signalRisk;
		if (rewardMultiple <= 0.0 || Double.isNaN(rewardMultiple) || Double.isInfinite(rewardMultiple)) {
			rewardMultiple = context.spec.defaultTargetR;
		}
		snapshot.targetPrice = "LONG".equals(signal.side)
			? roundToTick(context.spec, snapshot.entryPrice + (initialRisk * rewardMultiple))
			: roundToTick(context.spec, snapshot.entryPrice - (initialRisk * rewardMultiple));
		double originalRewardTicks = context.spec.tickSize <= 0.0 ? 0.0 : Math.abs(signal.targetPrice - signal.entryPrice) / context.spec.tickSize;
		snapshot.rewardRemainingTicks = context.spec.tickSize <= 0.0 ? 0.0 : Math.max(0.0, ("LONG".equals(signal.side) ? signal.targetPrice - snapshot.entryPrice : snapshot.entryPrice - signal.targetPrice) / context.spec.tickSize);
		snapshot.rewardConsumedTicks = Math.max(0.0, originalRewardTicks - snapshot.rewardRemainingTicks);
		snapshot.liveRewardRisk = snapshot.rawRiskTicks <= 0.0 ? 0.0 : snapshot.rewardRemainingTicks / snapshot.rawRiskTicks;
		snapshot.minimumLiveRewardRisk = liveEntryDecayMinimumRewardRisk(signal.strategyCode);
		double stopFillForRisk = applySlippage(context.spec, snapshot.stopPrice, signal.side, context.config.slippageTicks, false);
		snapshot.riskPerContract = (Math.abs(snapshot.entryPrice - stopFillForRisk) / context.spec.tickSize * context.spec.tickValue) + (context.config.commissionPerContract * 2.0);
		snapshot.sizingRiskPerContract = snapshot.riskPerContract * settings.openMaeRiskMultiplier;
		snapshot.contractsBeforeGuard = Math.min(snapshot.maxContracts, Math.min(aggregateRoom, (int) Math.floor(snapshot.effectiveRiskBudget / Math.max(1.0, snapshot.riskPerContract))));
		int finalContracts = snapshot.contractsBeforeGuard;
		while (finalContracts > 0 && (snapshot.sizingRiskPerContract * finalContracts) > Math.max(0.0, aggregateGuardBudget)) {
			finalContracts--;
		}
		snapshot.finalContracts = finalContracts;
		snapshot.expectedTargetPnl = targetPnlEstimate(context.spec, signal.side, snapshot.entryPrice, snapshot.targetPrice, snapshot.finalContracts);
		snapshot.expectedStopLoss = Math.abs(snapshot.riskPerContract * Math.max(0, snapshot.finalContracts));
		snapshot.limitingCap = liveSizingLimitingCap(snapshot);
		return snapshot;
	}

	private static double targetPnlEstimate(InstrumentSpec spec, String side, double entryPrice, double targetPrice, int contracts) {
		if (spec == null || spec.tickSize <= 0.0 || contracts <= 0 || entryPrice <= 0.0 || targetPrice <= 0.0) {
			return 0.0;
		}
		double move = "SHORT".equals(cleanOrDefault(side, "").toUpperCase(Locale.US)) ? entryPrice - targetPrice : targetPrice - entryPrice;
		return Math.max(0.0, move / spec.tickSize * spec.tickValue * contracts);
	}

	private static String liveSizingLimitingCap(LiveSizingSnapshot sizing) {
		if (sizing == null) {
			return "UNKNOWN";
		}
		if (!sizing.validStopRelation) return "INVALID_STOP_RELATION";
		if (sizing.finalContracts < 1) {
			if (sizing.effectiveRiskBudget <= 0.0) return "MAX_RISK_BUDGET";
			if (sizing.aggregateRoom <= 0) return "AGGREGATE_EXPOSURE_CAP";
			return "AGGREGATE_GUARD_BUDGET";
		}
		if (sizing.contractsBeforeGuard >= sizing.maxContracts && sizing.maxContracts > 0) return "PER_SYMBOL_CONTRACT_CAP";
		if (sizing.contractsBeforeGuard >= sizing.aggregateRoom && sizing.aggregateRoom > 0) return "AGGREGATE_EXPOSURE_CAP";
		if (sizing.finalContracts < sizing.contractsBeforeGuard) return "AGGREGATE_GUARD_BUDGET";
		return "MAX_RISK_BUDGET";
	}

	private static String limitingCapLabel(String code) {
		String normalized = cleanOrDefault(code, "").toUpperCase(Locale.US);
		if ("PER_SYMBOL_CONTRACT_CAP".equals(normalized)) return "Per-symbol contract cap limited size.";
		if ("AGGREGATE_EXPOSURE_CAP".equals(normalized)) return "Aggregate exposure or funded mini-unit cap limited size.";
		if ("AGGREGATE_GUARD_BUDGET".equals(normalized)) return "Daily/trailing guard room limited size.";
		if ("MAX_RISK_BUDGET".equals(normalized)) return "Max risk budget limited size.";
		if ("INVALID_STOP_RELATION".equals(normalized)) return "Entry/stop geometry invalid.";
		return "Sizing cap not available.";
	}

	private static class LiveSizingSnapshot {
		private boolean validStopRelation;
		private boolean compressedRiskPlan;
		private double entryPrice;
		private double signalStopPrice;
		private double stopPrice;
		private double targetPrice;
		private double rawRiskTicks;
		private double originalRiskTicks;
		private double maxInitialRiskTicks;
		private double rewardRemainingTicks;
		private double rewardConsumedTicks;
		private double liveRewardRisk;
		private double minimumLiveRewardRisk;
		private double riskPerContract;
		private double sizingRiskPerContract;
		private double effectiveRiskBudget;
		private double aggregateGuardBudget;
		private int aggregateRoom;
		private int maxContracts;
		private int contractsBeforeGuard;
		private int finalContracts;
		private double expectedTargetPnl;
		private double expectedStopLoss;
		private String limitingCap = "UNKNOWN";
	}

	private static LiveSignalOrder validateLiveSignalOrder(
		FuturesLiveSession session,
		LiveStrategySnapshotRow snapshot,
		BacktestConfig config,
		InstrumentSpec spec,
		String symbol,
		Signal signal,
		Bar executionBar
	) {
		LiveSignalOrder order = new LiveSignalOrder();
		order.entryPrice = roundToTick(spec, executionBar.open > 0.0 ? executionBar.open : executionBar.close);
		order.stopPrice = roundToTick(spec, signal.stopPrice);
		order.targetPrice = roundToTick(spec, signal.targetPrice);
		double riskPoints = Math.abs(order.entryPrice - order.stopPrice);
		if (riskPoints <= 0.0) {
			order.reason = "Rejected: signal has no live stop distance.";
			return order;
		}
		LiveAccountSizing accountSizing = liveAccountSizingFor(session, snapshot);
		FundedRuleProfile profile = accountSizing.profile;
		double maxRisk = positiveOrDefault(accountSizing.maxRiskPerTrade, config.maxRiskPerTrade);
		int maxContracts = Math.min(profileMaxContractsForSymbol(profile, symbol), Math.max(1, Math.min(accountSizing.maxContracts, config.maxContracts)));
		FuturesStrategySettings strategySettings = config.strategySettings == null ? defaultFuturesStrategySettings() : config.strategySettings;
		maxContracts = strategySpecificMaxContracts(symbol, signal.strategyCode, strategySettings, maxContracts);
		if (accountSizing.maxAggregateMiniUnits > 0.0) {
			maxContracts = Math.min(maxContracts, contractsAllowedByMiniUnitRoom(symbol, accountSizing.maxAggregateMiniUnits));
		}
		double riskPerContract = (riskPoints / spec.tickSize * spec.tickValue) + (config.commissionPerContract * 2.0);
		int contracts = Math.min(maxContracts, (int) Math.floor(maxRisk / Math.max(1.0, riskPerContract)));
		if (contracts < 1) {
			order.reason = "Rejected: live signal failed risk sizing.";
			return order;
		}
		order.contracts = contracts;
		order.fundedMiniUnits = round(fundedMiniUnitsPerContract(symbol) * contracts);
		order.accepted = true;
		order.reason = "Accepted live signal.";
		return order;
	}

	private static BacktestConfig liveSignalConfigFor(String symbol, FuturesLiveSession session, LiveStrategySnapshotRow snapshot) {
		BacktestConfig config = buildBacktestConfig(
			symbol,
			LocalDate.now(NEW_YORK_ZONE).toString(),
			LocalDate.now(NEW_YORK_ZONE).toString(),
			session.accountSize,
			session.maxTrailingDrawdown,
			session.dailyLossLimit,
			session.maxRiskPerTrade,
			session.maxContracts,
			session.commissionPerContract,
			session.slippageTicks,
			session.profitTarget
		);
		String liveStrategySlot = activeLiveStrategySlot(session, snapshot);
		config.strategySettings = loadFuturesStrategySettings(symbol, liveStrategySlot);
		config.fundedProfile = activeLiveFundedProfileCode(session, snapshot);
		FundedRuleProfile profile = fundedRuleProfileFor(config.fundedProfile);
		if (riskProfileUsesSavedRisk(profile.code)) {
			FuturesRiskSettings savedRisk = loadFuturesRiskSettings(symbol, liveStrategySlot);
			applyRiskSettingsToStrategySettings(config.strategySettings, savedRisk);
			config.maxRiskPerTrade = savedRisk.maxRiskPerTrade;
			config.maxContracts = savedRisk.maxContracts;
			config.commissionPerContract = savedRisk.commissionPerContract;
			config.slippageTicks = savedRisk.slippageTicks;
			config.profitTarget = savedRisk.profitTarget;
			if (isTopstep50KProfile(profile.code)) {
				if (scalesSavedSizingForProfile(profile.code)) {
					applySavedSizingScale(config, savedRisk, profile, symbol);
				} else {
					config.maxRiskPerTrade = Math.min(config.maxRiskPerTrade, profile.maxRiskPerTrade);
					config.maxContracts = Math.min(config.maxContracts, profileMaxContractsForSymbol(profile, symbol));
				}
			}
		}
		return config;
	}

	private static List<Bar> realtimeBarsForSymbol(String symbol, String timeframe, int limit) {
		List<Bar> capturedBars = liveCapturedBarsForSymbol(symbol, timeframe, limit);
		if (!capturedBars.isEmpty()) {
			LiveWarmupBars warmup = cachedLiveWarmupBarsForSymbol(symbol, timeframe, limit);
			List<Bar> bars = latestSessionBars(mergeBarSeries(warmup.bars, capturedBars, limit), limit);
			enrichLiveBars(bars, instrumentFor(symbol));
			return bars;
		}
		LiveWarmupBars warmup = liveWarmupBarsForSymbol(symbol, timeframe, limit);
		List<RealtimePricePoint> points = realtimePricePointsForSymbol(symbol, realtimePointLimitForCandles(limit, timeframe));
		List<RealtimeCandle> candles = aggregateRealtimeCandles(points, timeframe, limit);
		InstrumentSpec spec = instrumentFor(symbol);
		List<Bar> liveBars = barsFromRealtimeCandles(symbol, candles);
		List<Bar> bars = latestSessionBars(mergeBarSeries(warmup.bars, liveBars, limit), limit);
		enrichLiveBars(bars, spec);
		return bars;
	}

	private static List<Bar> liveHigherTimeframeBarsFromMinuteBars(List<Bar> minuteBars, InstrumentSpec spec, String timeframe, int limit) {
		List<Bar> bars = aggregateBarsForTimeframe(minuteBars, timeframe, limit);
		enrichLiveBars(bars, spec);
		return bars;
	}

	private static LiveWarmupBars cachedLiveWarmupBarsForSymbol(String symbol, String timeframe, int limit) {
		String startedAt = cleanOrDefault(ProjectXRealtimeManager.currentStartedAt(), "");
		int sessionId;
		synchronized (FuturesManager.class) {
			sessionId = liveSession.sessionId;
		}
		if (startedAt.length() == 0 && sessionId <= 0) {
			return new LiveWarmupBars();
		}
		String sessionKey = startedAt.length() > 0 ? startedAt : String.valueOf(sessionId);
		String cacheKey = sessionKey + "|" + normalizeSymbol(symbol) + "|" + normalizeLiveMonitorTimeframe(timeframe) + "|" + Math.max(1, limit);
		synchronized (LIVE_WARMUP_CACHE) {
			LiveWarmupBars cached = LIVE_WARMUP_CACHE.get(cacheKey);
			return cached == null ? new LiveWarmupBars() : copyWarmupBars(cached);
		}
	}

	private static List<Bar> liveCapturedBarsForSymbol(String symbol, String timeframe, int limit) {
		List<Bar> bars = new ArrayList<Bar>();
		String normalizedTimeframe = normalizeLiveMonitorTimeframe(timeframe);
		int minutesPerCandle = liveMonitorTimeframeMinutes(normalizedTimeframe);
		int sourceLimit = Math.min(5000, Math.max(Math.max(1, limit), (Math.max(1, limit) * Math.max(1, minutesPerCandle)) + 120));
		InstrumentSpec spec = instrumentFor(symbol);
		LocalDate activeMarketDate = liveMarketFeedActive() ? currentLiveMarketDataDate() : null;
		try {
			List<FuturesConnectionManager.InternalBar> captured = FuturesMarketDataStore.readRecentCapturedBars(spec.symbol, sourceLimit);
			for (int index = 0; index < captured.size(); index++) {
				Bar bar = barFromInternalCapturedBar(captured.get(index));
				if (bar == null || bar.marketTime == null || bar.marketTime.isBefore(RTH_START) || !bar.marketTime.isBefore(RTH_END)) {
					continue;
				}
				if (activeMarketDate != null && !activeMarketDate.equals(bar.marketDate)) {
					continue;
				}
				bars.add(bar);
			}
		} catch (Exception e) {
			e.printStackTrace();
			return new ArrayList<Bar>();
		}
		if (bars.isEmpty()) {
			return bars;
		}
		List<Bar> timeframeBars = aggregateBarsForTimeframe(bars, normalizedTimeframe, limit);
		enrichLiveBars(timeframeBars, spec);
		return selectLastBars(timeframeBars, limit);
	}

	private static LocalDate currentLiveMarketDataDate() {
		MarketSessionStatus status = currentMarketSessionStatus();
		if (status != null && status.marketDate != null) {
			try {
				return LocalDate.parse(status.marketDate);
			} catch (Exception ignored) {
			}
		}
		return ZonedDateTime.now(NEW_YORK_ZONE).toLocalDate();
	}

	private static List<Bar> recordedRealtimeBarsForSymbol(String symbol, LocalDate day, String timeframe, int limit) {
		if (day == null) {
			return new ArrayList<Bar>();
		}
		List<RealtimePricePoint> points = realtimePricePointsForSymbolBetween(
			symbol,
			day.atStartOfDay(),
			day.plusDays(1).atStartOfDay(),
			realtimePointLimitForCandles(Math.max(390, limit), timeframe)
		);
		List<RealtimeCandle> candles = aggregateRealtimeCandles(points, timeframe, limit);
		List<Bar> bars = barsFromRealtimeCandles(symbol, candles);
		enrichLiveBars(bars, instrumentFor(symbol));
		return bars;
	}

	private static List<RealtimePricePoint> realtimePricePointsForSymbolBetween(String symbol, LocalDateTime start, LocalDateTime end, int limit) {
		ProjectXRealtimeManager.initializeStore();
		List<RealtimePricePoint> points = new ArrayList<RealtimePricePoint>();
		if (start == null || end == null || !start.isBefore(end)) {
			return points;
		}
		String requestedSymbol = normalizeSymbol(symbol);
		String sql = "SELECT realtimeEventID, eventType, contractId, symbol, payloadJson, receivedAt FROM FuturesLiveRealtimeEvents "
			+ "WHERE hub = 'market' AND symbol = ? AND eventType <> 'GatewayDepth' AND receivedAt >= ? AND receivedAt < ? "
			+ "ORDER BY realtimeEventID DESC LIMIT ?";
		try (Connection conn = ProjectXRealtimeManager.openRealtimeConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setString(1, requestedSymbol);
			pstmt.setString(2, start.format(SERVER_TIME_FORMAT));
			pstmt.setString(3, end.format(SERVER_TIME_FORMAT));
			pstmt.setInt(4, boundedInt(limit, LIVE_REALTIME_EVENT_SAMPLE_FLOOR, 1, LIVE_REALTIME_EVENT_SAMPLE_CAP));
			try (ResultSet rs = pstmt.executeQuery()) {
				while (rs.next()) {
					String payloadJson = rs.getString("payloadJson");
					String eventSymbol = realtimeSymbolFromEvent(
						cleanOrDefault(rs.getString("symbol"), ""),
						cleanOrDefault(rs.getString("contractId"), ""),
						payloadJson
					);
					if (!requestedSymbol.equals(eventSymbol)) {
						continue;
					}
					double price = realtimePriceFromPayload(payloadJson);
					if (price <= 0.0) {
						continue;
					}
					RealtimePricePoint point = new RealtimePricePoint();
					point.id = rs.getInt("realtimeEventID");
					point.time = cleanOrDefault(rs.getString("receivedAt"), "");
					point.eventType = cleanOrDefault(rs.getString("eventType"), "GatewayTrade");
					point.price = price;
					point.volume = realtimeVolumeFromPayload(payloadJson);
					point.pollSnapshot = "LIVE_POLL_SNAPSHOT".equalsIgnoreCase(point.eventType);
					points.add(0, point);
				}
			}
			normalizeRealtimePointVolumes(points);
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return points;
	}

	private static List<Bar> barsFromRealtimeCandles(String symbol, List<RealtimeCandle> candles) {
		List<Bar> bars = new ArrayList<Bar>();
		InstrumentSpec spec = instrumentFor(symbol);
		for (int index = 0; index < candles.size(); index++) {
			RealtimeCandle candle = candles.get(index);
			LocalDateTime eventTime = parseDisplayLocalDateTime(candle.time);
			if (eventTime == null) {
				continue;
			}
			Bar bar = new Bar();
			bar.displayTime = candle.time;
			bar.marketDate = eventTime.toLocalDate();
			bar.marketTime = eventTime.toLocalTime();
			bar.open = candle.open;
			bar.high = candle.high;
			bar.low = candle.low;
			bar.close = candle.close;
			bar.volume = candle.volume;
			bar.vwap = candle.vwap;
			bar.ema9 = candle.ema9;
			bar.ema20 = candle.ema20;
			bar.ema50 = candle.ema20;
			bar.rsi14 = candle.rsi14 <= 0.0 ? 50.0 : candle.rsi14;
			bar.rangeTicks = spec.tickSize <= 0.0 ? 0.0 : Math.abs(bar.high - bar.low) / spec.tickSize;
			double range = Math.abs(bar.high - bar.low);
			bar.bodyPct = range <= 0.0 ? 0.0 : (Math.abs(bar.close - bar.open) / range) * 100.0;
			bars.add(bar);
		}
		return bars;
	}

	private static void applyRealtimeBarDerivedFields(List<Bar> bars, InstrumentSpec spec) {
		if (bars.isEmpty()) {
			return;
		}
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			int volumeStart = Math.max(0, index - 19);
			double volumeSum = 0.0;
			for (int volumeIndex = volumeStart; volumeIndex <= index; volumeIndex++) {
				volumeSum += bars.get(volumeIndex).volume;
			}
			bar.volumeSma20 = volumeSum / (index - volumeStart + 1);
			int atrStart = Math.max(0, index - 13);
			double trSum = 0.0;
			for (int trIndex = atrStart; trIndex <= index; trIndex++) {
				Bar current = bars.get(trIndex);
				double previousClose = trIndex == 0 ? current.close : bars.get(trIndex - 1).close;
				double trueRange = Math.max(current.high - current.low, Math.max(Math.abs(current.high - previousClose), Math.abs(current.low - previousClose)));
				trSum += trueRange;
			}
			bar.atr14 = trSum / (index - atrStart + 1);
			if (bar.rangeTicks <= 0.0 && spec.tickSize > 0.0) {
				bar.rangeTicks = Math.abs(bar.high - bar.low) / spec.tickSize;
			}
		}
	}

	private static List<Bar> previousLocalDayBarsForLive(String symbol, LocalDate currentDay) {
		String cacheKey = livePriorDayBarsCacheKey(symbol, currentDay);
		long now = System.currentTimeMillis();
		synchronized (LIVE_WARMUP_CACHE) {
			LiveWarmupBars cached = LIVE_WARMUP_CACHE.get(cacheKey);
			if (cached != null && now - cached.loadedAt <= LIVE_PRIOR_DAY_BARS_CACHE_TTL_MS) {
				return copyBars(cached.bars);
			}
		}
		List<Bar> recordedBars = previousRecordedRealtimeBarsForLive(symbol, currentDay);
		if (recordedBars.size() >= 60) {
			cacheLivePriorDayBars(cacheKey, recordedBars);
			return copyBars(recordedBars);
		}
		LocalDate endDate = currentDay == null ? LocalDate.now(NEW_YORK_ZONE) : currentDay;
		DataBundle bundle = loadNativeFuturesBars(symbol, endDate.minusDays(10), endDate, TIMEFRAME_FOLDER);
		Map<LocalDate, List<Bar>> byDay = groupByDay(bundle.bars);
		List<LocalDate> days = new ArrayList<LocalDate>(byDay.keySet());
		Collections.sort(days);
		for (int index = days.size() - 1; index >= 0; index--) {
			LocalDate day = days.get(index);
			if (currentDay == null || day.isBefore(currentDay)) {
				List<Bar> previousBars = byDay.get(day);
				cacheLivePriorDayBars(cacheKey, previousBars);
				return copyBars(previousBars);
			}
		}
		return new ArrayList<Bar>();
	}

	private static String livePriorDayBarsCacheKey(String symbol, LocalDate currentDay) {
		LocalDate day = currentDay == null ? LocalDate.now(NEW_YORK_ZONE) : currentDay;
		return "live-prior-day|" + normalizeSymbol(symbol) + "|" + day;
	}

	private static void cacheLivePriorDayBars(String cacheKey, List<Bar> bars) {
		if (cacheKey == null || cacheKey.length() == 0 || bars == null || bars.isEmpty()) {
			return;
		}
		synchronized (LIVE_WARMUP_CACHE) {
			LIVE_WARMUP_CACHE.put(cacheKey, warmupFromBars(bars, "LIVE_PRIOR_DAY_BARS"));
		}
	}

	private static List<Bar> previousRecordedRealtimeBarsForLive(String symbol, LocalDate currentDay) {
		LocalDate day = previousRecordedRealtimeDay(symbol, currentDay);
		if (day == null) {
			return new ArrayList<Bar>();
		}
		List<Bar> capturedBars = capturedRealtimeBarsForSymbolDay(symbol, day);
		if (capturedBars.size() >= 60) {
			enrichLiveBars(capturedBars, instrumentFor(symbol));
			return selectLastBars(capturedBars, 390);
		}
		return recordedRealtimeBarsForSymbol(symbol, day, "1m", 390);
	}

	private static LocalDate previousRecordedRealtimeDay(String symbol, LocalDate currentDay) {
		FuturesMarketDataStore.initializeStore();
		LocalDate effectiveDay = currentDay == null ? LocalDate.now(NEW_YORK_ZONE) : currentDay;
		String sql = "SELECT substr(timestamp, 1, 10) AS dayKey, COUNT(*) AS bars FROM FuturesLiveCapturedBars "
			+ "WHERE symbol = ? AND substr(timestamp, 1, 10) < ? "
			+ "GROUP BY dayKey HAVING bars >= 60 ORDER BY dayKey DESC LIMIT 1";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setString(1, normalizeSymbol(symbol));
			pstmt.setString(2, effectiveDay.toString());
			try (ResultSet rs = pstmt.executeQuery()) {
				if (rs.next()) {
					return LocalDate.parse(rs.getString("dayKey"));
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return null;
	}

	private static List<Bar> capturedRealtimeBarsForSymbolDay(String symbol, LocalDate day) {
		List<Bar> bars = new ArrayList<Bar>();
		if (day == null) {
			return bars;
		}
		InstrumentSpec spec = instrumentFor(symbol);
		try {
			Instant start = day.atStartOfDay(NEW_YORK_ZONE).toInstant();
			Instant end = day.plusDays(1).atStartOfDay(NEW_YORK_ZONE).minusNanos(1L).toInstant();
			List<FuturesConnectionManager.InternalBar> captured = FuturesMarketDataStore.readCapturedBarsForRange(spec.symbol, start, end);
			for (int index = 0; index < captured.size(); index++) {
				Bar bar = barFromInternalCapturedBar(captured.get(index));
				if (bar != null && !bar.marketTime.isBefore(RTH_START) && bar.marketTime.isBefore(RTH_END)) {
					bars.add(bar);
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return bars;
	}

