	private static List<PortfolioPosition> livePositionsForSession(int sessionId, int snapshotId, boolean includePendingReconcile) {
		List<PortfolioPosition> positions = new ArrayList<PortfolioPosition>();
		String exitPredicate = includePendingReconcile
			? "AND (exit.status LIKE '%EXIT%' OR exit.status LIKE '%CLOSED%' OR exit.status LIKE '%FLAT%') "
				+ "AND (exit.payloadJson LIKE '%\"authoritative\":true%' OR exit.payloadJson LIKE '%\"source\":\"TOPSTEPX_METRICS_RECONCILE\"%')"
			: "AND (exit.status LIKE '%EXIT%' OR exit.status LIKE '%CLOSED%' OR exit.status LIKE '%FLAT%')";
		String sql = "SELECT entry.symbol, entry.side, entry.contracts, entry.entryPrice, entry.stopPrice, entry.targetPrice, entry.entryTime, entry.signalTime, entry.strategyCode, entry.strategyName, entry.status, entry.payloadJson, "
			+ "COALESCE(snapshot.practiceAccountId, '') AS accountId, "
			+ "COALESCE(("
				+ "SELECT o.brokerOrderId FROM FuturesLiveOrderLedger o "
				+ "WHERE o.snapshotID = entry.snapshotID AND o.symbol = entry.symbol AND o.strategyCode = entry.strategyCode "
				+ "AND o.signalTime = entry.signalTime AND o.entryTime = entry.entryTime "
				+ "AND UPPER(COALESCE(o.orderType, '')) <> 'CLOSE_POSITION' "
				+ "ORDER BY o.liveOrderID DESC LIMIT 1"
			+ "), '') AS ledgerBrokerOrderId, "
			+ "COALESCE(("
				+ "SELECT o.customTag FROM FuturesLiveOrderLedger o "
				+ "WHERE o.snapshotID = entry.snapshotID AND o.symbol = entry.symbol AND o.strategyCode = entry.strategyCode "
				+ "AND o.signalTime = entry.signalTime AND o.entryTime = entry.entryTime "
				+ "AND UPPER(COALESCE(o.orderType, '')) <> 'CLOSE_POSITION' "
				+ "ORDER BY o.liveOrderID DESC LIMIT 1"
			+ "), '') AS ledgerCustomTag, "
			+ "COALESCE(("
				+ "SELECT o.responseJson FROM FuturesLiveOrderLedger o "
				+ "WHERE o.snapshotID = entry.snapshotID AND o.symbol = entry.symbol AND o.strategyCode = entry.strategyCode "
				+ "AND o.signalTime = entry.signalTime AND o.entryTime = entry.entryTime "
				+ "AND UPPER(COALESCE(o.orderType, '')) <> 'CLOSE_POSITION' "
				+ "ORDER BY o.liveOrderID DESC LIMIT 1"
			+ "), '') AS ledgerResponseJson "
			+ "FROM FuturesLiveSignalDecisions entry "
			+ "LEFT JOIN FuturesLiveStrategySnapshots snapshot ON entry.snapshotID = snapshot.snapshotID "
			+ "WHERE entry.sessionID = ? AND entry.snapshotID = ? AND entry.contracts > 0 "
			+ "AND entry.status IN ('SUBMITTED_TOPSTEPX', 'ACCEPTED_SIMULATED_LIVE') "
			+ "AND NOT EXISTS ("
				+ "SELECT 1 FROM FuturesLiveSignalDecisions exit "
				+ "WHERE exit.sessionID = entry.sessionID AND exit.snapshotID = entry.snapshotID "
				+ "AND exit.symbol = entry.symbol AND exit.strategyCode = entry.strategyCode "
				+ "AND exit.signalTime = entry.entryTime "
				+ exitPredicate
			+ ") "
			+ "ORDER BY entry.decisionID";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setInt(1, sessionId);
			pstmt.setInt(2, snapshotId);
			try (ResultSet rs = pstmt.executeQuery()) {
				while (rs.next()) {
					String symbol = normalizeSymbol(rs.getString("symbol"));
					InstrumentSpec spec = instrumentFor(symbol);
					String liveStrategySlot = activeLiveStrategySlot(currentLiveSessionCopy(), null);
					FuturesRiskSettings risk = loadFuturesRiskSettings(symbol, liveStrategySlot);
					FuturesStrategySettings strategySettings = loadFuturesStrategySettings(symbol, liveStrategySlot);
					String strategyCode = cleanOrDefault(rs.getString("strategyCode"), "LIVE");
					String payloadJson = cleanOrDefault(rs.getString("payloadJson"), "{}");
					String ledgerResponseJson = cleanOrDefault(rs.getString("ledgerResponseJson"), "{}");
					int maxHoldBars = Math.max(0, (int) Math.round(jsonNumber(payloadJson, "maxHoldBars", liveMaxHoldBarsForStrategy(strategyCode, strategySettings))));
					PortfolioPosition position = new PortfolioPosition();
					position.symbol = symbol;
					position.spec = spec;
					position.side = cleanOrDefault(rs.getString("side"), "LONG");
					position.accountId = cleanOrDefault(rs.getString("accountId"), "");
					position.brokerOrderId = firstNonBlank(rs.getString("ledgerBrokerOrderId"), brokerOrderIdFromJson(payloadJson));
					position.customTag = firstNonBlank(rs.getString("ledgerCustomTag"), jsonText(payloadJson, "customTag", ""));
						position.contractId = firstNonBlank(jsonText(ledgerResponseJson, "contractId", ""), jsonText(payloadJson, "contractId", ""));
						position.contracts = Math.max(1, rs.getInt("contracts"));
						position.entryPrice = rs.getDouble("entryPrice");
						position.plannedEntryPrice = position.entryPrice;
						position.stopPrice = rs.getDouble("stopPrice");
						position.activeStopPrice = position.stopPrice;
						position.targetPrice = rs.getDouble("targetPrice");
						hydrateLivePositionFromBroker(position);
						position.initialRisk = Math.abs(position.entryPrice - position.stopPrice);
					position.minTrailDistance = Math.max(spec.tickSize * 8.0, position.initialRisk * 0.55);
					position.commissionPerContract = risk.commissionPerContract;
					position.riskPerContract = ((position.initialRisk / spec.tickSize) * spec.tickValue) + (position.commissionPerContract * 2.0);
					position.openedAt = cleanOrDefault(rs.getString("entryTime"), "");
					LocalDateTime openedAt = parseDisplayLocalDateTime(position.openedAt);
					position.openedMarketTime = openedAt == null ? null : openedAt.toLocalTime();
					position.entryIndex = -1;
					position.signal = signal(
						strategyCode,
						cleanOrDefault(rs.getString("strategyName"), "Live Position"),
						position.side,
						-1,
						position.entryPrice,
						position.stopPrice,
						position.targetPrice,
						maxHoldBars,
						"Existing live portfolio exposure."
					);
					position.sourceStatus = cleanOrDefault(rs.getString("status"), "");
					applyDynamicTradeStateToPosition(sessionId, snapshotId, position);
					positions.add(position);
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return positions;
	}

	private static void resetDynamicTradeStatesForSession(int sessionId) {
		if (sessionId == 0) {
			return;
		}
		synchronized (FuturesManager.class) {
			String prefix = sessionId + "|";
			List<String> removeKeys = new ArrayList<String>();
			for (String key : LIVE_DTM_STATES.keySet()) {
				if (key.startsWith(prefix)) {
					removeKeys.add(key);
				}
			}
			for (String key : removeKeys) {
				LIVE_DTM_STATES.remove(key);
			}
		}
	}

	private static void hydrateLivePositionFromBroker(PortfolioPosition position) {
		if (position == null) {
			return;
		}
		String positionsJson = LiveRuntimeState.getBrokerPositionsJson();
		List<String> brokerPositions = jsonArrayObjects("{\"positions\":" + jsonObjectOrDefault(positionsJson, "[]") + "}", "positions");
		if (brokerPositions.isEmpty()) {
			return;
		}
		String expectedSymbol = normalizeSymbol(position.symbol);
		String expectedSide = cleanOrDefault(position.side, "").toUpperCase(Locale.US);
		String expectedAccount = cleanOrDefault(position.accountId, "");
		for (int index = 0; index < brokerPositions.size(); index++) {
			String brokerPosition = brokerPositions.get(index);
			String brokerSymbol = normalizeSymbol(jsonText(brokerPosition, "symbol", ""));
			if (!expectedSymbol.equals(brokerSymbol)) {
				continue;
			}
			String brokerAccount = cleanOrDefault(jsonText(brokerPosition, "accountId", ""), "");
			if (expectedAccount.length() > 0 && brokerAccount.length() > 0 && !expectedAccount.equals(brokerAccount)) {
				continue;
			}
			String brokerSide = cleanOrDefault(jsonText(brokerPosition, "side", ""), "").toUpperCase(Locale.US);
			if (expectedSide.length() > 0 && brokerSide.length() > 0 && !expectedSide.equals(brokerSide)) {
				continue;
			}
			double brokerEntry = jsonNumber(brokerPosition, "entryPrice", jsonNumber(brokerPosition, "averagePrice", 0.0));
			int brokerContracts = (int) Math.round(Math.abs(jsonNumber(brokerPosition, "contracts", 0.0)));
			if (brokerEntry > 0.0) {
				position.entryPrice = roundToTick(position.spec, brokerEntry);
			}
			if (brokerContracts > 0) {
				position.contracts = brokerContracts;
			}
			return;
		}
	}

	private static void applyDynamicTradeStateToPosition(int sessionId, int snapshotId, PortfolioPosition position) {
		if (position == null) {
			return;
		}
		position.originalContracts = position.contracts;
		DynamicTradeState state = dynamicTradeState(sessionId, snapshotId, position, false);
		if (state == null) {
			return;
		}
		if (state.remainingContracts > 0 && state.remainingContracts < position.contracts) {
			position.contracts = state.remainingContracts;
		}
			if (state.lastStopPrice > 0.0) {
				position.activeStopPrice = state.lastStopPrice;
			}
		if (state.lastTargetPrice > 0.0) {
			position.targetPrice = state.lastTargetPrice;
		}
		position.dtmPartialContractsClosed = state.partialContractsClosed;
		position.dtmRealizedPnl = state.realizedPnl;
		position.dtmTimelineJson = state.timelineJson;
		position.dtmFinalAction = state.finalAction;
		position.dtmPartialDecision = state.partialDecision;
		position.dtmRunnerDecision = state.runnerDecision;
	}

	private static DynamicTradeState dynamicTradeState(int sessionId, int snapshotId, PortfolioPosition position, boolean create) {
		if (position == null) {
			return null;
		}
		String key = dynamicTradeStateKey(sessionId, snapshotId, position);
		synchronized (FuturesManager.class) {
			DynamicTradeState state = LIVE_DTM_STATES.get(key);
			if (state == null && create) {
				state = new DynamicTradeState();
					state.originalContracts = Math.max(1, position.originalContracts > 0 ? position.originalContracts : position.contracts);
					state.remainingContracts = Math.max(1, position.contracts);
					state.lastStopPrice = position.activeStopPrice > 0.0 ? position.activeStopPrice : position.stopPrice;
					state.lastTargetPrice = position.targetPrice;
					LIVE_DTM_STATES.put(key, state);
				}
			return state;
		}
	}

	private static String dynamicTradeStateKey(int sessionId, int snapshotId, PortfolioPosition position) {
		return sessionId
			+ "|" + normalizeSymbol(position == null ? "" : position.symbol)
			+ "|" + cleanOrDefault(position == null || position.signal == null ? "" : position.signal.strategyCode, "")
			+ "|" + cleanOrDefault(position == null ? "" : position.side, "")
			+ "|" + round(position == null ? 0.0 : position.entryPrice)
			+ "|" + cleanOrDefault(position == null ? "" : position.openedAt, "")
			+ "|" + cleanOrderId(position == null ? "" : position.brokerOrderId);
	}

	private static int liveMaxHoldBarsForStrategy(String strategyCode, FuturesStrategySettings settings) {
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		String code = cleanOrDefault(strategyCode, "").toUpperCase();
		if ("ORB2".equals(code)) return Math.max(0, safe.openingMomentumMaxHoldBars);
		if ("LORB".equals(code)) return Math.max(0, safe.lateOrbContinuationMaxHoldBars);
		if ("OMOM".equals(code)) return Math.max(0, safe.openingMomentumMaxHoldBars);
		if ("VWAP".equals(code)) return 15;
		if ("VRCL".equals(code)) return 18;
		if ("MSCALP".equals(code)) return Math.max(0, safe.microScalpMaxHoldBars);
		if ("TLAD".equals(code)) return Math.max(0, safe.trendLadderMaxHoldBars);
		if ("RCB".equals(code)) return Math.max(0, safe.rangeCompressionMaxHoldBars);
		if ("VPB".equals(code)) return Math.max(0, safe.valueAreaMaxHoldBars);
		if ("KELT".equals(code) || "KREV".equals(code)) return Math.max(0, safe.keltnerMaxHoldBars);
		if ("AFT".equals(code)) return Math.max(0, safe.afternoonMaxHoldBars);
		if ("IPB".equals(code)) return 25;
		if ("MIM".equals(code)) return 35;
		if ("PDB".equals(code)) return 35;
		if ("FVG".equals(code)) return Math.max(0, safe.fvgMaxHoldBars);
		if ("IFVG".equals(code)) return Math.max(0, safe.fvgMaxHoldBars);
		if ("CMOM".equals(code)) return 40;
		if ("SHDW".equals(code)) return Math.max(0, safe.microShadowMaxHoldBars);
		if ("ECHO".equals(code)) return Math.max(0, safe.microEchoMaxHoldBars);
		if ("WFT".equals(code)) return Math.max(0, safe.winnerFollowThroughMaxHoldBars);
		if ("EIA".equals(code)) return Math.max(0, safe.mclEiaMaxHoldBars);
		if ("COPEN".equals(code)) return Math.max(0, safe.mclCrudeOpenMaxHoldBars);
		if ("IDXCONF".equals(code)) return Math.max(0, safe.mymIndexConfirmationMaxHoldBars);
		if ("MYMORB2".equals(code)) return Math.max(0, safe.mymOrbRetestMaxHoldBars);
		if ("MYMBR".equals(code)) return Math.max(0, safe.mymBreadthMaxHoldBars);
		if ("MCLTC".equals(code)) return Math.max(0, safe.mclTrendMaxHoldBars);
		if ("BOSRT".equals(code)) return Math.max(0, safe.bosRetestMaxHoldBars);
		return 0;
	}

	private static Map<String, Integer> liveTakenByStrategyForSession(int sessionId, int snapshotId) {
		Map<String, Integer> counts = new HashMap<String, Integer>();
		String todayPrefix = LocalDate.now(NEW_YORK_ZONE).toString() + " ";
		String sql = "SELECT symbol, strategyCode, COUNT(*) AS taken "
			+ "FROM FuturesLiveSignalDecisions "
			+ "WHERE sessionID = ? AND snapshotID = ? AND contracts > 0 "
			+ "AND signalTime LIKE ? "
			+ "AND status IN ('SUBMITTED_TOPSTEPX', 'ACCEPTED_SIMULATED_LIVE') "
			+ "GROUP BY symbol, strategyCode";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setInt(1, sessionId);
			pstmt.setInt(2, snapshotId);
			pstmt.setString(3, todayPrefix + "%");
			try (ResultSet rs = pstmt.executeQuery()) {
				while (rs.next()) {
					String key = strategyDailyLimitKey(rs.getString("symbol"), rs.getString("strategyCode"));
					counts.put(key, countFor(counts, key) + rs.getInt("taken"));
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return counts;
	}

	private static void insertLiveSignalDecisionFromSignal(
		int sessionId,
		int snapshotId,
		String symbol,
		Signal signal,
		String signalTime,
		String entryTime,
		int contracts,
		double entryPrice,
		double stopPrice,
		double targetPrice,
		double fundedMiniUnits,
		String status,
		String reason
	) {
		insertLiveSignalDecisionFromSignal(sessionId, snapshotId, symbol, signal, signalTime, entryTime, contracts, entryPrice, stopPrice, targetPrice, fundedMiniUnits, status, reason, "");
	}

	private static void insertLiveSignalDecisionFromSignal(
		int sessionId,
		int snapshotId,
		String symbol,
		Signal signal,
		String signalTime,
		String entryTime,
		int contracts,
		double entryPrice,
		double stopPrice,
		double targetPrice,
		double fundedMiniUnits,
		String status,
		String reason,
		String brokerSubmitJson
	) {
		insertLiveSignalDecisionFromSignal(sessionId, snapshotId, symbol, signal, signalTime, entryTime, contracts, entryPrice, stopPrice, targetPrice, fundedMiniUnits, status, reason, brokerSubmitJson, "{}");
	}

	private static void insertLiveSignalDecisionFromSignal(
		int sessionId,
		int snapshotId,
		String symbol,
		Signal signal,
		String signalTime,
		String entryTime,
		int contracts,
		double entryPrice,
		double stopPrice,
		double targetPrice,
		double fundedMiniUnits,
		String status,
		String reason,
		String brokerSubmitJson,
		String diagnosticsJson
	) {
		String brokerPayload = cleanOrDefault(brokerSubmitJson, "").length() == 0
			? ""
			: ",\"brokerSubmit\":" + jsonObjectOrDefault(brokerSubmitJson, "{}");
		String diagnosticsPayload = cleanOrDefault(diagnosticsJson, "").length() == 0 || "{}".equals(cleanOrDefault(diagnosticsJson, ""))
			? ""
			: ",\"sizingDiagnostics\":" + jsonObjectOrDefault(diagnosticsJson, "{}");
		insertLiveDecision(
			sessionId,
			snapshotId,
			symbol,
			signal.strategyCode,
			signal.strategyName,
			signal.side,
			signalTime,
			entryTime,
			contracts,
			entryPrice,
			stopPrice,
			targetPrice,
			fundedMiniUnits,
			status,
			reason,
			"{"
					+ "\"symbol\":" + jsonString(symbol) + ","
					+ "\"strategyCode\":" + jsonString(signal.strategyCode) + ","
					+ "\"strategyName\":" + jsonString(signal.strategyName) + ","
					+ "\"sourceStrategyCode\":" + jsonString(cleanOrDefault(signal.sourceStrategyCode, "")) + ","
					+ "\"sourceStrategyName\":" + jsonString(cleanOrDefault(signal.sourceStrategyName, "")) + ","
					+ "\"side\":" + jsonString(signal.side) + ","
				+ "\"traceKey\":" + jsonString(liveParityTraceKey(symbol, signal.strategyCode, signal.side, signalTime, entryTime)) + ","
				+ "\"signalTime\":" + jsonString(signalTime) + ","
				+ "\"entryTime\":" + jsonString(entryTime) + ","
				+ "\"signalEntryPrice\":" + round(signal.entryPrice) + ","
				+ "\"signalNotes\":" + jsonString(cleanOrDefault(signal.notes, "")) + ","
				+ "\"maxHoldBars\":" + signal.maxHoldBars + ","
				+ "\"entryPrice\":" + round(entryPrice) + ","
				+ "\"stopPrice\":" + round(stopPrice) + ","
				+ "\"targetPrice\":" + round(targetPrice) + ","
				+ "\"contracts\":" + contracts + ","
				+ "\"fundedMiniUnits\":" + round(fundedMiniUnits) + ","
				+ "\"reason\":" + jsonString(reason) + ","
				+ "\"tradeReason\":" + liveEntryTradeReasoningJson(symbol, signal, signal.side, contracts, entryPrice, stopPrice, targetPrice, fundedMiniUnits, status, reason, diagnosticsJson)
				+ brokerPayload
				+ diagnosticsPayload
				+ "}"
		);
	}

	private static String jsonStringSummary(String json) {
		String message = jsonText(json, "message", "");
		if (message != null && message.trim().length() > 0) {
			return message;
		}
		return cleanOrDefault(json, "").length() > 180 ? cleanOrDefault(json, "").substring(0, 180) : cleanOrDefault(json, "");
	}

	private static String brokerOrderIdFromJson(String json) {
		String text = firstNonBlank(
			jsonText(json, "brokerOrderId", ""),
			jsonText(json, "orderId", ""),
			jsonText(json, "closeOrderId", "")
		);
		if (text.length() > 0) {
			return cleanOrderId(text);
		}
		double numeric = jsonFirstNumber(json, new String[] { "brokerOrderId", "orderId", "closeOrderId" }, 0.0);
		return numeric > 0.0 ? String.valueOf((long) numeric) : "";
	}

	private static FuturesLiveSession copyLiveSession(FuturesLiveSession source) {
		FuturesLiveSession copy = new FuturesLiveSession();
		copy.running = source.running;
		copy.starting = source.starting;
		copy.sessionId = source.sessionId;
		copy.symbol = source.symbol;
		copy.executionMode = source.executionMode;
		copy.fundedProfile = source.fundedProfile;
		copy.strategyPreset = source.strategyPreset;
		copy.strategySlot = source.strategySlot;
		copy.symbols = source.symbols;
		copy.startedAt = source.startedAt;
		copy.lastUpdatedAt = source.lastUpdatedAt;
		copy.lastDryRunAt = source.lastDryRunAt;
		copy.dataMode = source.dataMode;
		copy.lastBarTime = source.lastBarTime;
		copy.accountSize = source.accountSize;
		copy.maxTrailingDrawdown = source.maxTrailingDrawdown;
		copy.dailyLossLimit = source.dailyLossLimit;
		copy.maxRiskPerTrade = source.maxRiskPerTrade;
		copy.maxContracts = source.maxContracts;
		copy.commissionPerContract = source.commissionPerContract;
		copy.slippageTicks = source.slippageTicks;
		copy.profitTarget = source.profitTarget;
		copy.maxOpenPositions = source.maxOpenPositions;
		copy.maxAggregateContracts = source.maxAggregateContracts;
		copy.maxAggregateMiniUnits = source.maxAggregateMiniUnits;
		copy.dtmEnabled = source.dtmEnabled;
		copy.decisionCount = source.decisionCount;
		copy.acceptedDecisionCount = source.acceptedDecisionCount;
		copy.rejectedDecisionCount = source.rejectedDecisionCount;
		copy.lastDecision = source.lastDecision;
		copy.lastProcessedLiveBarTime = source.lastProcessedLiveBarTime;
		copy.automationCycles = source.automationCycles;
		copy.flattenAttempted = source.flattenAttempted;
		copy.restingOrdersCancelAttempted = source.restingOrdersCancelAttempted;
		copy.postCloseVerified = source.postCloseVerified;
		copy.closeActionDate = source.closeActionDate;
		return copy;
	}

	public static String startLive(
		String symbol,
		String executionMode,
		String fundedProfile,
		String topstepAccountId,
		double accountSize,
		double maxTrailingDrawdown,
		double dailyLossLimit,
		double maxRiskPerTrade,
		int maxContracts,
		double commissionPerContract,
		double slippageTicks,
		double profitTarget,
		int maxOpenPositions,
		int maxAggregateContracts,
		double maxAggregateMiniUnits,
		String symbols,
		String strategyPreset,
		boolean dtmEnabled
		) {
			initializeStore();
			synchronized (FuturesManager.class) {
				if (liveSession.running) {
					return "{\"success\":true,\"message\":\"Futures live bot is already running.\",\"status\":" + getLiveStatusJson() + "}";
				}
				if (liveSession.starting) {
					return "{\"success\":true,\"message\":\"Futures live bot startup is already in progress.\",\"status\":" + getLiveStatusJson() + "}";
				}
			}
			String normalizedMode = normalizeExecutionMode(executionMode);
		FundedRuleProfile profile = fundedRuleProfileFor(fundedProfile);
		String cleanLiveSymbols = cleanSymbolsCsv(cleanOrDefault(symbols, DEFAULT_LIVE_SYMBOLS));
		String strategyPresetName = normalizeStrategyPresetName(strategyPreset);
		String strategySlot = strategyPresetSlot(strategyPresetName);
		boolean orderFlowFeaturesEnabled = dtmEnabled;
		String configuredAccountId = FuturesConnectionManager.getTopstepxConfiguredAccountId();
		String requestedAccountId = cleanOrDefault(topstepAccountId, "");
		String executionAccountId = requestedAccountId.length() > 0
			? requestedAccountId
			: cleanOrDefault(configuredAccountId, accountIdForFundedProfile(profile.code));
		if ("TOPSTEPX".equals(normalizedMode)) {
			String refreshedAccountId = FuturesConnectionManager.refreshTopstepxAccountForStart(executionAccountId);
			if (refreshedAccountId.length() > 0 && !refreshedAccountId.equals(executionAccountId)) {
				executionAccountId = refreshedAccountId;
				requestedAccountId = refreshedAccountId;
				configuredAccountId = FuturesConnectionManager.getTopstepxConfiguredAccountId();
			}
		}
			String presetValidationMessage = validateStrategyPresetForSymbols(strategyPresetName, cleanLiveSymbols);
			if (presetValidationMessage.length() > 0) {
				return "{\"success\":false,\"message\":" + jsonString(presetValidationMessage) + ",\"status\":" + getLiveStatusJson() + "}";
		}
		LiveStrategySnapshotRow snapshot = ensureLiveStrategySnapshotForPreset(cleanLiveSymbols, profile, strategyPresetName, strategySlot, executionAccountId);
			if (snapshot == null) {
				return "{\"success\":false,\"message\":\"Strategy preset could not be prepared for the live bot.\",\"status\":" + getLiveStatusJson() + "}";
			}
			String requiredAccountId = selectedTopstepAccountId(snapshot, profile.code);
			boolean riskConfigLocked = isTopstep50KProfile(profile.code);
			double selectedAccountBalance = liveSelectedAccountSize(requiredAccountId, profile.code, cleanLiveSymbols, positiveOrDefault(accountSize, profile.accountSize));
			double sessionAccountSize = riskConfigLocked ? profile.accountSize : selectedAccountBalance;
		double sessionTrailingDrawdown = riskConfigLocked ? profile.maxTrailingDrawdown : positiveOrDefault(maxTrailingDrawdown, profile.maxTrailingDrawdown);
		double sessionDailyLossLimit = riskConfigLocked ? profile.dailyLossLimit : positiveOrDefault(dailyLossLimit, profile.dailyLossLimit);
		double sessionMaxRiskPerTrade = riskConfigLocked ? profile.maxRiskPerTrade : positiveOrDefault(maxRiskPerTrade, profile.maxRiskPerTrade);
		int sessionMaxContracts = riskConfigLocked ? profile.maxMicroContracts : (maxContracts > 0 ? maxContracts : profile.maxMicroContracts);
		double sessionCommission = commissionPerContract >= 0.0 ? commissionPerContract : 1.24;
		double sessionSlippageTicks = slippageTicks >= 0.0 ? slippageTicks : 1.0;
		double sessionProfitTarget = profitTarget >= 0.0 ? profitTarget : profile.profitTarget;
		int sessionMaxOpenPositions = riskConfigLocked ? profile.maxOpenPositions : (maxOpenPositions > 0 ? maxOpenPositions : profile.maxOpenPositions);
		int sessionMaxAggregateContracts = riskConfigLocked ? profile.maxAggregateContracts : (maxAggregateContracts > 0 ? maxAggregateContracts : profile.maxAggregateContracts);
		double sessionMaxAggregateMiniUnits = riskConfigLocked ? profile.maxAggregateMiniUnits : (maxAggregateMiniUnits > 0.0 ? maxAggregateMiniUnits : profile.maxAggregateMiniUnits);
		if (!"SIMULATED".equals(normalizedMode)) {
			if (!"TOPSTEPX".equals(normalizedMode)) {
				return "{\"success\":false,\"message\":\"Only TopstepX order mode can be started from this live UI.\",\"status\":" + getLiveStatusJson() + "}";
			}
			if (requiredAccountId.length() == 0) {
				return "{\"success\":false,\"message\":" + jsonString(profile.name + " does not have a configured Topstep account ID yet.") + ",\"status\":" + getLiveStatusJson() + "}";
			}
			if (!requiredAccountId.equals(configuredAccountId)) {
				return "{\"success\":false,\"message\":" + jsonString("Select Topstep account " + requiredAccountId + " before starting the live bot.") + ",\"status\":" + getLiveStatusJson() + "}";
			}
				if (!FuturesConnectionManager.isExecutionProviderReady(normalizedMode)) {
					return "{\"success\":false,\"message\":"
						+ jsonString("Live futures execution is not ready for " + normalizedMode + ". Save and test that connection first.")
						+ ",\"status\":" + getLiveStatusJson() + "}";
				}
				boolean realtimeAccountMismatch = ProjectXRealtimeManager.isRunning()
					&& !requiredAccountId.equals(ProjectXRealtimeManager.currentAccountId());
				if (realtimeAccountMismatch || !ProjectXRealtimeManager.isRunning() || (orderFlowFeaturesEnabled && !ProjectXRealtimeManager.isDepthIncluded())) {
					boolean includeDepth = orderFlowFeaturesEnabled || (ProjectXRealtimeManager.isRunning() && !ProjectXRealtimeManager.isDepthIncluded());
					String realtimeStart = ProjectXRealtimeManager.isRunning()
						? ProjectXRealtimeManager.restartReadOnly(cleanLiveSymbols, includeDepth, true)
						: ProjectXRealtimeManager.startReadOnly(cleanLiveSymbols, includeDepth, true);
				if (!jsonBoolean(realtimeStart, "success")) {
					return "{\"success\":false,\"message\":"
						+ jsonString("ProjectX realtime start failed before Topstep order automation: " + jsonStringSummary(realtimeStart))
						+ ",\"status\":" + getLiveStatusJson() + "}";
				}
				}
				String startedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
				int sessionId = createLiveEngineSession(snapshot, normalizedMode, ProjectXRealtimeManager.currentDataMode(), "STARTING", "", startedAt);
				synchronized (FuturesManager.class) {
					liveSession.running = false;
					liveSession.starting = true;
						liveSession.symbol = normalizeSymbol(symbol);
						liveSession.sessionId = sessionId;
						liveSession.symbols = cleanLiveSymbols;
					liveSession.executionMode = normalizedMode;
					liveSession.fundedProfile = profile.code;
					liveSession.strategyPreset = strategyPresetName;
					liveSession.strategySlot = strategySlot;
				liveSession.accountSize = sessionAccountSize;
				liveSession.maxTrailingDrawdown = sessionTrailingDrawdown;
				liveSession.dailyLossLimit = sessionDailyLossLimit;
				liveSession.maxRiskPerTrade = sessionMaxRiskPerTrade;
				liveSession.maxContracts = sessionMaxContracts;
				liveSession.commissionPerContract = sessionCommission;
				liveSession.slippageTicks = sessionSlippageTicks;
				liveSession.profitTarget = sessionProfitTarget;
				liveSession.maxOpenPositions = sessionMaxOpenPositions;
				liveSession.maxAggregateContracts = sessionMaxAggregateContracts;
				liveSession.maxAggregateMiniUnits = sessionMaxAggregateMiniUnits;
				liveSession.dtmEnabled = dtmEnabled;
				liveSession.startedAt = startedAt;
				liveSession.lastUpdatedAt = liveSession.startedAt;
				liveSession.lastDryRunAt = "";
				liveSession.dataMode = ProjectXRealtimeManager.currentDataMode();
				liveSession.lastBarTime = "";
				liveSession.decisionCount = 0;
				liveSession.acceptedDecisionCount = 0;
				liveSession.rejectedDecisionCount = 0;
				liveSession.lastProcessedLiveBarTime = "";
				liveSession.automationCycles = 0;
				liveSession.flattenAttempted = false;
					liveSession.restingOrdersCancelAttempted = false;
					liveSession.postCloseVerified = false;
					liveSession.closeActionDate = "";
					liveSession.lastDecision = "Startup account reinitialization is running before strategy automation.";
				}
				resetDynamicTradeStatesForSession(sessionId);
				resetLiveMarketDataTransitionState();
				resetLiveThinkingLog(sessionId);
				String startupFlattenResponse = FuturesConnectionManager.flattenTopstepxPracticeAccount(requiredAccountId);
				boolean startupFlattened = jsonBoolean(startupFlattenResponse, "success");
				String startupMessage = startupFlattened
					? "Topstep account reinitialized. Startup flatten/cancel sweep completed before strategy automation."
					: "Topstep account reinitialization failed before start: " + jsonStringSummary(startupFlattenResponse);
				recordLiveAudit(
					startupFlattened ? "PRACTICE_START_REINIT_SWEEP" : "PRACTICE_START_REINIT_SWEEP_FAILED",
					startupFlattened ? "WARN" : "ERROR",
					startupMessage,
					startupFlattenResponse
				);
				if (!startupFlattened) {
					synchronized (FuturesManager.class) {
						liveSession.running = false;
						liveSession.starting = false;
						liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
						liveSession.lastDecision = startupMessage;
					}
					updateLiveEngineSession(sessionId, "START_BLOCKED", "", 0, 0, 0, startupMessage);
					pushLiveEvent(
						sessionId,
						"BOT_START_BLOCKED",
						"Start Safety",
						"error",
						"",
						"",
						"Startup reinit failed.",
						startupMessage,
						"{"
							+ "\"action\":\"startup_flatten\","
							+ "\"status\":\"needs_attention\","
							+ "\"account\":" + jsonString(requiredAccountId) + ","
							+ "\"summary\":" + jsonString(jsonStringSummary(startupFlattenResponse))
							+ "}"
					);
					return "{\"success\":false,\"message\":" + jsonString(startupMessage) + ",\"status\":" + getLiveStatusJson() + "}";
				}
				MarketSessionStatus marketStatus = currentMarketSessionStatus();
				synchronized (FuturesManager.class) {
					liveSession.running = true;
					liveSession.starting = false;
					liveSession.flattenAttempted = true;
					liveSession.restingOrdersCancelAttempted = true;
					if (marketStatus.tradingDay
						&& (marketStatus.flattenPositions || marketStatus.verifyFlat || "RTH_CLOSED".equals(marketStatus.code))) {
						liveSession.closeActionDate = marketStatus.marketDate;
					}
					liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
					liveSession.lastDecision = marketStatus.entryWindowOpen
						? "TopstepX account reinitialized for " + profile.name + ". Waiting for validated live signals."
						: marketStatus.label + ": " + marketStatus.detail;
				}
				updateLiveEngineSession(sessionId, "RUNNING", "", 0, 0, 0, startupMessage);
				pushLiveEvent(
					sessionId,
					"BOT_STARTED",
				"Live Bot",
					"active",
					"",
					"",
					"Bot Started",
					"Account initialized; Topstep flatten/cancel sweep completed before strategy automation.",
					"{"
							+ "\"symbols\":" + jsonString(cleanLiveSymbols) + ","
							+ "\"strategyConfig\":" + jsonString(strategyPresetName) + ","
							+ "\"strategyPreset\":" + jsonString(strategyPresetName) + ","
						+ "\"riskConfig\":" + jsonString(profile.name) + ","
						+ "\"dtmEnabled\":" + dtmEnabled + ","
						+ "\"includeDepth\":" + orderFlowFeaturesEnabled + ","
						+ "\"mode\":" + jsonString(normalizedMode) + ","
						+ "\"profile\":" + jsonString(profile.name) + ","
						+ "\"account\":" + jsonString(requiredAccountId) + ","
						+ "\"marketData\":" + jsonString(ProjectXRealtimeManager.currentDataMode()) + ","
						+ "\"tradingGate\":" + jsonString(cleanOrDefault(marketStatus.label, "")) + ","
						+ "\"entriesEnabled\":" + marketStatus.entryWindowOpen + ","
						+ "\"action\":\"startup_flatten\","
						+ "\"status\":\"completed\","
						+ "\"summary\":" + jsonString(jsonStringSummary(startupFlattenResponse))
						+ "}"
				);
			startLiveAutomationLoop();
			return "{\"success\":true,\"message\":"
				+ jsonString("Live futures bot started. ProjectX prices are live and " + profile.name + " order automation is enabled.")
				+ ",\"status\":" + getLiveStatusJson() + "}";
		}
		boolean realtimeAccountMismatch = ProjectXRealtimeManager.isRunning()
			&& requiredAccountId.length() > 0
			&& !requiredAccountId.equals(ProjectXRealtimeManager.currentAccountId());
		if (realtimeAccountMismatch || !ProjectXRealtimeManager.isRunning() || (orderFlowFeaturesEnabled && !ProjectXRealtimeManager.isDepthIncluded())) {
			boolean includeDepth = orderFlowFeaturesEnabled || (ProjectXRealtimeManager.isRunning() && !ProjectXRealtimeManager.isDepthIncluded());
			String realtimeStart = ProjectXRealtimeManager.isRunning()
				? ProjectXRealtimeManager.restartReadOnly(cleanLiveSymbols, includeDepth, true)
				: ProjectXRealtimeManager.startReadOnly(cleanLiveSymbols, includeDepth, true);
			if (!jsonBoolean(realtimeStart, "success")) {
				return "{\"success\":false,\"message\":"
					+ jsonString("ProjectX realtime start failed before simulated automation: " + jsonStringSummary(realtimeStart))
					+ ",\"status\":" + getLiveStatusJson() + "}";
			}
		}
		String startedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
		int sessionId = createLiveEngineSession(snapshot, normalizedMode, ProjectXRealtimeManager.currentDataMode(), "RUNNING", "", startedAt);
			synchronized (FuturesManager.class) {
				liveSession.running = true;
				liveSession.starting = false;
					liveSession.symbol = normalizeSymbol(symbol);
				liveSession.sessionId = sessionId;
				liveSession.symbols = cleanLiveSymbols;
				liveSession.executionMode = normalizedMode;
				liveSession.fundedProfile = profile.code;
				liveSession.strategyPreset = strategyPresetName;
				liveSession.strategySlot = strategySlot;
			liveSession.accountSize = sessionAccountSize;
			liveSession.maxTrailingDrawdown = sessionTrailingDrawdown;
			liveSession.dailyLossLimit = sessionDailyLossLimit;
			liveSession.maxRiskPerTrade = sessionMaxRiskPerTrade;
			liveSession.maxContracts = sessionMaxContracts;
			liveSession.commissionPerContract = sessionCommission;
			liveSession.slippageTicks = sessionSlippageTicks;
			liveSession.profitTarget = sessionProfitTarget;
			liveSession.maxOpenPositions = sessionMaxOpenPositions;
			liveSession.maxAggregateContracts = sessionMaxAggregateContracts;
			liveSession.maxAggregateMiniUnits = sessionMaxAggregateMiniUnits;
			liveSession.dtmEnabled = dtmEnabled;
			liveSession.startedAt = startedAt;
			liveSession.lastUpdatedAt = liveSession.startedAt;
			liveSession.lastDryRunAt = "";
			liveSession.dataMode = ProjectXRealtimeManager.currentDataMode();
			liveSession.lastBarTime = "";
			liveSession.decisionCount = 0;
			liveSession.acceptedDecisionCount = 0;
			liveSession.rejectedDecisionCount = 0;
			liveSession.lastProcessedLiveBarTime = "";
			liveSession.automationCycles = 0;
			liveSession.flattenAttempted = false;
			liveSession.restingOrdersCancelAttempted = false;
			liveSession.postCloseVerified = false;
			liveSession.closeActionDate = "";
			MarketSessionStatus marketStatus = currentMarketSessionStatus();
			liveSession.lastDecision = marketStatus.entryWindowOpen
				? "Simulated live futures runner started. Live prices are being monitored."
				: marketStatus.label + ": " + marketStatus.detail;
			}
			resetLiveMarketDataTransitionState();
			resetLiveThinkingLog(sessionId);
			pushLiveEvent(
				sessionId,
				"BOT_STARTED",
				"Live Bot",
				"active",
				"",
				"",
				"Bot Started",
				"Simulated mode is scanning the active strategy symbols without broker submission.",
				"{"
						+ "\"symbols\":" + jsonString(cleanLiveSymbols) + ","
						+ "\"strategyConfig\":" + jsonString(strategyPresetName) + ","
						+ "\"strategyPreset\":" + jsonString(strategyPresetName) + ","
					+ "\"riskConfig\":" + jsonString(profile.name) + ","
					+ "\"dtmEnabled\":" + dtmEnabled + ","
					+ "\"includeDepth\":" + orderFlowFeaturesEnabled + ","
					+ "\"mode\":" + jsonString(normalizedMode) + ","
					+ "\"profile\":" + jsonString(profile.name) + ","
					+ "\"marketData\":" + jsonString(ProjectXRealtimeManager.currentDataMode())
					+ "}"
			);
			startLiveAutomationLoop();
			return "{\"success\":true,\"message\":\"Futures simulator started.\",\"status\":" + getLiveStatusJson() + "}";
		}

	public static String stopLive() {
		int sessionId;
		boolean wasRunning;
		FuturesLiveSession session;
		synchronized (FuturesManager.class) {
			session = copyLiveSession(liveSession);
			sessionId = session.sessionId;
			wasRunning = liveSession.running;
			liveSession.running = false;
			liveSession.starting = false;
			liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
			liveSession.lastDecision = "Futures live runner stopping; broker safety flatten will run if needed.";
		}
		stopLiveAutomationLoop();
		if (ProjectXRealtimeManager.isRunning()) {
			ProjectXRealtimeManager.stopReadOnly();
		}
		String stopMessage = "Futures live runner stopped.";
		if (wasRunning && "TOPSTEPX".equals(session.executionMode)) {
			LiveStrategySnapshotRow snapshot = loadActiveLiveStrategySnapshot();
			String activeAccountId = activeLiveTopstepAccountId(session, snapshot);
			String flattenResponse = activeAccountId.length() == 0
				? "{\"success\":false,\"message\":\"Selected Topstep account has no account ID configured.\"}"
				: FuturesConnectionManager.flattenTopstepxPracticeAccount(activeAccountId);
			boolean flattened = jsonBoolean(flattenResponse, "success");
			stopMessage = flattened
				? "Futures live runner stopped. Topstep stop-safety flatten completed."
				: "Futures live runner stopped. Topstep stop-safety flatten needs attention: " + jsonStringSummary(flattenResponse);
			recordLiveAudit(
				flattened ? "PRACTICE_STOP_FLATTEN_SWEEP" : "PRACTICE_STOP_FLATTEN_SWEEP_FAILED",
				flattened ? "WARN" : "ERROR",
				stopMessage,
				flattenResponse
			);
			if (sessionId > 0) {
				pushLiveEvent(
					sessionId,
					"STOP_FLATTEN_SWEEP",
					"Stop Safety",
					flattened ? "warn" : "error",
					"",
					"",
					flattened ? "Account flattened." : "Stop flatten needs attention.",
					flattened ? "" : "Topstep stop-safety flatten failed.",
					"{"
						+ "\"action\":\"stop_flatten\","
						+ "\"status\":" + jsonString(flattened ? "completed" : "needs_attention") + ","
						+ "\"account\":" + jsonString(activeAccountId) + ","
						+ "\"summary\":" + jsonString(jsonStringSummary(flattenResponse))
						+ "}"
				);
			}
			synchronized (FuturesManager.class) {
				liveSession.flattenAttempted = true;
			}
		}
		String stoppedSymbols = cleanSymbolsCsv(cleanOrDefault(session.symbols, DEFAULT_LIVE_SYMBOLS));
		String marketDataReconciliation = FuturesMarketDataStore.reconcileLiveCapturedMarketDataOnStop(stoppedSymbols);
		boolean marketDataReconciled = jsonBoolean(marketDataReconciliation, "success");
		stopMessage = stopMessage + (marketDataReconciled
			? " Market-data stop merge completed."
			: " Market-data stop merge needs attention: " + jsonStringSummary(marketDataReconciliation));
		synchronized (FuturesManager.class) {
			liveSession.lastUpdatedAt = LocalDateTime.now().format(DISPLAY_TIME_FORMAT);
			liveSession.lastDecision = stopMessage;
		}
		resetLiveMarketDataTransitionState();
		if (sessionId > 0) {
			updateLiveEngineSession(sessionId, "STOPPED", "", session.decisionCount, session.acceptedDecisionCount, session.rejectedDecisionCount, stopMessage);
			pushLiveEvent(
				sessionId,
				"BOT_STOPPED",
				"Live Bot",
				"closed",
				"",
				"",
				"Live bot stopped.",
				stopMessage,
				"{\"sessionId\":" + sessionId + ",\"marketDataReconciliation\":" + marketDataReconciliation + "}"
			);
		}
		return "{\"success\":true,\"message\":" + jsonString(stopMessage) + ",\"marketDataReconciliation\":" + marketDataReconciliation + ",\"status\":" + getLiveStatusJson() + "}";
	}

	public static String getLiveTradeCacheJson(String accountId) {
		String cleanAccountId = cleanLiveTradeCacheAccountId(accountId);
		File file = liveTradeCacheFile(cleanAccountId);
		if (!file.exists()) {
			return emptyLiveTradeCacheJson(cleanAccountId);
		}
		try {
			if (file.length() > LIVE_TRADE_CACHE_MAX_BYTES) {
				return "{\"success\":false,\"message\":\"Live trade cache file is too large to load safely.\",\"accountId\":" + jsonString(cleanAccountId) + ",\"rows\":[]}";
			}
			String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8).trim();
			if (json.startsWith("{") && json.contains("\"rows\"")) {
				if (liveTradeCachePayloadMatchesAccount(json, cleanAccountId)) {
					return json;
				}
				return emptyLiveTradeCacheJson(cleanAccountId);
			}
			return emptyLiveTradeCacheJson(cleanAccountId);
		} catch (IOException e) {
			return "{\"success\":false,\"message\":" + jsonString("Failed to read live trade cache: " + cleanOrDefault(e.getMessage(), "unknown error")) + ",\"accountId\":" + jsonString(cleanAccountId) + ",\"rows\":[]}";
		}
	}

	public static String saveLiveTradeCacheJson(String accountId, String payloadJson) {
		String cleanAccountId = cleanLiveTradeCacheAccountId(accountId);
		String payload = cleanOrDefault(payloadJson, "{}").trim();
		if (payload.length() > LIVE_TRADE_CACHE_MAX_BYTES) {
			return "{\"success\":false,\"message\":\"Live trade cache payload is too large.\",\"accountId\":" + jsonString(cleanAccountId) + "}";
		}
		if (!payload.startsWith("{") || !payload.contains("\"rows\"")) {
			return "{\"success\":false,\"message\":\"Live trade cache payload must be a JSON object with rows.\",\"accountId\":" + jsonString(cleanAccountId) + "}";
		}
		if (!liveTradeCachePayloadMatchesAccount(payload, cleanAccountId)) {
			return "{\"success\":false,\"message\":\"Live trade cache payload account does not match the selected account.\",\"accountId\":" + jsonString(cleanAccountId) + "}";
		}
		File file = liveTradeCacheFile(cleanAccountId);
		try {
			Files.write(file.toPath(), payload.getBytes(StandardCharsets.UTF_8));
			return "{"
				+ "\"success\":true,"
				+ "\"message\":\"Live trade cache saved.\","
				+ "\"accountId\":" + jsonString(cleanAccountId) + ","
				+ "\"path\":" + jsonString(file.getAbsolutePath())
				+ "}";
		} catch (IOException e) {
			return "{\"success\":false,\"message\":" + jsonString("Failed to save live trade cache: " + cleanOrDefault(e.getMessage(), "unknown error")) + ",\"accountId\":" + jsonString(cleanAccountId) + "}";
		}
	}

