	private static FundedRuleProfile fundedRuleProfile(
		String code,
		String name,
		String provider,
		double accountSize,
		double maxTrailingDrawdown,
		double dailyLossLimit,
		double maxRiskPerTrade,
		int maxContracts,
		int maxMicroContracts,
		int maxOpenPositions,
		int maxAggregateContracts,
		double maxAggregateMiniUnits,
		double profitTarget,
		String trailingDrawdownMode,
		String dailySession,
		String forceFlatTime,
		String notes
	) {
		FundedRuleProfile profile = new FundedRuleProfile();
		profile.code = code;
		profile.name = name;
		profile.provider = provider;
		profile.accountSize = accountSize;
		profile.maxTrailingDrawdown = maxTrailingDrawdown;
		profile.dailyLossLimit = dailyLossLimit;
		profile.maxRiskPerTrade = maxRiskPerTrade;
		profile.maxContracts = maxContracts;
		profile.maxMicroContracts = maxMicroContracts;
		profile.maxOpenPositions = maxOpenPositions;
		profile.maxAggregateContracts = maxAggregateContracts;
		profile.maxAggregateMiniUnits = maxAggregateMiniUnits;
		profile.profitTarget = profitTarget;
		profile.trailingDrawdownMode = trailingDrawdownMode;
		profile.dailySession = dailySession;
		profile.forceFlatTime = forceFlatTime;
		profile.notes = notes;
		return profile;
	}

	private static FundedRuleProfile fundedRuleProfileFor(String code) {
		String normalized = normalizeFundedProfileCode(code);
		List<FundedRuleProfile> profiles = fundedRuleProfiles();
		for (int index = 0; index < profiles.size(); index++) {
			if (profiles.get(index).code.equals(normalized)) {
				return profiles.get(index);
			}
		}
		return profiles.get(profiles.size() - 1);
	}

	private static String normalizeFundedProfileCode(String code) {
		String normalized = code == null || code.trim().isEmpty() ? "CUSTOM" : code.trim().toUpperCase();
		if ("TOPSTEP_50K_COMBINE".equals(normalized) || "TOPSTEP_50K_RESEARCH".equals(normalized)) {
			return "TOPSTEP_50K";
		}
		if ("TOPSTEP_100K_COMBINE".equals(normalized) || "TOPSTEP_100K_RESEARCH".equals(normalized)) {
			return "TOPSTEP_100K";
		}
		if ("TOPSTEP_150K_PRACTICE".equals(normalized) || "TOPSTEP_150K_RESEARCH".equals(normalized)) {
			return "TOPSTEP_150K";
		}
		return normalized;
	}

	private static String accountIdForFundedProfile(String code) {
		String normalized = normalizeFundedProfileCode(code);
		if ("CUSTOM".equals(normalized)) {
			return "";
		}
		if ("TOPSTEP_50K".equals(normalized)) {
			return TOPSTEPX_50K_COMBINE_ACCOUNT_ID;
		}
		if ("TOPSTEP_100K".equals(normalized)) {
			return TOPSTEPX_100K_COMBINE_ACCOUNT_ID;
		}
		return TOPSTEPX_PRACTICE_ACCOUNT_ID;
	}

	private static double accountSizeForBrokerProfile(String accountId, String profileCode, double fallbackAccountSize) {
		String cleanAccountId = cleanOrDefault(accountId, "");
		if (TOPSTEPX_PRACTICE_ACCOUNT_ID.equals(cleanAccountId)) {
			return 150000.0;
		}
		if (TOPSTEPX_50K_COMBINE_ACCOUNT_ID.equals(cleanAccountId)) {
			return 50000.0;
		}
		if (cleanOrDefault(TOPSTEPX_100K_COMBINE_ACCOUNT_ID, "").length() > 0 && TOPSTEPX_100K_COMBINE_ACCOUNT_ID.equals(cleanAccountId)) {
			return 100000.0;
		}
		FundedRuleProfile profile = fundedRuleProfileFor(profileCode);
		if (profile != null && profile.accountSize > 0.0) {
			return profile.accountSize;
		}
		return fallbackAccountSize > 0.0 ? fallbackAccountSize : 50000.0;
	}

	private static String accountModeForFundedProfile(String code) {
		String normalized = normalizeFundedProfileCode(code);
		if ("TOPSTEP_50K".equals(normalized) || "TOPSTEP_100K".equals(normalized) || "TOPSTEP_150K".equals(normalized)) {
			return normalized;
		}
		return TOPSTEPX_DEFAULT_ACCOUNT_MODE;
	}

	private static String accountModeForTopstepAccountId(String accountId, String fallbackProfileCode) {
		String cleanAccountId = cleanOrDefault(accountId, "");
		if (TOPSTEPX_PRACTICE_ACCOUNT_ID.equals(cleanAccountId)) {
			return "TOPSTEP_150K";
		}
		if (TOPSTEPX_50K_COMBINE_ACCOUNT_ID.equals(cleanAccountId)) {
			return "TOPSTEP_50K";
		}
		if (TOPSTEPX_100K_COMBINE_ACCOUNT_ID.equals(cleanAccountId)) {
			return "TOPSTEP_100K";
		}
		return accountModeForFundedProfile(fallbackProfileCode);
	}

