	private static double savedSizingScale(FuturesRiskSettings sourceRisk, FundedRuleProfile profile) {
		if (sourceRisk == null || profile == null) {
			return 1.0;
		}
		double scale = profile.accountSize > 0.0 && sourceRisk.accountSize > 0.0
			? profile.accountSize / sourceRisk.accountSize
			: 1.0;
		if (profile.maxTrailingDrawdown > 0.0 && sourceRisk.maxTrailingDrawdown > 0.0) {
			scale = Math.min(scale, profile.maxTrailingDrawdown / sourceRisk.maxTrailingDrawdown);
		}
		if (profile.dailyLossLimit > 0.0 && sourceRisk.dailyLossLimit > 0.0) {
			scale = Math.min(scale, profile.dailyLossLimit / sourceRisk.dailyLossLimit);
		}
		if (profile.maxRiskPerTrade > 0.0 && sourceRisk.maxRiskPerTrade > 0.0) {
			scale = Math.min(scale, profile.maxRiskPerTrade / sourceRisk.maxRiskPerTrade);
		}
		return clamp(scale, 1.0, 10.0);
	}

	private static void applySavedSizingScale(BacktestConfig symbolConfig, FuturesRiskSettings sourceRisk, FundedRuleProfile profile, String symbol) {
		if (symbolConfig == null || sourceRisk == null || profile == null) {
			return;
		}
		double scale = savedSizingScale(sourceRisk, profile);
		symbolConfig.maxRiskPerTrade = Math.min(profile.maxRiskPerTrade, Math.max(1.0, sourceRisk.maxRiskPerTrade * scale));
		int scaledContracts = (int) Math.floor(Math.max(1.0, sourceRisk.maxContracts * scale));
		symbolConfig.maxContracts = Math.min(Math.max(1, scaledContracts), profileMaxContractsForSymbol(profile, symbol));
	}

	private static int profileMaxContractsForSymbol(FundedRuleProfile profile, String symbol) {
		if (profile == null) {
			return topstepMaxContractsForSymbol(symbol);
		}
		return isMicroFuturesSymbol(symbol) ? profile.maxMicroContracts : profile.maxContracts;
	}

	private static void applyFundedProfile(BacktestConfig config, FundedRuleProfile profile) {
		if (config == null || profile == null || !isTopstep50KProfile(profile.code)) {
			return;
		}
		config.accountSize = profile.accountSize;
		config.maxTrailingDrawdown = profile.maxTrailingDrawdown;
		config.dailyLossLimit = profile.dailyLossLimit;
		if (usesProfileSizingCeilings(profile.code)) {
			config.maxRiskPerTrade = profile.maxRiskPerTrade;
			config.maxContracts = profileMaxContractsForSymbol(profile, config.symbol);
		} else {
			config.maxRiskPerTrade = Math.min(config.maxRiskPerTrade, profile.maxRiskPerTrade);
			config.maxContracts = Math.min(config.maxContracts, profileMaxContractsForSymbol(profile, config.symbol));
		}
		config.profitTarget = profile.profitTarget;
		config.trailingDrawdownMode = profile.trailingDrawdownMode;
	}

	private static void applyFundedProfile(PortfolioBacktestConfig config, FundedRuleProfile profile) {
		if (config == null || profile == null || !isTopstep50KProfile(profile.code)) {
			return;
		}
		config.accountSize = profile.accountSize;
		config.maxTrailingDrawdown = profile.maxTrailingDrawdown;
		config.dailyLossLimit = profile.dailyLossLimit;
		if (usesProfileSizingCeilings(profile.code)) {
			config.maxRiskPerTrade = profile.maxRiskPerTrade;
			config.maxContracts = profile.maxMicroContracts;
			config.maxOpenPositions = profile.maxOpenPositions;
			config.maxAggregateContracts = profile.maxAggregateContracts;
		} else {
			config.maxRiskPerTrade = Math.min(config.maxRiskPerTrade, profile.maxRiskPerTrade);
			config.maxContracts = Math.min(config.maxContracts, profile.maxMicroContracts);
			config.maxOpenPositions = Math.min(config.maxOpenPositions, profile.maxOpenPositions);
			config.maxAggregateContracts = Math.min(config.maxAggregateContracts, profile.maxAggregateContracts);
		}
		config.maxAggregateMiniUnits = profile.maxAggregateMiniUnits;
		config.profitTarget = profile.profitTarget;
		config.trailingDrawdownMode = profile.trailingDrawdownMode;
	}

	private static PortfolioBacktestConfig buildPortfolioBacktestConfig(
		String symbols,
		String startDate,
		String endDate,
		double accountSize,
		double maxTrailingDrawdown,
		double dailyLossLimit,
		double maxRiskPerTrade,
		int maxContracts,
		double commissionPerContract,
		double slippageTicks,
		int maxOpenPositions,
		int maxAggregateContracts,
		double maxAggregateMiniUnits,
		boolean useSavedRisk,
		double profitTarget,
		String fundedProfile
	) {
		List<String> parsedSymbols = parseSymbols(symbols);
		if (parsedSymbols.isEmpty()) {
			parsedSymbols.add("MNQ");
		}
		FuturesRiskSettings defaultRisk = loadFuturesRiskSettings(parsedSymbols.get(0));
		FundedRuleProfile profile = fundedRuleProfileFor(fundedProfile);
		PortfolioBacktestConfig config = new PortfolioBacktestConfig();
		config.fundedProfile = profile.code;
		config.symbols = parsedSymbols;
		config.startDate = parseDate(startDate, LocalDate.now().minusYears(1));
		config.endDate = parseDate(endDate, LocalDate.now());
		config.accountSize = positiveOrDefault(accountSize, defaultRisk.accountSize);
		config.maxTrailingDrawdown = positiveOrDefault(maxTrailingDrawdown, defaultRisk.maxTrailingDrawdown);
		config.dailyLossLimit = positiveOrDefault(dailyLossLimit, defaultRisk.dailyLossLimit);
		config.maxRiskPerTrade = positiveOrDefault(maxRiskPerTrade, defaultRisk.maxRiskPerTrade);
		config.maxContracts = boundedInt(maxContracts, defaultRisk.maxContracts, 1, 100);
		config.commissionPerContract = commissionPerContract >= 0.0 ? commissionPerContract : defaultRisk.commissionPerContract;
		config.slippageTicks = slippageTicks >= 0.0 ? slippageTicks : defaultRisk.slippageTicks;
		config.maxOpenPositions = boundedInt(maxOpenPositions, 1, 1, Math.max(1, parsedSymbols.size()));
		config.maxAggregateContracts = boundedInt(maxAggregateContracts, config.maxContracts * Math.max(1, parsedSymbols.size()), 1, 1000);
		config.maxAggregateMiniUnits = maxAggregateMiniUnits > 0.0 ? clamp(maxAggregateMiniUnits, 0.1, 100.0) : profile.maxAggregateMiniUnits;
		config.trailingDrawdownMode = profile.trailingDrawdownMode;
		config.useSavedRisk = false;
		config.profitTarget = profitTarget >= 0.0 ? profitTarget : defaultRisk.profitTarget;
		applyFundedProfile(config, profile);
		config.dayStartBalance = config.accountSize;
		config.currentBalance = config.accountSize;
		return config;
	}

	private static PortfolioBacktestResult runPortfolioBacktest(PortfolioBacktestConfig config) {
		Map<String, PortfolioSymbolContext> contexts = buildPortfolioContexts(config);
		if (contexts.isEmpty()) {
			return null;
		}

		List<LocalDate> days = portfolioDays(contexts);
		if (days.isEmpty()) {
			return null;
		}

		PortfolioBacktestResult result = new PortfolioBacktestResult();
		result.symbols = String.join(",", config.symbols);
		result.fundedProfile = config.fundedProfile;
		result.startDate = days.get(0).toString();
		result.endDate = days.get(days.size() - 1).toString();
		result.startingBalance = round(config.accountSize);
		result.dataSource = "native futures csv portfolio 1min";
		if (RISK_SIZING_DYNAMIC_COMPOUND_MLL.equals(config.riskSizingMode)) {
			result.dataSource += " risk_sizing_mode=" + config.riskSizingMode
				+ " dllUsage=" + round(config.dynamicRiskPolicy.dailyRoomUsagePct)
				+ " mllUsage=" + round(config.dynamicRiskPolicy.mllRoomUsagePct)
				+ " maxRiskMultiplier=" + round(config.dynamicRiskPolicy.maxRiskMultiplier)
				+ " dllReserve=" + round(config.dynamicRiskPolicy.dllReserveDollars);
		}
		if (config.dynamicMllRiskEnabled) {
			result.dataSource += " dynamic_mll_risk maxMultiplier=" + round(config.dynamicMllRiskMaxMultiplier)
				+ " aggregateMiniUnits=" + config.dynamicMllAggregateMiniUnits;
		}

		double balance = config.accountSize;
		double peakEquity = balance;
		double trailingReferenceBalance = balance;
		double trailingThreshold = config.accountSize - config.maxTrailingDrawdown;
		double grossProfit = 0.0;
		double grossLoss = 0.0;
		int winners = 0;
		double maxDrawdownPct = 0.0;
		List<PortfolioPosition> openPositions = new ArrayList<PortfolioPosition>();
		boolean endOfDayTrailing = usesEndOfDayTrailing(config.trailingDrawdownMode);
		double maeRuleBuffer = Math.max(0.0, PORTFOLIO_BACKTEST_MAE_RULE_BUFFER);
		int backtestDtmSessionId = -Math.max(1, (int) (System.nanoTime() & 0x7fffffff));
		FuturesLiveSession backtestDtmSession = simulatedBacktestDtmSession(config, backtestDtmSessionId);
		LiveStrategySnapshotRow backtestDtmSnapshot = simulatedBacktestSnapshot(config, backtestDtmSessionId);

		for (int dayIndex = 0; dayIndex < days.size(); dayIndex++) {
			LocalDate day = days.get(dayIndex);
			List<LocalTime> times = portfolioTimes(contexts, day);
			if (times.isEmpty()) {
				continue;
			}
			Map<String, Integer> takenByStrategy = new HashMap<String, Integer>();
			double dayStartBalance = balance;
			boolean stopForDay = false;
				boolean dailyLossBreachRecorded = false;
				boolean trailingBreachRecorded = false;
				boolean maeBreachRecorded = false;
				boolean dailyLossHardStop = false;

			for (int timeIndex = 0; timeIndex < times.size(); timeIndex++) {
				LocalTime time = times.get(timeIndex);
				Map<String, Bar> currentBars = barsAt(contexts, day, time);
				if (currentBars.isEmpty()) {
					continue;
				}

				if (!stopForDay && (!result.ruleViolation || config.continueAfterRuleViolation)) {
					List<SignalEvent> events = signalEventsAt(contexts, day, time);
					rankPortfolioSignalEvents(events, contexts);
					for (int eventIndex = 0; eventIndex < events.size(); eventIndex++) {
						SignalEvent event = events.get(eventIndex);
						PortfolioSymbolContext context = contexts.get(event.symbol);
						Bar entryBar = currentBars.get(event.symbol);
						if (context == null || entryBar == null) {
							continue;
						}
						LivePortfolioSignalCandidate candidate = portfolioSignalCandidate(context, event, entryBar);
							if (hasOpenSymbol(openPositions, event.symbol)) {
								result.overlapRejections++;
								continue;
							}
							if (backtestHasCorrelatedPortfolioExposure(openPositions, event.symbol)) {
								result.exposureRejections++;
								continue;
							}
							if (openPositions.size() >= config.maxOpenPositions) {
								result.overlapRejections++;
								continue;
							}
						int openContracts = openContractCount(openPositions);
						double openMiniUnits = openMiniUnitCount(openPositions);
						double aggregateMiniUnitLimit = dynamicMllAggregateMiniUnitLimit(config, dayStartBalance);
						if (openContracts >= config.maxAggregateContracts || fundedMiniUnitLimitReached(config, openMiniUnits, aggregateMiniUnitLimit)) {
							result.exposureRejections++;
							continue;
						}
						String strategyKey = strategyDailyLimitKey(event.symbol, event.signal.strategyCode);
						int taken = countFor(takenByStrategy, strategyKey);
						if (taken >= maxTradesPerDay(event.signal.strategyCode, context.config.strategySettings)) {
							continue;
						}

							double equityAtOpen = balance + aggregateOpenPnl(openPositions, currentBars, "open");
							if (equityAtOpen - dayStartBalance <= -Math.abs(config.dailyLossLimit)) {
								stopForDay = true;
								dailyLossHardStop = true;
								if (config.continueAfterRuleViolation) {
									markPortfolioRuleViolation(result, "Portfolio daily loss limit breached before entry.");
									if (!dailyLossBreachRecorded) {
										result.dailyLossBreaches++;
										dailyLossBreachRecorded = true;
									}
								} else {
								}
								break;
							}
							if (equityAtOpen <= trailingThreshold) {
								stopForDay = true;
								markPortfolioRuleViolation(result, "Portfolio trailing drawdown threshold breached before entry.");
								if (!trailingBreachRecorded) {
									result.trailingDrawdownBreaches++;
									trailingBreachRecorded = true;
								}
								break;
							}

							double reservedOpenRisk = aggregateOpenRisk(openPositions);
							double dailyRiskBudget = Math.abs(config.dailyLossLimit) + (equityAtOpen - dayStartBalance) - reservedOpenRisk;
							double trailingRiskBudget = equityAtOpen - trailingThreshold - reservedOpenRisk;
							double aggregateGuardBudget = Math.min(dailyRiskBudget, trailingRiskBudget);
							DynamicRiskBudget policyBudget = dynamicRiskBudget(
								config.dynamicRiskPolicy,
								context.config.maxRiskPerTrade,
								dailyRiskBudget,
								trailingRiskBudget,
								config.maxTrailingDrawdown
							);
							double riskBudgetMultiplier = context.config.qualitativeRiskEnabled ? portfolioRiskBudgetMultiplier(
							context,
							event,
							balance - dayStartBalance,
							aggregateGuardBudget,
							openPositions.size()
						) : 1.0;
						double symbolRiskBudget = policyBudget.availableRiskBudget * riskBudgetMultiplier;
						double availableRiskBudget = Math.min(symbolRiskBudget, aggregateGuardBudget);
						int aggregateRoom = config.maxAggregateContracts - openContracts;
						if (aggregateMiniUnitLimit > 0.0) {
							aggregateRoom = Math.min(aggregateRoom, contractsAllowedByMiniUnitRoom(event.symbol, aggregateMiniUnitLimit - openMiniUnits));
						}
						if (availableRiskBudget <= 0.0 || aggregateRoom <= 0) {
							result.riskRejections++;
							continue;
						}

						PortfolioPosition position = openPortfolioPosition(
							context,
							event,
							entryBar,
							availableRiskBudget,
							aggregateRoom,
							aggregateGuardBudget,
							portfolioBacktestAllowsLiveRiskCompression(event.signal.strategyCode),
							config.dynamicRiskPolicy.stopRiskBufferMultiplier
						);
						if (position == null) {
							result.riskRejections++;
							continue;
						}
						position.concurrentPositionsAtEntry = openPositions.size() + 1;
						position.concurrentContractsAtEntry = openContracts + position.contracts;
						openPositions.add(position);
						takenByStrategy.put(strategyKey, taken + 1);
						updatePortfolioExposureMetrics(result, openPositions);
				}
				}

					updateOpenPositionExcursions(openPositions, currentBars);
					double worstOpenPnl = aggregateWorstOpenPnl(openPositions, currentBars);
					double recordedWorstOpenPnl = cappedDailyLossMetric(worstOpenPnl, config.dailyLossLimit);
					result.maxAggregateMae = round(Math.min(result.maxAggregateMae, recordedWorstOpenPnl));
					double worstEquity = balance + worstOpenPnl;
					double worstIntraday = worstEquity - dayStartBalance;
					double recordedWorstIntraday = cappedDailyLossMetric(worstIntraday, config.dailyLossLimit);
					result.maxIntradayLoss = round(Math.min(result.maxIntradayLoss, recordedWorstIntraday));
					if (!openPositions.isEmpty() && worstIntraday <= -(Math.abs(config.dailyLossLimit) + maeRuleBuffer)) {
						stopForDay = true;
						dailyLossHardStop = true;
						markPortfolioRuleViolation(result, "Portfolio daily loss limit breached intratrade.");
						if (!dailyLossBreachRecorded) {
						result.dailyLossBreaches++;
						dailyLossBreachRecorded = true;
					}
					if (!maeBreachRecorded) {
						result.maeBreaches++;
						maeBreachRecorded = true;
					}
					}
					if (!openPositions.isEmpty() && worstEquity <= trailingThreshold - maeRuleBuffer) {
						stopForDay = true;
						markPortfolioRuleViolation(result, "Portfolio trailing drawdown breached intratrade.");
						if (!trailingBreachRecorded) {
						result.trailingDrawdownBreaches++;
						trailingBreachRecorded = true;
					}
					if (!maeBreachRecorded) {
						result.maeBreaches++;
						maeBreachRecorded = true;
					}
				}

				List<FuturesTrade> closedTrades = closeTriggeredPortfolioPositions(openPositions, contexts, currentBars, day, time, config.dtmEnabled, backtestDtmSession, backtestDtmSnapshot, result);
				for (int closedIndex = 0; closedIndex < closedTrades.size(); closedIndex++) {
					FuturesTrade trade = closedTrades.get(closedIndex);
					balance = round(balance + trade.pnl);
					if (trade.pnl >= 0.0) {
						winners++;
						grossProfit = round(grossProfit + trade.pnl);
					} else {
						grossLoss = round(grossLoss + Math.abs(trade.pnl));
					}
					result.tradeRecords.add(trade);
					queueWinnerFollowThroughSignal(contexts, trade, day);
				}

					if (result.ruleViolation && !config.continueAfterRuleViolation) {
						List<FuturesTrade> forcedTrades = forceClosePortfolioPositions(openPositions, contexts, currentBars, day, time, "Portfolio rule breach flat exit");
						for (int forcedIndex = 0; forcedIndex < forcedTrades.size(); forcedIndex++) {
							FuturesTrade trade = forcedTrades.get(forcedIndex);
							if (dailyLossHardStop) {
								capTradeToDailyLossLimit(trade, balance, dayStartBalance, config.dailyLossLimit);
							}
							balance = round(balance + trade.pnl);
						if (trade.pnl >= 0.0) {
							winners++;
							grossProfit = round(grossProfit + trade.pnl);
						} else {
							grossLoss = round(grossLoss + Math.abs(trade.pnl));
						}
							result.tradeRecords.add(trade);
						}
					}
					if (stopForDay && result.ruleViolation && config.continueAfterRuleViolation) {
						List<FuturesTrade> forcedTrades = forceClosePortfolioPositions(openPositions, contexts, currentBars, day, time, "Portfolio daily loss guard flat exit");
						for (int forcedIndex = 0; forcedIndex < forcedTrades.size(); forcedIndex++) {
							FuturesTrade trade = forcedTrades.get(forcedIndex);
							if (dailyLossHardStop) {
								capTradeToDailyLossLimit(trade, balance, dayStartBalance, config.dailyLossLimit);
							}
							balance = round(balance + trade.pnl);
							if (trade.pnl >= 0.0) {
								winners++;
								grossProfit = round(grossProfit + trade.pnl);
							} else {
								grossLoss = round(grossLoss + Math.abs(trade.pnl));
							}
							result.tradeRecords.add(trade);
						}
					}

					double currentEquity = balance + aggregateOpenPnl(openPositions, currentBars, "close");
					peakEquity = Math.max(peakEquity, currentEquity);
				if (!endOfDayTrailing) {
					trailingThreshold = Math.max(trailingThreshold, peakEquity - config.maxTrailingDrawdown);
				}
					double drawdownPct = peakEquity <= 0.0 ? 0.0 : ((peakEquity - currentEquity) / peakEquity) * 100.0;
					maxDrawdownPct = Math.max(maxDrawdownPct, drawdownPct);
					double currentIntraday = currentEquity - dayStartBalance;
					result.maxIntradayLoss = round(Math.min(result.maxIntradayLoss, cappedDailyLossMetric(currentIntraday, config.dailyLossLimit)));
					if (currentIntraday <= -Math.abs(config.dailyLossLimit)) {
						stopForDay = true;
						dailyLossHardStop = true;
						markPortfolioRuleViolation(result, "Portfolio daily loss limit breached.");
						if (!dailyLossBreachRecorded) {
						result.dailyLossBreaches++;
						dailyLossBreachRecorded = true;
					}
					}
						if (currentEquity <= trailingThreshold) {
							stopForDay = true;
							markPortfolioRuleViolation(result, "Portfolio trailing drawdown threshold breached.");
							if (!trailingBreachRecorded) {
							result.trailingDrawdownBreaches++;
							trailingBreachRecorded = true;
						}
					}
					if (stopForDay && result.ruleViolation && !openPositions.isEmpty()) {
						List<FuturesTrade> forcedTrades = forceClosePortfolioPositions(openPositions, contexts, currentBars, day, time, "Portfolio daily loss guard flat exit");
						for (int forcedIndex = 0; forcedIndex < forcedTrades.size(); forcedIndex++) {
							FuturesTrade trade = forcedTrades.get(forcedIndex);
							if (dailyLossHardStop) {
								capTradeToDailyLossLimit(trade, balance, dayStartBalance, config.dailyLossLimit);
							}
							balance = round(balance + trade.pnl);
							if (trade.pnl >= 0.0) {
								winners++;
								grossProfit = round(grossProfit + trade.pnl);
							} else {
								grossLoss = round(grossLoss + Math.abs(trade.pnl));
							}
							result.tradeRecords.add(trade);
						}
					}
					if (config.profitTarget > 0.0 && currentEquity - config.accountSize >= config.profitTarget) {
						result.ruleMessage = "Portfolio profit target reached.";
						stopForDay = true;
				}
				updatePortfolioExposureMetrics(result, openPositions);
					if (stopForDay || (!config.continueAfterRuleViolation && result.ruleViolation) || "Portfolio profit target reached.".equals(result.ruleMessage)) {
						break;
					}
				}

			if (!openPositions.isEmpty()) {
				Map<String, Bar> closingBars = lastBarsForDay(contexts, day);
				List<FuturesTrade> forcedTrades = forceClosePortfolioPositions(openPositions, contexts, closingBars, day, times.get(times.size() - 1), "Portfolio end-of-day flat exit");
				for (int forcedIndex = 0; forcedIndex < forcedTrades.size(); forcedIndex++) {
					FuturesTrade trade = forcedTrades.get(forcedIndex);
					balance = round(balance + trade.pnl);
					if (trade.pnl >= 0.0) {
						winners++;
						grossProfit = round(grossProfit + trade.pnl);
					} else {
						grossLoss = round(grossLoss + Math.abs(trade.pnl));
					}
					result.tradeRecords.add(trade);
				}
			}
			if ((!config.continueAfterRuleViolation && result.ruleViolation) || "Portfolio profit target reached.".equals(result.ruleMessage)) {
				break;
			}
			if (endOfDayTrailing) {
				trailingReferenceBalance = Math.max(trailingReferenceBalance, balance);
				trailingThreshold = endOfDayTrailingThreshold(trailingThreshold, trailingReferenceBalance, config.accountSize, config.maxTrailingDrawdown);
			}
		}

		result.endingBalance = round(balance);
		result.totalProfit = round(balance - config.accountSize);
		result.returnPct = config.accountSize <= 0.0 ? 0.0 : round((result.totalProfit / config.accountSize) * 100.0);
		result.trades = result.tradeRecords.size();
		result.winRate = result.trades == 0 ? 0.0 : round((winners * 100.0) / result.trades);
		result.profitFactor = grossLoss == 0.0 ? round(grossProfit) : round(grossProfit / grossLoss);
		result.maxDrawdownPct = round(maxDrawdownPct);
		result.trailingThreshold = round(trailingThreshold);
		result.continuedAfterRuleViolation = config.continueAfterRuleViolation && result.ruleViolation;
		if (result.ruleMessage == null || result.ruleMessage.trim().isEmpty()) {
			result.ruleMessage = result.ruleViolation ? "Portfolio funded rule violation." : "Completed without portfolio funded-rule breach.";
		} else if (result.continuedAfterRuleViolation) {
			result.ruleMessage = result.ruleMessage + " Backtest continued after breach for full-trade analysis.";
		}
		resetDynamicTradeStatesForSession(backtestDtmSessionId);
		return result;
	}

	private static void markPortfolioRuleViolation(PortfolioBacktestResult result, String message) {
		if (result == null) {
			return;
		}
		if (!result.ruleViolation || result.ruleMessage == null || result.ruleMessage.trim().isEmpty() || "Portfolio profit target reached.".equals(result.ruleMessage)) {
			result.ruleMessage = cleanOrDefault(message, "Portfolio funded rule violation.");
		}
		result.ruleViolation = true;
	}

	private static double cappedDailyLossMetric(double value, double dailyLossLimit) {
		double floor = -Math.abs(dailyLossLimit);
		return value < floor ? floor : value;
	}

	private static void capTradeToDailyLossLimit(FuturesTrade trade, double balance, double dayStartBalance, double dailyLossLimit) {
		if (trade == null || dailyLossLimit <= 0.0) {
			return;
		}
		double floorBalance = dayStartBalance - Math.abs(dailyLossLimit);
		double minimumAllowedPnl = round(floorBalance - balance);
		if (balance + trade.pnl >= floorBalance) {
			return;
		}
		double adjustment = round(minimumAllowedPnl - trade.pnl);
		trade.pnl = minimumAllowedPnl;
		trade.finalLegPnl = round(trade.finalLegPnl + adjustment);
		trade.exitReason = cleanOrDefault(trade.exitReason, "Portfolio daily loss guard flat exit") + " (capped at daily loss limit)";
	}

	private static FuturesLiveSession simulatedBacktestDtmSession(PortfolioBacktestConfig config, int sessionId) {
		FuturesLiveSession session = new FuturesLiveSession();
		session.sessionId = sessionId;
		session.executionMode = "SIMULATED_BACKTEST";
		session.fundedProfile = config == null ? "CUSTOM" : cleanOrDefault(config.fundedProfile, "CUSTOM");
		session.strategyPreset = config == null ? DEFAULT_STRATEGY_PRESET : cleanOrDefault(config.strategyPreset, DEFAULT_STRATEGY_PRESET);
		session.strategySlot = config == null ? STRATEGY_SLOT_BACKTEST : cleanOrDefault(config.strategySlot, STRATEGY_SLOT_BACKTEST);
		session.symbols = config == null || config.symbols == null ? "" : String.join(",", config.symbols);
		session.dtmEnabled = config != null && config.dtmEnabled;
		return session;
	}

	private static LiveStrategySnapshotRow simulatedBacktestSnapshot(PortfolioBacktestConfig config, int snapshotId) {
		LiveStrategySnapshotRow snapshot = new LiveStrategySnapshotRow();
		snapshot.snapshotId = snapshotId;
		snapshot.sourcePortfolioBacktestId = config == null ? 0 : config.sourcePortfolioBacktestId;
		snapshot.symbols = config == null || config.symbols == null ? "" : String.join(",", config.symbols);
		snapshot.fundedProfile = config == null ? "CUSTOM" : cleanOrDefault(config.fundedProfile, "CUSTOM");
		snapshot.accountMode = "BACKTEST";
		return snapshot;
	}

	private static Map<String, PortfolioSymbolContext> buildPortfolioContexts(PortfolioBacktestConfig config) {
		Map<String, PortfolioSymbolContext> contexts = new TreeMap<String, PortfolioSymbolContext>();
		FundedRuleProfile profile = fundedRuleProfileFor(config.fundedProfile);
		for (int symbolIndex = 0; symbolIndex < config.symbols.size(); symbolIndex++) {
			String symbol = normalizeSymbol(config.symbols.get(symbolIndex));
			DataBundle bars = loadNativeFuturesBars(symbol, config.startDate, config.endDate, TIMEFRAME_FOLDER);
			if (bars.bars.isEmpty()) {
				return new TreeMap<String, PortfolioSymbolContext>();
			}

			PortfolioSymbolContext context = new PortfolioSymbolContext();
			context.symbol = symbol;
			context.spec = instrumentFor(symbol);
			context.bars = bars;
			context.config = buildBacktestConfig(
				symbol,
				config.startDate.toString(),
				config.endDate.toString(),
				config.accountSize,
				config.maxTrailingDrawdown,
				config.dailyLossLimit,
				config.maxRiskPerTrade,
				config.maxContracts,
				config.commissionPerContract,
				config.slippageTicks,
				config.profitTarget
			);
			FuturesStrategySettings sourceStrategySettings = loadPortfolioBacktestStrategySettings(config.sourcePortfolioBacktestId, symbol);
			context.config.strategySettings = sourceStrategySettings == null
				? loadFuturesStrategySettings(symbol, config.strategySlot)
				: sourceStrategySettings;
			FuturesRiskSettings savedRisk = null;
			if (config.useSavedRisk) {
				FuturesRiskSettings sourceRisk = loadPortfolioBacktestRiskSettings(config.sourcePortfolioBacktestId, symbol);
				savedRisk = sourceRisk == null ? loadFuturesRiskSettings(symbol, config.strategySlot) : sourceRisk;
				applyRiskSettingsToStrategySettings(context.config.strategySettings, savedRisk);
				context.config.maxRiskPerTrade = savedRisk.maxRiskPerTrade;
				context.config.maxContracts = savedRisk.maxContracts;
			}
			if (isTopstep50KProfile(config.fundedProfile)) {
				if (scalesSavedSizingForProfile(config.fundedProfile) && savedRisk != null) {
					applySavedSizingScale(context.config, savedRisk, profile, symbol);
				} else {
					context.config.maxRiskPerTrade = Math.min(context.config.maxRiskPerTrade, profile.maxRiskPerTrade);
					context.config.maxContracts = Math.min(context.config.maxContracts, profileMaxContractsForSymbol(profile, symbol));
				}
			}
			context.config.commissionPerContract = config.commissionPerContract;
			context.config.slippageTicks = config.slippageTicks;
			context.config.accountSize = config.accountSize;
			context.config.maxTrailingDrawdown = config.maxTrailingDrawdown;
			context.config.dailyLossLimit = config.dailyLossLimit;
			context.config.qualitativeRiskEnabled = config.qualitativeRiskEnabled;
			context.byDay = groupByDay(bars.bars);
			context.fifteenMinuteByDay = groupByDay(loadNativeFuturesBars(symbol, config.startDate, config.endDate, "15min").bars);
			context.oneHourByDay = groupByDay(loadNativeFuturesBars(symbol, config.startDate, config.endDate, "1hour").bars);
			context.indexByDayTime = indexBarsByDayTime(context.byDay);
			if (config.dtmEnabled || strategyUsesRangeMidpointContinuation(context.config.strategySettings)) {
				context.orderFlowByDayTime = loadCombinedOrderFlowSnapshots(symbol, config.startDate, config.endDate);
			}
			preparePortfolioSignalEvents(context);
			contexts.put(symbol, context);
		}
		addMymBreadthConfirmationSignalEvents(contexts);
		addMicroShadowSignalEvents(contexts);
		addMicroEchoSignalEvents(contexts);
		return contexts;
	}

	private static Map<LocalDate, Map<LocalTime, Integer>> indexBarsByDayTime(Map<LocalDate, List<Bar>> byDay) {
		Map<LocalDate, Map<LocalTime, Integer>> index = new HashMap<LocalDate, Map<LocalTime, Integer>>();
		for (LocalDate day : byDay.keySet()) {
			List<Bar> bars = byDay.get(day);
			Map<LocalTime, Integer> byTime = new HashMap<LocalTime, Integer>();
			for (int barIndex = 0; barIndex < bars.size(); barIndex++) {
				byTime.put(bars.get(barIndex).marketTime, barIndex);
			}
			index.put(day, byTime);
		}
		return index;
	}

	private static void preparePortfolioSignalEvents(PortfolioSymbolContext context) {
		List<LocalDate> days = new ArrayList<LocalDate>(context.byDay.keySet());
		Collections.sort(days);
		for (int dayIndex = 0; dayIndex < days.size(); dayIndex++) {
			LocalDate day = days.get(dayIndex);
			List<Bar> bars = context.byDay.get(day);
			if (bars == null || bars.size() < 40) {
				continue;
			}
			List<Signal> signals = buildSignals(
				context.spec,
				bars,
				previousDayBars(context.byDay, days, dayIndex),
				context.fifteenMinuteByDay.get(day),
				context.oneHourByDay.get(day),
				context.config,
				context.orderFlowByDayTime
			);
			List<SignalEvent> events = new ArrayList<SignalEvent>();
			for (int signalIndex = 0; signalIndex < signals.size(); signalIndex++) {
				Signal signal = signals.get(signalIndex);
				int executionIndex = signal.entryIndex + 1;
				if (executionIndex >= bars.size()) {
					continue;
				}
				Bar entryBar = bars.get(executionIndex);
				if (!isLiveEntryWindowTime(entryBar.marketTime)) {
					continue;
				}
				SignalEvent event = new SignalEvent();
				event.symbol = context.symbol;
				event.signal = signal;
				event.day = day;
				event.entryTime = entryBar.marketTime;
				event.executionIndex = executionIndex;
				events.add(event);
			}
			Collections.sort(events, new Comparator<SignalEvent>() {
				@Override
				public int compare(SignalEvent first, SignalEvent second) {
					int timeCompare = first.entryTime.compareTo(second.entryTime);
					if (timeCompare != 0) {
						return timeCompare;
					}
					return first.symbol.compareTo(second.symbol);
				}
			});
			context.eventsByDay.put(day, events);
		}
	}

	private static void addMymBreadthConfirmationSignalEvents(Map<String, PortfolioSymbolContext> contexts) {
		if (contexts == null || contexts.isEmpty()) {
			return;
		}
		PortfolioSymbolContext target = contexts.get("MYM");
		if (target == null || target.byDay == null || target.indexByDayTime == null) {
			return;
		}
		FuturesStrategySettings settings = target.config == null || target.config.strategySettings == null
			? defaultFuturesStrategySettings()
			: target.config.strategySettings;
		if (settings.mymBreadthConfirmation == null || !settings.mymBreadthConfirmation.enabled) {
			return;
		}
		List<LocalDate> days = new ArrayList<LocalDate>(target.byDay.keySet());
		Collections.sort(days);
		for (int dayIndex = 0; dayIndex < days.size(); dayIndex++) {
			LocalDate day = days.get(dayIndex);
			List<Bar> bars = target.byDay.get(day);
			Map<LocalTime, Integer> targetIndex = target.indexByDayTime.get(day);
			if (bars == null || bars.size() < 80 || targetIndex == null) {
				continue;
			}
			double rthOpen = firstOpenAtOrAfter(bars, 570);
			if (rthOpen <= 0.0) {
				continue;
			}
			List<SignalEvent> events = target.eventsByDay.get(day);
			if (events == null) {
				events = new ArrayList<SignalEvent>();
				target.eventsByDay.put(day, events);
			}
			int added = 0;
			int lastLongBucket = -1;
			int lastShortBucket = -1;
			int lookback = Math.max(3, settings.mymBreadthLookbackBars);
			int bucketMinutes = Math.max(3, settings.mymBreadthBucketMinutes);
			double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.mymBreadthMaxRiskTicks);
			for (int index = lookback + 5; index + 1 < bars.size(); index++) {
				Bar bar = bars.get(index);
				Bar entryBar = bars.get(index + 1);
				if (bar == null || entryBar == null || bar.marketTime == null || entryBar.marketTime == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
					continue;
				}
				if (!isLiveEntryWindowTime(entryBar.marketTime)) {
					continue;
				}
				int minute = minuteOfDay(bar);
				if (minute < settings.mymBreadthStartMinute || minute > settings.mymBreadthEndMinute) {
					continue;
				}
				double volumeRatio = volumeRatio(bar);
				if (volumeRatio < settings.mymBreadthMinVolumeRatio || bar.bodyPct < settings.mymBreadthMinBodyPct) {
					continue;
				}
				double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - lookback)).ema20) / target.spec.tickSize;
				double priorHigh = recentSwingHigh(bars, index - 1, lookback);
				double priorLow = recentSwingLow(bars, index - 1, lookback);
				double closeLocation = closeLocation(bar);
				int bucket = minute / bucketMinutes;
				if (settings.allowShorts
					&& settings.allowMymBreadthShorts
					&& bucket != lastShortBucket
					&& mymBreadthAlignedMarkets(contexts, day, bar.marketTime, "LONG", settings, lookback) >= settings.mymBreadthMinAlignedMarkets
					&& bar.close > rthOpen
					&& bar.close > bar.vwap
					&& bar.ema9 >= bar.ema20
					&& bar.ema20 >= bar.ema50
					&& trendSlopeTicks >= settings.mymBreadthMinTrendSlopeTicks
					&& bar.close > priorHigh + target.spec.tickSize
					&& bar.close > bar.open
					&& closeLocation >= 0.56
					&& bar.rsi14 >= 45.0
					&& bar.rsi14 <= 76.0) {
					double stop = Math.max(recentSwingHigh(bars, index, Math.min(lookback, 8)), bar.ema20) + (target.spec.tickSize * 2.0);
					if (riskTicks(target.spec, bar.close, stop) > maxRiskTicks) {
						stop = compressedShortStop(target.spec, bars, index, bar.close, maxRiskTicks);
					}
					double risk = stop - bar.close;
					if (risk > 0.0 && riskTicks(target.spec, bar.close, stop) <= maxRiskTicks) {
						events.add(mymBreadthEvent(target, day, index, index + 1, "SHORT", stop, bar.close - (risk * settings.mymBreadthRewardRisk), settings.mymBreadthMaxHoldBars));
						lastShortBucket = bucket;
						added++;
					}
				}
				if (settings.allowMymBreadthLongs
					&& bucket != lastLongBucket
					&& mymBreadthAlignedMarkets(contexts, day, bar.marketTime, "SHORT", settings, lookback) >= settings.mymBreadthMinAlignedMarkets
					&& bar.close < rthOpen
					&& bar.close < bar.vwap
					&& bar.ema9 <= bar.ema20
					&& bar.ema20 <= bar.ema50
					&& trendSlopeTicks <= -settings.mymBreadthMinTrendSlopeTicks
					&& bar.close < priorLow - target.spec.tickSize
					&& bar.close < bar.open
					&& closeLocation <= 0.44
					&& bar.rsi14 >= 24.0
					&& bar.rsi14 <= 55.0) {
					double stop = Math.min(recentSwingLow(bars, index, Math.min(lookback, 8)), bar.ema20) - (target.spec.tickSize * 2.0);
					if (riskTicks(target.spec, bar.close, stop) > maxRiskTicks) {
						stop = compressedLongStop(target.spec, bars, index, bar.close, maxRiskTicks);
					}
					double risk = bar.close - stop;
					if (risk > 0.0 && riskTicks(target.spec, bar.close, stop) <= maxRiskTicks) {
						events.add(mymBreadthEvent(target, day, index, index + 1, "LONG", stop, bar.close + (risk * settings.mymBreadthRewardRisk), settings.mymBreadthMaxHoldBars));
						lastLongBucket = bucket;
						added++;
					}
				}
				if (added >= settings.mymBreadthConfirmation.maxTradesPerDay) {
					break;
				}
			}
			sortSignalEvents(events);
		}
	}

	private static SignalEvent mymBreadthEvent(PortfolioSymbolContext context, LocalDate day, int signalIndex, int executionIndex, String side, double stop, double targetPrice, int maxHoldBars) {
		List<Bar> bars = context.byDay.get(day);
		Bar signalBar = bars.get(signalIndex);
		Bar entryBar = bars.get(executionIndex);
			Signal signal = signal(
				"MYMBR",
				"MYM Breadth Fade",
				side,
			signalIndex,
			signalBar.close,
			stop,
			targetPrice,
			maxHoldBars,
				"MYM breadth-fade entry after Dow price structure stretches with at least two major index markets aligned."
			);
		SignalEvent event = new SignalEvent();
		event.symbol = "MYM";
		event.signal = signal;
		event.day = day;
		event.entryTime = entryBar.marketTime;
		event.executionIndex = executionIndex;
		return event;
	}

	private static int mymBreadthAlignedMarkets(Map<String, PortfolioSymbolContext> contexts, LocalDate day, LocalTime time, String side, FuturesStrategySettings settings, int lookback) {
		int aligned = 0;
		for (String symbol : new String[] {"ES", "NQ", "M2K"}) {
			PortfolioSymbolContext context = contexts.get(symbol);
			if (context == null || context.indexByDayTime == null || context.byDay == null) {
				continue;
			}
			Map<LocalTime, Integer> byTime = context.indexByDayTime.get(day);
			List<Bar> bars = context.byDay.get(day);
			if (byTime == null || bars == null) {
				continue;
			}
			Integer indexValue = byTime.get(time);
			if (indexValue == null) {
				continue;
			}
			int index = indexValue.intValue();
			if (marketBarAligned(context.spec, bars, index, side, settings.mymBreadthMinTrendSlopeTicks * 0.60, Math.max(3, lookback))) {
				aligned++;
			}
		}
		return aligned;
	}

	private static boolean marketBarAligned(InstrumentSpec spec, List<Bar> bars, int index, String side, double minTrendSlopeTicks, int lookback) {
		if (spec == null || bars == null || index < Math.max(3, lookback) || index >= bars.size()) {
			return false;
		}
		Bar bar = bars.get(index);
		if (bar == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
			return false;
		}
		double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - lookback)).ema20) / spec.tickSize;
		double closeLocation = closeLocation(bar);
		if ("LONG".equals(side)) {
			return bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.ema20 >= bar.ema50
				&& trendSlopeTicks >= minTrendSlopeTicks
				&& closeLocation >= 0.52;
		}
		return bar.close < bar.vwap
			&& bar.ema9 <= bar.ema20
			&& bar.ema20 <= bar.ema50
			&& trendSlopeTicks <= -minTrendSlopeTicks
			&& closeLocation <= 0.48;
	}

	private static void addMicroShadowSignalEvents(Map<String, PortfolioSymbolContext> contexts) {
		if (contexts == null || contexts.isEmpty()) {
			return;
		}
		addMicroShadowSignalPair(contexts, "ES", "MES");
		addMicroShadowSignalPair(contexts, "NQ", "MNQ");
		addMicroShadowSignalPair(contexts, "ES", "MYM");
		addMicroShadowSignalPair(contexts, "NQ", "MYM");
		addMicroShadowSignalPair(contexts, "M2K", "MYM");
		addMicroShadowSignalPair(contexts, "MGC", "MCL");
	}

	private static void addMicroEchoSignalEvents(Map<String, PortfolioSymbolContext> contexts) {
		if (contexts == null || contexts.isEmpty()) {
			return;
		}
		addMicroEchoSignalPair(contexts, "ES", "MES");
		addMicroEchoSignalPair(contexts, "NQ", "MNQ");
		addMicroEchoSignalPair(contexts, "MES", "MES");
		addMicroEchoSignalPair(contexts, "MNQ", "MNQ");
		addMicroEchoSignalPair(contexts, "M2K", "M2K");
		addMicroEchoSignalPair(contexts, "MYM", "MYM");
		addMicroEchoSignalPair(contexts, "MGC", "MGC");
		addMicroEchoSignalPair(contexts, "MCL", "MCL");
	}

	private static void addMicroShadowSignalPair(Map<String, PortfolioSymbolContext> contexts, String sourceSymbol, String targetSymbol) {
		PortfolioSymbolContext source = contexts.get(sourceSymbol);
		PortfolioSymbolContext target = contexts.get(targetSymbol);
		if (source == null || target == null) {
			return;
		}
		FuturesStrategySettings settings = target.config.strategySettings == null ? defaultFuturesStrategySettings() : target.config.strategySettings;
		FuturesStrategySettings shadowSettings = settings;
		boolean liquidityShadow = settings.liquidityReclaim != null
			&& settings.liquidityReclaim.enabled
			&& liquidityReclaimOwnsComponent(targetSymbol, "SHDW")
			&& sourceStrategyAllowed("SHDW", settings.liquidityReclaimSourceCodes);
		if ((settings.microShadow == null || !settings.microShadow.enabled) && !liquidityShadow) {
			return;
		}
		List<LocalDate> days = new ArrayList<LocalDate>(source.eventsByDay.keySet());
		Collections.sort(days);
		int bucketMinutes = Math.max(3, shadowSettings.microShadowBucketMinutes);
		double maxRiskTicks = Math.min(shadowSettings.maxInitialRiskTicks, shadowSettings.microShadowMaxRiskTicks);
		for (int dayIndex = 0; dayIndex < days.size(); dayIndex++) {
			LocalDate day = days.get(dayIndex);
			List<SignalEvent> sourceEvents = source.eventsByDay.get(day);
			List<Bar> targetBars = target.byDay.get(day);
			Map<LocalTime, Integer> targetIndex = target.indexByDayTime.get(day);
			if (sourceEvents == null || sourceEvents.isEmpty() || targetBars == null || targetIndex == null) {
				continue;
			}
			List<SignalEvent> targetEvents = target.eventsByDay.get(day);
			if (targetEvents == null) {
				targetEvents = new ArrayList<SignalEvent>();
				target.eventsByDay.put(day, targetEvents);
			}
			Map<String, Integer> lastBucketBySide = new HashMap<String, Integer>();
			for (int eventIndex = 0; eventIndex < sourceEvents.size(); eventIndex++) {
				SignalEvent sourceEvent = sourceEvents.get(eventIndex);
				if (sourceEvent == null || sourceEvent.signal == null || sourceEvent.entryTime == null || !sourceStrategyAllowed(sourceEvent.signal.strategyCode, shadowSettings.microShadowSourceCodes)) {
					continue;
				}
				String side = sourceEvent.signal.side;
				if (("LONG".equals(side) && !shadowSettings.allowMicroShadowLongs) || ("SHORT".equals(side) && !shadowSettings.allowMicroShadowShorts)) {
					continue;
				}
				int minuteOfDay = (sourceEvent.entryTime.getHour() * 60) + sourceEvent.entryTime.getMinute();
				if (minuteOfDay < shadowSettings.microShadowStartMinute || minuteOfDay > shadowSettings.microShadowEndMinute) {
					continue;
				}
				int bucket = minuteOfDay / bucketMinutes;
				Integer lastBucket = lastBucketBySide.get(side);
				if (lastBucket != null && lastBucket.intValue() == bucket) {
					continue;
				}
				Integer executionIndexValue = targetIndex.get(sourceEvent.entryTime);
				if (executionIndexValue == null) {
					continue;
				}
				int executionIndex = executionIndexValue.intValue();
				int signalIndex = executionIndex - 1;
				if (signalIndex < 30 || executionIndex >= targetBars.size()) {
					continue;
				}
				Bar signalBar = targetBars.get(signalIndex);
				if (!microShadowTargetConfirms(target.spec, targetBars, signalIndex, side, shadowSettings)) {
					continue;
				}
				double stop = "LONG".equals(side)
					? compressedLongStop(target.spec, targetBars, signalIndex, signalBar.close, maxRiskTicks)
					: compressedShortStop(target.spec, targetBars, signalIndex, signalBar.close, maxRiskTicks);
				double risk = Math.abs(signalBar.close - stop);
				if (risk <= 0.0 || riskTicks(target.spec, signalBar.close, stop) > maxRiskTicks) {
					continue;
				}
				double targetPrice = "LONG".equals(side)
					? signalBar.close + (risk * shadowSettings.microShadowRewardRisk)
					: signalBar.close - (risk * shadowSettings.microShadowRewardRisk);
					Signal shadowSignal = signal(
						"SHDW",
						"Mini-Confirmed Micro Shadow",
					side,
					signalIndex,
					signalBar.close,
					stop,
					targetPrice,
					shadowSettings.microShadowMaxHoldBars,
						"Micro futures shadow entry when " + sourceSymbol + " prints a high-quality " + sourceEvent.signal.strategyCode + " signal and " + targetSymbol + " confirms VWAP/EMA direction with compressed risk."
					);
					withSourceStrategy(shadowSignal, sourceEvent.signal.strategyCode, sourceEvent.signal.strategyName);
					if (liquidityShadow) {
						relabelLiquidityReclaimSignal(shadowSignal);
					}
				SignalEvent shadowEvent = new SignalEvent();
				shadowEvent.symbol = targetSymbol;
				shadowEvent.signal = shadowSignal;
				shadowEvent.day = day;
				shadowEvent.entryTime = sourceEvent.entryTime;
				shadowEvent.executionIndex = executionIndex;
				targetEvents.add(shadowEvent);
				lastBucketBySide.put(side, bucket);
			}
			Collections.sort(targetEvents, new Comparator<SignalEvent>() {
				@Override
				public int compare(SignalEvent first, SignalEvent second) {
					int timeCompare = first.entryTime.compareTo(second.entryTime);
					if (timeCompare != 0) {
						return timeCompare;
					}
					return first.symbol.compareTo(second.symbol);
				}
			});
		}
	}

	private static boolean microShadowTargetConfirms(InstrumentSpec spec, List<Bar> bars, int index, String side, FuturesStrategySettings settings) {
		if (spec == null || bars == null || index < 10 || index >= bars.size()) {
			return false;
		}
		Bar bar = bars.get(index);
		if (bar == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
			return false;
		}
		double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
		if (volumeRatio < settings.microShadowMinVolumeRatio) {
			return false;
		}
		double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
		double closeLocation = closeLocation(bar);
		if ("LONG".equals(side)) {
			return bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.close >= bar.ema50
				&& trendSlopeTicks >= settings.microShadowMinTrendSlopeTicks
				&& closeLocation >= 0.52;
		}
		return bar.close < bar.vwap
			&& bar.ema9 <= bar.ema20
			&& bar.close <= bar.ema50
			&& trendSlopeTicks <= -settings.microShadowMinTrendSlopeTicks
			&& closeLocation <= 0.48;
	}

	private static void addMicroEchoSignalPair(Map<String, PortfolioSymbolContext> contexts, String sourceSymbol, String targetSymbol) {
		PortfolioSymbolContext source = contexts.get(sourceSymbol);
		PortfolioSymbolContext target = contexts.get(targetSymbol);
		if (source == null || target == null) {
			return;
		}
		FuturesStrategySettings settings = target.config.strategySettings == null ? defaultFuturesStrategySettings() : target.config.strategySettings;
		if (settings.microEcho == null || !settings.microEcho.enabled) {
			return;
		}
		List<LocalDate> days = new ArrayList<LocalDate>(source.eventsByDay.keySet());
		Collections.sort(days);
		int bucketMinutes = Math.max(3, settings.microEchoBucketMinutes);
		int delayMinutes = Math.max(1, settings.microEchoDelayMinutes);
		int maxDelays = Math.max(1, settings.microEchoMaxDelays);
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.microEchoMaxRiskTicks);
		for (int dayIndex = 0; dayIndex < days.size(); dayIndex++) {
			LocalDate day = days.get(dayIndex);
			List<SignalEvent> sourceEvents = source.eventsByDay.get(day);
			List<Bar> targetBars = target.byDay.get(day);
			Map<LocalTime, Integer> targetIndex = target.indexByDayTime.get(day);
			if (sourceEvents == null || sourceEvents.isEmpty() || targetBars == null || targetIndex == null) {
				continue;
			}
			List<SignalEvent> targetEvents = target.eventsByDay.get(day);
			if (targetEvents == null) {
				targetEvents = new ArrayList<SignalEvent>();
				target.eventsByDay.put(day, targetEvents);
			}
			Map<String, Integer> lastBucketBySideSource = new HashMap<String, Integer>();
			for (int eventIndex = 0; eventIndex < sourceEvents.size(); eventIndex++) {
				SignalEvent sourceEvent = sourceEvents.get(eventIndex);
				if (sourceEvent == null || sourceEvent.signal == null || sourceEvent.entryTime == null || !sourceStrategyAllowed(sourceEvent.signal.strategyCode, settings.microEchoSourceCodes)) {
					continue;
				}
				String side = sourceEvent.signal.side;
				if (("LONG".equals(side) && !settings.allowMicroEchoLongs) || ("SHORT".equals(side) && !settings.allowMicroEchoShorts)) {
					continue;
				}
				for (int delayIndex = 1; delayIndex <= maxDelays; delayIndex++) {
					LocalTime echoTime = sourceEvent.entryTime.plusMinutes((long) delayMinutes * delayIndex);
					int minuteOfDay = (echoTime.getHour() * 60) + echoTime.getMinute();
					if (minuteOfDay < settings.microEchoStartMinute || minuteOfDay > settings.microEchoEndMinute) {
						continue;
					}
					int bucket = minuteOfDay / bucketMinutes;
					String bucketKey = side + "|" + sourceEvent.signal.strategyCode + "|" + bucket;
					Integer lastBucket = lastBucketBySideSource.get(bucketKey);
					if (lastBucket != null && lastBucket.intValue() == bucket) {
						continue;
					}
					Integer executionIndexValue = targetIndex.get(echoTime);
					if (executionIndexValue == null) {
						continue;
					}
					int executionIndex = executionIndexValue.intValue();
					int signalIndex = executionIndex - 1;
					if (signalIndex < 30 || executionIndex >= targetBars.size()) {
						continue;
					}
					Bar signalBar = targetBars.get(signalIndex);
					if (!microEchoTargetConfirms(target.spec, targetBars, signalIndex, side, settings)) {
						continue;
					}
					double stop = "LONG".equals(side)
						? compressedLongStop(target.spec, targetBars, signalIndex, signalBar.close, maxRiskTicks)
						: compressedShortStop(target.spec, targetBars, signalIndex, signalBar.close, maxRiskTicks);
					double risk = Math.abs(signalBar.close - stop);
					if (risk <= 0.0 || riskTicks(target.spec, signalBar.close, stop) > maxRiskTicks) {
						continue;
					}
					double targetPrice = "LONG".equals(side)
						? signalBar.close + (risk * settings.microEchoRewardRisk)
						: signalBar.close - (risk * settings.microEchoRewardRisk);
						Signal echoSignal = signal(
							"ECHO",
							"Profit-Buffered Micro Echo",
						side,
						signalIndex,
						signalBar.close,
						stop,
						targetPrice,
						settings.microEchoMaxHoldBars,
							"Delayed micro echo " + delayIndex + " after " + sourceSymbol + " " + sourceEvent.signal.strategyCode + " signal, requiring " + targetSymbol + " VWAP/EMA continuation confirmation."
						);
						withSourceStrategy(echoSignal, sourceEvent.signal.strategyCode, sourceEvent.signal.strategyName);
					SignalEvent echoEvent = new SignalEvent();
					echoEvent.symbol = targetSymbol;
					echoEvent.signal = echoSignal;
					echoEvent.day = day;
					echoEvent.entryTime = echoTime;
					echoEvent.executionIndex = executionIndex;
					targetEvents.add(echoEvent);
					lastBucketBySideSource.put(bucketKey, bucket);
				}
			}
			Collections.sort(targetEvents, new Comparator<SignalEvent>() {
				@Override
				public int compare(SignalEvent first, SignalEvent second) {
					int timeCompare = first.entryTime.compareTo(second.entryTime);
					if (timeCompare != 0) {
						return timeCompare;
					}
					return first.symbol.compareTo(second.symbol);
				}
			});
		}
	}

	private static boolean microEchoTargetConfirms(InstrumentSpec spec, List<Bar> bars, int index, String side, FuturesStrategySettings settings) {
		if (spec == null || bars == null || index < 10 || index >= bars.size()) {
			return false;
		}
		Bar bar = bars.get(index);
		if (bar == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
			return false;
		}
		double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
		if (volumeRatio < settings.microEchoMinVolumeRatio) {
			return false;
		}
		double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
		double closeLocation = closeLocation(bar);
		if ("LONG".equals(side)) {
			return bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.close >= bar.ema50
				&& trendSlopeTicks >= settings.microEchoMinTrendSlopeTicks
				&& closeLocation >= 0.54
				&& bar.rsi14 >= 48.0;
		}
		return bar.close < bar.vwap
			&& bar.ema9 <= bar.ema20
			&& bar.close <= bar.ema50
			&& trendSlopeTicks <= -settings.microEchoMinTrendSlopeTicks
			&& closeLocation <= 0.46
			&& bar.rsi14 <= 52.0;
	}

	private static void queueWinnerFollowThroughSignal(Map<String, PortfolioSymbolContext> contexts, FuturesTrade sourceTrade, LocalDate day) {
		if (contexts == null || sourceTrade == null || day == null || !"Target reached".equals(sourceTrade.exitReason)) {
			return;
		}
		PortfolioSymbolContext context = contexts.get(sourceTrade.symbol);
		if (context == null || context.byDay == null || context.indexByDayTime == null) {
			return;
		}
		FuturesStrategySettings settings = context.config.strategySettings == null ? defaultFuturesStrategySettings() : context.config.strategySettings;
		if (settings.winnerFollowThrough == null || !settings.winnerFollowThrough.enabled) {
			return;
		}
		if (!winnerFollowThroughSourceAllowed(sourceTrade.strategyCode, settings.winnerFollowThroughSourceCodes)) {
			return;
		}
		if (sourceTrade.pnl < settings.winnerFollowThroughMinSourcePnl) {
			return;
		}
		String side = sourceTrade.side;
		if (("LONG".equals(side) && !settings.allowWinnerFollowThroughLongs) || ("SHORT".equals(side) && !settings.allowWinnerFollowThroughShorts)) {
			return;
		}
		List<Bar> bars = context.byDay.get(day);
		if (bars == null || bars.isEmpty()) {
			return;
		}
		int signalIndex = sourceTrade.exitIndex + Math.max(1, settings.winnerFollowThroughDelayBars);
		int executionIndex = signalIndex + 1;
		if (signalIndex < 30 || executionIndex >= bars.size()) {
			return;
		}
		Bar signalBar = bars.get(signalIndex);
		Bar entryBar = bars.get(executionIndex);
		if (signalBar == null || entryBar == null || !isLiveEntryWindowTime(entryBar.marketTime)) {
			return;
		}
		int minuteOfDay = (entryBar.marketTime.getHour() * 60) + entryBar.marketTime.getMinute();
		if (minuteOfDay < settings.winnerFollowThroughStartMinute || minuteOfDay > settings.winnerFollowThroughEndMinute) {
			return;
		}
		if (hasWinnerFollowThroughEvent(context.eventsByDay.get(day), entryBar.marketTime, side)) {
			return;
		}
		if (!winnerFollowThroughConfirms(context.spec, bars, signalIndex, side, settings)) {
			return;
		}
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.winnerFollowThroughMaxRiskTicks);
		double stop = "LONG".equals(side)
			? compressedLongStop(context.spec, bars, signalIndex, signalBar.close, maxRiskTicks)
			: compressedShortStop(context.spec, bars, signalIndex, signalBar.close, maxRiskTicks);
		double risk = Math.abs(signalBar.close - stop);
		if (risk <= 0.0 || riskTicks(context.spec, signalBar.close, stop) > maxRiskTicks) {
			return;
		}
		double targetPrice = "LONG".equals(side)
			? signalBar.close + (risk * settings.winnerFollowThroughRewardRisk)
			: signalBar.close - (risk * settings.winnerFollowThroughRewardRisk);
			Signal wftSignal = signal(
				"WFT",
				"Winner Follow-Through",
			side,
			signalIndex,
			signalBar.close,
			stop,
			targetPrice,
			settings.winnerFollowThroughMaxHoldBars,
				"Winner follow-through after " + sourceTrade.symbol + " " + sourceTrade.strategyCode + " target hit, requiring same-symbol VWAP/EMA continuation confirmation before the next entry."
			);
			withSourceStrategy(wftSignal, sourceTrade.strategyCode, sourceTrade.strategyName);
		SignalEvent wftEvent = new SignalEvent();
		wftEvent.symbol = sourceTrade.symbol;
		wftEvent.signal = wftSignal;
		wftEvent.day = day;
		wftEvent.entryTime = entryBar.marketTime;
		wftEvent.executionIndex = executionIndex;
		List<SignalEvent> events = context.eventsByDay.get(day);
		if (events == null) {
			events = new ArrayList<SignalEvent>();
			context.eventsByDay.put(day, events);
		}
		events.add(wftEvent);
		sortSignalEvents(events);
	}

	private static boolean winnerFollowThroughSourceAllowed(String strategyCode, String sourceCodes) {
		return sourceStrategyAllowed(strategyCode, sourceCodes);
	}

	private static boolean sourceStrategyAllowed(String strategyCode, String sourceCodes) {
		if (strategyCode == null || sourceCodes == null) {
			return false;
		}
		String normalizedStrategy = strategyCode.trim().toUpperCase();
		String[] tokens = sourceCodes.toUpperCase().split(",");
		for (int index = 0; index < tokens.length; index++) {
			String token = tokens[index].trim();
			if ("ALL".equals(token) || normalizedStrategy.equals(token)) {
				return true;
			}
		}
		return false;
	}

	private static boolean hasWinnerFollowThroughEvent(List<SignalEvent> events, LocalTime entryTime, String side) {
		if (events == null || entryTime == null) {
			return false;
		}
		for (int index = 0; index < events.size(); index++) {
			SignalEvent event = events.get(index);
			if (event != null
				&& event.signal != null
				&& "WFT".equals(event.signal.strategyCode)
				&& entryTime.equals(event.entryTime)
				&& side.equals(event.signal.side)) {
				return true;
			}
		}
		return false;
	}

	private static boolean winnerFollowThroughConfirms(InstrumentSpec spec, List<Bar> bars, int index, String side, FuturesStrategySettings settings) {
		if (spec == null || bars == null || index < 10 || index >= bars.size()) {
			return false;
		}
		Bar bar = bars.get(index);
		if (bar == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
			return false;
		}
		double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
		if (volumeRatio < settings.winnerFollowThroughMinVolumeRatio || bar.bodyPct < settings.winnerFollowThroughMinBodyPct) {
			return false;
		}
		double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
		double closeLocation = closeLocation(bar);
		if ("LONG".equals(side)) {
			return bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.close >= bar.ema50
				&& trendSlopeTicks >= settings.winnerFollowThroughMinTrendSlopeTicks
				&& closeLocation >= settings.winnerFollowThroughLongCloseLocation
				&& bar.rsi14 >= settings.winnerFollowThroughLongMinRsi;
		}
		return bar.close < bar.vwap
			&& bar.ema9 <= bar.ema20
			&& bar.close <= bar.ema50
			&& trendSlopeTicks <= -settings.winnerFollowThroughMinTrendSlopeTicks
			&& closeLocation <= settings.winnerFollowThroughShortCloseLocation
			&& bar.rsi14 <= settings.winnerFollowThroughShortMaxRsi;
	}

	private static void sortSignalEvents(List<SignalEvent> events) {
		Collections.sort(events, new Comparator<SignalEvent>() {
			@Override
			public int compare(SignalEvent first, SignalEvent second) {
				int timeCompare = first.entryTime.compareTo(second.entryTime);
				if (timeCompare != 0) {
					return timeCompare;
				}
				return first.symbol.compareTo(second.symbol);
			}
		});
	}

	private static List<LocalDate> portfolioDays(Map<String, PortfolioSymbolContext> contexts) {
		Set<LocalDate> days = new HashSet<LocalDate>();
		for (PortfolioSymbolContext context : contexts.values()) {
			days.addAll(context.byDay.keySet());
		}
		List<LocalDate> sorted = new ArrayList<LocalDate>(days);
		Collections.sort(sorted);
		return sorted;
	}

	private static List<LocalTime> portfolioTimes(Map<String, PortfolioSymbolContext> contexts, LocalDate day) {
		Set<LocalTime> times = new HashSet<LocalTime>();
		for (PortfolioSymbolContext context : contexts.values()) {
			Map<LocalTime, Integer> index = context.indexByDayTime.get(day);
			if (index != null) {
				times.addAll(index.keySet());
			}
		}
		List<LocalTime> sorted = new ArrayList<LocalTime>(times);
		Collections.sort(sorted);
		return sorted;
	}

	private static Map<String, Bar> barsAt(Map<String, PortfolioSymbolContext> contexts, LocalDate day, LocalTime time) {
		Map<String, Bar> bars = new HashMap<String, Bar>();
		for (PortfolioSymbolContext context : contexts.values()) {
			Integer index = barIndex(context, day, time);
			List<Bar> dayBars = context.byDay.get(day);
			if (index != null && dayBars != null && index >= 0 && index < dayBars.size()) {
				bars.put(context.symbol, dayBars.get(index));
			}
		}
		return bars;
	}

	private static Map<String, Bar> lastBarsForDay(Map<String, PortfolioSymbolContext> contexts, LocalDate day) {
		Map<String, Bar> bars = new HashMap<String, Bar>();
		for (PortfolioSymbolContext context : contexts.values()) {
			List<Bar> dayBars = context.byDay.get(day);
			if (dayBars != null && !dayBars.isEmpty()) {
				bars.put(context.symbol, dayBars.get(dayBars.size() - 1));
			}
		}
		return bars;
	}

	private static Integer barIndex(PortfolioSymbolContext context, LocalDate day, LocalTime time) {
		Map<LocalTime, Integer> byTime = context.indexByDayTime.get(day);
		return byTime == null ? null : byTime.get(time);
	}

	private static LiveRuntimeState.OrderFlowSnapshot orderFlowAt(PortfolioSymbolContext context, LocalDate day, LocalTime time) {
		if (context == null || context.orderFlowByDayTime == null || day == null || time == null) {
			return null;
		}
		Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot> byTime = context.orderFlowByDayTime.get(day);
		return byTime == null ? null : byTime.get(time);
	}

	private static LivePortfolioSignalCandidate portfolioSignalCandidate(PortfolioSymbolContext context, SignalEvent event, Bar entryBar) {
		LivePortfolioSignalCandidate candidate = new LivePortfolioSignalCandidate();
		candidate.symbol = event == null ? "" : event.symbol;
		candidate.context = context;
		candidate.event = event;
		candidate.entryBar = entryBar;
		LocalTime signalTime = signalBarTime(context, event);
		candidate.signalTime = displayTime(event == null ? null : event.day, signalTime);
		candidate.entryTime = displayTime(event == null ? null : event.day, event == null ? null : event.entryTime);
		return candidate;
	}

	private static List<SignalEvent> signalEventsAt(Map<String, PortfolioSymbolContext> contexts, LocalDate day, LocalTime time) {
		List<SignalEvent> events = new ArrayList<SignalEvent>();
		for (PortfolioSymbolContext context : contexts.values()) {
			List<SignalEvent> dayEvents = context.eventsByDay.get(day);
			if (dayEvents == null) {
				continue;
			}
			for (int index = 0; index < dayEvents.size(); index++) {
				SignalEvent event = dayEvents.get(index);
				if (time.equals(event.entryTime)) {
					events.add(event);
				}
			}
		}
		Collections.sort(events, new Comparator<SignalEvent>() {
			@Override
			public int compare(SignalEvent first, SignalEvent second) {
				return first.symbol.compareTo(second.symbol);
			}
		});
		return events;
	}

	private static void rankPortfolioSignalEvents(final List<SignalEvent> events, final Map<String, PortfolioSymbolContext> contexts) {
		Collections.sort(events, new Comparator<SignalEvent>() {
			@Override
			public int compare(SignalEvent first, SignalEvent second) {
				double firstScore = portfolioEventScore(contexts.get(first.symbol), first);
				double secondScore = portfolioEventScore(contexts.get(second.symbol), second);
				int scoreCompare = Double.compare(secondScore, firstScore);
				if (scoreCompare != 0) {
					return scoreCompare;
				}
				int timeCompare = first.entryTime.compareTo(second.entryTime);
				if (timeCompare != 0) {
					return timeCompare;
				}
				return first.symbol.compareTo(second.symbol);
			}
		});
	}

	private static double portfolioEventScore(PortfolioSymbolContext context, SignalEvent event) {
		if (context == null || event == null || event.signal == null) {
			return 0.0;
		}
		Signal signal = event.signal;
		Bar signalBar = signalBarForEvent(context, event);
		double signalRisk = Math.abs(signal.entryPrice - signal.stopPrice);
		double rewardRisk = signalRisk <= 0.0 ? context.spec.defaultTargetR : Math.abs(signal.targetPrice - signal.entryPrice) / signalRisk;
		double riskTicks = signalRisk <= 0.0 ? 999.0 : signalRisk / context.spec.tickSize;
		double score = 50.0 + (clamp(rewardRisk, 0.0, 3.0) * 5.0) - Math.min(25.0, riskTicks * 0.35);
		if (isFrequencyExpansionStrategy(signal.strategyCode)) {
			score -= 2.0;
		}
		if (signalBar != null) {
			double volumeRatio = signalBar.volumeSma20 <= 0.0 ? 1.0 : signalBar.volume / signalBar.volumeSma20;
			if (volumeRatio >= 1.25) {
				score += 3.0;
			}
			if (signalBar.bodyPct >= 35.0) {
				score += 2.0;
			}
			if (emaTrendAligned(signal.side, signalBar)) {
				score += 3.0;
			}
			if ("LONG".equals(signal.side) && closeLocation(signalBar) >= 0.65) {
				score += 1.0;
			}
			if ("SHORT".equals(signal.side) && closeLocation(signalBar) <= 0.35) {
				score += 1.0;
			}
		}
		return score;
	}

	private static Bar signalBarForEvent(PortfolioSymbolContext context, SignalEvent event) {
		if (context == null || event == null || event.signal == null) {
			return null;
		}
		List<Bar> bars = context.byDay.get(event.day);
		if (bars == null || bars.isEmpty()) {
			return null;
		}
		int signalIndex = Math.max(0, Math.min(event.signal.entryIndex, bars.size() - 1));
		return bars.get(signalIndex);
	}

	private static double portfolioRiskBudgetMultiplier(
		PortfolioSymbolContext context,
		SignalEvent event,
		double realizedDayPnl,
		double aggregateGuardBudget,
		int openPositions
	) {
		if (context == null || event == null || event.signal == null) {
			return 0.0;
		}
		Signal signal = event.signal;
		double signalRisk = Math.abs(signal.entryPrice - signal.stopPrice);
		double riskTicks = signalRisk <= 0.0 ? 999.0 : signalRisk / context.spec.tickSize;
		double multiplier = signalQualityRiskMultiplier(context, event);
		if (riskTicks <= 12.0) {
			multiplier *= 1.12;
		} else if (riskTicks <= 24.0) {
			multiplier *= 1.0;
		} else if (riskTicks <= 48.0) {
			multiplier *= 0.82;
		} else {
			multiplier *= 0.60;
		}
		FuturesStrategySettings settings = context.config.strategySettings == null ? defaultFuturesStrategySettings() : context.config.strategySettings;
		if ("ECHO".equals(signal.strategyCode) && realizedDayPnl < settings.microEchoMinRealizedDayPnl) {
			return 0.0;
		}
		if (isFrequencyExpansionStrategy(signal.strategyCode)) {
			multiplier *= frequencyExpansionRiskMultiplier(settings, signal.strategyCode);
		}

		if (realizedDayPnl >= 750.0 && aggregateGuardBudget > 750.0) {
			multiplier *= 1.22;
		} else if (realizedDayPnl >= 300.0 && aggregateGuardBudget > 450.0) {
			multiplier *= 1.12;
		} else if (realizedDayPnl < -150.0) {
			multiplier *= 0.65;
		} else if (realizedDayPnl < 0.0) {
			multiplier *= 0.85;
		}
		if (openPositions > 0 && aggregateGuardBudget < 350.0) {
			multiplier *= 0.65;
		}
		if (aggregateGuardBudget < 175.0) {
			multiplier *= 0.5;
		}
		return clamp(multiplier, 0.0, 1.35);
	}

	private static double frequencyExpansionRiskMultiplier(FuturesStrategySettings settings, String strategyCode) {
		FuturesStrategySettings safeSettings = settings == null ? defaultFuturesStrategySettings() : settings;
		if ("OMOM".equals(strategyCode)) {
			return clamp(safeSettings.openingMomentumPortfolioRiskMultiplier, 0.20, 1.35);
		}
		if ("SHDW".equals(strategyCode)) {
			return clamp(safeSettings.microShadowPortfolioRiskMultiplier, 0.05, 0.65);
		}
		if ("MSCALP".equals(strategyCode)) {
			return 0.14;
		}
		if ("ECHO".equals(strategyCode)) {
			return clamp(safeSettings.microEchoPortfolioRiskMultiplier, 0.05, 0.50);
		}
		if ("WFT".equals(strategyCode)) {
			return clamp(safeSettings.winnerFollowThroughPortfolioRiskMultiplier, 0.05, 0.50);
		}
		if ("RCB".equals(strategyCode) || "VPB".equals(strategyCode)) {
			return 0.20;
		}
		return 0.45;
	}

	private static double signalQualityRiskMultiplier(PortfolioSymbolContext context, SignalEvent event) {
		Bar signalBar = signalBarForEvent(context, event);
		if (signalBar == null || event == null || event.signal == null) {
			return 0.9;
		}
		double multiplier = 0.92;
		double volumeRatio = signalBar.volumeSma20 <= 0.0 ? 1.0 : signalBar.volume / signalBar.volumeSma20;
		if (volumeRatio >= 1.25) {
			multiplier += 0.08;
		}
		if (signalBar.bodyPct >= 35.0) {
			multiplier += 0.06;
		}
		if (emaTrendAligned(event.signal.side, signalBar)) {
			multiplier += 0.08;
		}
		return clamp(multiplier, 0.75, 1.12);
	}

	private static boolean isFrequencyExpansionStrategy(String strategyCode) {
		return "OMOM".equals(strategyCode)
			|| "AFT".equals(strategyCode)
			|| "MIM".equals(strategyCode)
			|| "IPB".equals(strategyCode)
			|| "VRCL".equals(strategyCode)
			|| "CMOM".equals(strategyCode)
			|| "MSCALP".equals(strategyCode)
			|| "SHDW".equals(strategyCode)
			|| "ECHO".equals(strategyCode)
			|| "WFT".equals(strategyCode)
			|| "TLAD".equals(strategyCode)
			|| "KELT".equals(strategyCode)
			|| "RCB".equals(strategyCode)
			|| "VPB".equals(strategyCode)
			|| "KREV".equals(strategyCode);
	}

	private static boolean isLiveRiskCompressibleStrategy(String strategyCode) {
		return portfolioRiskCompressionAllowed(strategyCode);
	}

	private static boolean portfolioBacktestAllowsLiveRiskCompression(String strategyCode) {
		return portfolioRiskCompressionAllowed(strategyCode);
	}

	private static boolean portfolioRiskCompressionAllowed(String strategyCode) {
		return false;
	}

	private static double liveInitialRiskLimitTicks(FuturesStrategySettings settings, String strategyCode) {
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		double limit = safe.maxInitialRiskTicks;
		if ("ORB2".equals(code)) {
			limit = safe.orbRetestMaxRiskTicks;
		} else if ("ORBX".equals(code)) {
			limit = safe.orbEventPackMaxRiskTicks;
		} else if ("LORB".equals(code)) {
			limit = safe.lateOrbContinuationMaxRiskTicks;
		} else if ("KREV".equals(code) || "KELT".equals(code)) {
			limit = Math.min(limit, safe.keltnerMaxRiskTicks);
		} else if ("VRCL".equals(code)) {
			limit = Math.min(limit, safe.vwapReclaimMaxRiskTicks);
		} else if ("OMOM".equals(code)) {
			limit = Math.min(limit, safe.openingMomentumMaxRiskTicks);
		} else if ("RMC".equals(code)) {
			limit = Math.min(limit, safe.rangeMidpointMaxRiskTicks);
		} else if ("BOSRT".equals(code)) {
			limit = Math.min(limit, safe.bosRetestMaxRiskTicks);
		} else if (isVolumePriceStrategyCode(code)) {
			limit = Math.min(limit, safe.volumePriceMaxRiskTicks);
		}
		return Math.max(1.0, limit);
	}

	private static boolean hasOpenSymbol(List<PortfolioPosition> positions, String symbol) {
		for (int index = 0; index < positions.size(); index++) {
			if (positions.get(index).symbol.equals(symbol)) {
				return true;
			}
		}
		return false;
	}

	private static boolean hasOpenCorrelatedPosition(List<PortfolioPosition> positions, String symbol) {
		if (positions == null || positions.isEmpty()) {
			return false;
		}
		String family = correlatedSymbolFamily(symbol);
		if (family.length() == 0) {
			return false;
		}
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			if (position != null && family.equals(correlatedSymbolFamily(position.symbol))) {
				return true;
			}
		}
		return false;
	}

	private static boolean backtestHasCorrelatedPortfolioExposure(List<PortfolioPosition> positions, String symbol) {
		return hasOpenCorrelatedPosition(positions, symbol);
	}

	private static boolean hasOpenCorrelatedSymbol(String symbols, String symbol) {
		String family = correlatedSymbolFamily(symbol);
		if (family.length() == 0 || symbols == null || symbols.trim().isEmpty()) {
			return false;
		}
		String[] parts = symbols.split(",");
		for (int index = 0; index < parts.length; index++) {
			if (family.equals(correlatedSymbolFamily(parts[index]))) {
				return true;
			}
		}
		return false;
	}

	private static String correlatedSymbolFamily(String symbol) {
		String normalized = normalizeSymbol(symbol);
		if ("NQ".equals(normalized) || "MNQ".equals(normalized)) return "NASDAQ";
		if ("ES".equals(normalized) || "MES".equals(normalized)) return "SP500";
		if ("GC".equals(normalized) || "MGC".equals(normalized)) return "GOLD";
		if ("YM".equals(normalized) || "MYM".equals(normalized)) return "DOW";
		if ("RTY".equals(normalized) || "M2K".equals(normalized)) return "RUSSELL";
		return "";
	}

	private static int openContractCount(List<PortfolioPosition> positions) {
		int contracts = 0;
		for (int index = 0; index < positions.size(); index++) {
			contracts += positions.get(index).contracts;
		}
		return contracts;
	}

	private static double openMiniUnitCount(List<PortfolioPosition> positions) {
		double units = 0.0;
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			units += fundedMiniUnitsPerContract(position.symbol) * position.contracts;
		}
		return units;
	}

	private static boolean fundedMiniUnitLimitReached(PortfolioBacktestConfig config, double openMiniUnits) {
		return config.maxAggregateMiniUnits > 0.0 && openMiniUnits >= config.maxAggregateMiniUnits - 0.000001;
	}

	private static boolean fundedMiniUnitLimitReached(PortfolioBacktestConfig config, double openMiniUnits, double aggregateMiniUnitLimit) {
		return aggregateMiniUnitLimit > 0.0 && openMiniUnits >= aggregateMiniUnitLimit - 0.000001;
	}

	private static DynamicRiskPolicy dynamicRiskPolicyForMode(String mode) {
		String normalized = cleanOrDefault(mode, RISK_SIZING_STATIC_WITHDRAW_DAILY).trim().toUpperCase(Locale.US);
		DynamicRiskPolicy policy = new DynamicRiskPolicy();
		if (RISK_SIZING_DYNAMIC_COMPOUND_MLL.equals(normalized)) {
			policy.mode = RISK_SIZING_DYNAMIC_COMPOUND_MLL;
			policy.stopRiskBufferMultiplier = 1.20;
			policy.dailyRoomUsagePct = 0.55;
			policy.mllRoomUsagePct = 0.30;
			policy.maxRiskMultiplier = 3.0;
			policy.dllReserveDollars = 200.0;
			policy.mllReserveDollars = 0.0;
		}
		return policy;
	}

	private static DynamicRiskBudget dynamicRiskBudget(
		DynamicRiskPolicy policy,
		double configuredMaxRisk,
		double dllRoom,
		double mllRoom,
		double configuredMllLimit
	) {
		DynamicRiskPolicy safe = policy == null ? dynamicRiskPolicyForMode(RISK_SIZING_STATIC_WITHDRAW_DAILY) : policy;
		DynamicRiskBudget budget = new DynamicRiskBudget();
		double mllBase = Math.max(1.0, Math.abs(configuredMllLimit));
		double multiplier = RISK_SIZING_DYNAMIC_COMPOUND_MLL.equals(safe.mode)
			? clamp(mllRoom / mllBase, 0.0, Math.max(0.0, safe.maxRiskMultiplier))
			: 1.0;
		budget.dynamicMaxRisk = Math.max(0.0, configuredMaxRisk * multiplier);
		budget.dailyRoomBudget = Math.max(0.0, dllRoom - Math.max(0.0, safe.dllReserveDollars)) * clamp(safe.dailyRoomUsagePct, 0.0, 1.0);
		budget.mllRoomBudget = Math.max(0.0, mllRoom - Math.max(0.0, safe.mllReserveDollars)) * clamp(safe.mllRoomUsagePct, 0.0, 1.0);
		budget.availableRiskBudget = Math.min(budget.dynamicMaxRisk, Math.min(budget.dailyRoomBudget, budget.mllRoomBudget));
		return budget;
	}

	private static double dynamicMllAggregateMiniUnitLimit(PortfolioBacktestConfig config, double dayStartBalance) {
		if (config == null || !config.dynamicMllRiskEnabled || !config.dynamicMllAggregateMiniUnits || config.maxAggregateMiniUnits <= 0.0) {
			return config == null ? 0.0 : config.maxAggregateMiniUnits;
		}
		double baseMllRoom = Math.max(1.0, Math.abs(config.maxTrailingDrawdown));
		double accountPnlAtDayStart = dayStartBalance - config.accountSize;
		double mllRoom = Math.max(0.0, accountPnlAtDayStart + baseMllRoom);
		double multiplier = clamp(mllRoom / baseMllRoom, 0.0, Math.max(0.0, config.dynamicMllRiskMaxMultiplier));
		return Math.max(0.0, config.maxAggregateMiniUnits * multiplier);
	}

	private static int contractsAllowedByMiniUnitRoom(String symbol, double room) {
		if (room <= 0.0) {
			return 0;
		}
		return (int) Math.floor((room + 0.000001) / fundedMiniUnitsPerContract(symbol));
	}

	private static double fundedMiniUnitsPerContract(String symbol) {
		return isMicroFuturesSymbol(symbol) ? 0.1 : 1.0;
	}

	private static int strategySpecificMaxContracts(String symbol, String strategyCode, FuturesStrategySettings settings, int configuredMaxContracts) {
		int maxContracts = Math.max(0, configuredMaxContracts);
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		if ("LIQREC".equals(code) && safe.liquidityReclaimMaxContracts > 0) {
			maxContracts = maxContracts <= 0 ? safe.liquidityReclaimMaxContracts : Math.min(maxContracts, safe.liquidityReclaimMaxContracts);
		}
		if ("ORBX".equals(code) && safe.orbEventPackMaxContracts > 0) {
			maxContracts = maxContracts <= 0 ? safe.orbEventPackMaxContracts : Math.min(maxContracts, safe.orbEventPackMaxContracts);
		}
		if (isVolumePriceStrategyCode(code) && safe.volumePriceMaxContracts > 0) {
			maxContracts = maxContracts <= 0 ? safe.volumePriceMaxContracts : Math.min(maxContracts, safe.volumePriceMaxContracts);
		}
		return maxContracts;
	}

	private static PortfolioPosition openPortfolioPosition(
		PortfolioSymbolContext context,
		SignalEvent event,
		Bar entryBar,
		double riskBudget,
		int aggregateRoom,
		double aggregateGuardBudget
	) {
		return openPortfolioPosition(context, event, entryBar, riskBudget, aggregateRoom, aggregateGuardBudget, false);
	}

	private static PortfolioPosition openPortfolioPosition(
		PortfolioSymbolContext context,
		SignalEvent event,
		Bar entryBar,
		double riskBudget,
		int aggregateRoom,
		double aggregateGuardBudget,
		boolean allowLiveRiskCompression
	) {
		return openPortfolioPosition(context, event, entryBar, riskBudget, aggregateRoom, aggregateGuardBudget, allowLiveRiskCompression, 1.0);
	}

	private static PortfolioPosition openPortfolioPosition(
		PortfolioSymbolContext context,
		SignalEvent event,
		Bar entryBar,
		double riskBudget,
		int aggregateRoom,
		double aggregateGuardBudget,
		boolean allowLiveRiskCompression,
		double stopRiskBufferMultiplier
	) {
		Signal signal = event.signal;
		double signalRisk = Math.abs(signal.entryPrice - signal.stopPrice);
		if (signalRisk <= 0.0) {
			return null;
		}
		double rewardMultiple = Math.abs(signal.targetPrice - signal.entryPrice) / signalRisk;
		if (rewardMultiple <= 0.0 || Double.isNaN(rewardMultiple) || Double.isInfinite(rewardMultiple)) {
			rewardMultiple = context.spec.defaultTargetR;
		}

		double entryPrice = applySlippage(context.spec, entryBar.open, signal.side, context.config.slippageTicks, true);
		double stopPrice = roundToTick(context.spec, signal.stopPrice);
		if ("LONG".equals(signal.side) && entryPrice <= stopPrice) {
			return null;
		}
		if ("SHORT".equals(signal.side) && entryPrice >= stopPrice) {
			return null;
		}

		double initialRisk = Math.abs(entryPrice - stopPrice);
		double rawRiskTicks = initialRisk / context.spec.tickSize;
			if (rawRiskTicks < 1.0) {
				return null;
			}
			FuturesStrategySettings settings = context.config.strategySettings == null ? defaultFuturesStrategySettings() : context.config.strategySettings;
			double maxLiveRiskTicks = liveInitialRiskLimitTicks(settings, signal.strategyCode);
			double originalStopPrice = stopPrice;
			boolean compressedRiskPlan = false;
			if (rawRiskTicks > maxLiveRiskTicks && allowLiveRiskCompression && isLiveRiskCompressibleStrategy(signal.strategyCode)) {
				List<Bar> dayBarsForCompression = context.byDay.get(event.day);
				double compressedStop = "LONG".equals(signal.side)
					? compressedLongStop(context.spec, dayBarsForCompression, event.executionIndex, entryPrice, maxLiveRiskTicks)
					: compressedShortStop(context.spec, dayBarsForCompression, event.executionIndex, entryPrice, maxLiveRiskTicks);
				boolean validCompressedStop = ("LONG".equals(signal.side) && entryPrice > compressedStop)
					|| ("SHORT".equals(signal.side) && entryPrice < compressedStop);
				if (validCompressedStop) {
					double compressedRisk = Math.abs(entryPrice - compressedStop);
					double compressedRiskTicks = compressedRisk / context.spec.tickSize;
					if (compressedRiskTicks >= 1.0 && compressedRiskTicks <= maxLiveRiskTicks) {
						stopPrice = compressedStop;
						initialRisk = compressedRisk;
						rawRiskTicks = compressedRiskTicks;
						compressedRiskPlan = true;
					}
				}
			}
			if (rawRiskTicks > maxLiveRiskTicks) {
				return null;
			}
		List<Bar> dayBars = context.byDay.get(event.day);
		rewardMultiple = adaptiveRewardMultiple(context.spec, dayBars, signal, event.executionIndex, rewardMultiple, settings);

		double stopFillForRisk = applySlippage(context.spec, stopPrice, signal.side, context.config.slippageTicks, false);
		double riskPerContract = (Math.abs(entryPrice - stopFillForRisk) / context.spec.tickSize * context.spec.tickValue) + (context.config.commissionPerContract * 2.0);
		double sizingRiskPerContract = riskPerContract * settings.openMaeRiskMultiplier;
		double bufferedRiskPerContract = riskPerContract * Math.max(1.0, stopRiskBufferMultiplier);
		double effectiveRiskBudget = Math.max(0.0, riskBudget);
		int maxContracts = strategySpecificMaxContracts(context.symbol, signal.strategyCode, settings, context.config.maxContracts);
		int contracts = Math.min(maxContracts, Math.min(aggregateRoom, (int) Math.floor(effectiveRiskBudget / Math.max(1.0, bufferedRiskPerContract))));
		while (contracts > 0 && (sizingRiskPerContract * contracts) > Math.max(0.0, aggregateGuardBudget)) {
			contracts--;
		}
		if (contracts < 1) {
			return null;
		}

		double targetPrice = "LONG".equals(signal.side)
			? roundToTick(context.spec, entryPrice + (initialRisk * rewardMultiple))
			: roundToTick(context.spec, entryPrice - (initialRisk * rewardMultiple));

		PortfolioPosition position = new PortfolioPosition();
		position.symbol = context.symbol;
		position.spec = context.spec;
		position.signal = signal;
		position.side = signal.side;
			position.contracts = contracts;
			position.entryPrice = roundToTick(context.spec, entryPrice);
			position.plannedEntryPrice = roundToTick(context.spec, signal.entryPrice);
			position.stopPrice = roundToTick(context.spec, stopPrice);
		position.activeStopPrice = position.stopPrice;
		position.targetPrice = roundToTick(context.spec, targetPrice);
		position.initialRisk = initialRisk;
		position.rawRiskTicks = rawRiskTicks;
			position.maxRiskTicks = maxLiveRiskTicks;
		position.originalStopPrice = originalStopPrice;
		position.compressedRiskPlan = compressedRiskPlan;
		position.minTrailDistance = managedTrailDistance(context.spec, initialRisk, settings);
		position.riskPerContract = riskPerContract;
		position.commissionPerContract = context.config.commissionPerContract;
		position.originalContracts = contracts;
		position.entryIndex = event.executionIndex;
		position.openedAt = entryBar.displayTime;
		position.openedMarketTime = entryBar.marketTime;
		return position;
	}

	private static void updateOpenPositionExcursions(List<PortfolioPosition> positions, Map<String, Bar> currentBars) {
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			Bar bar = currentBars.get(position.symbol);
			if (bar == null) {
				continue;
			}
			double favorable = favorablePnl(position.spec, position.side, position.entryPrice, bar, position.contracts);
			double adverse = adversePnl(position.spec, position.side, position.entryPrice, bar, position.contracts);
			position.maxFavorable = Math.max(position.maxFavorable, favorable);
			position.maxAdverse = Math.min(position.maxAdverse, adverse);
		}
	}

	private static double aggregateOpenRisk(List<PortfolioPosition> positions) {
		double risk = 0.0;
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			risk += position.riskPerContract * position.contracts;
		}
		return round(risk);
	}

	private static double aggregateOpenPnl(List<PortfolioPosition> positions, Map<String, Bar> currentBars, String priceField) {
		double pnl = 0.0;
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			Bar bar = currentBars.get(position.symbol);
			if (bar == null) {
				continue;
			}
			double mark = "open".equals(priceField) ? bar.open : bar.close;
			pnl += pnlForPrice(position.spec, position.side, position.entryPrice, mark, position.contracts) - roundTripCommission(position);
		}
		return round(pnl);
	}

	private static double aggregateWorstOpenPnl(List<PortfolioPosition> positions, Map<String, Bar> currentBars) {
		double pnl = 0.0;
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			Bar bar = currentBars.get(position.symbol);
			if (bar == null) {
				continue;
			}
			pnl += adversePnl(position.spec, position.side, position.entryPrice, bar, position.contracts) - roundTripCommission(position);
		}
		return round(pnl);
	}

	private static double roundTripCommission(PortfolioPosition position) {
		return position.commissionPerContract * position.contracts * 2.0;
	}

	private static void updatePortfolioExposureMetrics(PortfolioBacktestResult result, List<PortfolioPosition> positions) {
		int contracts = 0;
		double miniUnits = 0.0;
		double notionalExposure = 0.0;
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			contracts += position.contracts;
			miniUnits += fundedMiniUnitsPerContract(position.symbol) * position.contracts;
			notionalExposure += Math.abs(position.entryPrice * position.spec.pointValue * position.contracts);
		}
		result.maxConcurrentPositions = Math.max(result.maxConcurrentPositions, positions.size());
		result.maxConcurrentContracts = Math.max(result.maxConcurrentContracts, contracts);
		result.maxConcurrentMiniUnits = round(Math.max(result.maxConcurrentMiniUnits, miniUnits));
		result.maxNotionalExposure = round(Math.max(result.maxNotionalExposure, notionalExposure));
	}

	private static List<FuturesTrade> closeTriggeredPortfolioPositions(
		List<PortfolioPosition> positions,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBars,
		LocalDate day,
		LocalTime time
	) {
		return closeTriggeredPortfolioPositions(positions, contexts, currentBars, day, time, false, null, null);
	}

	private static List<FuturesTrade> closeTriggeredPortfolioPositions(
		List<PortfolioPosition> positions,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBars,
		LocalDate day,
		LocalTime time,
		boolean dtmEnabled,
		FuturesLiveSession dtmSession,
		LiveStrategySnapshotRow dtmSnapshot
	) {
		return closeTriggeredPortfolioPositions(positions, contexts, currentBars, day, time, dtmEnabled, dtmSession, dtmSnapshot, null);
	}

	private static List<FuturesTrade> closeTriggeredPortfolioPositions(
		List<PortfolioPosition> positions,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBars,
		LocalDate day,
		LocalTime time,
		boolean dtmEnabled,
		FuturesLiveSession dtmSession,
		LiveStrategySnapshotRow dtmSnapshot,
		PortfolioBacktestResult result
	) {
		List<FuturesTrade> trades = new ArrayList<FuturesTrade>();
		for (int index = positions.size() - 1; index >= 0; index--) {
			PortfolioPosition position = positions.get(index);
			PortfolioSymbolContext context = contexts.get(position.symbol);
			Bar bar = currentBars.get(position.symbol);
			if (context == null || bar == null) {
				continue;
			}
			FuturesTrade triggeredTrade = dtmEnabled
				? closePortfolioPositionIfStopTriggered(position, context, bar, day, time)
				: closePortfolioPositionIfTriggered(position, context, bar, day, time);
			if (triggeredTrade != null) {
				if (dtmEnabled) {
					applyDynamicTradeStateToTrade(
						dtmSession == null ? 0 : dtmSession.sessionId,
						dtmSnapshot == null ? 0 : dtmSnapshot.snapshotId,
						position,
						triggeredTrade,
						""
					);
				}
				trades.add(0, triggeredTrade);
				positions.remove(index);
				continue;
			}
			if (dtmEnabled) {
				LiveRuntimeState.OrderFlowSnapshot flow = orderFlowAt(context, day, time);
				position.dtmEvaluationCount++;
				if (flow != null && flow.available && flow.fresh) {
					position.dtmOrderFlowAvailableCount++;
				}
				if (result != null) {
					result.dtmEvaluations++;
					if (flow != null && flow.available && flow.fresh) {
						result.dtmOrderFlowAvailable++;
					} else {
						result.dtmOrderFlowMissing++;
					}
				}
				double preDtmTargetPrice = position.targetPrice;
				DynamicTradeDecision dtmDecision = evaluateDynamicTradeManager(dtmSession, dtmSnapshot, position, context, bar, flow, false);
				if (dtmDecision != null) {
					position.dtmDecisionCount++;
					recordPortfolioDtmDecision(result, dtmDecision);
				}
				if (dtmDecision != null && dtmDecision.finalExit) {
					FuturesTrade dtmTrade = buildPortfolioTrade(position, context, bar, currentIndexOrEntry(position, context, bar), bar.close, dtmDecision.exitReason);
					applyDynamicTradeStateToTrade(
						dtmSession == null ? 0 : dtmSession.sessionId,
						dtmSnapshot == null ? 0 : dtmSnapshot.snapshotId,
						position,
						dtmTrade,
						dtmDecision.actionCode
					);
					trades.add(0, dtmTrade);
					positions.remove(index);
					continue;
				}
				FuturesTrade postDtmTrade = closePortfolioPositionAfterDtmDecision(position, context, bar, day, time, dtmDecision, preDtmTargetPrice);
				if (postDtmTrade != null) {
					applyDynamicTradeStateToTrade(
						dtmSession == null ? 0 : dtmSession.sessionId,
						dtmSnapshot == null ? 0 : dtmSnapshot.snapshotId,
						position,
						postDtmTrade,
						""
					);
					trades.add(0, postDtmTrade);
					positions.remove(index);
				}
			}
		}
		return trades;
	}

	private static FuturesTrade closePortfolioPositionIfTriggered(
		PortfolioPosition position,
		PortfolioSymbolContext context,
		Bar bar,
		LocalDate day,
		LocalTime time
	) {
		Integer currentIndexValue = barIndex(context, day, time);
		if (currentIndexValue == null || currentIndexValue < position.entryIndex) {
			return null;
		}
		int currentIndex = currentIndexValue.intValue();
		double exitPrice = bar.close;
		String exitReason = null;
		if ("LONG".equals(position.side)) {
			if (bar.low <= position.activeStopPrice && bar.high >= position.targetPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = "Stop and target touched; stop assumed first";
			} else if (bar.low <= position.activeStopPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = position.activeStopPrice == position.stopPrice ? "Stop loss hit" : "Managed stop hit";
			} else if (bar.high >= position.targetPrice) {
				exitPrice = position.targetPrice;
				exitReason = "Target reached";
			}
		} else {
			if (bar.high >= position.activeStopPrice && bar.low <= position.targetPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = "Stop and target touched; stop assumed first";
			} else if (bar.high >= position.activeStopPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = position.activeStopPrice == position.stopPrice ? "Stop loss hit" : "Managed stop hit";
			} else if (bar.low <= position.targetPrice) {
				exitPrice = position.targetPrice;
				exitReason = "Target reached";
			}
		}
		FuturesStrategySettings settings = context.config.strategySettings == null ? defaultFuturesStrategySettings() : context.config.strategySettings;
		if (exitReason == null && shouldEarlyLossCut(position.spec, settings, position.side, position.entryPrice, position.initialRisk, bar, position.contracts, currentIndex - position.entryIndex)) {
			exitPrice = bar.close;
			exitReason = "Adaptive loss cut exit";
		}
		if (exitReason == null && shouldManagedGivebackExit(position.spec, settings, position.side, position.entryPrice, position.initialRisk, position.maxFavorable, bar, position.contracts, currentIndex - position.entryIndex)) {
			exitPrice = bar.close;
			exitReason = "Managed giveback exit";
		}
		if (exitReason == null && !bar.marketTime.isBefore(FORCED_EXIT_TIME)) {
			exitPrice = bar.close;
			exitReason = "Funded-session flat exit";
		}
		if (exitReason == null && position.signal.maxHoldBars > 0 && currentIndex - position.entryIndex >= position.signal.maxHoldBars) {
			exitPrice = bar.close;
			exitReason = "Time stop exit";
		}
		if (exitReason == null) {
			position.activeStopPrice = updateManagedStop(position.spec, position.side, position.entryPrice, position.activeStopPrice, bar.close, position.initialRisk, position.minTrailDistance, settings);
			return null;
		}
		return buildPortfolioTrade(position, context, bar, currentIndex, exitPrice, exitReason);
	}

	private static FuturesTrade closePortfolioPositionAfterDtmDecision(
		PortfolioPosition position,
		PortfolioSymbolContext context,
		Bar bar,
		LocalDate day,
		LocalTime time,
		DynamicTradeDecision decision,
		double preDtmTargetPrice
	) {
		if (decision == null) {
			return closePortfolioPositionIfTriggered(position, context, bar, day, time);
		}
		String code = cleanOrDefault(decision.actionCode, "");
		if ("DTM_MOVE_STOP_BREAKEVEN".equals(code) || "DTM_TRAIL_STOP".equals(code) || "DTM_PARTIAL_BLOCKED".equals(code)) {
			return closePortfolioPositionIfTargetTriggered(position, context, bar, day, time, preDtmTargetPrice);
		}
		return null;
	}

	private static FuturesTrade closePortfolioPositionIfTargetTriggered(
		PortfolioPosition position,
		PortfolioSymbolContext context,
		Bar bar,
		LocalDate day,
		LocalTime time,
		double targetPrice
	) {
		Integer currentIndexValue = barIndex(context, day, time);
		if (currentIndexValue == null || currentIndexValue < position.entryIndex || targetPrice <= 0.0) {
			return null;
		}
		if ("LONG".equals(position.side)) {
			if (bar.high >= targetPrice) {
				return buildPortfolioTrade(position, context, bar, currentIndexValue.intValue(), targetPrice, "Target reached");
			}
		} else if (bar.low <= targetPrice) {
			return buildPortfolioTrade(position, context, bar, currentIndexValue.intValue(), targetPrice, "Target reached");
		}
		return null;
	}

	private static FuturesTrade closePortfolioPositionIfStopTriggered(
		PortfolioPosition position,
		PortfolioSymbolContext context,
		Bar bar,
		LocalDate day,
		LocalTime time
	) {
		Integer currentIndexValue = barIndex(context, day, time);
		if (currentIndexValue == null || currentIndexValue < position.entryIndex) {
			return null;
		}
		int currentIndex = currentIndexValue.intValue();
		double exitPrice = 0.0;
		String exitReason = null;
		if ("LONG".equals(position.side)) {
			if (bar.low <= position.activeStopPrice && bar.high >= position.targetPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = "Stop and target touched; stop assumed first";
			} else if (bar.low <= position.activeStopPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = position.activeStopPrice == position.stopPrice ? "Stop loss hit" : "Managed stop hit";
			}
		} else {
			if (bar.high >= position.activeStopPrice && bar.low <= position.targetPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = "Stop and target touched; stop assumed first";
			} else if (bar.high >= position.activeStopPrice) {
				exitPrice = position.activeStopPrice;
				exitReason = position.activeStopPrice == position.stopPrice ? "Stop loss hit" : "Managed stop hit";
			}
		}
		return exitReason == null ? null : buildPortfolioTrade(position, context, bar, currentIndex, exitPrice, exitReason);
	}

	private static List<FuturesTrade> forceClosePortfolioPositions(
		List<PortfolioPosition> positions,
		Map<String, PortfolioSymbolContext> contexts,
		Map<String, Bar> currentBars,
		LocalDate day,
		LocalTime time,
		String reason
	) {
		List<FuturesTrade> trades = new ArrayList<FuturesTrade>();
		for (int index = 0; index < positions.size(); index++) {
			PortfolioPosition position = positions.get(index);
			PortfolioSymbolContext context = contexts.get(position.symbol);
			Bar bar = currentBars.get(position.symbol);
			if (context == null || bar == null) {
				continue;
			}
			Integer currentIndexValue = barIndex(context, day, time);
			int currentIndex = currentIndexValue == null ? position.entryIndex : currentIndexValue.intValue();
			trades.add(buildPortfolioTrade(position, context, bar, currentIndex, bar.close, reason));
		}
		positions.clear();
		return trades;
	}

	private static void recordPortfolioDtmDecision(PortfolioBacktestResult result, DynamicTradeDecision decision) {
		if (result == null) {
			return;
		}
		String actionCode = decision == null ? "" : decision.actionCode;
		String code = cleanOrDefault(actionCode, "");
		if (code.length() == 0) {
			return;
		}
		result.dtmDecisions++;
		if ("DTM_MOVE_STOP_BREAKEVEN".equals(code)) {
			result.dtmBreakevenMoves++;
		} else if ("DTM_PARTIAL_TARGET".equals(code) || "DTM_PARTIAL_HALF_RUNNER_EXTENDED".equals(code) || "DTM_PARTIAL_BLOCKED".equals(code)) {
			result.dtmPartialActions++;
			if (("DTM_PARTIAL_TARGET".equals(code) || "DTM_PARTIAL_HALF_RUNNER_EXTENDED".equals(code)) && decision != null && decision.targetPrice > 0.0 && decision.stopPrice > 0.0) {
				result.dtmTargetExtensions++;
			}
		} else if ("DTM_TRAIL_STOP".equals(code)) {
			result.dtmTrailActions++;
		} else if ("DTM_CUT_EARLY_THESIS_FAILED".equals(code)) {
			result.dtmEarlyCuts++;
		} else if ("DTM_EXTEND_TARGET_CONTINUATION".equals(code)) {
			result.dtmTargetExtensions++;
		} else if ("DTM_EXTEND_ONE_CONTRACT_RUNNER".equals(code)) {
			result.dtmOneContractExtensions++;
		}
	}

	private static FuturesTrade buildPortfolioTrade(
		PortfolioPosition position,
		PortfolioSymbolContext context,
		Bar bar,
		int exitIndex,
		double rawExitPrice,
		String exitReason
		) {
			double exitPrice = applySlippage(position.spec, rawExitPrice, position.side, context.config.slippageTicks, false);
			double grossPnl = pnlForPrice(position.spec, position.side, position.entryPrice, exitPrice, position.contracts);
			double commissions = roundTripCommission(position);
			double finalLegPnl = round(grossPnl - commissions);
			double dtmRealizedPnl = round(position.dtmRealizedPnl);

			FuturesTrade trade = new FuturesTrade();
			trade.symbol = position.symbol;
			trade.strategyCode = position.signal.strategyCode;
			trade.strategyName = position.signal.strategyName;
			trade.sourceStrategyCode = cleanOrDefault(position.signal.sourceStrategyCode, "");
			trade.sourceStrategyName = cleanOrDefault(position.signal.sourceStrategyName, "");
			trade.side = position.side;
			trade.contracts = position.contracts;
			trade.originalContracts = position.originalContracts <= 0 ? position.contracts + position.dtmPartialContractsClosed : position.originalContracts;
			trade.entryPrice = roundToTick(position.spec, position.entryPrice);
			trade.exitPrice = roundToTick(position.spec, exitPrice);
		trade.stopPrice = roundToTick(position.spec, position.stopPrice);
			trade.targetPrice = roundToTick(position.spec, position.targetPrice);
			trade.openedAt = position.openedAt;
			trade.closedAt = bar.displayTime;
			trade.finalLegPnl = finalLegPnl;
			trade.dtmRealizedPnl = dtmRealizedPnl;
			trade.dtmPartialContractsClosed = position.dtmPartialContractsClosed;
			trade.pnl = round(finalLegPnl + dtmRealizedPnl);
			trade.mfe = round(position.maxFavorable);
		trade.mae = round(position.maxAdverse);
		trade.exitReason = exitReason;
		trade.dtmTimelineJson = position.dtmTimelineJson;
		trade.dtmFinalAction = position.dtmFinalAction;
		trade.dtmPartialDecision = position.dtmPartialDecision;
		trade.dtmRunnerDecision = position.dtmRunnerDecision;
		trade.entryIndex = position.entryIndex;
		trade.exitIndex = exitIndex;
		trade.openedMarketTime = position.openedMarketTime;
		trade.closedMarketTime = bar.marketTime;
		String dtmNote = position.dtmEvaluationCount <= 0
			? ""
			: ", DTM evals " + position.dtmEvaluationCount
				+ ", DTM L2 available " + position.dtmOrderFlowAvailableCount
					+ ", DTM decisions " + position.dtmDecisionCount
					+ ", DTM final action " + cleanOrDefault(position.dtmFinalAction, "DTM_NO_OVERRIDE");
			String dtmPnlNote = position.dtmPartialContractsClosed <= 0 && Math.abs(position.dtmRealizedPnl) <= 0.0
				? ""
				: ", DTM partial contracts " + position.dtmPartialContractsClosed
					+ ", DTM realized PnL $" + round(dtmRealizedPnl)
					+ ", final leg PnL $" + round(finalLegPnl);
			trade.notes = position.signal.notes
				+ " Portfolio event-driven entry; concurrent positions " + position.concurrentPositionsAtEntry
				+ ", concurrent contracts " + position.concurrentContractsAtEntry
				+ ", entered next bar open"
				+ dtmNote
				+ dtmPnlNote
				+ ", risk/contract $" + round(position.riskPerContract)
			+ ", MAE sizing multiplier " + round(context.config.strategySettings.openMaeRiskMultiplier)
			+ ", commission $" + round(commissions)
			+ ", MFE $" + trade.mfe
			+ ", MAE $" + trade.mae
			+ ".";
		return trade;
	}

	private static BacktestResult runBacktest(BacktestConfig config) {
		InstrumentSpec spec = instrumentFor(config.symbol);
		DataBundle bundle = loadBars(config.symbol, config.startDate, config.endDate);
		if (bundle.bars.isEmpty()) {
			return null;
		}
		DataBundle fifteenMinuteBundle = loadNativeFuturesBars(config.symbol, config.startDate, config.endDate, "15min");
		DataBundle oneHourBundle = loadNativeFuturesBars(config.symbol, config.startDate, config.endDate, "1hour");

		Map<LocalDate, List<Bar>> byDay = groupByDay(bundle.bars);
		Map<LocalDate, List<Bar>> fifteenMinuteByDay = groupByDay(fifteenMinuteBundle.bars);
		Map<LocalDate, List<Bar>> oneHourByDay = groupByDay(oneHourBundle.bars);
		List<LocalDate> days = new ArrayList<LocalDate>(byDay.keySet());
		Collections.sort(days);

		BacktestResult result = new BacktestResult();
		result.symbol = spec.symbol;
		result.contractName = spec.name;
		result.startDate = days.isEmpty() ? config.startDate.toString() : days.get(0).toString();
		result.endDate = days.isEmpty() ? config.endDate.toString() : days.get(days.size() - 1).toString();
		result.startingBalance = round(config.accountSize);
		result.dataSource = bundle.source;

		double balance = config.accountSize;
		double peakBalance = balance;
		double trailingReferenceBalance = balance;
		double trailingThreshold = config.accountSize - config.maxTrailingDrawdown;
		double grossProfit = 0.0;
		double grossLoss = 0.0;
		int winners = 0;
		double maxDrawdownPct = 0.0;
		boolean endOfDayTrailing = usesEndOfDayTrailing(config.trailingDrawdownMode);

		for (int dayIndex = 0; dayIndex < days.size(); dayIndex++) {
			LocalDate day = days.get(dayIndex);
			List<Bar> bars = byDay.get(day);
			if (bars == null || bars.size() < 40) {
				continue;
			}

			double dayStartBalance = balance;
			List<Signal> signals = buildSignals(
				spec,
				bars,
				previousDayBars(byDay, days, dayIndex),
				fifteenMinuteByDay.get(day),
				oneHourByDay.get(day),
				config
			);
			Collections.sort(signals, new Comparator<Signal>() {
				@Override
				public int compare(Signal first, Signal second) {
					return bars.get(first.entryIndex).marketTime.compareTo(bars.get(second.entryIndex).marketTime);
				}
			});

			Map<String, Integer> takenByStrategy = new HashMap<String, Integer>();
			int flatAfterIndex = -1;
			for (int signalIndex = 0; signalIndex < signals.size(); signalIndex++) {
				Signal signal = signals.get(signalIndex);
				if (signal.entryIndex <= flatAfterIndex) {
					continue;
				}
				if (balance - dayStartBalance <= -Math.abs(config.dailyLossLimit)) {
					break;
				}
				if (balance <= trailingThreshold) {
					result.ruleViolation = true;
					result.ruleMessage = "Trailing drawdown threshold breached.";
					break;
				}
				if (config.profitTarget > 0.0 && balance - config.accountSize >= config.profitTarget) {
					result.ruleMessage = "Profit target reached.";
					break;
				}

				String strategyKey = dailyLimitStrategyCode(signal.strategyCode);
				int taken = countFor(takenByStrategy, strategyKey);
				if (taken >= maxTradesPerDay(signal.strategyCode, config.strategySettings)) {
					continue;
				}
				double realizedDayPnl = balance - dayStartBalance;
				double dailyRiskBudget = Math.abs(config.dailyLossLimit) + realizedDayPnl;
				double trailingRiskBudget = balance - trailingThreshold;
				double availableRiskBudget = Math.min(config.maxRiskPerTrade, Math.min(dailyRiskBudget, trailingRiskBudget));
				if (availableRiskBudget <= 0.0) {
					continue;
				}
				FuturesTrade trade = simulateTrade(spec, bars, signal, config, availableRiskBudget, Math.min(dailyRiskBudget, trailingRiskBudget));
				if (trade == null) {
					continue;
				}
				double entryCost = (config.commissionPerContract * trade.contracts) + (config.slippageTicks * spec.tickValue * trade.contracts);
				double worstOpenPnl = trade.mae - entryCost;
				if ((balance - dayStartBalance) + worstOpenPnl <= -Math.abs(config.dailyLossLimit)) {
					result.ruleViolation = true;
					result.ruleMessage = "Intraday daily loss limit breached before exit.";
				}
				if (balance + worstOpenPnl <= trailingThreshold) {
					result.ruleViolation = true;
					result.ruleMessage = "Trailing drawdown threshold breached intratrade.";
				}

				balance = round(balance + trade.pnl);
				if (trade.pnl >= 0.0) {
					winners++;
					grossProfit = round(grossProfit + trade.pnl);
				} else {
					grossLoss = round(grossLoss + Math.abs(trade.pnl));
				}
				peakBalance = Math.max(peakBalance, balance);
				if (!endOfDayTrailing) {
					trailingThreshold = Math.max(trailingThreshold, peakBalance - config.maxTrailingDrawdown);
				}
				double drawdownPct = peakBalance <= 0.0 ? 0.0 : ((peakBalance - balance) / peakBalance) * 100.0;
				maxDrawdownPct = Math.max(maxDrawdownPct, drawdownPct);
				result.tradeRecords.add(trade);
				takenByStrategy.put(strategyKey, taken + 1);
				flatAfterIndex = Math.max(flatAfterIndex, trade.exitIndex);
			}

			if (result.ruleViolation || "Profit target reached.".equals(result.ruleMessage)) {
				break;
			}
			if (endOfDayTrailing) {
				trailingReferenceBalance = Math.max(trailingReferenceBalance, balance);
				trailingThreshold = endOfDayTrailingThreshold(trailingThreshold, trailingReferenceBalance, config.accountSize, config.maxTrailingDrawdown);
			}
		}

		result.endingBalance = round(balance);
		result.totalProfit = round(balance - config.accountSize);
		result.returnPct = config.accountSize <= 0.0 ? 0.0 : round((result.totalProfit / config.accountSize) * 100.0);
		result.trades = result.tradeRecords.size();
		result.winRate = result.trades == 0 ? 0.0 : round((winners * 100.0) / result.trades);
		result.profitFactor = grossLoss == 0.0 ? round(grossProfit) : round(grossProfit / grossLoss);
		result.maxDrawdownPct = round(maxDrawdownPct);
		result.trailingThreshold = round(trailingThreshold);
		if (result.ruleMessage == null || result.ruleMessage.trim().isEmpty()) {
			result.ruleMessage = result.ruleViolation ? "Funded rule violation." : "Completed without funded rule breach.";
		}
		return result;
	}

	private static FuturesTrade simulateTrade(InstrumentSpec spec, List<Bar> bars, Signal signal, BacktestConfig config, double riskBudget, double aggregateGuardBudget) {
		int executionIndex = signal.entryIndex + 1;
		if (executionIndex >= bars.size()) {
			return null;
		}

		Bar entryBar = bars.get(executionIndex);
		if (!isLiveEntryWindowTime(entryBar.marketTime)) {
			return null;
		}

		double signalRisk = Math.abs(signal.entryPrice - signal.stopPrice);
		if (signalRisk <= 0.0) {
			return null;
		}

		double rewardMultiple = Math.abs(signal.targetPrice - signal.entryPrice) / signalRisk;
		if (rewardMultiple <= 0.0 || Double.isNaN(rewardMultiple) || Double.isInfinite(rewardMultiple)) {
			rewardMultiple = spec.defaultTargetR;
		}

		double entryPrice = applySlippage(spec, entryBar.open, signal.side, config.slippageTicks, true);
		double stopPrice = roundToTick(spec, signal.stopPrice);
		if ("LONG".equals(signal.side) && entryPrice <= stopPrice) {
			return null;
		}
		if ("SHORT".equals(signal.side) && entryPrice >= stopPrice) {
			return null;
		}

		double initialRisk = Math.abs(entryPrice - stopPrice);
		double rawRiskTicks = initialRisk / spec.tickSize;
		if (rawRiskTicks < 1.0) {
			return null;
		}

		FuturesStrategySettings settings = config.strategySettings == null ? defaultFuturesStrategySettings() : config.strategySettings;
		if (rawRiskTicks > settings.maxInitialRiskTicks) {
			return null;
		}
		rewardMultiple = adaptiveRewardMultiple(spec, bars, signal, executionIndex, rewardMultiple, settings);

		double stopFillForRisk = applySlippage(spec, stopPrice, signal.side, config.slippageTicks, false);
		double riskPerContract = (Math.abs(entryPrice - stopFillForRisk) / spec.tickSize * spec.tickValue) + (config.commissionPerContract * 2.0);
		double sizingRiskPerContract = riskPerContract * settings.openMaeRiskMultiplier;
		double effectiveRiskBudget = Math.max(0.0, Math.min(config.maxRiskPerTrade, riskBudget));
		int maxContracts = strategySpecificMaxContracts(spec.symbol, signal.strategyCode, settings, config.maxContracts);
		int contracts = Math.min(maxContracts, (int) Math.floor(effectiveRiskBudget / Math.max(1.0, riskPerContract)));
		while (contracts > 0 && (sizingRiskPerContract * contracts) > Math.max(0.0, aggregateGuardBudget)) {
			contracts--;
		}
		if (contracts < 1) {
			return null;
		}

		double targetPrice = "LONG".equals(signal.side)
			? roundToTick(spec, entryPrice + (initialRisk * rewardMultiple))
			: roundToTick(spec, entryPrice - (initialRisk * rewardMultiple));
		double activeStopPrice = stopPrice;
		double minTrailDistance = managedTrailDistance(spec, initialRisk, settings);
		int exitIndex = bars.size() - 1;
		double exitPrice = bars.get(exitIndex).close;
		String exitReason = "Session close exit";
		double maxFavorable = 0.0;
		double maxAdverse = 0.0;

		for (int index = executionIndex; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			double favorable = favorablePnl(spec, signal.side, entryPrice, bar, contracts);
			double adverse = adversePnl(spec, signal.side, entryPrice, bar, contracts);
			maxFavorable = Math.max(maxFavorable, favorable);
			maxAdverse = Math.min(maxAdverse, adverse);

			if ("LONG".equals(signal.side)) {
				if (bar.low <= activeStopPrice && bar.high >= targetPrice) {
					exitPrice = activeStopPrice;
					exitIndex = index;
					exitReason = "Stop and target touched; stop assumed first";
					break;
				}
				if (bar.low <= activeStopPrice) {
					exitPrice = activeStopPrice;
					exitIndex = index;
					exitReason = activeStopPrice == stopPrice ? "Stop loss hit" : "Managed stop hit";
					break;
				}
				if (bar.high >= targetPrice) {
					exitPrice = targetPrice;
					exitIndex = index;
					exitReason = "Target reached";
					break;
				}
			} else {
				if (bar.high >= activeStopPrice && bar.low <= targetPrice) {
					exitPrice = activeStopPrice;
					exitIndex = index;
					exitReason = "Stop and target touched; stop assumed first";
					break;
				}
				if (bar.high >= activeStopPrice) {
					exitPrice = activeStopPrice;
					exitIndex = index;
					exitReason = activeStopPrice == stopPrice ? "Stop loss hit" : "Managed stop hit";
					break;
				}
				if (bar.low <= targetPrice) {
					exitPrice = targetPrice;
					exitIndex = index;
					exitReason = "Target reached";
					break;
				}
			}

			double guardCostBuffer = (config.commissionPerContract * contracts * 2.0) + (config.slippageTicks * spec.tickValue * contracts);
			if (aggregateGuardBudget > 0.0 && adverse - guardCostBuffer <= -Math.abs(aggregateGuardBudget)) {
				exitPrice = "LONG".equals(signal.side) ? bar.low : bar.high;
				exitIndex = index;
				exitReason = "Funded guard breach flat exit";
				break;
			}
			if (shouldEarlyLossCut(spec, settings, signal.side, entryPrice, initialRisk, bar, contracts, index - executionIndex)) {
				exitPrice = bar.close;
				exitIndex = index;
				exitReason = "Adaptive loss cut exit";
				break;
			}
			if (shouldManagedGivebackExit(spec, settings, signal.side, entryPrice, initialRisk, maxFavorable, bar, contracts, index - executionIndex)) {
				exitPrice = bar.close;
				exitIndex = index;
				exitReason = "Managed giveback exit";
				break;
			}
			if (!bar.marketTime.isBefore(FORCED_EXIT_TIME)) {
				exitPrice = bar.close;
				exitIndex = index;
				exitReason = "Funded-session flat exit";
				break;
			}
			if (signal.maxHoldBars > 0 && index - executionIndex >= signal.maxHoldBars) {
				exitPrice = bar.close;
				exitIndex = index;
				exitReason = "Time stop exit";
				break;
			}
			activeStopPrice = updateManagedStop(spec, signal.side, entryPrice, activeStopPrice, bar.close, initialRisk, minTrailDistance, settings);
		}

		exitPrice = applySlippage(spec, exitPrice, signal.side, config.slippageTicks, false);
		double grossPnl = pnlForPrice(spec, signal.side, entryPrice, exitPrice, contracts);
		double commissions = config.commissionPerContract * contracts * 2.0;

			FuturesTrade trade = new FuturesTrade();
			trade.symbol = spec.symbol;
			trade.strategyCode = signal.strategyCode;
			trade.strategyName = signal.strategyName;
			trade.sourceStrategyCode = cleanOrDefault(signal.sourceStrategyCode, "");
			trade.sourceStrategyName = cleanOrDefault(signal.sourceStrategyName, "");
			trade.side = signal.side;
			trade.contracts = contracts;
			trade.originalContracts = contracts;
		trade.entryPrice = roundToTick(spec, entryPrice);
		trade.exitPrice = roundToTick(spec, exitPrice);
		trade.stopPrice = roundToTick(spec, stopPrice);
		trade.targetPrice = roundToTick(spec, targetPrice);
		trade.openedAt = bars.get(executionIndex).displayTime;
			trade.closedAt = bars.get(exitIndex).displayTime;
			trade.pnl = round(grossPnl - commissions);
			trade.finalLegPnl = trade.pnl;
			trade.mfe = round(maxFavorable);
		trade.mae = round(maxAdverse);
		trade.exitReason = exitReason;
		trade.entryIndex = executionIndex;
		trade.exitIndex = exitIndex;
		trade.openedMarketTime = bars.get(executionIndex).marketTime;
		trade.closedMarketTime = bars.get(exitIndex).marketTime;
		trade.notes = signal.notes
			+ " Contracts " + contracts
			+ ", signal bar " + bars.get(signal.entryIndex).displayTime
			+ ", entered next bar open"
			+ ", risk/contract $" + round(riskPerContract)
			+ ", MAE sizing risk/contract $" + round(sizingRiskPerContract)
			+ ", risk budget $" + round(effectiveRiskBudget)
			+ ", commission $" + round(commissions)
			+ ", MFE $" + trade.mfe
			+ ", MAE $" + trade.mae
			+ ".";
		return trade;
	}

	private static List<Signal> buildSignals(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> previousBars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		BacktestConfig config
	) {
		return buildSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, config, null);
	}

	private static List<Signal> buildSignals(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> previousBars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		BacktestConfig config,
		Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> orderFlowByDayTime
	) {
		List<Signal> signals = new ArrayList<Signal>();
		FuturesStrategySettings settings = config.strategySettings == null ? defaultFuturesStrategySettings() : config.strategySettings;
			if (settings.orb.enabled) {
				Signal signal = findOrbSignal(spec, bars, fifteenMinuteBars, oneHourBars, settings);
			if (signal != null) {
				signals.add(signal);
			}
			if (settings.enableOrbRetest) {
				signals.addAll(findOrbRetestSignals(spec, bars, settings));
			}
		}
		if (settings.lateOrbContinuation.enabled) {
			signals.addAll(findLateOrbContinuationSignals(spec, bars, settings));
		}
		if (settings.orbEventPack.enabled) {
			signals.addAll(findOrbEventPackSignals(spec, bars, settings, signals));
		}
		if (settings.openingMomentum.enabled) {
			signals.addAll(findOpeningMomentumSignals(spec, bars, settings));
		}
		if (settings.vwapPullback.enabled) {
			signals.addAll(findVwapPullbackSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.vwapReclaim.enabled) {
			signals.addAll(findVwapReclaimSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.afternoonContinuation.enabled) {
			signals.addAll(findAfternoonContinuationSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.marketIntradayMomentum.enabled) {
			signals.addAll(findMarketIntradayMomentumSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.keltnerScalp.enabled) {
			signals.addAll(findKeltnerScalpSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.keltnerReversion.enabled) {
			signals.addAll(findKeltnerReversionSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.microScalp.enabled) {
			signals.addAll(findMicroScalpSignals(spec, bars, settings));
		}
		if (settings.trendLadder.enabled) {
			signals.addAll(findTrendLadderSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.rangeCompressionBreakout.enabled) {
			signals.addAll(findRangeCompressionBreakoutSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
			if (settings.rangeMidpointContinuation.enabled) {
				signals.addAll(findRangeMidpointContinuationSignals(spec, bars, fifteenMinuteBars, settings, orderFlowByDayTime));
			}
			if (settings.bosRetest.enabled) {
				signals.addAll(findBosRetestSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
			}
			if (settings.valueAreaReclaim.enabled) {
				signals.addAll(findValueAreaReclaimSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings));
			}
		if (settings.vwapMeanReversion.enabled) {
			signals.addAll(findMeanReversionSignals(spec, bars, settings));
		}
		if (settings.sweep.enabled) {
			signals.addAll(findSweepSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.priorDayBreakout.enabled) {
			signals.addAll(findPriorDayBreakoutSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.fvg.enabled) {
			signals.addAll(findFvgSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.ifvg.enabled) {
			signals.addAll(findIfvgSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.closeMomentum.enabled) {
			signals.addAll(findCloseMomentumSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.mclEiaContinuation.enabled) {
			signals.addAll(findMclEiaContinuationSignals(spec, bars, settings));
		}
		if (settings.mclCrudeSessionOpen.enabled) {
			signals.addAll(findMclCrudeSessionOpenSignals(spec, bars, settings));
		}
		if (settings.mymIndexConfirmation.enabled) {
			signals.addAll(findMymIndexConfirmationSignals(spec, bars, settings));
		}
		if (settings.mymOrbRetest.enabled) {
			signals.addAll(findMymOrbRetestSignals(spec, bars, settings));
		}
		if (settings.mclTrendContinuation.enabled) {
			signals.addAll(findMclTrendContinuationSignals(spec, bars, settings));
		}
		if (settings.volumePriceManipulation.enabled) {
			signals.addAll(findVolumePriceManipulationSignals(spec, bars, fifteenMinuteBars, oneHourBars, settings));
		}
		if (settings.liquidityReclaim.enabled) {
			signals.addAll(findLiquidityReclaimSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings, signals));
		}
		if (settings.requireMultiTimeframeStack) {
			signals = filterMultiTimeframeStackSignals(signals, settings, spec, bars, fifteenMinuteBars, oneHourBars);
		}
		return signals;
	}

	private static boolean isInstrumentSymbol(InstrumentSpec spec, String symbol) {
		return spec != null && cleanOrDefault(spec.symbol, "").equalsIgnoreCase(symbol);
	}

	private static boolean isLiquidityReclaimSourceSymbol(String symbol) {
		String normalized = normalizeSymbol(symbol);
		return "MES".equals(normalized)
			|| "MNQ".equals(normalized)
			|| "NQ".equals(normalized)
			|| "MGC".equals(normalized)
			|| "ES".equals(normalized)
			|| "M2K".equals(normalized)
			|| "MYM".equals(normalized)
			|| "MCL".equals(normalized);
	}

	private static FuturesStrategySettings liquidityReclaimSource2268Settings(String symbol, FuturesStrategySettings fallback) {
		ensureLiquidityReclaimSource2268SettingsLoaded();
		FuturesStrategySettings source = LIQREC_SOURCE_2268_SETTINGS.get(normalizeSymbol(symbol));
		return source == null ? (fallback == null ? defaultFuturesStrategySettings() : fallback) : source;
	}

	private static synchronized void ensureLiquidityReclaimSource2268SettingsLoaded() {
		if (liqrecSource2268SettingsLoaded) {
			return;
		}
		Properties props = new Properties();
		try (InputStream input = FuturesManager.class.getClassLoader().getResourceAsStream(LIQREC_SOURCE_2268_RESOURCE)) {
			if (input != null) {
				props.load(input);
			}
		} catch (IOException e) {
			e.printStackTrace();
		}
		for (String symbol : supportedInstrumentSymbols()) {
			String normalized = normalizeSymbol(symbol);
			String prefix = normalized + ".";
			FuturesStrategySettings settings = defaultFuturesStrategySettings();
			boolean found = false;
			for (String key : props.stringPropertyNames()) {
				if (!key.startsWith(prefix)) {
					continue;
				}
				found = true;
				applyFuturesSetting(settings, key.substring(prefix.length()), props.getProperty(key));
			}
			if (found) {
				clampFuturesStrategySettings(settings);
				LIQREC_SOURCE_2268_SETTINGS.put(normalized, settings);
			}
		}
		liqrecSource2268SettingsLoaded = true;
	}

	private static boolean liquidityReclaimOwnsComponent(String symbol, String strategyCode) {
		String normalized = normalizeSymbol(symbol);
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		if ("AFT".equals(code)) {
			return "MCL".equals(normalized) || "MES".equals(normalized) || "MNQ".equals(normalized);
		}
		if ("MES".equals(normalized)) {
			return "SHDW".equals(code);
		}
		if ("MNQ".equals(normalized) || "NQ".equals(normalized)) {
			return "FVG".equals(code) || "KREV".equals(code) || "PDB".equals(code) || "SWEEP".equals(code) || "VWAP".equals(code);
		}
		if ("MGC".equals(normalized)) {
			return "KREV".equals(code) || "PDB".equals(code) || "SWEEP".equals(code) || "VWAP".equals(code);
		}
		if ("ES".equals(normalized)) {
			return "SWEEP".equals(code) || "VWAP".equals(code);
		}
		if ("M2K".equals(normalized)) {
			return "VPB".equals(code);
		}
		if ("MYM".equals(normalized)) {
			return "SHDW".equals(code) || "SWEEP".equals(code);
		}
		if ("MCL".equals(normalized)) {
			return "PDB".equals(code);
		}
		return false;
	}

	private static void relabelLiquidityReclaimSignal(Signal signal) {
		if (signal == null) {
			return;
		}
		String sourceCode = cleanOrDefault(signal.strategyCode, "");
		String sourceName = cleanOrDefault(signal.strategyName, sourceCode);
		withSourceStrategy(signal, sourceCode, sourceName);
		signal.strategyCode = "LIQREC";
		signal.strategyName = "Liquidity Reclaim";
		signal.notes = "Liquidity Reclaim: " + sourceName + " structure passed as part of the accepted reclaim source stack. " + cleanOrDefault(signal.notes, "");
	}

	private static List<Signal> findLiquidityReclaimSignals(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> previousBars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		FuturesStrategySettings settings,
		List<Signal> existingSignals
	) {
		List<Signal> signals = new ArrayList<Signal>();
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		if (!safe.liquidityReclaim.enabled || spec == null || !isLiquidityReclaimSourceSymbol(spec.symbol)) {
			return signals;
		}
		String symbol = normalizeSymbol(spec.symbol);
		FuturesStrategySettings sourceSettings = liquidityReclaimSource2268Settings(symbol, safe);
		List<Signal> candidates = new ArrayList<Signal>();
		if (liquidityReclaimOwnsComponent(symbol, "AFT")) {
			candidates.addAll(findAfternoonContinuationSignals(spec, bars, fifteenMinuteBars, oneHourBars, sourceSettings));
		}
		if ("MNQ".equals(symbol) || "NQ".equals(symbol)) {
			candidates.addAll(findFvgSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findKeltnerReversionSignals(spec, bars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findPriorDayBreakoutSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findSweepSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findVwapPullbackSignals(spec, bars, fifteenMinuteBars, oneHourBars, sourceSettings));
		} else if ("MGC".equals(symbol)) {
			candidates.addAll(findKeltnerReversionSignals(spec, bars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findPriorDayBreakoutSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findSweepSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findVwapPullbackSignals(spec, bars, fifteenMinuteBars, oneHourBars, sourceSettings));
		} else if ("ES".equals(symbol)) {
			candidates.addAll(findVwapPullbackSignals(spec, bars, fifteenMinuteBars, oneHourBars, sourceSettings));
			candidates.addAll(findSweepSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
		} else if ("M2K".equals(symbol)) {
			candidates.addAll(findValueAreaReclaimSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
		} else if ("MYM".equals(symbol)) {
			candidates.addAll(findSweepSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
		} else if ("MCL".equals(symbol)) {
			candidates.addAll(findPriorDayBreakoutSignals(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, sourceSettings));
		}
		for (int index = 0; index < candidates.size(); index++) {
			Signal candidate = candidates.get(index);
			if (candidate == null || !liquidityReclaimOwnsComponent(symbol, candidate.strategyCode)) {
				continue;
			}
			if (!sourceStrategyAllowed(candidate.strategyCode, safe.liquidityReclaimSourceCodes)) {
				continue;
			}
			Bar signalBar = signalBarForIndex(bars, candidate.entryIndex);
			if (signalBar == null || !inMinuteWindow(minuteOfDay(signalBar), safe.liquidityReclaimStartMinute, safe.liquidityReclaimEndMinute)) {
				continue;
			}
			if (!safe.liquidityReclaimAllowDuplicates && sameSignalGeometryExists(existingSignals, candidate)) {
				continue;
			}
			relabelLiquidityReclaimSignal(candidate);
			signals.add(candidate);
		}
		return limitSignalsByDailyCount(signals, safe.liquidityReclaim.maxTradesPerDay);
	}

	private static Bar signalBarForIndex(List<Bar> bars, int index) {
		if (bars == null || index < 0 || index >= bars.size()) {
			return null;
		}
		return bars.get(index);
	}

	private static boolean sameSignalGeometryExists(List<Signal> signals, Signal candidate) {
		if (signals == null || candidate == null) {
			return false;
		}
		for (int index = 0; index < signals.size(); index++) {
			Signal existing = signals.get(index);
			if (existing == null) {
				continue;
			}
			if (existing.entryIndex == candidate.entryIndex
				&& cleanOrDefault(existing.side, "").equals(cleanOrDefault(candidate.side, ""))
				&& Math.abs(existing.entryPrice - candidate.entryPrice) < 0.000001
				&& Math.abs(existing.stopPrice - candidate.stopPrice) < 0.000001
				&& Math.abs(existing.targetPrice - candidate.targetPrice) < 0.000001) {
				return true;
			}
		}
		return false;
	}

	private static class StructureSwing {
		private boolean high;
		private int index;
		private double price;
		private int strength;
	}

	private static class StructureSetup {
		private String side;
		private int breakIndex;
		private int retestIndex;
		private int confirmationIndex;
		private double brokenLevel;
		private double entry;
		private double stop;
		private double target;
		private double rewardRisk;
		private double displacementScore;
		private String retestZone;
	}

	private static List<Signal> findBosRetestSignals(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		FuturesStrategySettings settings
	) {
		List<Signal> signals = new ArrayList<Signal>();
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		if (spec == null || bars == null || bars.size() < 80) {
			return signals;
		}
		List<StructureSetup> setups = classifyBosRetestSetups(spec, bars, fifteenMinuteBars, oneHourBars, safe);
		for (int index = 0; index < setups.size(); index++) {
			StructureSetup setup = setups.get(index);
			signals.add(signal(
				"BOSRT",
				"BOS Retest",
				setup.side,
				setup.confirmationIndex,
				setup.entry,
				setup.stop,
				setup.target,
				safe.bosRetestMaxHoldBars,
				bosRetestNotes(setup)
			));
		}
		return limitSignalsByDailyCount(dedupeByHour(signals, safe.bosRetest.maxTradesPerDay), safe.bosRetest.maxTradesPerDay);
	}

	private static List<StructureSetup> classifyBosRetestSetups(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		FuturesStrategySettings settings
	) {
		List<StructureSetup> setups = new ArrayList<StructureSetup>();
		double tick = Math.max(0.000001, spec.tickSize);
		int lookback = Math.max(12, settings.bosRetestSwingLookbackBars);
		int pivotBars = Math.max(1, settings.bosRetestPivotBars);
		int startIndex = Math.max(lookback + pivotBars + 1, 30);
		for (int breakIndex = startIndex; breakIndex < bars.size() - 2; breakIndex++) {
			Bar breakBar = bars.get(breakIndex);
			if (breakBar == null || breakBar.marketTime == null) {
				continue;
			}
			int minute = minuteOfDay(breakBar);
			if (!inMinuteWindow(minute, settings.bosRetestStartMinute, settings.bosRetestEndMinute)) {
				continue;
			}
			double displacementScore = bosRetestDisplacementScore(bars, breakIndex, settings);
			if (displacementScore <= 0.0) {
				continue;
			}
			if (settings.allowBosRetestLongs) {
				StructureSwing swingHigh = latestConfirmedStructureSwing(bars, breakIndex - 1, lookback, pivotBars, true);
				if (swingHigh != null && breakBar.close > swingHigh.price + (settings.bosRetestMinBreakTicks * tick) && closeLocation(breakBar) >= 0.58) {
					StructureSetup setup = buildBosRetestSetup("LONG", spec, bars, fifteenMinuteBars, oneHourBars, settings, swingHigh, breakIndex, displacementScore);
					if (setup != null) {
						setups.add(setup);
					}
				}
			}
			if (settings.allowShorts && settings.allowBosRetestShorts) {
				StructureSwing swingLow = latestConfirmedStructureSwing(bars, breakIndex - 1, lookback, pivotBars, false);
				if (swingLow != null && breakBar.close < swingLow.price - (settings.bosRetestMinBreakTicks * tick) && closeLocation(breakBar) <= 0.42) {
					StructureSetup setup = buildBosRetestSetup("SHORT", spec, bars, fifteenMinuteBars, oneHourBars, settings, swingLow, breakIndex, displacementScore);
					if (setup != null) {
						setups.add(setup);
					}
				}
			}
		}
		return setups;
	}

	private static StructureSetup buildBosRetestSetup(
		String side,
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		FuturesStrategySettings settings,
		StructureSwing brokenSwing,
		int breakIndex,
		double displacementScore
	) {
		boolean longSide = "LONG".equals(side);
		Bar breakBar = bars.get(breakIndex);
		if (settings.bosRetestRequireHigherTimeframeAlignment) {
			boolean htfAligned = longSide
				? higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, breakBar.marketTime)
				: higherTimeframeBearish(fifteenMinuteBars, oneHourBars, breakBar.marketTime);
			if (!htfAligned) {
				return null;
			}
		}
		int retestIndex = bosRetestRetestIndex(bars, settings, brokenSwing.price, breakIndex, longSide, spec.tickSize);
		if (retestIndex < 0) {
			return null;
		}
		int confirmationIndex = bosRetestConfirmationIndex(bars, settings, brokenSwing.price, retestIndex, longSide);
		if (confirmationIndex < 0) {
			return null;
		}
		Bar confirmation = bars.get(confirmationIndex);
		double tick = Math.max(0.000001, spec.tickSize);
		double invalidation = longSide
			? lowestLowBetween(bars, retestIndex, confirmationIndex)
			: highestHighBetween(bars, retestIndex, confirmationIndex);
		double stop = longSide
			? invalidation - (settings.bosRetestInvalidationBufferTicks * tick)
			: invalidation + (settings.bosRetestInvalidationBufferTicks * tick);
		stop = roundToTick(spec, stop);
		double risk = longSide ? confirmation.close - stop : stop - confirmation.close;
		if (risk <= 0.0 || riskTicks(spec, confirmation.close, stop) > settings.bosRetestMaxRiskTicks) {
			return null;
		}
		double target = bosRetestStructureTarget(spec, bars, settings, confirmationIndex, brokenSwing.price, longSide);
		double reward = longSide ? target - confirmation.close : confirmation.close - target;
		double rewardRisk = reward / risk;
		if (target <= 0.0 || rewardRisk < settings.bosRetestMinRewardRisk) {
			return null;
		}
		StructureSetup setup = new StructureSetup();
		setup.side = side;
		setup.breakIndex = breakIndex;
		setup.retestIndex = retestIndex;
		setup.confirmationIndex = confirmationIndex;
		setup.brokenLevel = brokenSwing.price;
		setup.entry = confirmation.close;
		setup.stop = stop;
		setup.target = roundToTick(spec, target);
		setup.rewardRisk = rewardRisk;
		setup.displacementScore = displacementScore;
		setup.retestZone = "BROKEN_SWING";
		return setup;
	}

	private static int bosRetestRetestIndex(List<Bar> bars, FuturesStrategySettings settings, double level, int breakIndex, boolean longSide, double tickSize) {
		double buffer = Math.max(0.0, settings.bosRetestRetestBufferTicks) * Math.max(0.000001, tickSize);
		int end = Math.min(bars.size() - 1, breakIndex + Math.max(1, settings.bosRetestRetestBars));
		for (int index = breakIndex + 1; index <= end; index++) {
			Bar bar = bars.get(index);
			if (longSide) {
				if (bar.close < level - buffer) {
					return -1;
				}
				if (bar.low <= level + buffer && bar.close >= level - buffer) {
					return index;
				}
			} else {
				if (bar.close > level + buffer) {
					return -1;
				}
				if (bar.high >= level - buffer && bar.close <= level + buffer) {
					return index;
				}
			}
		}
		return -1;
	}

	private static int bosRetestConfirmationIndex(List<Bar> bars, FuturesStrategySettings settings, double level, int retestIndex, boolean longSide) {
		Bar retest = bars.get(retestIndex);
		int end = Math.min(bars.size() - 1, retestIndex + Math.max(1, settings.bosRetestConfirmationBars));
		for (int index = retestIndex + 1; index <= end; index++) {
			Bar bar = bars.get(index);
			if (longSide) {
				if (bar.close > bar.open && bar.close > level && bar.close > retest.close && closeLocation(bar) >= 0.58) {
					return index;
				}
			} else if (bar.close < bar.open && bar.close < level && bar.close < retest.close && closeLocation(bar) <= 0.42) {
				return index;
			}
		}
		return -1;
	}

	private static double bosRetestStructureTarget(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int entryIndex, double brokenLevel, boolean longSide) {
		int start = Math.max(0, entryIndex - Math.max(10, settings.bosRetestTargetLookbackBars));
		int end = Math.max(0, entryIndex - 1);
		double tick = Math.max(0.000001, spec.tickSize);
		double target = 0.0;
		for (int index = start; index <= end; index++) {
			Bar bar = bars.get(index);
			if (longSide && bar.high > brokenLevel + (settings.bosRetestMinBreakTicks * tick)) {
				target = Math.max(target, bar.high);
			} else if (!longSide && bar.low < brokenLevel - (settings.bosRetestMinBreakTicks * tick)) {
				target = target <= 0.0 ? bar.low : Math.min(target, bar.low);
			}
		}
		return target;
	}

	private static StructureSwing latestConfirmedStructureSwing(List<Bar> bars, int endIndex, int lookbackBars, int pivotBars, boolean highSwing) {
		if (bars == null || bars.isEmpty()) {
			return null;
		}
		int end = Math.min(endIndex - pivotBars, bars.size() - 1 - pivotBars);
		int start = Math.max(pivotBars, endIndex - Math.max(1, lookbackBars));
		for (int index = end; index >= start; index--) {
			if (isConfirmedStructureSwing(bars, index, pivotBars, highSwing)) {
				StructureSwing swing = new StructureSwing();
				swing.high = highSwing;
				swing.index = index;
				swing.price = highSwing ? bars.get(index).high : bars.get(index).low;
				swing.strength = pivotBars;
				return swing;
			}
		}
		return null;
	}

	private static boolean isConfirmedStructureSwing(List<Bar> bars, int index, int pivotBars, boolean highSwing) {
		Bar candidate = bars.get(index);
		double price = highSwing ? candidate.high : candidate.low;
		for (int offset = 1; offset <= pivotBars; offset++) {
			Bar left = bars.get(index - offset);
			Bar right = bars.get(index + offset);
			if (highSwing) {
				if (left.high >= price || right.high >= price) {
					return false;
				}
			} else if (left.low <= price || right.low <= price) {
				return false;
			}
		}
		return true;
	}

	private static double bosRetestDisplacementScore(List<Bar> bars, int index, FuturesStrategySettings settings) {
		Bar bar = bars.get(index);
		double bodyPct = bar.bodyPct > 0.0 ? bar.bodyPct : defaultBodyPct(bar);
		if (bodyPct < settings.bosRetestMinDisplacementBodyPct) {
			return 0.0;
		}
		double averageRangeTicks = averageRangeTicks(bars, index, 20);
		if (averageRangeTicks <= 0.0) {
			return 0.0;
		}
		double rangeRatio = bar.rangeTicks / averageRangeTicks;
		if (rangeRatio < settings.bosRetestMinDisplacementRangeRatio) {
			return 0.0;
		}
		return rangeRatio * (bodyPct / 100.0) * Math.max(0.5, volumeRatio(bar));
	}

	private static double averageRangeTicks(List<Bar> bars, int index, int period) {
		int start = Math.max(0, index - Math.max(1, period));
		int end = Math.max(start, index - 1);
		double total = 0.0;
		int count = 0;
		for (int cursor = start; cursor <= end; cursor++) {
			Bar bar = bars.get(cursor);
			total += bar.rangeTicks;
			count++;
		}
		return count == 0 ? 0.0 : total / count;
	}

	private static String bosRetestNotes(StructureSetup setup) {
		return "BOS retest " + cleanOrDefault(setup.side, "").toLowerCase(Locale.US)
			+ ": broke level " + round(setup.brokenLevel)
			+ ", retest zone " + cleanOrDefault(setup.retestZone, "BROKEN_SWING")
			+ ", break index " + setup.breakIndex
			+ ", retest index " + setup.retestIndex
			+ ", confirmation index " + setup.confirmationIndex
			+ ", displacement score " + round(setup.displacementScore)
			+ ", RR " + round(setup.rewardRisk)
			+ ".";
	}

	private static List<Signal> findRangeMidpointContinuationSignals(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> fifteenMinuteBars,
		FuturesStrategySettings settings,
		Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> orderFlowByDayTime
	) {
		List<Signal> signals = new ArrayList<Signal>();
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		if (spec == null || bars == null || bars.size() < 80) {
			return signals;
		}
		int impulseBars = Math.max(12, safe.rangeMidpointImpulseBars);
		int pullbackBars = Math.max(3, safe.rangeMidpointPullbackBars);
		int startIndex = Math.max(impulseBars + pullbackBars + 2, 30);
		double tick = Math.max(0.000001, spec.tickSize);
		for (int index = startIndex; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketDate == null || bar.marketTime == null) {
				continue;
			}
			int minute = minuteOfDay(bar);
			if (!inMinuteWindow(minute, safe.rangeMidpointStartMinute, safe.rangeMidpointEndMinute)) {
				continue;
			}
			if (bar.bodyPct < safe.rangeMidpointMinBodyPct || volumeRatio(bar) < safe.rangeMidpointMinVolumeRatio) {
				continue;
			}
			double impulseHigh = recentSwingHigh(bars, index - 1, impulseBars + pullbackBars);
			double impulseLow = recentSwingLow(bars, index - 1, impulseBars + pullbackBars);
			double impulseTicks = (impulseHigh - impulseLow) / tick;
			if (impulseTicks < safe.rangeMidpointMinImpulseTicks) {
				continue;
			}
			double midpoint = (impulseHigh + impulseLow) / 2.0;
			double midpointBuffer = Math.max(0.0, safe.rangeMidpointMidpointBufferTicks) * tick;
			double impulseRange = Math.max(tick, impulseHigh - impulseLow);
			double closeLocation = closeLocation(bar);
			int impulseLowIndex = recentSwingLowIndex(bars, index - 1, impulseBars + pullbackBars);
			int impulseHighIndex = recentSwingHighIndex(bars, index - 1, impulseBars + pullbackBars);
			double pullbackHigh = impulseLowIndex >= 0 && impulseLowIndex + 1 <= index - 1
				? highestHighBetween(bars, impulseLowIndex + 1, index - 1)
				: recentSwingHigh(bars, index - 1, pullbackBars);
			double pullbackLow = impulseHighIndex >= 0 && impulseHighIndex + 1 <= index - 1
				? lowestLowBetween(bars, impulseHighIndex + 1, index - 1)
				: recentSwingLow(bars, index - 1, pullbackBars);
			LiveRuntimeState.OrderFlowSnapshot flow = orderFlowSnapshotAt(orderFlowByDayTime, bar.marketDate, bar.marketTime);
			if (safe.allowRangeMidpointShorts && safe.allowShorts && bar.close < bar.open) {
				double retracePct = impulseHigh <= impulseLow ? 0.0 : (pullbackHigh - impulseLow) / (impulseHigh - impulseLow);
				double closeExtensionPct = Math.max(0.0, midpoint - bar.close) / impulseRange;
				double pullbackVolumeRatio = rmcPullbackVolumeRatio(bars, impulseLowIndex, index - 1, impulseBars);
				boolean midpointRejected = pullbackHigh >= midpoint - midpointBuffer
					&& bar.high >= midpoint - midpointBuffer
					&& bar.close < midpoint + midpointBuffer
					&& closeExtensionPct <= safe.rangeMidpointMaxCloseExtensionPct
					&& pullbackVolumeRatio <= safe.rangeMidpointMaxPullbackVolumeRatio
					&& retracePct >= safe.rangeMidpointMinRetracePct
					&& retracePct <= safe.rangeMidpointMaxRetracePct
					&& closeLocation <= 1.0 - safe.rangeMidpointMinCloseLocation;
				if (midpointRejected && rmcHigherTimeframeAligned("SHORT", fifteenMinuteBars, bar.marketTime) && rmcOrderFlowConfirms("SHORT", flow, safe)) {
					double stop = roundToTick(spec, Math.min(Math.max(bar.high, pullbackHigh) + (2.0 * tick), bar.close + (safe.rangeMidpointMaxRiskTicks * tick)));
					double risk = stop - bar.close;
					if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= safe.rangeMidpointMaxRiskTicks) {
						double target = roundToTick(spec, bar.close - (risk * safe.rangeMidpointRewardRisk));
						signals.add(signal("RMC", "Range Midpoint Continuation", "SHORT", index, bar.close, stop, target, safe.rangeMidpointMaxHoldBars, rmcNotes("short", midpoint, impulseTicks, retracePct, flow)));
					}
				}
			}
			if (safe.allowRangeMidpointLongs && bar.close > bar.open) {
				double retracePct = impulseHigh <= impulseLow ? 0.0 : (impulseHigh - pullbackLow) / (impulseHigh - impulseLow);
				double closeExtensionPct = Math.max(0.0, bar.close - midpoint) / impulseRange;
				double pullbackVolumeRatio = rmcPullbackVolumeRatio(bars, impulseHighIndex, index - 1, impulseBars);
				boolean midpointRejected = pullbackLow <= midpoint + midpointBuffer
					&& bar.low <= midpoint + midpointBuffer
					&& bar.close > midpoint - midpointBuffer
					&& closeExtensionPct <= safe.rangeMidpointMaxCloseExtensionPct
					&& pullbackVolumeRatio <= safe.rangeMidpointMaxPullbackVolumeRatio
					&& retracePct >= safe.rangeMidpointMinRetracePct
					&& retracePct <= safe.rangeMidpointMaxRetracePct
					&& closeLocation >= safe.rangeMidpointMinCloseLocation;
				if (midpointRejected && rmcHigherTimeframeAligned("LONG", fifteenMinuteBars, bar.marketTime) && rmcOrderFlowConfirms("LONG", flow, safe)) {
					double stop = roundToTick(spec, Math.max(Math.min(bar.low, pullbackLow) - (2.0 * tick), bar.close - (safe.rangeMidpointMaxRiskTicks * tick)));
					double risk = bar.close - stop;
					if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= safe.rangeMidpointMaxRiskTicks) {
						double target = roundToTick(spec, bar.close + (risk * safe.rangeMidpointRewardRisk));
						signals.add(signal("RMC", "Range Midpoint Continuation", "LONG", index, bar.close, stop, target, safe.rangeMidpointMaxHoldBars, rmcNotes("long", midpoint, impulseTicks, retracePct, flow)));
					}
				}
			}
		}
		return limitSignalsByDailyCount(dedupeByHour(signals, safe.rangeMidpointContinuation.maxTradesPerDay), safe.rangeMidpointContinuation.maxTradesPerDay);
	}

	private static boolean rmcHigherTimeframeAligned(String side, List<Bar> fifteenMinuteBars, LocalTime entryTime) {
		Bar fifteenMinute = latestClosedBar(fifteenMinuteBars, entryTime, 15);
		if (fifteenMinute == null || fifteenMinute.vwap <= 0.0 || fifteenMinute.ema20 <= 0.0) {
			return true;
		}
		return trendWithPosition(side, fifteenMinute);
	}

	private static LiveRuntimeState.OrderFlowSnapshot orderFlowSnapshotAt(Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> orderFlowByDayTime, LocalDate day, LocalTime time) {
		if (orderFlowByDayTime == null || day == null || time == null) {
			return null;
		}
		Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot> byTime = orderFlowByDayTime.get(day);
		if (byTime == null || byTime.isEmpty()) {
			return null;
		}
		LiveRuntimeState.OrderFlowSnapshot exact = byTime.get(time.withSecond(0).withNano(0));
		if (exact != null) {
			return exact;
		}
		for (int offset = 1; offset <= 2; offset++) {
			LiveRuntimeState.OrderFlowSnapshot before = byTime.get(time.minusMinutes(offset).withSecond(0).withNano(0));
			if (before != null) {
				return before;
			}
		}
		return null;
	}

	private static double rmcPullbackVolumeRatio(List<Bar> bars, int impulseExtremeIndex, int pullbackEndIndex, int impulseBars) {
		if (bars == null || bars.isEmpty() || impulseExtremeIndex < 0 || impulseExtremeIndex >= bars.size()) {
			return 1.0;
		}
		int impulseStart = Math.max(0, impulseExtremeIndex - Math.max(1, impulseBars) + 1);
		double impulseVolume = averageVolumeBetween(bars, impulseStart, impulseExtremeIndex);
		double pullbackVolume = averageVolumeBetween(bars, impulseExtremeIndex + 1, pullbackEndIndex);
		if (impulseVolume <= 0.0 || pullbackVolume <= 0.0) {
			return 1.0;
		}
		return pullbackVolume / impulseVolume;
	}

	private static double averageVolumeBetween(List<Bar> bars, int startIndex, int endIndex) {
		if (bars == null || bars.isEmpty()) {
			return 0.0;
		}
		int start = Math.max(0, startIndex);
		int end = Math.min(endIndex, bars.size() - 1);
		if (start > end) {
			return 0.0;
		}
		double total = 0.0;
		int count = 0;
		for (int index = start; index <= end; index++) {
			Bar bar = bars.get(index);
			if (bar == null) {
				continue;
			}
			total += Math.max(0.0, bar.volume);
			count++;
		}
		return count == 0 ? 0.0 : total / count;
	}

	private static boolean rmcOrderFlowConfirms(String side, LiveRuntimeState.OrderFlowSnapshot flow, FuturesStrategySettings settings) {
		if (flow == null || !flow.available || !flow.fresh) {
			return false;
		}
		if (flow.spreadTicks > 0.0 && flow.spreadTicks > settings.rangeMidpointMaxSpreadTicks) {
			return false;
		}
		if (flow.sourceConfidence > 0.0 && flow.sourceConfidence < settings.rangeMidpointMinOrderFlowConfidence) {
			return false;
		}
		boolean longSide = "LONG".equalsIgnoreCase(side);
		double imbalance = flow.depthImbalance5 != 0.0 ? flow.depthImbalance5 : flow.topBookImbalance;
		double tape = flow.tapeDelta;
		String flip = cleanOrDefault(flow.bookFlip, "").toUpperCase(Locale.US);
		String absorption = cleanOrDefault(flow.absorption, "").toUpperCase(Locale.US);
		String flowState = cleanOrDefault(flow.flowState, "").toUpperCase(Locale.US);
		double minImbalance = Math.max(0.01, settings.rangeMidpointMinDepthImbalance);
		double minTape = Math.max(1.0, settings.rangeMidpointMinTapeDelta);
		int minVotes = Math.max(1, settings.rangeMidpointMinOrderFlowVotes);
		int votes = 0;
		if (longSide) {
			if (imbalance <= -minImbalance && tape <= -minTape) {
				return false;
			}
			votes += imbalance >= minImbalance ? 1 : 0;
			votes += tape >= minTape ? 1 : 0;
			votes += flip.contains("BID") ? 1 : 0;
			votes += absorption.contains("BID") || absorption.contains("BUY") ? 1 : 0;
			votes += flowState.contains("BID") || flowState.contains("BUY") ? 1 : 0;
			return votes >= minVotes;
		}
		if (imbalance >= minImbalance && tape >= minTape) {
			return false;
		}
		votes += imbalance <= -minImbalance ? 1 : 0;
		votes += tape <= -minTape ? 1 : 0;
		votes += flip.contains("ASK") ? 1 : 0;
		votes += absorption.contains("ASK") || absorption.contains("SELL") ? 1 : 0;
		votes += flowState.contains("ASK") || flowState.contains("SELL") ? 1 : 0;
		return votes >= minVotes;
	}

	private static String rmcNotes(String side, double midpoint, double impulseTicks, double retracePct, LiveRuntimeState.OrderFlowSnapshot flow) {
		String source = flow == null ? "" : cleanOrDefault(flow.source, "");
		double confidence = flow == null ? 0.0 : flow.sourceConfidence;
		return "Range midpoint continuation " + side
			+ ": impulse " + round(impulseTicks) + " ticks, midpoint " + round(midpoint)
			+ ", pullback retrace " + round(retracePct * 100.0) + "%"
			+ ", Level 2 confirmed with imbalance " + round(flow == null ? 0.0 : flow.depthImbalance5)
			+ ", tape delta " + round(flow == null ? 0.0 : flow.tapeDelta)
			+ (source.length() == 0 ? "" : ", source " + source)
			+ (confidence <= 0.0 ? "" : ", confidence " + round(confidence))
			+ ".";
	}

	private static List<Signal> findMclEiaContinuationSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (!isInstrumentSymbol(spec, "MCL") || bars == null || bars.size() < 80) {
			return signals;
		}
		Bar first = bars.get(0);
		if (first == null || first.marketDate == null || first.marketDate.getDayOfWeek() != DayOfWeek.WEDNESDAY) {
			return signals;
		}
		double rangeHigh = Double.NEGATIVE_INFINITY;
		double rangeLow = Double.POSITIVE_INFINITY;
		int rangeBars = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			int minute = minuteOfDay(bar);
			if (minute >= settings.mclEiaRangeStartMinute && minute <= settings.mclEiaRangeEndMinute) {
				rangeHigh = Math.max(rangeHigh, bar.high);
				rangeLow = Math.min(rangeLow, bar.low);
				rangeBars++;
			}
		}
		if (rangeBars < 2 || rangeHigh <= rangeLow) {
			return signals;
		}
		boolean longTaken = false;
		boolean shortTaken = false;
		double buffer = settings.mclEiaBreakoutBufferTicks * spec.tickSize;
		double stopDistance = settings.mclEiaStopTicks * spec.tickSize;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketTime == null || bar.vwap <= 0.0) {
				continue;
			}
			int minute = minuteOfDay(bar);
			if (minute < settings.mclEiaStartMinute || minute > settings.mclEiaEndMinute) {
				continue;
			}
			double volumeRatio = volumeRatio(bar);
			if (volumeRatio < settings.mclEiaMinVolumeRatio || bar.bodyPct < settings.mclEiaMinBodyPct) {
				continue;
			}
			double closeLocation = closeLocation(bar);
			if (!longTaken
				&& settings.allowMclEiaLongs
				&& bar.close > rangeHigh + buffer
				&& bar.close > bar.open
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& closeLocation >= 0.55) {
				double stop = bar.close - stopDistance;
				double risk = bar.close - stop;
				if (risk > 0.0) {
					signals.add(signal("EIA", "MCL EIA Continuation", "LONG", index, bar.close, stop, bar.close + (risk * settings.mclEiaRewardRisk), settings.mclEiaMaxHoldBars, "Wednesday post-inventory crude continuation above the pre-release range with VWAP/EMA confirmation."));
					longTaken = true;
				}
			}
			if (!shortTaken
				&& settings.allowShorts
				&& settings.allowMclEiaShorts
				&& bar.close < rangeLow - buffer
				&& bar.close < bar.open
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& closeLocation <= 0.45) {
				double stop = bar.close + stopDistance;
				double risk = stop - bar.close;
				if (risk > 0.0) {
					signals.add(signal("EIA", "MCL EIA Continuation", "SHORT", index, bar.close, stop, bar.close - (risk * settings.mclEiaRewardRisk), settings.mclEiaMaxHoldBars, "Wednesday post-inventory crude continuation below the pre-release range with VWAP/EMA confirmation."));
					shortTaken = true;
				}
			}
			if (signals.size() >= settings.mclEiaContinuation.maxTradesPerDay || (longTaken && shortTaken)) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findMclCrudeSessionOpenSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (!isInstrumentSymbol(spec, "MCL") || bars == null || bars.size() < 80) {
			return signals;
		}
		double rangeHigh = Double.NEGATIVE_INFINITY;
		double rangeLow = Double.POSITIVE_INFINITY;
		double rangeVolume = 0.0;
		int rangeBars = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			int minute = minuteOfDay(bar);
			if (minute >= settings.mclCrudeOpenRangeStartMinute && minute <= settings.mclCrudeOpenRangeEndMinute) {
				rangeHigh = Math.max(rangeHigh, bar.high);
				rangeLow = Math.min(rangeLow, bar.low);
				rangeVolume += bar.volume;
				rangeBars++;
			}
		}
		if (rangeBars < 5 || rangeHigh <= rangeLow) {
			return signals;
		}
		double averageRangeVolume = rangeVolume / rangeBars;
		double buffer = settings.mclCrudeOpenBreakoutBufferTicks * spec.tickSize;
		double stopDistance = settings.mclCrudeOpenStopTicks * spec.tickSize;
		boolean longTaken = false;
		boolean shortTaken = false;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketTime == null || bar.vwap <= 0.0) {
				continue;
			}
			int minute = minuteOfDay(bar);
			if (minute < settings.mclCrudeOpenStartMinute || minute > settings.mclCrudeOpenEndMinute) {
				continue;
			}
			double volumeRatio = averageRangeVolume <= 0.0 ? 1.0 : bar.volume / averageRangeVolume;
			if (volumeRatio < settings.mclCrudeOpenMinVolumeRatio || bar.bodyPct < settings.mclCrudeOpenMinBodyPct) {
				continue;
			}
			double closeLocation = closeLocation(bar);
			if (!longTaken
				&& settings.allowMclCrudeOpenLongs
				&& bar.close > rangeHigh + buffer
				&& bar.close > bar.open
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& closeLocation >= 0.55) {
				double stop = bar.close - stopDistance;
				double risk = bar.close - stop;
				if (risk > 0.0) {
					signals.add(signal("COPEN", "MCL Crude Session Open", "LONG", index, bar.close, stop, bar.close + (risk * settings.mclCrudeOpenRewardRisk), settings.mclCrudeOpenMaxHoldBars, "Crude-specific morning range expansion above the 9:00 ET energy open range."));
					longTaken = true;
				}
			}
			if (!shortTaken
				&& settings.allowShorts
				&& settings.allowMclCrudeOpenShorts
				&& bar.close < rangeLow - buffer
				&& bar.close < bar.open
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& closeLocation <= 0.45) {
				double stop = bar.close + stopDistance;
				double risk = stop - bar.close;
				if (risk > 0.0) {
					signals.add(signal("COPEN", "MCL Crude Session Open", "SHORT", index, bar.close, stop, bar.close - (risk * settings.mclCrudeOpenRewardRisk), settings.mclCrudeOpenMaxHoldBars, "Crude-specific morning range expansion below the 9:00 ET energy open range."));
					shortTaken = true;
				}
			}
			if (signals.size() >= settings.mclCrudeSessionOpen.maxTradesPerDay || (longTaken && shortTaken)) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findMclTrendContinuationSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (!isInstrumentSymbol(spec, "MCL") || bars == null || bars.size() < 80) {
			return signals;
		}
		double sessionOpen = firstOpenAtOrAfter(bars, Math.min(540, settings.mclTrendStartMinute));
		if (sessionOpen <= 0.0) {
			return signals;
		}
		int lookback = Math.max(3, settings.mclTrendLookbackBars);
		int bucketMinutes = Math.max(3, settings.mclTrendBucketMinutes);
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.mclTrendMaxRiskTicks);
		double buffer = settings.mclTrendBreakoutBufferTicks * spec.tickSize;
		int lastLongBucket = -1;
		int lastShortBucket = -1;
		for (int index = lookback + 5; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketTime == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
				continue;
			}
			int minute = minuteOfDay(bar);
			if (minute < settings.mclTrendStartMinute || minute > settings.mclTrendEndMinute) {
				continue;
			}
			int bucket = minute / bucketMinutes;
			double volumeRatio = volumeRatio(bar);
			if (volumeRatio < settings.mclTrendMinVolumeRatio || bar.bodyPct < settings.mclTrendMinBodyPct) {
				continue;
			}
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - lookback)).ema20) / spec.tickSize;
			double priorHigh = recentSwingHigh(bars, index - 1, lookback);
			double priorLow = recentSwingLow(bars, index - 1, lookback);
			double closeLocation = closeLocation(bar);
			double openMoveTicks = Math.abs(bar.close - sessionOpen) / spec.tickSize;
			if (openMoveTicks < settings.mclTrendMinOpenMoveTicks) {
				continue;
			}
			if (settings.allowShorts
				&& settings.allowMclTrendShorts
				&& bucket != lastShortBucket
				&& bar.close > sessionOpen
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.ema20 >= bar.ema50
				&& trendSlopeTicks >= settings.mclTrendMinTrendSlopeTicks
				&& bar.close > priorHigh + buffer
				&& bar.close > bar.open
				&& closeLocation >= 0.56
				&& bar.rsi14 >= 45.0
				&& bar.rsi14 <= 78.0) {
				double stop = Math.max(recentSwingHigh(bars, index, Math.min(lookback, 8)), bar.ema20) + (spec.tickSize * 2.0);
				if (riskTicks(spec, bar.close, stop) > maxRiskTicks) {
					stop = compressedShortStop(spec, bars, index, bar.close, maxRiskTicks);
				}
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MCLTC", "MCL Trend Fade", "SHORT", index, bar.close, stop, bar.close - (risk * settings.mclTrendRewardRisk), settings.mclTrendMaxHoldBars, "MCL trend-fade entry after crude stretches above VWAP/EMA and session-open structure with bounded reversal risk."));
					lastShortBucket = bucket;
				}
			}
			if (settings.allowMclTrendLongs
				&& bucket != lastLongBucket
				&& bar.close < sessionOpen
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.ema20 <= bar.ema50
				&& trendSlopeTicks <= -settings.mclTrendMinTrendSlopeTicks
				&& bar.close < priorLow - buffer
				&& bar.close < bar.open
				&& closeLocation <= 0.44
				&& bar.rsi14 >= 22.0
				&& bar.rsi14 <= 55.0) {
				double stop = Math.min(recentSwingLow(bars, index, Math.min(lookback, 8)), bar.ema20) - (spec.tickSize * 2.0);
				if (riskTicks(spec, bar.close, stop) > maxRiskTicks) {
					stop = compressedLongStop(spec, bars, index, bar.close, maxRiskTicks);
				}
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MCLTC", "MCL Trend Fade", "LONG", index, bar.close, stop, bar.close + (risk * settings.mclTrendRewardRisk), settings.mclTrendMaxHoldBars, "MCL trend-fade entry after crude stretches below VWAP/EMA and session-open structure with bounded reversal risk."));
					lastLongBucket = bucket;
				}
			}
			if (signals.size() >= settings.mclTrendContinuation.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static double firstOpenAtOrAfter(List<Bar> bars, int minuteOfDay) {
		if (bars == null) {
			return 0.0;
		}
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar != null && bar.open > 0.0 && minuteOfDay(bar) >= minuteOfDay) {
				return bar.open;
			}
		}
		return 0.0;
	}

	private static List<Signal> findMymIndexConfirmationSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (!isInstrumentSymbol(spec, "MYM") || bars == null || bars.size() < 80) {
			return signals;
		}
		double rthOpen = 0.0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (minuteOfDay(bar) >= 570) {
				rthOpen = bar.open;
				break;
			}
		}
		if (rthOpen <= 0.0) {
			return signals;
		}
		int lastLongBucket = -1;
		int lastShortBucket = -1;
		int lookback = Math.max(3, settings.mymIndexConfirmationLookbackBars);
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.mymIndexConfirmationMaxRiskTicks);
		for (int index = lookback + 5; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketTime == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
				continue;
			}
			int minute = minuteOfDay(bar);
			if (minute < settings.mymIndexConfirmationStartMinute || minute > settings.mymIndexConfirmationEndMinute) {
				continue;
			}
			int bucket = minute / Math.max(3, settings.mymIndexConfirmationBucketMinutes);
			double volumeRatio = volumeRatio(bar);
			if (volumeRatio < settings.mymIndexConfirmationMinVolumeRatio || bar.bodyPct < settings.mymIndexConfirmationMinBodyPct) {
				continue;
			}
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - lookback)).ema20) / spec.tickSize;
			double priorHigh = recentSwingHigh(bars, index - 1, lookback);
			double priorLow = recentSwingLow(bars, index - 1, lookback);
			double closeLocation = closeLocation(bar);
			if (settings.allowMymIndexConfirmationLongs
				&& bucket != lastLongBucket
				&& bar.close > rthOpen
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.ema20 >= bar.ema50
				&& trendSlopeTicks >= settings.mymIndexConfirmationMinTrendSlopeTicks
				&& bar.close > priorHigh + spec.tickSize
				&& closeLocation >= 0.55
				&& bar.rsi14 >= 45.0
				&& bar.rsi14 <= 76.0) {
				double stop = Math.min(recentSwingLow(bars, index, 5), bar.ema20) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("IDXCONF", "MYM Index Confirmation", "LONG", index, bar.close, stop, bar.close + (risk * settings.mymIndexConfirmationRewardRisk), settings.mymIndexConfirmationMaxHoldBars, "MYM continuation after Dow-style broad trend confirmation from VWAP, EMA slope, session open, and range expansion."));
					lastLongBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowMymIndexConfirmationShorts
				&& bucket != lastShortBucket
				&& bar.close < rthOpen
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.ema20 <= bar.ema50
				&& trendSlopeTicks <= -settings.mymIndexConfirmationMinTrendSlopeTicks
				&& bar.close < priorLow - spec.tickSize
				&& closeLocation <= 0.45
				&& bar.rsi14 >= 24.0
				&& bar.rsi14 <= 55.0) {
				double stop = Math.max(recentSwingHigh(bars, index, 5), bar.ema20) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("IDXCONF", "MYM Index Confirmation", "SHORT", index, bar.close, stop, bar.close - (risk * settings.mymIndexConfirmationRewardRisk), settings.mymIndexConfirmationMaxHoldBars, "MYM continuation after Dow-style broad trend confirmation from VWAP, EMA slope, session open, and range expansion."));
					lastShortBucket = bucket;
				}
			}
			if (signals.size() >= settings.mymIndexConfirmation.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findMymOrbRetestSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (!isInstrumentSymbol(spec, "MYM") || bars == null || bars.size() < 80) {
			return signals;
		}
		double high = Double.NEGATIVE_INFINITY;
		double low = Double.POSITIVE_INFINITY;
		double volume = 0.0;
		int openingBars = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (!bar.marketTime.isBefore(RTH_START) && bar.marketTime.isBefore(ORB_END)) {
				high = Math.max(high, bar.high);
				low = Math.min(low, bar.low);
				volume += bar.volume;
				openingBars++;
			}
		}
		if (openingBars < 5 || high <= low) {
			return signals;
		}
		double averageVolume = volume / openingBars;
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.mymOrbRetestMaxRiskTicks);
		double buffer = settings.mymOrbRetestBreakoutBufferTicks * spec.tickSize;
		double retest = settings.mymOrbRetestRetestTicks * spec.tickSize;
		boolean brokeLong = false;
		boolean brokeShort = false;
		boolean longTaken = false;
		boolean shortTaken = false;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketTime == null || bar.vwap <= 0.0) {
				continue;
			}
			int minute = minuteOfDay(bar);
			if (minute < 570 || minute > settings.mymOrbRetestEndMinute) {
				continue;
			}
			if (bar.close > high + buffer) {
				brokeLong = true;
			}
				if (settings.allowShorts && bar.close < low - buffer) {
					brokeShort = true;
				}
				if (minute < settings.mymOrbRetestStartMinute) {
					continue;
				}
				double volumeRatio = averageVolume <= 0.0 ? 1.0 : bar.volume / averageVolume;
			if (volumeRatio < settings.mymOrbRetestMinVolumeRatio || bar.bodyPct < settings.mymOrbRetestMinBodyPct) {
				continue;
			}
			double closeLocation = closeLocation(bar);
			if (!longTaken
				&& settings.allowMymOrbRetestLongs
				&& brokeLong
				&& bar.low <= high + retest
				&& bar.close > high
				&& bar.close > bar.open
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& closeLocation >= 0.56) {
				double stop = Math.min(recentSwingLow(bars, index, 4), high - buffer) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MYMORB2", "MYM ORB Retest", "LONG", index, bar.close, stop, bar.close + (risk * settings.mymOrbRetestRewardRisk), settings.mymOrbRetestMaxHoldBars, "MYM-specific second-chance ORB retest after breakout holds the opening range."));
					longTaken = true;
				}
			}
			if (!shortTaken
				&& settings.allowShorts
				&& settings.allowMymOrbRetestShorts
				&& brokeShort
				&& bar.high >= low - retest
				&& bar.close < low
				&& bar.close < bar.open
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& closeLocation <= 0.44) {
				double stop = Math.max(recentSwingHigh(bars, index, 4), low + buffer) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MYMORB2", "MYM ORB Retest", "SHORT", index, bar.close, stop, bar.close - (risk * settings.mymOrbRetestRewardRisk), settings.mymOrbRetestMaxHoldBars, "MYM-specific second-chance ORB retest after breakdown rejects the opening range."));
					shortTaken = true;
				}
			}
			if (signals.size() >= settings.mymOrbRetest.maxTradesPerDay || (longTaken && shortTaken)) {
				break;
			}
		}
		return signals;
	}

	private static Signal findOrbSignal(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		double high = Double.NEGATIVE_INFINITY;
		double low = Double.POSITIVE_INFINITY;
		double volume = 0.0;
		int openingBars = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (!bar.marketTime.isBefore(RTH_START) && bar.marketTime.isBefore(ORB_END)) {
				high = Math.max(high, bar.high);
				low = Math.min(low, bar.low);
				volume += bar.volume;
				openingBars++;
			}
		}
		if (openingBars < 5 || high <= low) {
			return null;
		}
		double averageVolume = volume / openingBars;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar.marketTime.isBefore(ORB_END)) {
				continue;
			}
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay > settings.orbBreakoutEndMinute) {
				break;
			}
			if (bar.volume < averageVolume * 0.85) {
				continue;
			}
			double closeLocation = closeLocation(bar);
			double signalRangeTicks = riskTicks(spec, bar.high, bar.low);
			double vwapDistanceTicks = bar.vwap <= 0.0 ? 0.0 : riskTicks(spec, bar.close, bar.vwap);
			double trendSlopeTicks = riskTicks(spec, bar.ema20, bars.get(Math.max(0, index - 10)).ema20);
				if (
					settings.allowOrbLongs
					&& !inMinuteWindow(minuteOfDay, settings.orbLongSkipStartMinute, settings.orbLongSkipEndMinute)
					&& bar.close > high + (spec.tickSize * 2.0)
				&& bar.close > bar.open
				&& bar.bodyPct >= settings.orbMinBodyPct
				&& (settings.orbMaxSignalRangeTicks <= 0.0 || signalRangeTicks <= settings.orbMaxSignalRangeTicks)
				&& (settings.orbMaxBreakoutExtensionTicks <= 0.0 || riskTicks(spec, bar.close, high) <= settings.orbMaxBreakoutExtensionTicks)
				&& (settings.orbMaxVwapDistanceTicks <= 0.0 || vwapDistanceTicks <= settings.orbMaxVwapDistanceTicks)
				&& (settings.orbMaxTrendSlopeTicks <= 0.0 || trendSlopeTicks <= settings.orbMaxTrendSlopeTicks)
				&& closeLocation >= ORB_LONG_MIN_CLOSE_LOCATION
				&& closeLocation <= ORB_LONG_MAX_CLOSE_LOCATION
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))
			) {
				double stop = settings.enableCompressedOrbBreakout
					? compressedLongStop(spec, bars, index, bar.close, Math.min(settings.orbCompressedMaxRiskTicks, settings.maxInitialRiskTicks))
					: low - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk <= 0.0) {
					continue;
				}
				return signal("ORB", "Opening Range Breakout", "LONG", index, bar.close, stop, bar.close + (risk * 1.2), "Futures ORB long above RTH opening range with body-location and higher-timeframe filters.");
			}
				if ((settings.orbShortConfirmationMinute > 0 && minuteOfDay < settings.orbShortConfirmationMinute) || !settings.allowShorts || !settings.allowOrbShorts) {
					continue;
				}
				if (inMinuteWindow(minuteOfDay, settings.orbShortSkipStartMinute, settings.orbShortSkipEndMinute)) {
					continue;
				}
			if (bar.close < low - (spec.tickSize * 2.0)
				&& bar.close < bar.open
				&& bar.bodyPct >= settings.orbMinBodyPct
				&& (settings.orbMaxSignalRangeTicks <= 0.0 || signalRangeTicks <= settings.orbMaxSignalRangeTicks)
				&& (settings.orbMaxBreakoutExtensionTicks <= 0.0 || riskTicks(spec, low, bar.close) <= settings.orbMaxBreakoutExtensionTicks)
				&& (settings.orbMaxVwapDistanceTicks <= 0.0 || vwapDistanceTicks <= settings.orbMaxVwapDistanceTicks)
				&& (settings.orbMaxTrendSlopeTicks <= 0.0 || trendSlopeTicks <= settings.orbMaxTrendSlopeTicks)) {
				double stop = settings.enableCompressedOrbBreakout
					? compressedShortStop(spec, bars, index, bar.close, Math.min(settings.orbCompressedMaxRiskTicks, settings.maxInitialRiskTicks))
					: high + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk <= 0.0) {
					continue;
				}
				return signal("ORB", "Opening Range Breakout", "SHORT", index, bar.close, stop, bar.close - (risk * 1.2), "Futures ORB short below RTH opening range after confirmation window.");
			}
		}
		return null;
	}

	private static List<Signal> findOrbRetestSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		double high = Double.NEGATIVE_INFINITY;
		double low = Double.POSITIVE_INFINITY;
		double volume = 0.0;
		int openingBars = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (!bar.marketTime.isBefore(RTH_START) && bar.marketTime.isBefore(ORB_END)) {
				high = Math.max(high, bar.high);
				low = Math.min(low, bar.low);
				volume += bar.volume;
				openingBars++;
			}
		}
		if (openingBars < 5 || high <= low) {
			return signals;
		}
		double averageVolume = volume / openingBars;
		double maxOrbRetestRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.orbRetestMaxRiskTicks);
		boolean brokeLong = false;
		boolean brokeShort = false;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar.marketTime.isBefore(ORB_END)) {
				continue;
			}
			if (bar.marketTime.isAfter(LocalTime.of(11, 45))) {
				break;
			}
			if (bar.close > high + (spec.tickSize * 2.0)) {
				brokeLong = true;
			}
			if (settings.allowShorts && bar.close < low - (spec.tickSize * 2.0)) {
				brokeShort = true;
			}
			if (settings.allowOrbRetestLongs && brokeLong && bar.low <= high + (spec.tickSize * 2.0) && bar.close > high && bar.close > bar.open && closeLocation(bar) >= 0.58 && bar.volume >= averageVolume * 0.65) {
				double stop = recentSwingLow(bars, index, 3) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxOrbRetestRiskTicks) {
					signals.add(signal("ORB2", "Opening Range Retest", "LONG", index, bar.close, stop, bar.close + (risk * Math.max(settings.minRewardRisk, 1.0)), settings.openingMomentumMaxHoldBars, "ORB long retest after breakout holds opening range high with compressed swing risk."));
					break;
				}
			}
			if (settings.allowOrbRetestShorts && brokeShort && bar.high >= low - (spec.tickSize * 2.0) && bar.close < low && bar.close < bar.open && closeLocation(bar) <= 0.42 && bar.volume >= averageVolume * 0.65) {
				double stop = recentSwingHigh(bars, index, 3) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxOrbRetestRiskTicks) {
					signals.add(signal("ORB2", "Opening Range Retest", "SHORT", index, bar.close, stop, bar.close - (risk * Math.max(settings.minRewardRisk, 1.0)), settings.openingMomentumMaxHoldBars, "ORB short retest after breakdown holds opening range low with compressed swing risk."));
					break;
				}
			}
		}
		return signals;
	}

	private static boolean orbRetestSymbolAllowed(InstrumentSpec spec, FuturesStrategySettings settings) {
		String allowedSymbols = cleanOrDefault(settings.orbRetestAllowedSymbols, "");
		if (allowedSymbols.isEmpty()) {
			return true;
		}
		String normalized = normalizeSymbol(spec == null ? "" : spec.symbol);
		String[] parts = allowedSymbols.split(",");
		for (int index = 0; index < parts.length; index++) {
			if (normalized.equals(normalizeSymbol(parts[index]))) {
				return true;
			}
		}
		return false;
	}

	private static boolean orbRetestExtensionOk(InstrumentSpec spec, FuturesStrategySettings settings, double high, double low, double close, boolean isLong) {
		if (settings.orbRetestMaxExtensionPctOfRange <= 0.0) {
			return true;
		}
		return orbRetestExtensionPct(spec, high, low, close, isLong) <= settings.orbRetestMaxExtensionPctOfRange;
	}

	private static double orbRetestExtensionPct(InstrumentSpec spec, double high, double low, double close, boolean isLong) {
		double openingRangeTicks = Math.max(1.0, riskTicks(spec, high, low));
		double extensionTicks = isLong ? riskTicks(spec, close, high) : riskTicks(spec, low, close);
		return Math.max(0.0, extensionTicks) / openingRangeTicks;
	}

	private static boolean emaStackAligned(Bar bar, boolean isLong) {
		if (bar == null || bar.ema9 <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
			return false;
		}
		return isLong ? (bar.ema9 >= bar.ema20 && bar.ema20 >= bar.ema50) : (bar.ema9 <= bar.ema20 && bar.ema20 <= bar.ema50);
	}

	private static List<Signal> findOrbEventPackSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, List<Signal> existingSignals) {
		List<Signal> signals = new ArrayList<Signal>();
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		if (spec == null || bars == null || bars.size() < 120) {
			return signals;
		}
		String symbol = normalizeSymbol(spec.symbol);
		if ("M2K".equals(symbol)) {
			if (orbEventPackSetupEnabled(safe, "M2K_FAIL_LONG")) {
				addOrbEventPackFailedReclaim(signals, spec, bars, safe, 5, "LONG", 2.0, true);
			}
			if (orbEventPackSetupEnabled(safe, "M2K_RETEST_LONG")) {
				addOrbEventPackRetest(signals, spec, bars, safe, 5, "LONG", 1.5, false, true);
			}
		} else if ("MNQ".equals(symbol)) {
			if (orbEventPackSetupEnabled(safe, "MNQ_RETEST_LONG")) {
				addOrbEventPackRetest(signals, spec, bars, safe, 5, "LONG", 2.0, true, true);
			}
		} else if ("NQ".equals(symbol)) {
			if (orbEventPackSetupEnabled(safe, "NQ_RETEST_LONG")) {
				addOrbEventPackRetest(signals, spec, bars, safe, 5, "LONG", 1.5, false, true);
			}
		} else if ("MES".equals(symbol)) {
			if (orbEventPackSetupEnabled(safe, "MES_RETEST_LONG")) {
				addOrbEventPackRetest(signals, spec, bars, safe, 5, "LONG", 2.0, true, true);
			}
		} else if ("MCL".equals(symbol)) {
			if (orbEventPackSetupEnabled(safe, "MCL_FIRST_LONG")) {
				addOrbEventPackFirstBreak(signals, spec, bars, safe, 15, "LONG", 1.2, false, true);
			}
		} else if ("MGC".equals(symbol)) {
			if (orbEventPackSetupEnabled(safe, "MGC_FIRST_SHORT")) {
				addOrbEventPackFirstBreak(signals, spec, bars, safe, 5, "SHORT", 1.5, true, true);
			}
			if (orbEventPackSetupEnabled(safe, "MGC_FAIL_SHORT")) {
				addOrbEventPackFailedReclaim(signals, spec, bars, safe, 15, "SHORT", 1.5, true);
			}
		} else if ("MYM".equals(symbol) && orbEventPackSetupEnabled(safe, "MYM_FAIL_SHORT")) {
			addOrbEventPackFailedReclaim(signals, spec, bars, safe, 5, "SHORT", 1.2, true);
		}
		if (safe.orbEventPackRequireSimilarOrb) {
			List<Signal> filtered = new ArrayList<Signal>();
			for (int index = 0; index < signals.size(); index++) {
				Signal signal = signals.get(index);
				if (hasSimilarOrbFamilySignal(signal, existingSignals, safe.orbEventPackSimilarWindowBars)) {
					filtered.add(signal);
				}
			}
			signals = filtered;
		}
		signals = limitSignalsByDailyCount(dedupeByHour(signals, safe.orbEventPack.maxTradesPerDay), safe.orbEventPack.maxTradesPerDay);
		return signals;
	}

	private static boolean hasSimilarOrbFamilySignal(Signal candidate, List<Signal> existingSignals, int windowBars) {
		if (candidate == null || existingSignals == null || existingSignals.isEmpty()) {
			return false;
		}
		for (int index = 0; index < existingSignals.size(); index++) {
			Signal existing = existingSignals.get(index);
			if (existing == null || !isOrbFamilyStrategy(existing.strategyCode)) {
				continue;
			}
			if (!cleanOrDefault(candidate.side, "").equals(cleanOrDefault(existing.side, ""))) {
				continue;
			}
			if (Math.abs(candidate.entryIndex - existing.entryIndex) <= Math.max(1, windowBars)) {
				return true;
			}
		}
		return false;
	}

	private static boolean isOrbFamilyStrategy(String strategyCode) {
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		return "ORB".equals(code) || "ORB2".equals(code) || "LORB".equals(code) || "ORBX".equals(code);
	}

	private static boolean orbEventPackSetupEnabled(FuturesStrategySettings settings, String setup) {
		String selected = cleanOrDefault(settings == null ? "ALL" : settings.orbEventPackSetups, "ALL").toUpperCase(Locale.US);
		if (selected.length() == 0 || "ALL".equals(selected)) {
			return true;
		}
		String normalized = cleanOrDefault(setup, "").toUpperCase(Locale.US);
		String[] parts = selected.split(",");
		for (int index = 0; index < parts.length; index++) {
			if (normalized.equals(parts[index].trim().toUpperCase(Locale.US))) {
				return true;
			}
		}
		return false;
	}

	private static void addOrbEventPackFirstBreak(List<Signal> signals, InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int rangeMinutes, String side, double targetR, boolean requireEma, boolean requireVwap) {
		OrbOpeningRange range = orbOpeningRange(bars, rangeMinutes);
		if (range == null) {
			return;
		}
		OrbBreak firstBreak = firstOrbBreak(spec, bars, range);
		if (firstBreak == null || !side.equals(firstBreak.side)) {
			return;
		}
		Bar bar = bars.get(firstBreak.index);
		if (!orbEventPackBreakQualityOk(spec, bars, range, firstBreak.index, side, settings)) {
			return;
		}
		if (requireVwap && !orbEventVwapSide(bar, side)) {
			return;
		}
		if ((requireEma || settings.orbEventPackRequireEmaAlignment) && !emaStackAligned(bar, "LONG".equals(side))) {
			return;
		}
		double stop = "LONG".equals(side) ? range.low - (spec.tickSize * 2.0) : range.high + (spec.tickSize * 2.0);
		addOrbEventPackSignal(signals, spec, bars, settings, firstBreak.index, side, stop, targetR, "1m ORB event-pack first break with VWAP/EMA participation.");
	}

	private static void addOrbEventPackRetest(List<Signal> signals, InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int rangeMinutes, String side, double targetR, boolean requireEma, boolean requireVwap) {
		OrbOpeningRange range = orbOpeningRange(bars, rangeMinutes);
		if (range == null) {
			return;
		}
		OrbBreak firstBreak = firstOrbBreak(spec, bars, range);
		if (firstBreak == null || !side.equals(firstBreak.side)) {
			return;
		}
		if (!orbEventPackBreakQualityOk(spec, bars, range, firstBreak.index, side, settings)) {
			return;
		}
		double level = "LONG".equals(side) ? range.high : range.low;
		int firstRetestIndex = Math.max(firstBreak.index + 2, firstBreak.index + settings.orbEventPackMinRetestBarsAfterBreak);
		for (int index = firstRetestIndex; index < Math.min(bars.size() - 1, firstBreak.index + 45); index++) {
			Bar bar = bars.get(index);
			if (bar.marketTime != null && bar.marketTime.isAfter(LocalTime.of(12, 0))) {
				break;
			}
			boolean touched;
			boolean confirmed;
			double stop;
			if ("LONG".equals(side)) {
				touched = bar.low <= level + (spec.tickSize * 2.0);
				confirmed = bar.close > level && bar.close > bar.open && closeLocation(bar) >= 0.58;
				stop = recentSwingLow(bars, index, 5) - (spec.tickSize * 2.0);
			} else {
				touched = bar.high >= level - (spec.tickSize * 2.0);
				confirmed = bar.close < level && bar.close < bar.open && closeLocation(bar) <= 0.42;
				stop = recentSwingHigh(bars, index, 5) + (spec.tickSize * 2.0);
			}
			if (!touched || !confirmed) {
				continue;
			}
			if (bar.bodyPct < settings.orbEventPackMinRetestBodyPct) {
				continue;
			}
			if (range.averageVolume() > 0.0 && bar.volume < range.averageVolume() * settings.orbEventPackMinRetestVolumeRatio) {
				continue;
			}
			if (!orbEventPackExtensionOk(spec, range, bar.close, side, settings)) {
				continue;
			}
			if (requireVwap && !orbEventVwapSide(bar, side)) {
				continue;
			}
			if ((requireEma || settings.orbEventPackRequireEmaAlignment) && !emaStackAligned(bar, "LONG".equals(side))) {
				continue;
			}
			if (riskTicks(spec, bar.close, stop) > settings.orbEventPackMaxRiskTicks) {
				return;
			}
			addOrbEventPackSignal(signals, spec, bars, settings, index, side, stop, targetR, "1m ORB event-pack retest after first range break held the broken level.");
			return;
		}
	}

	private static void addOrbEventPackFailedReclaim(List<Signal> signals, InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int rangeMinutes, String side, double targetR, boolean requireVwap) {
		OrbOpeningRange range = orbOpeningRange(bars, rangeMinutes);
		if (range == null) {
			return;
		}
		OrbBreak firstBreak = firstOrbBreak(spec, bars, range);
		if (firstBreak == null) {
			return;
		}
		if (!orbEventPackBreakQualityOk(spec, bars, range, firstBreak.index, firstBreak.side, settings)) {
			return;
		}
		String reversalSide = "LONG".equals(firstBreak.side) ? "SHORT" : "LONG";
		if (!side.equals(reversalSide)) {
			return;
		}
		double midpoint = (range.high + range.low) / 2.0;
		for (int index = firstBreak.index + 1; index < Math.min(bars.size() - 1, firstBreak.index + 20); index++) {
			Bar bar = bars.get(index);
			boolean trigger;
			double stop;
			if ("LONG".equals(firstBreak.side)) {
				trigger = bar.close < range.high && bar.close < bar.open && bar.close < midpoint;
				stop = recentSwingHigh(bars, index, Math.max(1, index - firstBreak.index + 1)) + (spec.tickSize * 2.0);
			} else {
				trigger = bar.close > range.low && bar.close > bar.open && bar.close > midpoint;
				stop = recentSwingLow(bars, index, Math.max(1, index - firstBreak.index + 1)) - (spec.tickSize * 2.0);
			}
			if (!trigger) {
				continue;
			}
			if (bar.bodyPct < settings.orbEventPackMinRetestBodyPct) {
				continue;
			}
			if (range.averageVolume() > 0.0 && bar.volume < range.averageVolume() * settings.orbEventPackMinRetestVolumeRatio) {
				continue;
			}
			if (requireVwap && !orbEventVwapSide(bar, side)) {
				continue;
			}
			addOrbEventPackSignal(signals, spec, bars, settings, index, side, stop, targetR, "1m ORB event-pack failed break reclaimed the range midpoint and reversed.");
			return;
		}
	}

	private static void addOrbEventPackSignal(List<Signal> signals, InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int index, String side, double stop, double targetR, String notes) {
		if (index < 0 || index >= bars.size()) {
			return;
		}
		Bar bar = bars.get(index);
		double risk = "LONG".equals(side) ? bar.close - stop : stop - bar.close;
		if (risk <= 0.0 || riskTicks(spec, bar.close, stop) > settings.orbEventPackMaxRiskTicks) {
			return;
		}
		double target = "LONG".equals(side) ? bar.close + (risk * targetR) : bar.close - (risk * targetR);
		signals.add(signal("ORBX", "ORB Event Pack", side, index, bar.close, stop, target, settings.orbEventPackMaxHoldBars, notes));
	}

	private static boolean orbEventPackBreakQualityOk(InstrumentSpec spec, List<Bar> bars, OrbOpeningRange range, int index, String side, FuturesStrategySettings settings) {
		if (index < 0 || index >= bars.size()) {
			return false;
		}
		Bar bar = bars.get(index);
		if (bar.bodyPct < settings.orbEventPackMinBreakBodyPct) {
			return false;
		}
		if (range.averageVolume() > 0.0 && bar.volume < range.averageVolume() * settings.orbEventPackMinBreakVolumeRatio) {
			return false;
		}
		return orbEventPackExtensionOk(spec, range, bar.close, side, settings);
	}

	private static boolean orbEventPackExtensionOk(InstrumentSpec spec, OrbOpeningRange range, double close, String side, FuturesStrategySettings settings) {
		if (settings.orbEventPackMaxExtensionPctOfRange <= 0.0) {
			return true;
		}
		double rangeTicks = Math.max(1.0, riskTicks(spec, range.high, range.low));
		double extensionTicks = "LONG".equals(side) ? riskTicks(spec, close, range.high) : riskTicks(spec, range.low, close);
		return Math.max(0.0, extensionTicks) / rangeTicks <= settings.orbEventPackMaxExtensionPctOfRange;
	}

	private static boolean orbEventVwapSide(Bar bar, String side) {
		if (bar == null || bar.vwap <= 0.0) {
			return false;
		}
		return "LONG".equals(side) ? bar.close >= bar.vwap : bar.close <= bar.vwap;
	}

	private static OrbOpeningRange orbOpeningRange(List<Bar> bars, int rangeMinutes) {
		int start = -1;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar.marketTime != null && !bar.marketTime.isBefore(RTH_START)) {
				start = index;
				break;
			}
		}
		if (start < 0 || start + rangeMinutes >= bars.size()) {
			return null;
		}
		OrbOpeningRange range = new OrbOpeningRange();
		range.startIndex = start;
		range.endIndex = start + rangeMinutes - 1;
		range.high = Double.NEGATIVE_INFINITY;
		range.low = Double.POSITIVE_INFINITY;
		for (int index = start; index < start + rangeMinutes; index++) {
			Bar bar = bars.get(index);
			range.high = Math.max(range.high, bar.high);
			range.low = Math.min(range.low, bar.low);
			range.volume += Math.max(0.0, bar.volume);
			range.bars++;
		}
		return range.high > range.low ? range : null;
	}

	private static OrbBreak firstOrbBreak(InstrumentSpec spec, List<Bar> bars, OrbOpeningRange range) {
		for (int index = range.endIndex + 1; index < bars.size() - 1; index++) {
			Bar bar = bars.get(index);
			if (bar.marketTime != null && bar.marketTime.isAfter(LocalTime.of(12, 0))) {
				break;
			}
			if (bar.close > range.high + (spec.tickSize * 2.0)) {
				return new OrbBreak(index, "LONG");
			}
			if (bar.close < range.low - (spec.tickSize * 2.0)) {
				return new OrbBreak(index, "SHORT");
			}
		}
		return null;
	}

	private static class OrbOpeningRange {
		private int startIndex;
		private int endIndex;
		private double high;
		private double low;
		private double volume;
		private int bars;

		private double averageVolume() {
			return bars <= 0 ? 0.0 : volume / bars;
		}
	}

	private static class OrbBreak {
		private final int index;
		private final String side;

		private OrbBreak(int index, String side) {
			this.index = index;
			this.side = side;
		}
	}

	private static List<Signal> findVolumePriceManipulationSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		FuturesStrategySettings safe = settings == null ? defaultFuturesStrategySettings() : settings;
		if (spec == null || bars == null || bars.size() < 40) {
			return signals;
		}
		if (volumePriceModeAllows(safe, "VABS")) {
			signals.addAll(findVolumeAbsorptionReversals(spec, bars, fifteenMinuteBars, oneHourBars, safe));
		}
		return limitSignalsByDailyCount(dedupeByHour(signals, safe.volumePriceManipulation.maxTradesPerDay), safe.volumePriceManipulation.maxTradesPerDay);
	}

	private static List<Signal> findVolumeAbsorptionReversals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		double tick = Math.max(0.000001, spec.tickSize);
		int lookback = Math.max(8, settings.volumePriceLookbackBars);
		for (int index = Math.max(lookback + 2, 30); index < bars.size(); index++) {
			Bar entry = bars.get(index);
			Bar absorption = bars.get(index - 1);
			if (!volumePriceBaseEntryOk(entry, settings) || !sameMarketDateWindow(bars, index, lookback)) {
				continue;
			}
			double recentLow = lowestLowBetween(bars, index - lookback, index - 2);
			if (absorption.low < recentLow - tick
				&& volumeRatio(absorption) >= Math.max(settings.volumePriceMinVolumeRatio, 1.5)
				&& closeLocation(absorption) >= 0.55
				&& entry.close > absorption.high + tick
				&& entry.close > entry.open
				&& closeLocation(entry) >= 0.62
				&& volumePriceHtfOk(true, entry, fifteenMinuteBars, oneHourBars, settings)) {
				Signal signal = volumePriceSignal(spec, bars, index, true, "VABS", "Volume Absorption Reversal", absorption.low, "high-volume downside effort rejected, next candle reclaimed the absorption high", settings);
				if (signal != null) {
					signals.add(signal);
				}
			}
			if (settings.allowShorts) {
				double recentHigh = highestHighBetween(bars, index - lookback, index - 2);
				if (absorption.high > recentHigh + tick
					&& volumeRatio(absorption) >= Math.max(settings.volumePriceMinVolumeRatio, 1.5)
					&& closeLocation(absorption) <= 0.45
					&& entry.close < absorption.low - tick
					&& entry.close < entry.open
					&& closeLocation(entry) <= 0.38
					&& volumePriceHtfOk(false, entry, fifteenMinuteBars, oneHourBars, settings)) {
					Signal signal = volumePriceSignal(spec, bars, index, false, "VABS", "Volume Absorption Reversal", absorption.high, "high-volume upside effort rejected, next candle lost the absorption low", settings);
					if (signal != null) {
						signals.add(signal);
					}
				}
			}
		}
		return signals;
	}

	private static boolean volumePriceBaseEntryOk(Bar bar, FuturesStrategySettings settings) {
		if (bar == null || bar.marketTime == null) {
			return false;
		}
		if (!inMinuteWindow(minuteOfDay(bar), settings.volumePriceStartMinute, settings.volumePriceEndMinute)) {
			return false;
		}
		double bodyPct = bar.bodyPct > 0.0 ? bar.bodyPct : defaultBodyPct(bar);
		return bodyPct >= settings.volumePriceMinBodyPct && volumeRatio(bar) >= settings.volumePriceMinVolumeRatio;
	}

	private static Signal volumePriceSignal(InstrumentSpec spec, List<Bar> bars, int index, boolean longSide, String code, String name, double invalidation, String thesis, FuturesStrategySettings settings) {
		Bar bar = bars.get(index);
		double tick = Math.max(0.000001, spec.tickSize);
		double entry = roundToTick(spec, bar.close);
		double stop = longSide
			? roundToTick(spec, invalidation - (2.0 * tick))
			: roundToTick(spec, invalidation + (2.0 * tick));
		double risk = longSide ? entry - stop : stop - entry;
		if (risk <= 0.0 || riskTicks(spec, entry, stop) > settings.volumePriceMaxRiskTicks) {
			return null;
		}
		double target = longSide
			? roundToTick(spec, entry + (risk * settings.volumePriceRewardRisk))
			: roundToTick(spec, entry - (risk * settings.volumePriceRewardRisk));
		String notes = name + ": " + thesis
			+ ", volume ratio " + round(volumeRatio(bar))
			+ ", body " + round(bar.bodyPct > 0.0 ? bar.bodyPct : defaultBodyPct(bar))
			+ "%, close location " + round(closeLocation(bar))
			+ ".";
		return signal(code, name, longSide ? "LONG" : "SHORT", index, entry, stop, target, settings.volumePriceMaxHoldBars, notes);
	}

	private static boolean volumePriceHtfOk(boolean longSide, Bar bar, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		if (!settings.volumePriceRequireHigherTimeframe) {
			return true;
		}
		return longSide
			? higherTimeframeConstructive(fifteenMinuteBars, oneHourBars, bar.marketTime)
			: higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime);
	}

	private static boolean sameMarketDateWindow(List<Bar> bars, int endIndex, int lookback) {
		if (bars == null || bars.isEmpty() || endIndex < 0 || endIndex >= bars.size()) {
			return false;
		}
		LocalDate date = bars.get(endIndex).marketDate;
		if (date == null) {
			return true;
		}
		int start = Math.max(0, endIndex - Math.max(1, lookback));
		for (int index = start; index <= endIndex; index++) {
			if (bars.get(index).marketDate != null && !date.equals(bars.get(index).marketDate)) {
				return false;
			}
		}
		return true;
	}

	private static boolean isVolumePriceStrategyCode(String strategyCode) {
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		return "VABS".equals(code);
	}

	private static String normalizedVolumePriceMode(String mode) {
		String clean = cleanOrDefault(mode, "ALL").trim().toUpperCase(Locale.US);
		if (clean.length() == 0 || "ALL".equals(clean)) {
			return "ALL";
		}
		StringBuilder builder = new StringBuilder();
		String[] parts = clean.split(",");
		for (int index = 0; index < parts.length; index++) {
			String part = parts[index].trim();
			if (isVolumePriceStrategyCode(part)) {
				if (builder.length() > 0) {
					builder.append(",");
				}
				builder.append(part);
			}
		}
		return builder.length() == 0 ? "ALL" : builder.toString();
	}

	private static boolean volumePriceModeAllows(FuturesStrategySettings settings, String strategyCode) {
		String mode = normalizedVolumePriceMode(settings == null ? "ALL" : settings.volumePriceMode);
		String code = cleanOrDefault(strategyCode, "").toUpperCase(Locale.US);
		if ("ALL".equals(mode)) {
			return true;
		}
		String[] parts = mode.split(",");
		for (int index = 0; index < parts.length; index++) {
			if (code.equals(parts[index].trim())) {
				return true;
			}
		}
		return false;
	}

	private static List<Signal> findLateOrbContinuationSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 90) {
			return signals;
		}
		double high = Double.NEGATIVE_INFINITY;
		double low = Double.POSITIVE_INFINITY;
		double volume = 0.0;
		int openingBars = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (!bar.marketTime.isBefore(RTH_START) && bar.marketTime.isBefore(ORB_END)) {
				high = Math.max(high, bar.high);
				low = Math.min(low, bar.low);
				volume += bar.volume;
				openingBars++;
			}
		}
		if (openingBars < 5 || high <= low) {
			return signals;
		}
		double averageVolume = volume / openingBars;
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.lateOrbContinuationMaxRiskTicks);
		for (int index = 45; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar == null || bar.marketTime == null) {
				continue;
			}
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay < settings.lateOrbContinuationStartMinute || minuteOfDay > settings.lateOrbContinuationEndMinute) {
				continue;
			}
			double volumeRatio = averageVolume <= 0.0 ? 1.0 : bar.volume / averageVolume;
			if (volumeRatio < settings.lateOrbContinuationMinVolumeRatio) {
				continue;
			}
			if (settings.allowLateOrbContinuationLongs
				&& bar.close > high + (spec.tickSize * 2.0)
				&& bar.close > bar.open
				&& closeLocation(bar) >= ORB_LONG_MIN_CLOSE_LOCATION
				&& closeLocation(bar) <= ORB_LONG_MAX_CLOSE_LOCATION) {
				double stop = compressedLongStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("LORB", "Late ORB Continuation", "LONG", index, bar.close, stop, bar.close + (risk * settings.lateOrbContinuationRewardRisk), settings.lateOrbContinuationMaxHoldBars, "Late opening-range continuation after the initial breakout window, using a compressed swing stop."));
				}
			}
			if (settings.allowShorts
				&& settings.allowLateOrbContinuationShorts
				&& bar.close < low - (spec.tickSize * 2.0)
				&& bar.close < bar.open
				&& bar.vwap > 0.0
				&& bar.ema20 > 0.0
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.close <= bar.ema50
				&& bar.rsi14 <= 52.0
				&& bar.rsi14 >= 24.0
				&& closeLocation(bar) <= 0.42) {
				double stop = compressedShortStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("LORB", "Late ORB Continuation", "SHORT", index, bar.close, stop, bar.close - (risk * settings.lateOrbContinuationRewardRisk), settings.lateOrbContinuationMaxHoldBars, "Late opening-range continuation after the initial breakdown window, using a compressed swing stop."));
				}
			}
			if (signals.size() >= settings.lateOrbContinuation.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findOpeningMomentumSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		LocalTime rangeEnd = RTH_START.plusMinutes(settings.openingMomentumRangeMinutes);
		double high = Double.NEGATIVE_INFINITY;
		double low = Double.POSITIVE_INFINITY;
		double volume = 0.0;
		int openingBars = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (!bar.marketTime.isBefore(RTH_START) && bar.marketTime.isBefore(rangeEnd)) {
				high = Math.max(high, bar.high);
				low = Math.min(low, bar.low);
				volume += bar.volume;
				openingBars++;
			}
		}
		if (openingBars < Math.max(5, settings.openingMomentumRangeMinutes / 2) || high <= low) {
			return signals;
		}

		double averageVolume = volume / openingBars;
		boolean longTaken = false;
		boolean shortTaken = false;
		int lastLongBucket = -1;
		int lastShortBucket = -1;
		int longCount = 0;
		int shortCount = 0;
		int bucketMinutes = Math.max(5, settings.openingMomentumBucketMinutes);
		double longVolumeRatioThreshold = settings.openingMomentumLongVolumeRatio > 0.0 ? settings.openingMomentumLongVolumeRatio : settings.openingMomentumVolumeRatio;
		double shortVolumeRatioThreshold = settings.openingMomentumShortVolumeRatio > 0.0 ? settings.openingMomentumShortVolumeRatio : settings.openingMomentumVolumeRatio;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar.marketTime.isBefore(rangeEnd)) {
				continue;
			}
			if (bar.marketTime.isAfter(OPENING_MOMENTUM_END)) {
				break;
			}
			double volumeRatio = averageVolume <= 0.0 ? 1.0 : bar.volume / averageVolume;
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			int bucket = minuteOfDay / bucketMinutes;
			double closeLocation = closeLocation(bar);
			if (settings.allowOpeningMomentumLongs
				&& (!longTaken || (settings.openingMomentumAllowMultiplePerSide && bucket != lastLongBucket && signals.size() < settings.openingMomentum.maxTradesPerDay))
				&& volumeRatio >= longVolumeRatioThreshold
				&& inOpeningMomentumLongWindow(bar, minuteOfDay, settings)
				&& bar.close > high + (spec.tickSize * 2.0)
				&& bar.close > bar.open
				&& bar.bodyPct >= settings.openingMomentumMinBodyPct
				&& closeLocation >= 0.55
				&& closeLocation <= 0.78) {
				double stop = recentSwingLow(bars, index, 3) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= Math.min(settings.maxInitialRiskTicks, settings.openingMomentumMaxRiskTicks)) {
					signals.add(signal("OMOM", "Compressed Opening Momentum", "LONG", index, bar.close, stop, bar.close + (risk * settings.openingMomentumRewardRisk), settings.openingMomentumMaxHoldBars, settings.openingMomentumRangeMinutes + "m compressed opening range long breakout with swing-risk stop."));
					longTaken = true;
					lastLongBucket = bucket;
					longCount++;
				}
			}
			if (settings.allowShorts
				&& settings.allowOpeningMomentumShorts
				&& (!shortTaken || (settings.openingMomentumAllowMultiplePerSide && bucket != lastShortBucket && signals.size() < settings.openingMomentum.maxTradesPerDay))
				&& volumeRatio >= shortVolumeRatioThreshold
				&& !bar.marketTime.isBefore(ORB_SHORT_CONFIRMATION_TIME)
				&& inOpeningMomentumShortWindow(bar, minuteOfDay, settings)
				&& bar.rsi14 >= settings.openingMomentumShortMinRsi
				&& bar.rsi14 <= settings.openingMomentumShortMaxRsi
				&& bar.close < low - (spec.tickSize * 2.0)
				&& bar.close < bar.open
				&& bar.bodyPct >= settings.openingMomentumMinBodyPct
				&& (1.0 - closeLocation) >= 0.55) {
				double stop = recentSwingHigh(bars, index, 3) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= Math.min(settings.maxInitialRiskTicks, settings.openingMomentumMaxRiskTicks)) {
					signals.add(signal("OMOM", "Compressed Opening Momentum", "SHORT", index, bar.close, stop, bar.close - (risk * settings.openingMomentumRewardRisk), settings.openingMomentumMaxHoldBars, settings.openingMomentumRangeMinutes + "m compressed opening range short breakdown with swing-risk stop."));
					shortTaken = true;
					lastShortBucket = bucket;
					shortCount++;
				}
			}
			if (signals.size() >= settings.openingMomentum.maxTradesPerDay) {
				break;
			}
		}
		return dedupeByHour(signals, settings.openingMomentum.maxTradesPerDay);
	}

	private static boolean inOpeningMomentumLongWindow(Bar bar, int minuteOfDay, FuturesStrategySettings settings) {
		boolean primaryWindow = minuteOfDay >= settings.openingMomentumLongStartMinute
			&& minuteOfDay <= settings.openingMomentumLongEndMinute
			&& !inMinuteWindow(minuteOfDay, settings.openingMomentumLongSkipStartMinute, settings.openingMomentumLongSkipEndMinute)
			&& !inDayOfWeekMask(bar.marketDate, settings.openingMomentumLongSkipDowMask);
		if (primaryWindow) {
			return true;
		}
		return inOpeningMomentumExtraWindow(bar, minuteOfDay, settings.openingMomentumLongExtraWindows);
	}

	private static boolean inOpeningMomentumShortWindow(Bar bar, int minuteOfDay, FuturesStrategySettings settings) {
		boolean primaryWindow = minuteOfDay >= settings.openingMomentumShortStartMinute
			&& minuteOfDay <= settings.openingMomentumShortEndMinute
			&& !inMinuteWindow(minuteOfDay, settings.openingMomentumShortSkipStartMinute, settings.openingMomentumShortSkipEndMinute)
			&& !inDayOfWeekMask(bar.marketDate, settings.openingMomentumShortSkipDowMask);
		if (primaryWindow) {
			return true;
		}
		boolean altWindow = settings.openingMomentumShortAltEnabled
			&& minuteOfDay >= settings.openingMomentumShortAltStartMinute
			&& minuteOfDay <= settings.openingMomentumShortAltEndMinute
			&& !inDayOfWeekMask(bar.marketDate, settings.openingMomentumShortAltSkipDowMask);
		return altWindow || inOpeningMomentumExtraWindow(bar, minuteOfDay, settings.openingMomentumShortExtraWindows);
	}

	private static boolean inOpeningMomentumExtraWindow(Bar bar, int minuteOfDay, String extraWindows) {
		if (extraWindows == null || extraWindows.trim().isEmpty()) {
			return false;
		}
		String[] windows = extraWindows.split(";");
		for (int index = 0; index < windows.length; index++) {
			String window = windows[index] == null ? "" : windows[index].trim();
			if (window.isEmpty()) {
				continue;
			}
			int colonIndex = window.indexOf(':');
			int dashIndex = window.indexOf('-');
			if (dashIndex <= 0) {
				continue;
			}
			String startText = window.substring(0, dashIndex).trim();
			String endText = colonIndex > dashIndex ? window.substring(dashIndex + 1, colonIndex).trim() : window.substring(dashIndex + 1).trim();
			String skipText = colonIndex > dashIndex ? window.substring(colonIndex + 1).trim() : "0";
			int startMinute = parseInt(startText, -1);
			int endMinute = parseInt(endText, -1);
			int skipDowMask = parseInt(skipText, 0);
			if (startMinute <= 0 || endMinute < startMinute) {
				continue;
			}
			if (minuteOfDay >= startMinute && minuteOfDay <= endMinute && !inDayOfWeekMask(bar == null ? null : bar.marketDate, skipDowMask)) {
				return true;
			}
		}
		return false;
	}

	private static boolean inMinuteWindow(int minuteOfDay, int startMinute, int endMinute) {
		return startMinute > 0 && endMinute > 0 && endMinute >= startMinute && minuteOfDay >= startMinute && minuteOfDay <= endMinute;
	}

	private static boolean researchWindowRelaxed(String strategyCode) {
		String raw = System.getProperty(RESEARCH_RELAXED_WINDOWS_PROPERTY, "");
		if (raw == null || raw.trim().isEmpty()) {
			return false;
		}
		String normalized = strategyCode == null ? "" : strategyCode.trim().toUpperCase(Locale.US);
		String[] tokens = raw.toUpperCase(Locale.US).split(",");
		for (String token : tokens) {
			String candidate = token.trim();
			if ("ALL".equals(candidate) || normalized.equals(candidate)) {
				return true;
			}
		}
		return false;
	}

	private static boolean patternHardWindowRelaxed(FuturesStrategySettings settings, String strategyCode) {
		return (settings != null && settings.relaxPatternHardWindows) || researchWindowRelaxed(strategyCode);
	}

	private static boolean inOptionalMinuteWindow(int minuteOfDay, int startMinute, int endMinute) {
		return startMinute <= 0 || endMinute <= 0 || inMinuteWindow(minuteOfDay, startMinute, endMinute);
	}

	private static boolean inDayOfWeekMask(LocalDate marketDate, int skipDowMask) {
		if (marketDate == null || skipDowMask <= 0) {
			return false;
		}
		DayOfWeek day = marketDate.getDayOfWeek();
		return (skipDowMask & (1 << day.getValue())) != 0;
	}

	private static boolean inDayOfWeekMinuteWindow(LocalDate marketDate, int minuteOfDay, int skipDowMask, int startMinute, int endMinute) {
		return inDayOfWeekMask(marketDate, skipDowMask) && inMinuteWindow(minuteOfDay, startMinute, endMinute);
	}

	private static boolean inAllowedDayOfWeekMask(LocalDate marketDate, int allowDowMask) {
		if (allowDowMask <= 0) {
			return true;
		}
		if (marketDate == null) {
			return false;
		}
		DayOfWeek day = marketDate.getDayOfWeek();
		return (allowDowMask & (1 << day.getValue())) != 0;
	}

	private static List<Signal> findVwapPullbackSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		boolean relaxedWindow = patternHardWindowRelaxed(settings, "VWAP");
		for (int index = 22; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if ((!relaxedWindow && (bar.marketTime.isBefore(VWAP_START) || bar.marketTime.isAfter(VWAP_END))) || bar.vwap <= 0.0) {
				continue;
			}
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if ((settings.vwapStartMinute > 0 && minuteOfDay < settings.vwapStartMinute)
				|| (settings.vwapEndMinute > 0 && minuteOfDay > settings.vwapEndMinute)
				|| inMinuteWindow(minuteOfDay, settings.vwapSkipStartMinute, settings.vwapSkipEndMinute)) {
				continue;
			}
			double vwapDistanceTicks = Math.abs(bar.close - bar.vwap) / spec.tickSize;
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			double trendSlopeTicks = Math.abs(bar.ema20 - bars.get(Math.max(0, index - 5)).ema20) / spec.tickSize;
			if (vwapDistanceTicks > settings.vwapMaxDistanceTicks || volumeRatio < settings.vwapMinVolumeRatio || trendSlopeTicks < settings.vwapMinTrendSlopeTicks) {
				continue;
			}
			double maxVwapRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.vwapMaxRiskTicks);
			double closeLocation = closeLocation(bar);
		if (settings.allowVwapPullbackLongs
			&& bar.close > bar.vwap
			&& bar.ema9 > bar.ema20
			&& bar.ema20 >= bar.ema50
			&& previous.low <= previous.ema20 + spec.tickSize
			&& bar.close > previous.high
			&& closeLocation >= 0.55
			&& (!settings.vwapRequireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.min(recentSwingLow(bars, index, 4), bar.ema20) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxVwapRiskTicks) {
					signals.add(signal("VWAP", "VWAP Trend Pullback", "LONG", index, bar.close, stop, bar.close + (risk * Math.max(settings.minRewardRisk, 1.1)), 15, "Compressed VWAP/EMA trend-continuation long after pullback holds above VWAP."));
				}
			}
			if (settings.allowShorts
				&& settings.allowVwapPullbackShorts
				&& !inDayOfWeekMask(bar.marketDate, settings.vwapShortSkipDowMask)
				&& bar.close < bar.vwap
				&& bar.ema9 < bar.ema20
				&& bar.ema20 <= bar.ema50
				&& previous.high >= previous.ema20 - spec.tickSize
				&& bar.close < previous.low
				&& closeLocation <= 0.45
				&& (!settings.vwapRequireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.max(recentSwingHigh(bars, index, 4), bar.ema20) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				double rewardMultiple = Math.max(settings.minRewardRisk, 1.1);
				double targetTicks = (risk * rewardMultiple) / spec.tickSize;
				if (risk > 0.0
					&& riskTicks(spec, bar.close, stop) <= maxVwapRiskTicks
					&& (settings.vwapShortMaxTargetTicks <= 0.0 || targetTicks <= settings.vwapShortMaxTargetTicks)) {
					signals.add(signal("VWAP", "VWAP Trend Pullback", "SHORT", index, bar.close, stop, bar.close - (risk * Math.max(settings.minRewardRisk, 1.1)), 15, "Compressed VWAP/EMA trend-continuation short after pullback fails below VWAP."));
				}
			}
		}
		return dedupeByHour(signals, settings.vwapPullback.maxTradesPerDay);
	}

	private static List<Signal> findVwapReclaimSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 80) {
			return signals;
		}
		boolean relaxedWindow = patternHardWindowRelaxed(settings, "VRCL");
		int lastBucket = -1;
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.vwapReclaimMaxRiskTicks);
		int bucketMinutes = Math.max(5, settings.vwapReclaimBucketMinutes);
		for (int index = 35; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if ((!relaxedWindow && (bar.marketTime.isBefore(LocalTime.of(10, 0)) || bar.marketTime.isAfter(LocalTime.of(15, 10)))) || bar.vwap <= 0.0 || previous.vwap <= 0.0) {
				continue;
			}
			int bucket = ((bar.marketTime.getHour() * 60) + bar.marketTime.getMinute()) / bucketMinutes;
			if (bucket == lastBucket) {
				continue;
			}
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			double distanceTicks = Math.abs(bar.close - bar.vwap) / spec.tickSize;
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 8)).ema20) / spec.tickSize;
			if (volumeRatio < settings.vwapReclaimMinVolumeRatio || distanceTicks > settings.vwapMaxDistanceTicks) {
				continue;
			}
			double closeLocation = closeLocation(bar);
			boolean recentVwapTouch = previous.low <= previous.vwap + (spec.tickSize * 2.0)
				&& previous.high >= previous.vwap - (spec.tickSize * 2.0);

			if (settings.allowVwapReclaimLongs
				&& bar.close > bar.vwap + spec.tickSize
				&& recentVwapTouch
				&& previous.close <= previous.vwap + (spec.tickSize * 2.0)
				&& bar.close > previous.high
				&& bar.close > bar.open
				&& bar.ema9 >= bar.ema20
				&& bar.ema20 >= bar.ema50
				&& trendSlopeTicks >= Math.max(0.5, settings.vwapMinTrendSlopeTicks * 0.5)
				&& closeLocation >= 0.58
				&& (!settings.vwapRequireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.min(recentSwingLow(bars, index, 4), bar.vwap) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("VRCL", "VWAP Reclaim Continuation", "LONG", index, bar.close, stop, bar.close + (risk * settings.vwapReclaimRewardRisk), 18, "VWAP reclaim continuation long after a controlled cross back above VWAP with EMA and volume confirmation."));
					lastBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowVwapReclaimShorts
				&& bar.close < bar.vwap - spec.tickSize
				&& recentVwapTouch
				&& previous.close >= previous.vwap - (spec.tickSize * 2.0)
				&& bar.close < previous.low
				&& bar.close < bar.open
				&& bar.ema9 <= bar.ema20
				&& bar.ema20 <= bar.ema50
				&& trendSlopeTicks <= -Math.max(0.5, settings.vwapMinTrendSlopeTicks * 0.5)
				&& closeLocation <= 0.42
				&& (!settings.vwapRequireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.max(recentSwingHigh(bars, index, 4), bar.vwap) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("VRCL", "VWAP Reclaim Continuation", "SHORT", index, bar.close, stop, bar.close - (risk * settings.vwapReclaimRewardRisk), 18, "VWAP reclaim continuation short after a controlled cross back below VWAP with EMA and volume confirmation."));
					lastBucket = bucket;
				}
			}
			if (signals.size() >= settings.vwapReclaim.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findMicroScalpSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 80) {
			return signals;
		}
		int lastBucket = -1;
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.microScalpMaxRiskTicks);
		for (int index = 30; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay < settings.microScalpStartMinute
				|| minuteOfDay > settings.microScalpEndMinute
				|| inMinuteWindow(minuteOfDay, settings.microScalpSkipStartMinute, settings.microScalpSkipEndMinute)
				|| inDayOfWeekMask(bar.marketDate, settings.microScalpSkipDowMask)
				|| bar.vwap <= 0.0) {
				continue;
			}
			int bucket = minuteOfDay / Math.max(5, settings.microScalpBucketMinutes);
			if (bucket == lastBucket) {
				continue;
			}
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.microScalpMinVolumeRatio || bar.bodyPct < settings.microScalpMinBodyPct) {
				continue;
			}
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 8)).ema20) / spec.tickSize;
			double closeLocation = closeLocation(bar);
			if (settings.allowMicroScalpLongs
				&& inMicroScalpSideWindow(minuteOfDay, settings, true)
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.ema20 >= bar.ema50
				&& trendSlopeTicks >= settings.microScalpMinTrendSlopeTicks
				&& previous.low <= Math.max(previous.ema9, previous.ema20) + (spec.tickSize * 2.0)
				&& bar.close > previous.high
				&& closeLocation >= 0.56) {
				double stop = Math.min(recentSwingLow(bars, index, 3), bar.ema20) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MSCALP", "Micro Trend Scalp", "LONG", index, bar.close, stop, bar.close + (risk * settings.microScalpRewardRisk), settings.microScalpMaxHoldBars, "Causal 1-minute futures scalp after VWAP/EMA trend pullback and next-bar execution."));
					lastBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowMicroScalpShorts
				&& inMicroScalpSideWindow(minuteOfDay, settings, false)
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.ema20 <= bar.ema50
				&& trendSlopeTicks <= -settings.microScalpMinTrendSlopeTicks
				&& previous.high >= Math.min(previous.ema9, previous.ema20) - (spec.tickSize * 2.0)
				&& bar.close < previous.low
				&& closeLocation <= 0.44) {
				double stop = Math.max(recentSwingHigh(bars, index, 3), bar.ema20) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MSCALP", "Micro Trend Scalp", "SHORT", index, bar.close, stop, bar.close - (risk * settings.microScalpRewardRisk), settings.microScalpMaxHoldBars, "Causal 1-minute futures scalp after VWAP/EMA trend pullback and next-bar execution."));
					lastBucket = bucket;
				}
			}
			if (signals.size() >= settings.microScalp.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static boolean inMicroScalpSideWindow(int minuteOfDay, FuturesStrategySettings settings, boolean longSide) {
		int startMinute = longSide ? settings.microScalpLongStartMinute : settings.microScalpShortStartMinute;
		int endMinute = longSide ? settings.microScalpLongEndMinute : settings.microScalpShortEndMinute;
		if (startMinute <= 0 || endMinute <= 0) {
			return true;
		}
		return minuteOfDay >= startMinute && minuteOfDay <= endMinute;
	}

	private static List<Signal> findTrendLadderSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 90) {
			return signals;
		}
		int lastLongBucket = -1;
		int lastShortBucket = -1;
		int bucketMinutes = Math.max(3, settings.trendLadderBucketMinutes);
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.trendLadderMaxRiskTicks);
		double pullbackTicks = Math.max(0.0, settings.trendLadderPullbackTicks);
		for (int index = 55; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if (bar == null || previous == null || bar.marketTime == null || bar.marketDate == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
				continue;
			}
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay < settings.trendLadderStartMinute || minuteOfDay > settings.trendLadderEndMinute) {
				continue;
			}
			int bucket = minuteOfDay / bucketMinutes;
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.trendLadderMinVolumeRatio) {
				continue;
			}
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 12)).ema20) / spec.tickSize;
			double closeLocation = closeLocation(bar);
			double distanceToVwapTicks = Math.abs(bar.close - bar.vwap) / spec.tickSize;
			if (distanceToVwapTicks > Math.max(settings.vwapMaxDistanceTicks, pullbackTicks * 6.0)) {
				continue;
			}

			if (settings.allowTrendLadderLongs
				&& bucket != lastLongBucket
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.ema20 >= bar.ema50
				&& trendSlopeTicks >= settings.trendLadderMinTrendSlopeTicks
				&& previous.low <= previous.ema20 + (spec.tickSize * pullbackTicks)
				&& bar.close > previous.high
				&& bar.close > bar.open
				&& closeLocation >= 0.55
				&& bar.rsi14 >= 48.0
				&& bar.rsi14 <= 76.0
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeConstructive(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.min(recentSwingLow(bars, index, 5), bar.ema20) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("TLAD", "Trend Ladder Pullback", "LONG", index, bar.close, stop, bar.close + (risk * settings.trendLadderRewardRisk), settings.trendLadderMaxHoldBars, "Repeated intraday trend-ladder long after EMA/VWAP pullback and continuation confirmation."));
					lastLongBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowTrendLadderShorts
				&& bucket != lastShortBucket
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.ema20 <= bar.ema50
				&& trendSlopeTicks <= -settings.trendLadderMinTrendSlopeTicks
				&& previous.high >= previous.ema20 - (spec.tickSize * pullbackTicks)
				&& bar.close < previous.low
				&& bar.close < bar.open
				&& closeLocation <= 0.45
				&& bar.rsi14 <= 52.0
				&& bar.rsi14 >= 24.0
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.max(recentSwingHigh(bars, index, 5), bar.ema20) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("TLAD", "Trend Ladder Pullback", "SHORT", index, bar.close, stop, bar.close - (risk * settings.trendLadderRewardRisk), settings.trendLadderMaxHoldBars, "Repeated intraday trend-ladder short after EMA/VWAP pullback and continuation confirmation."));
					lastShortBucket = bucket;
				}
			}
			if (signals.size() >= settings.trendLadder.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findRangeCompressionBreakoutSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 90) {
			return signals;
		}
		int boxBars = Math.max(3, settings.rangeCompressionBars);
		int bucketMinutes = Math.max(3, settings.rangeCompressionBucketMinutes);
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.rangeCompressionMaxRiskTicks);
		int lastLongBucket = -1;
		int lastShortBucket = -1;
		for (int index = Math.max(60, boxBars + 2); index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if (bar == null || previous == null || bar.marketTime == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0 || bar.ema50 <= 0.0) {
				continue;
			}
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay < settings.rangeCompressionStartMinute
				|| minuteOfDay > settings.rangeCompressionEndMinute
				|| inMinuteWindow(minuteOfDay, settings.rangeCompressionSkipStartMinute, settings.rangeCompressionSkipEndMinute)) {
				continue;
			}
			double boxHigh = Double.NEGATIVE_INFINITY;
			double boxLow = Double.POSITIVE_INFINITY;
			double totalRangeTicks = 0.0;
			for (int boxIndex = index - boxBars; boxIndex < index; boxIndex++) {
				Bar boxBar = bars.get(boxIndex);
				boxHigh = Math.max(boxHigh, boxBar.high);
				boxLow = Math.min(boxLow, boxBar.low);
				double rangeTicks = boxBar.rangeTicks > 0.0 ? boxBar.rangeTicks : Math.abs(boxBar.high - boxBar.low) / spec.tickSize;
				totalRangeTicks += rangeTicks;
			}
			if (boxHigh <= boxLow) {
				continue;
			}
			double averageRangeTicks = totalRangeTicks / boxBars;
			double atrTicks = bar.atr14 > 0.0 ? bar.atr14 / spec.tickSize : averageRangeTicks;
			double boxWidthTicks = (boxHigh - boxLow) / spec.tickSize;
			if (averageRangeTicks > atrTicks * settings.rangeCompressionMaxAtrRatio || boxWidthTicks > maxRiskTicks) {
				continue;
			}
			double distanceToVwapTicks = Math.abs(bar.close - bar.vwap) / spec.tickSize;
			double distanceToEmaTicks = Math.abs(bar.close - bar.ema20) / spec.tickSize;
			if (Math.min(distanceToVwapTicks, distanceToEmaTicks) > settings.rangeCompressionMaxDistanceTicks) {
				continue;
			}
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.rangeCompressionMinVolumeRatio || bar.bodyPct < settings.rangeCompressionMinBodyPct) {
				continue;
			}
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 12)).ema20) / spec.tickSize;
			double closeLocation = closeLocation(bar);
			int bucket = minuteOfDay / bucketMinutes;

			if (settings.allowRangeCompressionLongs
				&& bucket != lastLongBucket
				&& bar.close > boxHigh + spec.tickSize
				&& previous.close <= boxHigh + spec.tickSize
				&& bar.close > bar.open
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.close >= bar.ema50
				&& trendSlopeTicks >= settings.rangeCompressionMinTrendSlopeTicks
				&& bar.rsi14 >= 48.0
				&& bar.rsi14 <= 76.0
				&& closeLocation >= 0.58
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = boxLow - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("RCB", "Range Compression Breakout", "LONG", index, bar.close, stop, bar.close + (risk * settings.rangeCompressionRewardRisk), settings.rangeCompressionMaxHoldBars, "Tight intraday range compression resolves upward with VWAP, EMA, volume, and next-bar execution filters."));
					lastLongBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowRangeCompressionShorts
				&& bucket != lastShortBucket
				&& bar.close < boxLow - spec.tickSize
				&& previous.close >= boxLow - spec.tickSize
				&& bar.close < bar.open
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.close <= bar.ema50
				&& trendSlopeTicks <= -settings.rangeCompressionMinTrendSlopeTicks
				&& bar.rsi14 <= 52.0
				&& bar.rsi14 >= 24.0
				&& closeLocation <= 0.42
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = boxHigh + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("RCB", "Range Compression Breakout", "SHORT", index, bar.close, stop, bar.close - (risk * settings.rangeCompressionRewardRisk), settings.rangeCompressionMaxHoldBars, "Tight intraday range compression resolves downward with VWAP, EMA, volume, and next-bar execution filters."));
					lastShortBucket = bucket;
				}
			}
			if (signals.size() >= settings.rangeCompressionBreakout.maxTradesPerDay) {
				break;
			}
		}
		return dedupeByHour(signals, settings.rangeCompressionBreakout.maxTradesPerDay);
	}

	private static List<Signal> findValueAreaReclaimSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> previousBars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 80 || previousBars == null || previousBars.size() < 80) {
			return signals;
		}
		VolumeProfile profile = previousSessionVolumeProfile(spec, previousBars, settings);
		if (profile == null || !profile.valid || profile.valueAreaHigh <= profile.valueAreaLow) {
			return signals;
		}
		int lastLongBucket = -1;
		int lastShortBucket = -1;
		int bucketMinutes = Math.max(5, settings.valueAreaBucketMinutes);
		double reclaimDistance = Math.max(1.0, settings.valueAreaReclaimTicks) * spec.tickSize;
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.valueAreaMaxRiskTicks);
		for (int index = 25; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if (bar == null || previous == null || bar.marketTime == null || bar.vwap <= 0.0 || bar.ema20 <= 0.0) {
				continue;
			}
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay < settings.valueAreaStartMinute || minuteOfDay > settings.valueAreaEndMinute) {
				continue;
			}
			int bucket = minuteOfDay / bucketMinutes;
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.valueAreaMinVolumeRatio) {
				continue;
			}
			double closeLocation = closeLocation(bar);
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;

			if (settings.allowValueAreaLongs
				&& bucket != lastLongBucket
				&& bar.low <= profile.valueAreaHigh + reclaimDistance
				&& bar.close > profile.valueAreaHigh + reclaimDistance
				&& previous.close >= profile.valueAreaLow
				&& bar.close > bar.open
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& trendSlopeTicks >= Math.max(0.0, settings.rangeCompressionMinTrendSlopeTicks * 0.5)
				&& closeLocation >= 0.56
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeConstructive(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.min(recentSwingLow(bars, index, 5), profile.valueAreaHigh - reclaimDistance) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("VPB", "Prior Value Area Hold", "LONG", index, bar.close, stop, bar.close + (risk * settings.valueAreaRewardRisk), settings.valueAreaMaxHoldBars, "Prior-session value area high holds as support; approximate volume profile bias is long with VWAP/EMA confirmation."));
					lastLongBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowValueAreaShorts
				&& bucket != lastShortBucket
				&& bar.high >= profile.valueAreaLow - reclaimDistance
				&& bar.close < profile.valueAreaLow - reclaimDistance
				&& previous.close <= profile.valueAreaHigh
				&& bar.close < bar.open
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& trendSlopeTicks <= -Math.max(0.0, settings.rangeCompressionMinTrendSlopeTicks * 0.5)
				&& closeLocation <= 0.44
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.max(recentSwingHigh(bars, index, 5), profile.valueAreaLow + reclaimDistance) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("VPB", "Prior Value Area Rejection", "SHORT", index, bar.close, stop, bar.close - (risk * settings.valueAreaRewardRisk), settings.valueAreaMaxHoldBars, "Prior-session value area low rejects as resistance; approximate volume profile bias is short with VWAP/EMA confirmation."));
					lastShortBucket = bucket;
				}
			}
			if (signals.size() >= settings.valueAreaReclaim.maxTradesPerDay) {
				break;
			}
		}
		return dedupeByHour(signals, settings.valueAreaReclaim.maxTradesPerDay);
	}

	private static VolumeProfile previousSessionVolumeProfile(InstrumentSpec spec, List<Bar> previousBars, FuturesStrategySettings settings) {
		VolumeProfile profile = new VolumeProfile();
		if (spec == null || previousBars == null || previousBars.isEmpty()) {
			return profile;
		}
		double binWidth = Math.max(spec.tickSize, settings.valueAreaBinTicks * spec.tickSize);
		TreeMap<Integer, Double> volumeByBin = new TreeMap<Integer, Double>();
		double totalVolume = 0.0;
		for (int index = 0; index < previousBars.size(); index++) {
			Bar bar = previousBars.get(index);
			if (bar == null || bar.volume <= 0.0) {
				continue;
			}
			double price = bar.vwap > 0.0 ? bar.vwap : ((bar.high + bar.low + bar.close) / 3.0);
			int bin = (int) Math.round(price / binWidth);
			Double existing = volumeByBin.get(bin);
			volumeByBin.put(bin, Double.valueOf((existing == null ? 0.0 : existing.doubleValue()) + bar.volume));
			totalVolume += bar.volume;
		}
		if (volumeByBin.isEmpty() || totalVolume <= 0.0) {
			return profile;
		}
		int pocBin = volumeByBin.firstKey().intValue();
		double pocVolume = -1.0;
		for (Map.Entry<Integer, Double> entry : volumeByBin.entrySet()) {
			if (entry.getValue().doubleValue() > pocVolume) {
				pocVolume = entry.getValue().doubleValue();
				pocBin = entry.getKey().intValue();
			}
		}
		int lowBin = pocBin;
		int highBin = pocBin;
		double selectedVolume = Math.max(0.0, pocVolume);
		double targetVolume = totalVolume * clamp(settings.valueAreaPct, 0.50, 0.90);
		while (selectedVolume < targetVolume) {
			Double lower = volumeByBin.get(Integer.valueOf(lowBin - 1));
			Double upper = volumeByBin.get(Integer.valueOf(highBin + 1));
			double lowerVolume = lower == null ? -1.0 : lower.doubleValue();
			double upperVolume = upper == null ? -1.0 : upper.doubleValue();
			if (lowerVolume < 0.0 && upperVolume < 0.0) {
				break;
			}
			if (upperVolume >= lowerVolume) {
				highBin++;
				selectedVolume += Math.max(0.0, upperVolume);
			} else {
				lowBin--;
				selectedVolume += Math.max(0.0, lowerVolume);
			}
		}
		profile.valid = true;
		profile.pointOfControl = roundToTick(spec, pocBin * binWidth);
		profile.valueAreaLow = roundToTick(spec, (lowBin * binWidth) - (binWidth / 2.0));
		profile.valueAreaHigh = roundToTick(spec, (highBin * binWidth) + (binWidth / 2.0));
		return profile;
	}

	private static List<Signal> findKeltnerScalpSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 80) {
			return signals;
		}
		boolean relaxedWindow = patternHardWindowRelaxed(settings, "KELT");
		int lastBucket = -1;
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.keltnerMaxRiskTicks);
		double atrMultiplier = Math.max(0.7, settings.keltnerAtrMultiplier);
		int bucketMinutes = Math.max(3, settings.keltnerBucketMinutes);
		for (int index = 55; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if ((!relaxedWindow && (bar.marketTime.isBefore(KELTNER_SCALP_START) || bar.marketTime.isAfter(KELTNER_SCALP_END))) || bar.vwap <= 0.0 || bar.atr14 <= 0.0 || bar.ema20 <= 0.0) {
				continue;
			}
			int bucket = ((bar.marketTime.getHour() * 60) + bar.marketTime.getMinute()) / bucketMinutes;
			if (bucket == lastBucket) {
				continue;
			}
			double upperBand = bar.ema20 + (bar.atr14 * atrMultiplier);
			double lowerBand = bar.ema20 - (bar.atr14 * atrMultiplier);
			double bandWidthTicks = (upperBand - lowerBand) / spec.tickSize;
			if (bandWidthTicks < settings.keltnerMinBandWidthTicks) {
				continue;
			}
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.keltnerMinVolumeRatio || bar.bodyPct < settings.keltnerMinBodyPct) {
				continue;
			}
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
			double closeLocation = closeLocation(bar);
			double previousUpperBand = previous.ema20 + (Math.max(0.0, previous.atr14) * atrMultiplier);
			double previousLowerBand = previous.ema20 - (Math.max(0.0, previous.atr14) * atrMultiplier);
			boolean longMomentum = previous.close > previousUpperBand || bar.close > previous.high + spec.tickSize;
			boolean shortMomentum = previous.close < previousLowerBand || bar.close < previous.low - spec.tickSize;

			if (settings.allowKeltnerScalpLongs
				&& bar.close > upperBand
				&& longMomentum
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.ema20 >= bar.ema50
				&& trendSlopeTicks >= settings.keltnerMinTrendSlopeTicks
				&& bar.rsi14 >= 50.0
				&& closeLocation >= 0.56
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedLongStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("KELT", "Keltner ATR Breakout Scalp", "LONG", index, bar.close, stop, bar.close + (risk * settings.keltnerRewardRisk), settings.keltnerMaxHoldBars, "1-minute Keltner/ATR volatility breakout scalp with VWAP, EMA, RSI, volume, and next-bar execution filters."));
					lastBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowKeltnerScalpShorts
				&& bar.close < lowerBand
				&& shortMomentum
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.ema20 <= bar.ema50
				&& trendSlopeTicks <= -settings.keltnerMinTrendSlopeTicks
				&& bar.rsi14 <= 50.0
				&& closeLocation <= 0.44
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedShortStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("KELT", "Keltner ATR Breakout Scalp", "SHORT", index, bar.close, stop, bar.close - (risk * settings.keltnerRewardRisk), settings.keltnerMaxHoldBars, "1-minute Keltner/ATR volatility breakout scalp with VWAP, EMA, RSI, volume, and next-bar execution filters."));
					lastBucket = bucket;
				}
			}
			if (signals.size() >= settings.keltnerScalp.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findKeltnerReversionSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 80) {
			return signals;
		}
		boolean relaxedWindow = patternHardWindowRelaxed(settings, "KREV");
		int lastBucket = -1;
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.keltnerMaxRiskTicks);
		double atrMultiplier = Math.max(0.7, settings.keltnerAtrMultiplier);
		double maxTrendSlopeTicks = Math.max(3.0, settings.keltnerMinTrendSlopeTicks * 8.0);
		int bucketMinutes = Math.max(3, settings.keltnerBucketMinutes);
		for (int index = 55; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if ((!relaxedWindow && (bar.marketTime.isBefore(LocalTime.of(10, 0)) || bar.marketTime.isAfter(KELTNER_SCALP_END))) || bar.vwap <= 0.0 || bar.atr14 <= 0.0 || bar.ema20 <= 0.0) {
				continue;
			}
			int bucket = ((bar.marketTime.getHour() * 60) + bar.marketTime.getMinute()) / bucketMinutes;
			if (bucket == lastBucket) {
				continue;
			}
			double upperBand = bar.ema20 + (bar.atr14 * atrMultiplier);
			double lowerBand = bar.ema20 - (bar.atr14 * atrMultiplier);
			double previousUpperBand = previous.ema20 + (Math.max(0.0, previous.atr14) * atrMultiplier);
			double previousLowerBand = previous.ema20 - (Math.max(0.0, previous.atr14) * atrMultiplier);
			double bandWidthTicks = (upperBand - lowerBand) / spec.tickSize;
			double distanceToVwapTicks = Math.abs(bar.close - bar.vwap) / spec.tickSize;
			if (bandWidthTicks < settings.keltnerMinBandWidthTicks || distanceToVwapTicks > settings.vwapMaxDistanceTicks) {
				continue;
			}
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.keltnerMinVolumeRatio || bar.bodyPct < settings.keltnerMinBodyPct) {
				continue;
			}
			double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
			if (Math.abs(trendSlopeTicks) > maxTrendSlopeTicks) {
				continue;
			}
			double closeLocation = closeLocation(bar);

			if (settings.allowKeltnerScalpLongs
				&& previous.close < previousLowerBand
				&& bar.close > lowerBand
				&& bar.close > previous.high
				&& bar.rsi14 <= 48.0
				&& closeLocation >= 0.56
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeConstructive(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedLongStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = bar.close - stop;
				double target = Math.min(bar.ema20, bar.close + (risk * settings.keltnerRewardRisk));
				if (risk > 0.0 && target > bar.close + (spec.tickSize * 2.0) && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("KREV", "Keltner Band Reclaim Reversion", "LONG", index, bar.close, stop, target, settings.keltnerMaxHoldBars, "1-minute Keltner lower-band reclaim mean-reversion scalp in flatter VWAP/EMA conditions."));
					lastBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowKeltnerScalpShorts
				&& previous.close > previousUpperBand
				&& bar.close < upperBand
				&& bar.close < previous.low
				&& bar.rsi14 >= 52.0
				&& closeLocation <= 0.44
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedShortStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = stop - bar.close;
				double target = Math.max(bar.ema20, bar.close - (risk * settings.keltnerRewardRisk));
				if (risk > 0.0 && target < bar.close - (spec.tickSize * 2.0) && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("KREV", "Keltner Band Reclaim Reversion", "SHORT", index, bar.close, stop, target, settings.keltnerMaxHoldBars, "1-minute Keltner upper-band reclaim mean-reversion scalp in flatter VWAP/EMA conditions."));
					lastBucket = bucket;
				}
			}
			if (signals.size() >= settings.keltnerReversion.maxTradesPerDay) {
				break;
			}
		}
		return signals;
	}

	private static List<Signal> findMeanReversionSignals(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		boolean relaxedWindow = patternHardWindowRelaxed(settings, "MRVWAP");
		double[] rsi = rsi(bars, RSI_PERIOD);
		for (int index = 25; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			Bar previous = bars.get(index - 1);
			if ((!relaxedWindow && (bar.marketTime.isBefore(MEAN_REVERSION_START) || bar.marketTime.isAfter(MEAN_REVERSION_END))) || bar.vwap <= 0.0) {
				continue;
			}
			double distanceTicks = Math.abs(bar.close - bar.vwap) / spec.tickSize;
			if (distanceTicks < settings.meanReversionMinDistanceTicks) {
				continue;
			}
			if (bar.close < bar.vwap && rsi[index] < settings.meanReversionOversoldRsi && bar.close > previous.high && closeLocation(bar) >= 0.55) {
				double stop = Math.min(bar.low, previous.low) - (spec.tickSize * 2.0);
				signals.add(signal("MRVWAP", "VWAP Mean Reversion", "LONG", index, bar.close, stop, Math.min(bar.vwap, bar.close + ((bar.close - stop) * Math.max(settings.minRewardRisk, 1.35))), "Mean reversion long after stretched move below VWAP."));
			}
			if (settings.allowShorts && bar.close > bar.vwap && rsi[index] > settings.meanReversionOverboughtRsi && bar.close < previous.low && closeLocation(bar) <= 0.45) {
				double stop = Math.max(bar.high, previous.high) + (spec.tickSize * 2.0);
				signals.add(signal("MRVWAP", "VWAP Mean Reversion", "SHORT", index, bar.close, stop, Math.max(bar.vwap, bar.close - ((stop - bar.close) * Math.max(settings.minRewardRisk, 1.35))), "Mean reversion short after stretched move above VWAP."));
			}
		}
		return dedupeByHour(signals, settings.vwapMeanReversion.maxTradesPerDay);
	}

	private static List<Signal> findAfternoonContinuationSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 120) {
			return signals;
		}

		double maxRiskTicks = Math.min(settings.afternoonMaxRiskTicks, settings.maxInitialRiskTicks);
		double minTrendSlopeTicks = Math.max(1.0, settings.vwapMinTrendSlopeTicks * 0.5);
		for (int index = 60; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay < settings.afternoonStartMinute
				|| minuteOfDay > settings.afternoonEndMinute
				|| inMinuteWindow(minuteOfDay, settings.afternoonSkipStartMinute, settings.afternoonSkipEndMinute)
				|| bar.vwap <= 0.0) {
				continue;
			}
				double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
				if (volumeRatio < settings.afternoonMinVolumeRatio || bar.bodyPct < settings.afternoonMinBodyPct) {
					continue;
				}
				double signalRangeTicks = riskTicks(spec, bar.high, bar.low);
				if (settings.afternoonMaxSignalRangeTicks > 0.0 && signalRangeTicks > settings.afternoonMaxSignalRangeTicks) {
					continue;
				}
				double closeLocation = closeLocation(bar);
				double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
			double channelHigh = recentSwingHigh(bars, index - 1, settings.afternoonChannelBars);
			double channelLow = recentSwingLow(bars, index - 1, settings.afternoonChannelBars);

			if (settings.allowAfternoonContinuationLongs
				&& inOptionalMinuteWindow(minuteOfDay, settings.afternoonLongStartMinute, settings.afternoonLongEndMinute)
				&& bar.close > channelHigh + spec.tickSize
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& bar.close >= bar.ema50
				&& trendSlopeTicks >= minTrendSlopeTicks
				&& closeLocation >= 0.55
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedLongStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("AFT", "Afternoon Continuation", "LONG", index, bar.close, stop, bar.close + (risk * settings.afternoonRewardRisk), settings.afternoonMaxHoldBars, "Afternoon local-range continuation long with VWAP, EMA, volume, and next-bar execution filters."));
				}
			}
			if (settings.allowShorts
				&& settings.allowAfternoonContinuationShorts
				&& !inDayOfWeekMask(bar.marketDate, settings.afternoonShortSkipDowMask)
				&& inOptionalMinuteWindow(minuteOfDay, settings.afternoonShortStartMinute, settings.afternoonShortEndMinute)
				&& bar.close < channelLow - spec.tickSize
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& bar.close <= bar.ema50
				&& trendSlopeTicks <= -minTrendSlopeTicks
				&& closeLocation <= 0.45
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedShortStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("AFT", "Afternoon Continuation", "SHORT", index, bar.close, stop, bar.close - (risk * settings.afternoonRewardRisk), settings.afternoonMaxHoldBars, "Afternoon local-range continuation short with VWAP, EMA, volume, and next-bar execution filters."));
				}
			}
			if (signals.size() >= settings.afternoonContinuation.maxTradesPerDay) {
				break;
			}
		}
		return dedupeByHour(signals, settings.afternoonContinuation.maxTradesPerDay);
	}

	private static List<Signal> findMarketIntradayMomentumSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 300) {
			return signals;
		}

		Bar openBar = null;
		Bar firstHalfHourCloseBar = null;
		Bar lateReferenceBar = null;
		double openingHigh = Double.NEGATIVE_INFINITY;
		double openingLow = Double.POSITIVE_INFINITY;
		double openingVolumeRatioTotal = 0.0;
		int openingVolumeRatioCount = 0;
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (openBar == null && !bar.marketTime.isBefore(RTH_START)) {
				openBar = bar;
			}
			if (!bar.marketTime.isBefore(RTH_START) && bar.marketTime.isBefore(MARKET_INTRADAY_MOMENTUM_OPEN_END)) {
				firstHalfHourCloseBar = bar;
				openingHigh = Math.max(openingHigh, bar.high);
				openingLow = Math.min(openingLow, bar.low);
				if (bar.volumeSma20 > 0.0) {
					openingVolumeRatioTotal += bar.volume / bar.volumeSma20;
					openingVolumeRatioCount++;
				}
			}
			if (lateReferenceBar == null && !bar.marketTime.isBefore(MARKET_INTRADAY_MOMENTUM_LATE_START)) {
				lateReferenceBar = bar;
			}
		}
		if (openBar == null || firstHalfHourCloseBar == null || lateReferenceBar == null || openingHigh <= openingLow) {
			return signals;
		}

		double firstMoveTicks = (firstHalfHourCloseBar.close - openBar.open) / spec.tickSize;
		double openingRangeTicks = (openingHigh - openingLow) / spec.tickSize;
		double minimumOpeningMove = settings.marketIntradayMomentumMinOpenMoveTicks;
		if (Math.abs(firstMoveTicks) < minimumOpeningMove || openingRangeTicks < minimumOpeningMove * 1.2) {
			return signals;
		}

		double maxRiskTicks = Math.min(settings.marketIntradayMomentumMaxRiskTicks, settings.maxInitialRiskTicks);
		double impulseRewardRisk = settings.marketImpulsePullbackRewardRisk > 0.0
			? settings.marketImpulsePullbackRewardRisk
			: settings.marketIntradayMomentumRewardRisk;
		double averageOpeningVolumeRatio = openingVolumeRatioCount == 0 ? 1.0 : openingVolumeRatioTotal / openingVolumeRatioCount;
		boolean strongOpeningContext = openingRangeTicks >= minimumOpeningMove * 1.6
			|| averageOpeningVolumeRatio >= settings.marketIntradayMomentumMinVolumeRatio + 0.25;
		int pullbackSignals = 0;
		int lastPullbackBucket = -1;
		for (int index = 60; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (bar.vwap <= 0.0) {
				continue;
			}
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.marketIntradayMomentumMinVolumeRatio) {
				continue;
			}
			double closeLocation = closeLocation(bar);
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (settings.marketIntradayMomentum.maxTradesPerDay > 1
				&& strongOpeningContext
				&& !bar.marketTime.isBefore(MARKET_IMPULSE_PULLBACK_START)
				&& !bar.marketTime.isAfter(MARKET_IMPULSE_PULLBACK_END)
				&& minuteOfDay >= settings.marketImpulsePullbackStartMinute
				&& minuteOfDay <= settings.marketImpulsePullbackEndMinute
				&& !inMinuteWindow(minuteOfDay, settings.marketImpulsePullbackSkipStartMinute, settings.marketImpulsePullbackSkipEndMinute)
				&& pullbackSignals < settings.marketIntradayMomentum.maxTradesPerDay) {
				Bar previous = bars.get(index - 1);
				double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
				int bucket = ((bar.marketTime.getHour() * 60) + bar.marketTime.getMinute()) / 30;
				if (bucket != lastPullbackBucket) {
					if (settings.allowMarketIntradayMomentumLongs
						&& !inDayOfWeekMask(bar.marketDate, settings.marketImpulsePullbackLongSkipDowMask)
						&& firstMoveTicks > 0.0
						&& bar.close > bar.vwap
						&& bar.ema9 >= bar.ema20
						&& bar.ema20 >= bar.ema50
						&& trendSlopeTicks >= Math.max(1.0, settings.marketIntradayMomentumMinLateMoveTicks * 0.25)
						&& previous.low <= Math.max(previous.vwap, previous.ema20) + (spec.tickSize * 2.0)
						&& bar.close > previous.high
						&& closeLocation >= 0.55
						&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
						double stop = compressedLongStop(spec, bars, index, bar.close, maxRiskTicks);
						double risk = bar.close - stop;
						if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
							signals.add(signal("IPB", "Opening Impulse Pullback", "LONG", index, bar.close, stop, bar.close + (risk * Math.max(0.85, impulseRewardRisk)), 25, "First-half-hour directional impulse followed by VWAP/EMA pullback continuation with opening volume/volatility confirmation."));
							pullbackSignals++;
							lastPullbackBucket = bucket;
						}
					}
					if (settings.allowShorts
						&& settings.allowMarketIntradayMomentumShorts
						&& !inDayOfWeekMask(bar.marketDate, settings.marketImpulsePullbackShortSkipDowMask)
						&& firstMoveTicks < 0.0
						&& bar.close < bar.vwap
						&& bar.ema9 <= bar.ema20
						&& bar.ema20 <= bar.ema50
						&& trendSlopeTicks <= -Math.max(1.0, settings.marketIntradayMomentumMinLateMoveTicks * 0.25)
						&& previous.high >= Math.min(previous.vwap, previous.ema20) - (spec.tickSize * 2.0)
						&& bar.close < previous.low
						&& closeLocation <= 0.45
						&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
						double stop = compressedShortStop(spec, bars, index, bar.close, maxRiskTicks);
						double risk = stop - bar.close;
						if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
							signals.add(signal("IPB", "Opening Impulse Pullback", "SHORT", index, bar.close, stop, bar.close - (risk * Math.max(0.85, impulseRewardRisk)), 25, "First-half-hour directional impulse followed by VWAP/EMA pullback continuation with opening volume/volatility confirmation."));
							pullbackSignals++;
							lastPullbackBucket = bucket;
						}
					}
				}
			}

			if (bar.marketTime.isBefore(MARKET_INTRADAY_MOMENTUM_SIGNAL_START) || bar.marketTime.isAfter(MARKET_INTRADAY_MOMENTUM_SIGNAL_END)) {
				continue;
			}
			double lateMoveTicks = (bar.close - lateReferenceBar.open) / spec.tickSize;
			if (Math.abs(lateMoveTicks) < settings.marketIntradayMomentumMinLateMoveTicks || Math.signum(firstMoveTicks) != Math.signum(lateMoveTicks)) {
				continue;
			}
			if (settings.allowMarketIntradayMomentumLongs
				&& firstMoveTicks > 0.0
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& closeLocation >= 0.55
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedLongStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MIM", "Market Intraday Momentum", "LONG", index, bar.close, stop, bar.close + (risk * settings.marketIntradayMomentumRewardRisk), 35, "Late-session long when first-half-hour and late-session futures momentum align with VWAP/EMA confirmation."));
					break;
				}
			}
			if (settings.allowShorts
				&& settings.allowMarketIntradayMomentumShorts
				&& firstMoveTicks < 0.0
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& closeLocation <= 0.45
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = compressedShortStop(spec, bars, index, bar.close, maxRiskTicks);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("MIM", "Market Intraday Momentum", "SHORT", index, bar.close, stop, bar.close - (risk * settings.marketIntradayMomentumRewardRisk), 35, "Late-session short when first-half-hour and late-session futures momentum align with VWAP/EMA confirmation."));
					break;
				}
			}
		}
		return dedupeByHour(signals, settings.marketIntradayMomentum.maxTradesPerDay);
	}

	private static List<Signal> findSweepSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> previousBars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (previousBars == null || previousBars.isEmpty()) {
			return signals;
		}
		boolean relaxedWindow = patternHardWindowRelaxed(settings, "SWEEP");
		double previousHigh = highest(previousBars);
		double previousLow = lowest(previousBars);
		double maxSweepRiskTicks = Math.min(DEFAULT_SWEEP_MAX_RISK_TICKS, settings.maxInitialRiskTicks);
		for (int index = 20; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			if (!relaxedWindow && (bar.marketTime.isBefore(SWEEP_START) || bar.marketTime.isAfter(SWEEP_END))) {
				continue;
			}
			if (bar.low < previousLow - spec.tickSize && bar.close > previousLow && bar.close > bar.open) {
				boolean lateAfternoon = !bar.marketTime.isBefore(LocalTime.of(13, 45));
				double reclaimTicks = (bar.close - previousLow) / spec.tickSize;
				double closeLocation = closeLocation(bar);
				if (settings.requireHigherTimeframeGuard && !higherTimeframeConstructive(fifteenMinuteBars, oneHourBars, bar.marketTime)) {
					continue;
				}
				if (lateAfternoon && settings.enableLateSweep) {
					if (reclaimTicks < settings.lateSweepReclaimTicks || closeLocation < settings.lateSweepCloseLocation) {
						continue;
					}
					double stop = bar.low - (spec.tickSize * 2.0);
					if (riskTicks(spec, bar.close, stop) > maxSweepRiskTicks) {
						continue;
					}
					signals.add(signal("SWEEP", "Prior-Day Liquidity Sweep", "LONG", index, bar.close, stop, bar.close + ((bar.close - stop) * Math.max(settings.minRewardRisk, 1.0)), "Late-afternoon long after sweeping prior-day low and closing back above it."));
				}
				if (!lateAfternoon && settings.enableEarlySweep && settings.enableSweepSecondChance) {
					if (reclaimTicks < settings.earlySweepReclaimTicks || closeLocation < settings.sweepCloseLocation || bar.bodyPct < settings.minBodyPct || index + 1 >= bars.size()) {
						continue;
					}
					Bar confirmation = bars.get(index + 1);
					if (confirmation.close <= bar.high || confirmation.close <= previousLow + (spec.tickSize * 2.0)) {
						continue;
					}
					double stop = Math.min(bar.low, confirmation.low) - (spec.tickSize * 2.0);
					if (riskTicks(spec, confirmation.close, stop) > maxSweepRiskTicks) {
						continue;
					}
					signals.add(signal("SWEEP2", "Confirmed Prior-Day Sweep", "LONG", index + 1, confirmation.close, stop, confirmation.close + ((confirmation.close - stop) * Math.max(settings.minRewardRisk, 1.25)), "Early-afternoon confirmed long after prior-day low sweep, strong reclaim, and next-bar continuation."));
				}
				if (signals.size() >= settings.sweep.maxTradesPerDay) {
					break;
				}
			}
			if (settings.allowShorts && bar.high > previousHigh + spec.tickSize && bar.close < previousHigh && bar.close < bar.open) {
				int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
				if (inMinuteWindow(minuteOfDay, settings.sweepShortSkipStartMinute, settings.sweepShortSkipEndMinute)) {
					continue;
				}
				boolean lateAfternoon = !bar.marketTime.isBefore(LocalTime.of(13, 45));
				double reclaimTicks = (previousHigh - bar.close) / spec.tickSize;
				double closeLocation = 1.0 - closeLocation(bar);
					if (settings.requireHigherTimeframeGuard && higherTimeframeConstructive(fifteenMinuteBars, oneHourBars, bar.marketTime)) {
						continue;
					}
						if (!lateAfternoon || reclaimTicks < settings.lateSweepReclaimTicks || closeLocation < settings.lateSweepCloseLocation) {
							continue;
						}
						if (bar.bodyPct < settings.sweepShortMinBodyPct) {
							continue;
						}
						if (bar.rsi14 > settings.sweepShortMaxRsi) {
							continue;
						}
					double stop = bar.high + (spec.tickSize * 2.0);
				if (riskTicks(spec, bar.close, stop) > maxSweepRiskTicks) {
					continue;
				}
				signals.add(signal("SWEEP", "Prior-Day Liquidity Sweep", "SHORT", index, bar.close, stop, bar.close - ((stop - bar.close) * Math.max(settings.minRewardRisk, 1.0)), "Late-afternoon short after sweeping prior-day high and closing back below it."));
				if (signals.size() >= settings.sweep.maxTradesPerDay) {
					break;
				}
			}
		}
		return dedupeByHour(signals, settings.sweep.maxTradesPerDay);
	}

	private static List<Signal> findPriorDayBreakoutSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> previousBars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (previousBars == null || previousBars.isEmpty() || bars == null || bars.size() < 80) {
			return signals;
		}
		double previousHigh = highest(previousBars);
		double previousLow = lowest(previousBars);
		double maxRiskTicks = Math.min(settings.maxInitialRiskTicks, settings.priorDayBreakoutMaxRiskTicks);
		int bucketMinutes = Math.max(10, settings.priorDayBreakoutBucketMinutes);
		int lastLongBucket = -1;
		int lastShortBucket = -1;
		boolean acceptedLongBreak = false;
		boolean acceptedShortBreak = false;
		for (int index = 30; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
			if (minuteOfDay > settings.priorDayBreakoutEndMinute) {
				break;
			}
			double breakTicksLong = (bar.high - previousHigh) / spec.tickSize;
			double breakTicksShort = (previousLow - bar.low) / spec.tickSize;
			if (breakTicksLong >= settings.priorDayBreakoutMinBreakTicks && bar.close > previousHigh) {
				acceptedLongBreak = true;
			}
			if (breakTicksShort >= settings.priorDayBreakoutMinBreakTicks && bar.close < previousLow) {
				acceptedShortBreak = true;
			}
			if (minuteOfDay < settings.priorDayBreakoutStartMinute || bar.vwap <= 0.0) {
				continue;
			}
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.priorDayBreakoutMinVolumeRatio) {
				continue;
			}
			int bucket = minuteOfDay / bucketMinutes;
			double retestDistance = settings.priorDayBreakoutRetestTicks * spec.tickSize;
			double closeLocation = closeLocation(bar);
			if (settings.allowPriorDayBreakoutLongs
				&& acceptedLongBreak
				&& bucket != lastLongBucket
				&& !inMinuteWindow(minuteOfDay, settings.priorDayBreakoutLongSkipStartMinute, settings.priorDayBreakoutLongSkipEndMinute)
				&& bar.low <= previousHigh + retestDistance
				&& bar.close > previousHigh + spec.tickSize
				&& bar.close > bar.open
				&& bar.close > bar.vwap
				&& bar.ema9 >= bar.ema20
				&& closeLocation >= 0.55
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.min(recentSwingLow(bars, index, 5), previousHigh - retestDistance) - (spec.tickSize * 2.0);
				double risk = bar.close - stop;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("PDB", "Prior-Day Breakout Retest", "LONG", index, bar.close, stop, bar.close + (risk * settings.priorDayBreakoutRewardRisk), 35, "Accepted prior-day high breakout retest with VWAP/EMA continuation confirmation."));
					lastLongBucket = bucket;
				}
			}
			if (settings.allowShorts
				&& settings.allowPriorDayBreakoutShorts
				&& acceptedShortBreak
				&& bucket != lastShortBucket
				&& !inMinuteWindow(minuteOfDay, settings.priorDayBreakoutShortSkipStartMinute, settings.priorDayBreakoutShortSkipEndMinute)
				&& !inMinuteWindow(minuteOfDay, settings.priorDayBreakoutShortSecondSkipStartMinute, settings.priorDayBreakoutShortSecondSkipEndMinute)
				&& !inMinuteWindow(minuteOfDay, settings.priorDayBreakoutShortThirdSkipStartMinute, settings.priorDayBreakoutShortThirdSkipEndMinute)
				&& bar.high >= previousLow - retestDistance
				&& bar.close < previousLow - spec.tickSize
				&& bar.close < bar.open
				&& bar.close < bar.vwap
				&& bar.ema9 <= bar.ema20
				&& closeLocation <= 0.45
				&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
				double stop = Math.max(recentSwingHigh(bars, index, 5), previousLow + retestDistance) + (spec.tickSize * 2.0);
				double risk = stop - bar.close;
				if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxRiskTicks) {
					signals.add(signal("PDB", "Prior-Day Breakout Retest", "SHORT", index, bar.close, stop, bar.close - (risk * settings.priorDayBreakoutRewardRisk), 35, "Accepted prior-day low breakdown retest with VWAP/EMA continuation confirmation."));
					lastShortBucket = bucket;
				}
			}
			if (signals.size() >= settings.priorDayBreakout.maxTradesPerDay) {
				break;
			}
		}
		return dedupeByHour(signals, settings.priorDayBreakout.maxTradesPerDay);
	}

	private static List<Signal> findFvgSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> previousBars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		double maxRiskTicks = Math.min(settings.fvgMaxRiskTicks, settings.maxInitialRiskTicks);
		for (int index = 2; index < bars.size(); index++) {
			Bar first = bars.get(index - 2);
			Bar middle = bars.get(index - 1);
			Bar third = bars.get(index);
			int minuteOfDay = (third.marketTime.getHour() * 60) + third.marketTime.getMinute();
			if (minuteOfDay < settings.fvgStartMinute
				|| minuteOfDay > settings.fvgEndMinute
				|| inMinuteWindow(minuteOfDay, settings.fvgSkipStartMinute, settings.fvgSkipEndMinute)) {
				continue;
			}
			double middleVolumeRatio = middle.volumeSma20 <= 0.0 ? 1.0 : middle.volume / middle.volumeSma20;
			double thirdVolumeRatio = third.volumeSma20 <= 0.0 ? 1.0 : third.volume / third.volumeSma20;
			if (Math.max(middleVolumeRatio, thirdVolumeRatio) < settings.fvgMinVolumeRatio) {
				continue;
			}
			if (settings.allowFvgLongs && !inDayOfWeekMask(third.marketDate, settings.fvgLongSkipDowMask) && first.high < third.low && middle.close > middle.open) {
				double gapLow = first.high;
				double gapHigh = third.low;
				double widthTicks = (gapHigh - gapLow) / spec.tickSize;
				if (widthTicks >= settings.fvgMinWidthTicks) {
					for (int entryIndex = index + 1; entryIndex < Math.min(index + settings.fvgRetestBars, bars.size()); entryIndex++) {
						Bar entry = bars.get(entryIndex);
						if (entry.close < gapLow) {
							break;
						}
						int entryMinuteOfDay = (entry.marketTime.getHour() * 60) + entry.marketTime.getMinute();
						if (inDayOfWeekMinuteWindow(entry.marketDate, entryMinuteOfDay, settings.fvgLongDowWindowSkipMask, settings.fvgLongDowWindowSkipStartMinute, settings.fvgLongDowWindowSkipEndMinute)) {
							continue;
						}
						double entryVolumeRatio = entry.volumeSma20 <= 0.0 ? 1.0 : entry.volume / entry.volumeSma20;
						if (entry.low <= gapHigh
							&& entry.low >= gapLow - (spec.tickSize * 2.0)
							&& entry.close > gapHigh
							&& entry.close > entry.open
							&& closeLocation(entry) >= 0.58
							&& entryVolumeRatio >= settings.fvgMinVolumeRatio
							&& fvgCoreQualityPass(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings, index, entryIndex, "LONG", gapLow, gapHigh)) {
							int acceptedIndex = fvgAcceptanceIndex(spec, bars, settings, entryIndex, "LONG", gapLow, gapHigh);
							if (acceptedIndex < 0) {
								continue;
							}
							Bar accepted = bars.get(acceptedIndex);
							double stop = Math.min(gapLow - (spec.tickSize * 2.0), recentSwingLow(bars, acceptedIndex, 5) - (spec.tickSize * 2.0));
							double minRisk = settings.fvgMinRiskTicks * spec.tickSize;
							if (accepted.close - stop < minRisk) {
								stop = accepted.close - minRisk;
							}
							double risk = accepted.close - stop;
							if (risk > 0.0 && riskTicks(spec, accepted.close, stop) <= maxRiskTicks) {
								signals.add(signal("FVG", "Fair Value Gap Reclaim", "LONG", acceptedIndex, accepted.close, stop, accepted.close + (risk * settings.fvgRewardRisk), settings.fvgMaxHoldBars, fvgSignalNotes(spec, "Bullish", gapLow, gapHigh, index, acceptedIndex, settings)));
								break;
							}
						}
					}
				}
			}
			if (settings.allowShorts && settings.allowFvgShorts && !inDayOfWeekMask(third.marketDate, settings.fvgShortSkipDowMask) && first.low > third.high && middle.close < middle.open) {
				double gapLow = third.high;
				double gapHigh = first.low;
				double widthTicks = (gapHigh - gapLow) / spec.tickSize;
				if (widthTicks < settings.fvgMinWidthTicks) {
					continue;
				}
				for (int entryIndex = index + 1; entryIndex < Math.min(index + settings.fvgRetestBars, bars.size()); entryIndex++) {
					Bar entry = bars.get(entryIndex);
					if (entry.close > gapHigh) {
						break;
					}
					int entryMinuteOfDay = (entry.marketTime.getHour() * 60) + entry.marketTime.getMinute();
					if (inDayOfWeekMinuteWindow(entry.marketDate, entryMinuteOfDay, settings.fvgShortDowWindowSkipMask, settings.fvgShortDowWindowSkipStartMinute, settings.fvgShortDowWindowSkipEndMinute)) {
						continue;
					}
					double entryVolumeRatio = entry.volumeSma20 <= 0.0 ? 1.0 : entry.volume / entry.volumeSma20;
					if (entry.high >= gapLow
						&& entry.high <= gapHigh + (spec.tickSize * 2.0)
						&& entry.close < gapLow
						&& entry.close < entry.open
						&& closeLocation(entry) <= 0.42
						&& entryVolumeRatio >= settings.fvgMinVolumeRatio
						&& fvgCoreQualityPass(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings, index, entryIndex, "SHORT", gapLow, gapHigh)) {
						int acceptedIndex = fvgAcceptanceIndex(spec, bars, settings, entryIndex, "SHORT", gapLow, gapHigh);
						if (acceptedIndex < 0) {
							continue;
						}
						Bar accepted = bars.get(acceptedIndex);
						double stop = Math.max(gapHigh + (spec.tickSize * 2.0), recentSwingHigh(bars, acceptedIndex, 5) + (spec.tickSize * 2.0));
						double minRisk = settings.fvgMinRiskTicks * spec.tickSize;
						if (stop - accepted.close < minRisk) {
							stop = accepted.close + minRisk;
						}
						double risk = stop - accepted.close;
						if (risk > 0.0 && riskTicks(spec, accepted.close, stop) <= maxRiskTicks) {
							signals.add(signal("FVG", "Fair Value Gap Reclaim", "SHORT", acceptedIndex, accepted.close, stop, accepted.close - (risk * settings.fvgRewardRisk), settings.fvgMaxHoldBars, fvgSignalNotes(spec, "Bearish", gapLow, gapHigh, index, acceptedIndex, settings)));
							break;
						}
					}
				}
			}
		}
		return dedupeByHour(signals, settings.fvg.maxTradesPerDay);
	}

	private static List<Signal> findIfvgSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> previousBars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (spec == null || bars == null || settings == null) {
			return signals;
		}
		double maxRiskTicks = Math.min(settings.fvgMaxRiskTicks, settings.maxInitialRiskTicks);
		double breakDistance = Math.max(0.0, settings.fvgMinSourceBreakTicks) * spec.tickSize;
		for (int index = 2; index < bars.size(); index++) {
			Bar first = bars.get(index - 2);
			Bar middle = bars.get(index - 1);
			Bar third = bars.get(index);
			int minuteOfDay = minuteOfDay(third);
			if (minuteOfDay < settings.fvgStartMinute
				|| minuteOfDay > settings.fvgEndMinute
				|| inMinuteWindow(minuteOfDay, settings.fvgSkipStartMinute, settings.fvgSkipEndMinute)) {
				continue;
			}
			double middleVolumeRatio = middle.volumeSma20 <= 0.0 ? 1.0 : middle.volume / middle.volumeSma20;
			double thirdVolumeRatio = third.volumeSma20 <= 0.0 ? 1.0 : third.volume / third.volumeSma20;
			if (Math.max(middleVolumeRatio, thirdVolumeRatio) < settings.fvgMinVolumeRatio) {
				continue;
			}
			if (settings.allowShorts && settings.allowFvgShorts && !inDayOfWeekMask(third.marketDate, settings.fvgShortSkipDowMask) && first.high < third.low && middle.close > middle.open) {
				double gapLow = first.high;
				double gapHigh = third.low;
				double widthTicks = (gapHigh - gapLow) / spec.tickSize;
				if (widthTicks >= settings.fvgMinWidthTicks) {
					int invalidationIndex = ifvgInvalidationIndex(spec, bars, settings, index, true, gapLow, gapHigh, breakDistance);
					if (invalidationIndex >= 0) {
						for (int entryIndex = invalidationIndex + 1; entryIndex < Math.min(invalidationIndex + settings.fvgRetestBars, bars.size()); entryIndex++) {
							Bar entry = bars.get(entryIndex);
							int entryMinuteOfDay = minuteOfDay(entry);
							if (inDayOfWeekMinuteWindow(entry.marketDate, entryMinuteOfDay, settings.fvgShortDowWindowSkipMask, settings.fvgShortDowWindowSkipStartMinute, settings.fvgShortDowWindowSkipEndMinute)) {
								continue;
							}
							double entryVolumeRatio = entry.volumeSma20 <= 0.0 ? 1.0 : entry.volume / entry.volumeSma20;
							if (entry.high >= gapLow - (spec.tickSize * 2.0)
								&& entry.high <= gapHigh + (spec.tickSize * 2.0)
								&& entry.close < gapLow - breakDistance
								&& entry.close < entry.open
								&& closeLocation(entry) <= 0.42
								&& entryVolumeRatio >= settings.fvgMinVolumeRatio
								&& ifvgQualityPass(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings, index, invalidationIndex, entryIndex, "SHORT", gapLow, gapHigh)) {
								double stop = Math.max(gapHigh + (spec.tickSize * 2.0), recentSwingHigh(bars, entryIndex, 5) + (spec.tickSize * 2.0));
								double minRisk = settings.fvgMinRiskTicks * spec.tickSize;
								if (stop - entry.close < minRisk) {
									stop = entry.close + minRisk;
								}
								double risk = stop - entry.close;
								if (risk > 0.0 && riskTicks(spec, entry.close, stop) <= maxRiskTicks) {
									signals.add(signal("IFVG", "Inversion Fair Value Gap Retest", "SHORT", entryIndex, entry.close, stop, entry.close - (risk * settings.fvgRewardRisk), settings.fvgMaxHoldBars, ifvgSignalNotes(spec, "Bearish", gapLow, gapHigh, index, invalidationIndex, entryIndex, settings)));
									break;
								}
							}
						}
					}
				}
			}
			if (settings.allowFvgLongs && !inDayOfWeekMask(third.marketDate, settings.fvgLongSkipDowMask) && first.low > third.high && middle.close < middle.open) {
				double gapLow = third.high;
				double gapHigh = first.low;
				double widthTicks = (gapHigh - gapLow) / spec.tickSize;
				if (widthTicks >= settings.fvgMinWidthTicks) {
					int invalidationIndex = ifvgInvalidationIndex(spec, bars, settings, index, false, gapLow, gapHigh, breakDistance);
					if (invalidationIndex >= 0) {
						for (int entryIndex = invalidationIndex + 1; entryIndex < Math.min(invalidationIndex + settings.fvgRetestBars, bars.size()); entryIndex++) {
							Bar entry = bars.get(entryIndex);
							int entryMinuteOfDay = minuteOfDay(entry);
							if (inDayOfWeekMinuteWindow(entry.marketDate, entryMinuteOfDay, settings.fvgLongDowWindowSkipMask, settings.fvgLongDowWindowSkipStartMinute, settings.fvgLongDowWindowSkipEndMinute)) {
								continue;
							}
							double entryVolumeRatio = entry.volumeSma20 <= 0.0 ? 1.0 : entry.volume / entry.volumeSma20;
							if (entry.low <= gapHigh + (spec.tickSize * 2.0)
								&& entry.low >= gapLow - (spec.tickSize * 2.0)
								&& entry.close > gapHigh + breakDistance
								&& entry.close > entry.open
								&& closeLocation(entry) >= 0.58
								&& entryVolumeRatio >= settings.fvgMinVolumeRatio
								&& ifvgQualityPass(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings, index, invalidationIndex, entryIndex, "LONG", gapLow, gapHigh)) {
								double stop = Math.min(gapLow - (spec.tickSize * 2.0), recentSwingLow(bars, entryIndex, 5) - (spec.tickSize * 2.0));
								double minRisk = settings.fvgMinRiskTicks * spec.tickSize;
								if (entry.close - stop < minRisk) {
									stop = entry.close - minRisk;
								}
								double risk = entry.close - stop;
								if (risk > 0.0 && riskTicks(spec, entry.close, stop) <= maxRiskTicks) {
									signals.add(signal("IFVG", "Inversion Fair Value Gap Retest", "LONG", entryIndex, entry.close, stop, entry.close + (risk * settings.fvgRewardRisk), settings.fvgMaxHoldBars, ifvgSignalNotes(spec, "Bullish", gapLow, gapHigh, index, invalidationIndex, entryIndex, settings)));
									break;
								}
							}
						}
					}
				}
			}
		}
		return dedupeByHour(signals, settings.ifvg.maxTradesPerDay);
	}

	private static int ifvgInvalidationIndex(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int gapIndex, boolean bullishGap, double gapLow, double gapHigh, double breakDistance) {
		int endIndex = Math.min(bars.size() - 1, gapIndex + Math.max(2, settings.fvgInversionBreakBars));
		for (int index = gapIndex + 1; index <= endIndex; index++) {
			Bar bar = bars.get(index);
			double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
			if (volumeRatio < settings.fvgMinVolumeRatio) {
				continue;
			}
			if (settings.fvgMinInversionBodyPct > 0.0 && bar.bodyPct < settings.fvgMinInversionBodyPct) {
				continue;
			}
			if (settings.fvgRequireInversionStructureBreak && !ifvgBreaksLocalStructure(spec, bars, settings, index, bullishGap, breakDistance)) {
				continue;
			}
			if (bullishGap) {
				if (bar.close < gapLow - breakDistance && bar.close < bar.open && closeLocation(bar) <= 0.42) {
					return index;
				}
			} else if (bar.close > gapHigh + breakDistance && bar.close > bar.open && closeLocation(bar) >= 0.58) {
				return index;
			}
		}
		return -1;
	}

	private static boolean ifvgBreaksLocalStructure(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int invalidationIndex, boolean bullishGap, double breakDistance) {
		if (spec == null || spec.tickSize <= 0.0 || bars == null || settings == null || invalidationIndex <= 0 || invalidationIndex >= bars.size()) {
			return false;
		}
		int lookback = Math.max(5, settings.fvgInversionStructureBars);
		int start = Math.max(0, invalidationIndex - lookback);
		int end = invalidationIndex - 1;
		if (end < start) {
			return false;
		}
		double high = Double.NEGATIVE_INFINITY;
		double low = Double.POSITIVE_INFINITY;
		for (int index = start; index <= end; index++) {
			Bar bar = bars.get(index);
			high = Math.max(high, bar.high);
			low = Math.min(low, bar.low);
		}
		Bar invalidation = bars.get(invalidationIndex);
		return bullishGap
			? low < Double.POSITIVE_INFINITY && invalidation.close < low - breakDistance
			: high > Double.NEGATIVE_INFINITY && invalidation.close > high + breakDistance;
	}

	private static boolean ifvgQualityPass(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> previousBars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		FuturesStrategySettings settings,
		int gapIndex,
		int invalidationIndex,
		int entryIndex,
		String side,
		double gapLow,
		double gapHigh
	) {
		if (settings == null || !settings.fvgRequireCoreQuality) {
			return true;
		}
		if (spec == null || bars == null || gapIndex < 2 || invalidationIndex <= gapIndex || entryIndex <= invalidationIndex || entryIndex >= bars.size()) {
			return false;
		}
		Bar middle = bars.get(gapIndex - 1);
		Bar third = bars.get(gapIndex);
		Bar entry = bars.get(entryIndex);
		boolean longSide = "LONG".equals(side);
		double impulseBody = Math.max(middle == null ? 0.0 : middle.bodyPct, third == null ? 0.0 : third.bodyPct);
		if (settings.fvgMinImpulseBodyPct > 0.0 && impulseBody < settings.fvgMinImpulseBodyPct) {
			return false;
		}
		if (settings.fvgMinReclaimBodyPct > 0.0 && entry.bodyPct < settings.fvgMinReclaimBodyPct) {
			return false;
		}
		double boundary = longSide ? gapHigh : gapLow;
		double reclaimTicks = riskTicks(spec, entry.close, boundary);
		if (settings.fvgMinReclaimTicks > 0.0 && reclaimTicks < settings.fvgMinReclaimTicks) {
			return false;
		}
		if (settings.fvgMaxEntryExtensionTicks > 0.0 && reclaimTicks > settings.fvgMaxEntryExtensionTicks) {
			return false;
		}
		if (settings.fvgMaxRetestDepthPct > 0.0) {
			double gapHeight = Math.max(spec.tickSize, gapHigh - gapLow);
			double retestDepth = longSide
				? (gapHigh - entry.low) / gapHeight
				: (entry.high - gapLow) / gapHeight;
			if (retestDepth > settings.fvgMaxRetestDepthPct) {
				return false;
			}
		}
		if (settings.fvgMinReclaimCloseLocation > 0.0) {
			double sideCloseLocation = longSide ? closeLocation(entry) : 1.0 - closeLocation(entry);
			if (sideCloseLocation < settings.fvgMinReclaimCloseLocation) {
				return false;
			}
		}
		if (settings.fvgMaxVwapDistanceTicks > 0.0) {
			if (entry.vwap <= 0.0 || riskTicks(spec, entry.close, entry.vwap) > settings.fvgMaxVwapDistanceTicks) {
				return false;
			}
		}
		if (settings.fvgRequireEmaStack) {
			if (entry.ema9 <= 0.0 || entry.ema20 <= 0.0 || entry.ema50 <= 0.0 || entry.vwap <= 0.0) {
				return false;
			}
			if (longSide) {
				if (!(entry.close > entry.vwap && entry.ema9 >= entry.ema20 && entry.ema20 >= entry.ema50)) {
					return false;
				}
			} else if (!(entry.close < entry.vwap && entry.ema9 <= entry.ema20 && entry.ema20 <= entry.ema50)) {
				return false;
			}
		}
		if (settings.fvgRequireHigherTimeframeGuard) {
			boolean higherTimeframePass = longSide
				? higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, entry.marketTime)
				: higherTimeframeBearish(fifteenMinuteBars, oneHourBars, entry.marketTime);
			if (!higherTimeframePass) {
				return false;
			}
		}
		if (settings.fvgMinTrendSlopeTicks > 0.0) {
			Bar reference = bars.get(Math.max(0, entryIndex - 10));
			if (entry.ema20 <= 0.0 || reference.ema20 <= 0.0 || spec.tickSize <= 0.0) {
				return false;
			}
			double slopeTicks = (entry.ema20 - reference.ema20) / spec.tickSize;
			if (longSide && slopeTicks < settings.fvgMinTrendSlopeTicks) {
				return false;
			}
			if (!longSide && slopeTicks > -settings.fvgMinTrendSlopeTicks) {
				return false;
			}
		}
		return true;
	}

	private static String ifvgSignalNotes(InstrumentSpec spec, String bias, double gapLow, double gapHigh, int gapIndex, int invalidationIndex, int entryIndex, FuturesStrategySettings settings) {
		double tickSize = spec == null || spec.tickSize <= 0.0 ? 1.0 : spec.tickSize;
		double widthTicks = (gapHigh - gapLow) / tickSize;
		return bias + " futures IFVG retest after gap invalidation"
			+ ", flipped gap " + round(gapLow) + " to " + round(gapHigh)
			+ ", gap " + round(gapLow) + "-" + round(gapHigh)
			+ ", width " + round(widthTicks) + " ticks"
			+ ", gap bar index " + gapIndex
			+ ", invalidation lag " + Math.max(0, invalidationIndex - gapIndex) + " bars"
			+ ", retest lag " + Math.max(0, entryIndex - invalidationIndex) + " bars"
			+ ", core quality " + (settings != null && settings.fvgRequireCoreQuality ? "required" : "not required")
			+ ".";
	}

	private static String fvgSignalNotes(InstrumentSpec spec, String bias, double gapLow, double gapHigh, int gapIndex, int entryIndex, FuturesStrategySettings settings) {
		double tickSize = spec == null || spec.tickSize <= 0.0 ? 1.0 : spec.tickSize;
		double widthTicks = (gapHigh - gapLow) / tickSize;
		return bias + " futures FVG reclaim with bounded gap risk"
			+ ", gap " + round(gapLow) + "-" + round(gapHigh)
			+ ", width " + round(widthTicks) + " ticks"
			+ ", gap bar index " + gapIndex
			+ ", reclaim lag " + Math.max(0, entryIndex - gapIndex) + " bars"
			+ ", core quality " + (settings != null && settings.fvgRequireCoreQuality ? "required" : "not required")
			+ ".";
	}

	private static int fvgAcceptanceIndex(
		InstrumentSpec spec,
		List<Bar> bars,
		FuturesStrategySettings settings,
		int reclaimIndex,
		String side,
		double gapLow,
		double gapHigh
	) {
		int acceptanceBars = settings == null ? 0 : settings.fvgAcceptanceBars;
		if (acceptanceBars <= 0) {
			return reclaimIndex;
		}
		if (spec == null || bars == null || reclaimIndex < 0 || reclaimIndex >= bars.size()) {
			return -1;
		}
		Bar reclaim = bars.get(reclaimIndex);
		boolean longSide = "LONG".equals(side);
		double minCloseLocation = Math.max(0.0, settings.fvgAcceptanceMinCloseLocation);
		double tickSize = Math.max(spec.tickSize, 0.000001);
		int endIndex = Math.min(bars.size() - 1, reclaimIndex + acceptanceBars);
		for (int index = reclaimIndex + 1; index <= endIndex; index++) {
			Bar candidate = bars.get(index);
			if (longSide && candidate.close < gapLow) {
				return -1;
			}
			if (!longSide && candidate.close > gapHigh) {
				return -1;
			}
			double sideCloseLocation = longSide ? closeLocation(candidate) : 1.0 - closeLocation(candidate);
			if (sideCloseLocation < minCloseLocation) {
				continue;
			}
			if (longSide) {
				double requiredClose = settings.fvgAcceptanceRequireReclaimExtremeBreak ? reclaim.high : reclaim.close;
				if (candidate.close > candidate.open && candidate.close > requiredClose + (tickSize * 0.01)) {
					return index;
				}
			} else {
				double requiredClose = settings.fvgAcceptanceRequireReclaimExtremeBreak ? reclaim.low : reclaim.close;
				if (candidate.close < candidate.open && candidate.close < requiredClose - (tickSize * 0.01)) {
					return index;
				}
			}
		}
		return -1;
	}

	private static boolean fvgCoreQualityPass(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> previousBars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		FuturesStrategySettings settings,
		int gapIndex,
		int entryIndex,
		String side,
		double gapLow,
		double gapHigh
	) {
		if (settings == null) {
			return true;
		}
		if (spec == null || bars == null || gapIndex < 2 || entryIndex <= gapIndex || entryIndex >= bars.size()) {
			return false;
		}
		Bar middle = bars.get(gapIndex - 1);
		Bar third = bars.get(gapIndex);
		Bar entry = bars.get(entryIndex);
		boolean longSide = "LONG".equals(side);
		if (!fvgSourceEventPass(spec, bars, previousBars, fifteenMinuteBars, oneHourBars, settings, gapIndex, longSide)) {
			return false;
		}
		if (!settings.fvgRequireCoreQuality) {
			return true;
		}
		double impulseBody = Math.max(middle == null ? 0.0 : middle.bodyPct, third == null ? 0.0 : third.bodyPct);
		if (settings.fvgMinImpulseBodyPct > 0.0 && impulseBody < settings.fvgMinImpulseBodyPct) {
			return false;
		}
		if (settings.fvgMinReclaimBodyPct > 0.0 && entry.bodyPct < settings.fvgMinReclaimBodyPct) {
			return false;
		}
		double reclaimTicks = longSide
			? riskTicks(spec, entry.close, gapHigh)
			: riskTicks(spec, gapLow, entry.close);
		if (settings.fvgMinReclaimTicks > 0.0 && reclaimTicks < settings.fvgMinReclaimTicks) {
			return false;
		}
		if (settings.fvgMaxEntryExtensionTicks > 0.0) {
			if (reclaimTicks > settings.fvgMaxEntryExtensionTicks) {
				return false;
			}
		}
		if (settings.fvgMaxRetestDepthPct > 0.0) {
			double gapHeight = Math.max(spec.tickSize, gapHigh - gapLow);
			double retestDepth = longSide
				? (gapHigh - entry.low) / gapHeight
				: (entry.high - gapLow) / gapHeight;
			if (retestDepth > settings.fvgMaxRetestDepthPct) {
				return false;
			}
		}
		if (settings.fvgMinReclaimCloseLocation > 0.0) {
			double sideCloseLocation = longSide ? closeLocation(entry) : 1.0 - closeLocation(entry);
			if (sideCloseLocation < settings.fvgMinReclaimCloseLocation) {
				return false;
			}
		}
		if (settings.fvgMaxPriorMoveTicks > 0.0) {
			Bar reference = bars.get(Math.max(0, gapIndex - 20));
			double priorMoveTicks = longSide
				? (third.close - reference.close) / spec.tickSize
				: (reference.close - third.close) / spec.tickSize;
			if (priorMoveTicks > settings.fvgMaxPriorMoveTicks) {
				return false;
			}
		}
		if (!fvgSourceRangeBreakPass(spec, bars, settings, gapIndex, longSide)) {
			return false;
		}
		if (settings.fvgMaxVwapDistanceTicks > 0.0) {
			if (entry.vwap <= 0.0 || riskTicks(spec, entry.close, entry.vwap) > settings.fvgMaxVwapDistanceTicks) {
				return false;
			}
		}
		if (settings.fvgRequireEmaStack) {
			if (entry.ema9 <= 0.0 || entry.ema20 <= 0.0 || entry.ema50 <= 0.0 || entry.vwap <= 0.0) {
				return false;
			}
			if (longSide) {
				if (!(entry.close > entry.vwap && entry.ema9 >= entry.ema20 && entry.ema20 >= entry.ema50)) {
					return false;
				}
			} else if (!(entry.close < entry.vwap && entry.ema9 <= entry.ema20 && entry.ema20 <= entry.ema50)) {
				return false;
			}
		}
		if (settings.fvgRequireHigherTimeframeGuard) {
			boolean higherTimeframePass = longSide
				? higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, entry.marketTime)
				: higherTimeframeBearish(fifteenMinuteBars, oneHourBars, entry.marketTime);
			if (!higherTimeframePass) {
				return false;
			}
		}
		if (settings.fvgMinTrendSlopeTicks > 0.0) {
			Bar reference = bars.get(Math.max(0, entryIndex - 10));
			if (entry.ema20 <= 0.0 || reference.ema20 <= 0.0 || spec.tickSize <= 0.0) {
				return false;
			}
			double slopeTicks = (entry.ema20 - reference.ema20) / spec.tickSize;
			if (longSide && slopeTicks < settings.fvgMinTrendSlopeTicks) {
				return false;
			}
			if (!longSide && slopeTicks > -settings.fvgMinTrendSlopeTicks) {
				return false;
			}
		}
		return true;
	}

	private static boolean fvgSourceRangeBreakPass(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int gapIndex, boolean longSide) {
		int sourceRangeBars = settings == null ? 0 : settings.fvgSourceRangeBars;
		if (sourceRangeBars <= 0) {
			return true;
		}
		if (spec == null || spec.tickSize <= 0.0 || bars == null || gapIndex < 3 || gapIndex >= bars.size()) {
			return false;
		}
		int priorEnd = gapIndex - 3;
		int priorStart = Math.max(0, priorEnd - sourceRangeBars + 1);
		if (priorEnd < priorStart || (priorEnd - priorStart + 1) < Math.min(5, sourceRangeBars)) {
			return false;
		}
		double priorHigh = Double.NEGATIVE_INFINITY;
		double priorLow = Double.POSITIVE_INFINITY;
		for (int index = priorStart; index <= priorEnd; index++) {
			Bar prior = bars.get(index);
			priorHigh = Math.max(priorHigh, prior.high);
			priorLow = Math.min(priorLow, prior.low);
		}
		if (priorHigh == Double.NEGATIVE_INFINITY || priorLow == Double.POSITIVE_INFINITY) {
			return false;
		}
		Bar displacement = bars.get(gapIndex);
		double breakDistance = Math.max(0.0, settings.fvgMinSourceBreakTicks) * spec.tickSize;
		return longSide
			? displacement.close > priorHigh + breakDistance
			: displacement.close < priorLow - breakDistance;
	}

	private static String normalizedFvgSourceMode(String rawMode) {
		String mode = cleanOrDefault(rawMode, FVG_SOURCE_NONE).trim().toUpperCase(Locale.US).replace('-', '_').replace(' ', '_');
		if (FVG_SOURCE_PRIOR_LEVEL_BREAK.equals(mode)
			|| FVG_SOURCE_ORB_BREAK.equals(mode)
			|| FVG_SOURCE_SWEEP_DISPLACEMENT.equals(mode)
			|| FVG_SOURCE_VWAP_TREND_RECLAIM.equals(mode)
			|| FVG_SOURCE_HTF_BREAKOUT.equals(mode)
			|| FVG_SOURCE_ANY_CONTEXT.equals(mode)) {
			return mode;
		}
		return FVG_SOURCE_NONE;
	}

	private static boolean fvgSourceEventPass(
		InstrumentSpec spec,
		List<Bar> bars,
		List<Bar> previousBars,
		List<Bar> fifteenMinuteBars,
		List<Bar> oneHourBars,
		FuturesStrategySettings settings,
		int gapIndex,
		boolean longSide
	) {
		String mode = settings == null ? FVG_SOURCE_NONE : normalizedFvgSourceMode(settings.fvgSourceMode);
		if (FVG_SOURCE_NONE.equals(mode)) {
			return true;
		}
		if (FVG_SOURCE_ANY_CONTEXT.equals(mode)) {
			return fvgPriorLevelBreakPass(spec, bars, previousBars, settings, gapIndex, longSide)
				|| fvgOrbBreakPass(spec, bars, settings, gapIndex, longSide)
				|| fvgSweepDisplacementPass(spec, bars, previousBars, settings, gapIndex, longSide)
				|| fvgVwapTrendReclaimPass(spec, bars, gapIndex, longSide)
				|| fvgHtfBreakoutPass(fifteenMinuteBars, oneHourBars, bars, gapIndex, longSide);
		}
		if (FVG_SOURCE_PRIOR_LEVEL_BREAK.equals(mode)) {
			return fvgPriorLevelBreakPass(spec, bars, previousBars, settings, gapIndex, longSide);
		}
		if (FVG_SOURCE_ORB_BREAK.equals(mode)) {
			return fvgOrbBreakPass(spec, bars, settings, gapIndex, longSide);
		}
		if (FVG_SOURCE_SWEEP_DISPLACEMENT.equals(mode)) {
			return fvgSweepDisplacementPass(spec, bars, previousBars, settings, gapIndex, longSide);
		}
		if (FVG_SOURCE_VWAP_TREND_RECLAIM.equals(mode)) {
			return fvgVwapTrendReclaimPass(spec, bars, gapIndex, longSide);
		}
		if (FVG_SOURCE_HTF_BREAKOUT.equals(mode)) {
			return fvgHtfBreakoutPass(fifteenMinuteBars, oneHourBars, bars, gapIndex, longSide);
		}
		return true;
	}

	private static boolean fvgPriorLevelBreakPass(InstrumentSpec spec, List<Bar> bars, List<Bar> previousBars, FuturesStrategySettings settings, int gapIndex, boolean longSide) {
		if (spec == null || spec.tickSize <= 0.0 || bars == null || gapIndex < 0 || gapIndex >= bars.size() || previousBars == null || previousBars.isEmpty()) {
			return false;
		}
		Bar displacement = bars.get(gapIndex);
		double breakDistance = Math.max(0.0, settings == null ? 0.0 : settings.fvgMinSourceBreakTicks) * spec.tickSize;
		double previousHigh = highest(previousBars);
		double previousLow = lowest(previousBars);
		return longSide
			? previousHigh > 0.0 && displacement.close > previousHigh + breakDistance
			: previousLow > 0.0 && displacement.close < previousLow - breakDistance;
	}

	private static boolean fvgOrbBreakPass(InstrumentSpec spec, List<Bar> bars, FuturesStrategySettings settings, int gapIndex, boolean longSide) {
		if (spec == null || spec.tickSize <= 0.0 || bars == null || gapIndex < 0 || gapIndex >= bars.size()) {
			return false;
		}
		Bar displacement = bars.get(gapIndex);
		if (displacement.marketTime == null || !displacement.marketTime.isAfter(ORB_END)) {
			return false;
		}
		double openingHigh = Double.NEGATIVE_INFINITY;
		double openingLow = Double.POSITIVE_INFINITY;
		int count = 0;
		for (int index = 0; index < gapIndex; index++) {
			Bar bar = bars.get(index);
			if (bar.marketTime == null || bar.marketTime.isBefore(RTH_START) || !bar.marketTime.isBefore(ORB_END)) {
				continue;
			}
			openingHigh = Math.max(openingHigh, bar.high);
			openingLow = Math.min(openingLow, bar.low);
			count++;
		}
		if (count < 5 || openingHigh == Double.NEGATIVE_INFINITY || openingLow == Double.POSITIVE_INFINITY) {
			return false;
		}
		double breakDistance = Math.max(0.0, settings == null ? 0.0 : settings.fvgMinSourceBreakTicks) * spec.tickSize;
		return longSide
			? displacement.close > openingHigh + breakDistance
			: displacement.close < openingLow - breakDistance;
	}

	private static boolean fvgSweepDisplacementPass(InstrumentSpec spec, List<Bar> bars, List<Bar> previousBars, FuturesStrategySettings settings, int gapIndex, boolean longSide) {
		if (spec == null || spec.tickSize <= 0.0 || bars == null || gapIndex < 3 || gapIndex >= bars.size() || previousBars == null || previousBars.isEmpty()) {
			return false;
		}
		int lookback = Math.max(6, settings == null ? 20 : settings.fvgSourceRangeBars);
		int start = Math.max(0, gapIndex - lookback);
		double recentHigh = Double.NEGATIVE_INFINITY;
		double recentLow = Double.POSITIVE_INFINITY;
		for (int index = start; index <= gapIndex; index++) {
			Bar bar = bars.get(index);
			recentHigh = Math.max(recentHigh, bar.high);
			recentLow = Math.min(recentLow, bar.low);
		}
		Bar displacement = bars.get(gapIndex);
		double previousHigh = highest(previousBars);
		double previousLow = lowest(previousBars);
		double breakDistance = Math.max(0.0, settings == null ? 0.0 : settings.fvgMinSourceBreakTicks) * spec.tickSize;
		double sweepBuffer = spec.tickSize;
		return longSide
			? previousLow > 0.0 && recentLow < previousLow - sweepBuffer && displacement.close > previousLow + breakDistance && displacement.close > displacement.open
			: previousHigh > 0.0 && recentHigh > previousHigh + sweepBuffer && displacement.close < previousHigh - breakDistance && displacement.close < displacement.open;
	}

	private static boolean fvgVwapTrendReclaimPass(InstrumentSpec spec, List<Bar> bars, int gapIndex, boolean longSide) {
		if (spec == null || spec.tickSize <= 0.0 || bars == null || gapIndex < 1 || gapIndex >= bars.size()) {
			return false;
		}
		Bar displacement = bars.get(gapIndex);
		if (displacement.vwap <= 0.0 || displacement.ema9 <= 0.0 || displacement.ema20 <= 0.0 || displacement.ema50 <= 0.0) {
			return false;
		}
		boolean touchedVwap = false;
		int start = Math.max(0, gapIndex - 8);
		double touchBuffer = spec.tickSize * 2.0;
		for (int index = start; index <= gapIndex; index++) {
			Bar bar = bars.get(index);
			if (bar.vwap <= 0.0) {
				continue;
			}
			if (longSide && bar.low <= bar.vwap + touchBuffer) {
				touchedVwap = true;
			}
			if (!longSide && bar.high >= bar.vwap - touchBuffer) {
				touchedVwap = true;
			}
		}
		if (!touchedVwap) {
			return false;
		}
		return longSide
			? displacement.close > displacement.vwap && displacement.ema9 >= displacement.ema20 && displacement.ema20 >= displacement.ema50 && displacement.close > displacement.open
			: displacement.close < displacement.vwap && displacement.ema9 <= displacement.ema20 && displacement.ema20 <= displacement.ema50 && displacement.close < displacement.open;
	}

	private static boolean fvgHtfBreakoutPass(List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, List<Bar> bars, int gapIndex, boolean longSide) {
		if (bars == null || gapIndex < 0 || gapIndex >= bars.size()) {
			return false;
		}
		Bar displacement = bars.get(gapIndex);
		return longSide
			? higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, displacement.marketTime)
			: higherTimeframeBearish(fifteenMinuteBars, oneHourBars, displacement.marketTime);
	}

	private static List<Signal> findCloseMomentumSignals(InstrumentSpec spec, List<Bar> bars, List<Bar> fifteenMinuteBars, List<Bar> oneHourBars, FuturesStrategySettings settings) {
		List<Signal> signals = new ArrayList<Signal>();
		if (bars == null || bars.size() < 120) {
			return signals;
		}

		double rthOpen = bars.get(0).open;
		double sessionHigh = bars.get(0).high;
		double sessionLow = bars.get(0).low;
		double maxCloseMomentumRiskTicks = Math.min(settings.maxInitialRiskTicks, 80.0);
		double minSlopeTicks = Math.max(1.0, settings.vwapMinTrendSlopeTicks * 0.5);

		for (int index = 1; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			double priorHigh = sessionHigh;
			double priorLow = sessionLow;

			if (!bar.marketTime.isBefore(CLOSE_MOMENTUM_START) && !bar.marketTime.isAfter(CLOSE_MOMENTUM_END)) {
				int minuteOfDay = (bar.marketTime.getHour() * 60) + bar.marketTime.getMinute();
				double moveTicks = Math.abs(bar.close - rthOpen) / spec.tickSize;
				double volumeRatio = bar.volumeSma20 <= 0.0 ? 1.0 : bar.volume / bar.volumeSma20;
				if (moveTicks >= settings.closeMomentumMinMoveTicks && volumeRatio >= settings.closeMomentumVolumeRatio && bar.vwap > 0.0) {
					double closeLocation = closeLocation(bar);
					double trendSlopeTicks = (bar.ema20 - bars.get(Math.max(0, index - 10)).ema20) / spec.tickSize;
					if (settings.allowCloseMomentumLongs
						&& inCloseMomentumLongWindow(bar, minuteOfDay, settings)
						&& !inDayOfWeekMinuteWindow(bar.marketDate, minuteOfDay, settings.closeMomentumLongDowWindowSkipMask, settings.closeMomentumLongDowWindowSkipStartMinute, settings.closeMomentumLongDowWindowSkipEndMinute)
						&& bar.close > rthOpen
						&& bar.close > bar.vwap
						&& bar.ema9 >= bar.ema20
						&& bar.ema20 >= bar.ema50
						&& trendSlopeTicks >= minSlopeTicks
						&& bar.close >= priorHigh - spec.tickSize
						&& bar.bodyPct >= settings.closeMomentumMinBodyPct
						&& closeLocation >= 0.58
						&& (!settings.requireHigherTimeframeGuard || higherTimeframeBreakoutLong(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
						double stop = Math.min(recentSwingLow(bars, index, 8), bar.ema20) - (spec.tickSize * 2.0);
						double risk = bar.close - stop;
						if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxCloseMomentumRiskTicks) {
							signals.add(signal("CMOM", "Close Momentum", "LONG", index, bar.close, stop, bar.close + (risk * settings.closeMomentumRewardRisk), 40, "Late-session trend continuation after rest-of-day momentum confirms near session high."));
						}
					}
					if (settings.allowShorts
						&& settings.allowCloseMomentumShorts
						&& minuteOfDay >= settings.closeMomentumShortStartMinute
						&& minuteOfDay <= settings.closeMomentumShortEndMinute
						&& bar.close < rthOpen
						&& bar.close < bar.vwap
						&& bar.ema9 <= bar.ema20
						&& bar.ema20 <= bar.ema50
						&& trendSlopeTicks <= -minSlopeTicks
						&& bar.close <= priorLow + spec.tickSize
						&& bar.bodyPct >= settings.closeMomentumMinBodyPct
						&& closeLocation <= 0.42
						&& (!settings.requireHigherTimeframeGuard || higherTimeframeBearish(fifteenMinuteBars, oneHourBars, bar.marketTime))) {
						double stop = Math.max(recentSwingHigh(bars, index, 8), bar.ema20) + (spec.tickSize * 2.0);
						double risk = stop - bar.close;
						if (risk > 0.0 && riskTicks(spec, bar.close, stop) <= maxCloseMomentumRiskTicks) {
							signals.add(signal("CMOM", "Close Momentum", "SHORT", index, bar.close, stop, bar.close - (risk * settings.closeMomentumRewardRisk), 40, "Late-session trend continuation after rest-of-day momentum confirms near session low."));
						}
					}
				}
				if (signals.size() >= settings.closeMomentum.maxTradesPerDay) {
					break;
				}
			}

			sessionHigh = Math.max(sessionHigh, bar.high);
			sessionLow = Math.min(sessionLow, bar.low);
		}
		return dedupeByHour(signals, settings.closeMomentum.maxTradesPerDay);
	}

	private static boolean inCloseMomentumLongWindow(Bar bar, int minuteOfDay, FuturesStrategySettings settings) {
		if (minuteOfDay >= settings.closeMomentumLongStartMinute && minuteOfDay <= settings.closeMomentumLongEndMinute) {
			return true;
		}
		return settings.closeMomentumLongAltEnabled
			&& minuteOfDay >= settings.closeMomentumLongAltStartMinute
			&& minuteOfDay <= settings.closeMomentumLongAltEndMinute
			&& inAllowedDayOfWeekMask(bar == null ? null : bar.marketDate, settings.closeMomentumLongAltAllowDowMask);
	}

	private static Signal signal(String code, String name, String side, int entryIndex, double entry, double stop, double target, String notes) {
		return signal(code, name, side, entryIndex, entry, stop, target, 0, notes);
	}

	private static Signal signal(String code, String name, String side, int entryIndex, double entry, double stop, double target, int maxHoldBars, String notes) {
		Signal signal = new Signal();
		signal.strategyCode = code;
		signal.strategyName = name;
		signal.side = side;
		signal.entryIndex = entryIndex;
		signal.entryPrice = entry;
		signal.stopPrice = stop;
		signal.targetPrice = target;
		signal.maxHoldBars = maxHoldBars;
		signal.notes = notes;
		return signal;
	}

	private static Signal withSourceStrategy(Signal signal, String sourceCode, String sourceName) {
		if (signal == null) {
			return null;
		}
		signal.sourceStrategyCode = cleanOrDefault(sourceCode, "");
		signal.sourceStrategyName = cleanOrDefault(sourceName, "");
		return signal;
	}

	private static List<Signal> dedupeByHour(List<Signal> signals, int maxPerStrategy) {
		Collections.sort(signals, new Comparator<Signal>() {
			@Override
			public int compare(Signal first, Signal second) {
				return first.entryIndex - second.entryIndex;
			}
		});
		List<Signal> filtered = new ArrayList<Signal>();
		Map<String, Integer> counts = new HashMap<String, Integer>();
		int lastIndex = -999;
		for (int index = 0; index < signals.size(); index++) {
			Signal signal = signals.get(index);
			String strategyKey = dailyLimitStrategyCode(signal.strategyCode);
			int count = countFor(counts, strategyKey);
			if (count >= maxPerStrategy) {
				continue;
			}
			if (signal.entryIndex - lastIndex < 20) {
				continue;
			}
			filtered.add(signal);
			counts.put(strategyKey, count + 1);
			lastIndex = signal.entryIndex;
		}
		return filtered;
	}

	private static List<Signal> limitSignalsByDailyCount(List<Signal> signals, int maxPerStrategy) {
		Collections.sort(signals, new Comparator<Signal>() {
			@Override
			public int compare(Signal first, Signal second) {
				return first.entryIndex - second.entryIndex;
			}
		});
		List<Signal> filtered = new ArrayList<Signal>();
		Map<String, Integer> counts = new HashMap<String, Integer>();
		for (int index = 0; index < signals.size(); index++) {
			Signal signal = signals.get(index);
			String strategyKey = dailyLimitStrategyCode(signal.strategyCode);
			int count = countFor(counts, strategyKey);
			if (count >= maxPerStrategy) {
				continue;
			}
			filtered.add(signal);
			counts.put(strategyKey, count + 1);
		}
		return filtered;
	}

	private static int saveBacktest(BacktestResult result, BacktestConfig config) {
		String insertBacktest = "INSERT INTO FuturesBacktests (symbol, contractName, startDate, endDate, startingBalance, endingBalance, totalProfit, returnPct, winRate, numTrades, profitFactor, maxDrawdownPct, maxTrailingDrawdown, dailyLossLimit, maxRiskPerTrade, maxContracts, trailingThreshold, ruleViolation, ruleMessage, dataSource, createdAt) "
			+ "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(insertBacktest, Statement.RETURN_GENERATED_KEYS)) {
			pstmt.setString(1, result.symbol);
			pstmt.setString(2, result.contractName);
			pstmt.setString(3, result.startDate);
			pstmt.setString(4, result.endDate);
			pstmt.setDouble(5, result.startingBalance);
			pstmt.setDouble(6, result.endingBalance);
			pstmt.setDouble(7, result.totalProfit);
			pstmt.setDouble(8, result.returnPct);
			pstmt.setDouble(9, result.winRate);
			pstmt.setInt(10, result.trades);
			pstmt.setDouble(11, result.profitFactor);
			pstmt.setDouble(12, result.maxDrawdownPct);
			pstmt.setDouble(13, config.maxTrailingDrawdown);
			pstmt.setDouble(14, config.dailyLossLimit);
			pstmt.setDouble(15, config.maxRiskPerTrade);
			pstmt.setInt(16, config.maxContracts);
			pstmt.setDouble(17, result.trailingThreshold);
			pstmt.setInt(18, result.ruleViolation ? 1 : 0);
			pstmt.setString(19, result.ruleMessage);
			pstmt.setString(20, result.dataSource);
			pstmt.setString(21, LocalDateTime.now().format(DISPLAY_TIME_FORMAT));
			pstmt.executeUpdate();

			int backtestId = -1;
			try (ResultSet keys = pstmt.getGeneratedKeys()) {
				if (keys.next()) {
					backtestId = keys.getInt(1);
				}
			}
			if (backtestId <= 0) {
				return -1;
			}
			insertTrades(conn, backtestId, result.tradeRecords);
			return backtestId;
		} catch (SQLException e) {
			e.printStackTrace();
			return -1;
		}
	}

