	private static DataBundle loadBars(String symbol, LocalDate startDate, LocalDate endDate) {
		InstrumentSpec spec = instrumentFor(symbol);
		DataBundle futures = loadCsv(new File(futuresDataDir() + "/" + TIMEFRAME_FOLDER + "/" + spec.symbol + ".csv"), startDate, endDate, 1.0, "native futures csv");
		if (!futures.bars.isEmpty()) {
			return futures;
		}
		DataBundle proxy = loadCsv(new File(RuntimePaths.equityMarketDataDir() + "/1min/" + spec.proxySymbol + ".csv"), startDate, endDate, spec.proxyScale, "equity proxy " + spec.proxySymbol + " scaled for futures development");
		if (!proxy.bars.isEmpty()) {
			return proxy;
		}
		DataBundle synthetic = new DataBundle();
		synthetic.bars = syntheticBars(spec, startDate, endDate);
		synthetic.source = "deterministic synthetic futures bars";
		return synthetic;
	}

