		InstrumentSpec spec = instrumentFor(symbol);
		return loadCsv(new File(futuresDataDir() + "/" + timeframeFolder + "/" + spec.symbol + ".csv"), startDate, endDate, 1.0, "native futures csv " + timeframeFolder);
