	private static Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> loadSyntheticOrderFlowSnapshots(String symbol, LocalDate startDate, LocalDate endDate) {
		Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> snapshots = new HashMap<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>>();
		InstrumentSpec spec = instrumentFor(symbol);
		File file = new File(futuresDataDir() + "/" + SYNTHETIC_LEVEL2_FOLDER + "/" + spec.symbol + ".csv");
		if (!file.exists()) {
			return snapshots;
		}
		double previousImbalance5 = 0.0;
		try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
			String header = reader.readLine();
			if (header == null) {
				return snapshots;
			}
			String line;
			while ((line = reader.readLine()) != null) {
				String[] parts = line.split(",", -1);
				if (parts.length < 14) {
					continue;
				}
				ZonedDateTime timestamp = parseMarketTimestamp(parts[0]);
				if (timestamp == null) {
					continue;
				}
				LocalDate day = timestamp.toLocalDate();
				LocalTime time = timestamp.toLocalTime().withSecond(0).withNano(0);
				if (day.isBefore(startDate) || day.isAfter(endDate) || time.isBefore(RTH_START) || !time.isBefore(RTH_END)) {
					continue;
				}
				LiveRuntimeState.OrderFlowSnapshot snapshot = new LiveRuntimeState.OrderFlowSnapshot();
				snapshot.symbol = spec.symbol;
				snapshot.available = true;
				snapshot.fresh = true;
				snapshot.ageSeconds = 0L;
				snapshot.lastUpdatedAt = displayTime(day, time);
				snapshot.bestBid = parseCsvDouble(parts, 1, 0.0);
				snapshot.bestAsk = parseCsvDouble(parts, 2, 0.0);
				snapshot.spreadTicks = parseCsvDouble(parts, 3, 0.0);
				snapshot.spread = Math.max(0.0, snapshot.spreadTicks * spec.tickSize);
				snapshot.depthImbalance5 = parseCsvDouble(parts, 4, 0.0);
				snapshot.depthImbalance3 = snapshot.depthImbalance5;
				snapshot.depthImbalance10 = snapshot.depthImbalance5;
				snapshot.topBookImbalance = snapshot.depthImbalance5;
				snapshot.tapeDelta = parseCsvDouble(parts, 5, 0.0);
				if (snapshot.tapeDelta >= 0.0) {
					snapshot.aggressiveBuyVolume = snapshot.tapeDelta;
				} else {
					snapshot.aggressiveSellVolume = Math.abs(snapshot.tapeDelta);
				}
				snapshot.cvd = parseCsvDouble(parts, 6, 0.0);
				snapshot.bidWallDistanceTicks = parseCsvDouble(parts, 7, 0.0);
				snapshot.askWallDistanceTicks = parseCsvDouble(parts, 8, 0.0);
				snapshot.liquidityWallDistanceTicks = minPositive(snapshot.bidWallDistanceTicks, snapshot.askWallDistanceTicks);
				snapshot.bidStacking = parseCsvDouble(parts, 9, 0.0);
				snapshot.askStacking = parseCsvDouble(parts, 10, 0.0);
				snapshot.absorption = cleanOrDefault(parts[11], "NONE");
				snapshot.liquidityVacuum = parseBoolean(parts[12], false);
				snapshot.flowState = cleanOrDefault(parts[13], "BALANCED");
				snapshot.source = parts.length > 21 ? cleanOrDefault(parts[21], "SYNTHETIC_FROM_1MIN_CANDLE") : "SYNTHETIC_FROM_1MIN_CANDLE";
				snapshot.sourceConfidence = 0.60;
				if (previousImbalance5 < -0.20 && snapshot.depthImbalance5 > 0.20) {
					snapshot.bookFlip = "BID_FLIP";
				} else if (previousImbalance5 > 0.20 && snapshot.depthImbalance5 < -0.20) {
					snapshot.bookFlip = "ASK_FLIP";
				}
				previousImbalance5 = snapshot.depthImbalance5;
				Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot> byTime = snapshots.get(day);
				if (byTime == null) {
					byTime = new HashMap<LocalTime, LiveRuntimeState.OrderFlowSnapshot>();
					snapshots.put(day, byTime);
				}
				byTime.put(time, snapshot);
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return snapshots;
	}

	private static Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> loadCombinedOrderFlowSnapshots(String symbol, LocalDate startDate, LocalDate endDate) {
		Map<LocalDate, Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot>> snapshots = loadSyntheticOrderFlowSnapshots(symbol, startDate, endDate);
		InstrumentSpec spec = instrumentFor(symbol);
		String sql = "SELECT timestamp, bestBid, bestAsk, spreadTicks, depthImbalance3, depthImbalance5, depthImbalance10, "
			+ "topBookImbalance, tapeDelta, cvd, bidWallDistanceTicks, askWallDistanceTicks, bidStacking, askStacking, "
			+ "absorption, liquidityVacuum, bookFlip, flowState, source, sourceConfidence "
			+ "FROM FuturesHistoricalLevel2Snapshots WHERE symbol = ? ORDER BY timestamp";
		try (Connection conn = DatabaseManager.getConnection();
			 PreparedStatement pstmt = conn.prepareStatement(sql)) {
			pstmt.setString(1, spec.symbol);
			try (ResultSet rs = pstmt.executeQuery()) {
				while (rs.next()) {
					ZonedDateTime timestamp = parseMarketTimestamp(rs.getString("timestamp"));
					if (timestamp == null) {
						continue;
					}
					LocalDate day = timestamp.toLocalDate();
					LocalTime time = timestamp.toLocalTime().withSecond(0).withNano(0);
					if (day.isBefore(startDate) || day.isAfter(endDate) || time.isBefore(RTH_START) || !time.isBefore(RTH_END)) {
						continue;
					}
					LiveRuntimeState.OrderFlowSnapshot snapshot = new LiveRuntimeState.OrderFlowSnapshot();
					snapshot.symbol = spec.symbol;
					snapshot.available = true;
					snapshot.fresh = true;
					snapshot.ageSeconds = 0L;
					snapshot.lastUpdatedAt = displayTime(day, time);
					snapshot.bestBid = rs.getDouble("bestBid");
					snapshot.bestAsk = rs.getDouble("bestAsk");
					snapshot.spreadTicks = rs.getDouble("spreadTicks");
					snapshot.spread = Math.max(0.0, snapshot.spreadTicks * spec.tickSize);
					snapshot.depthImbalance3 = rs.getDouble("depthImbalance3");
					snapshot.depthImbalance5 = rs.getDouble("depthImbalance5");
					snapshot.depthImbalance10 = rs.getDouble("depthImbalance10");
					snapshot.topBookImbalance = rs.getDouble("topBookImbalance");
					snapshot.tapeDelta = rs.getDouble("tapeDelta");
					if (snapshot.tapeDelta >= 0.0) {
						snapshot.aggressiveBuyVolume = snapshot.tapeDelta;
					} else {
						snapshot.aggressiveSellVolume = Math.abs(snapshot.tapeDelta);
					}
					snapshot.cvd = rs.getDouble("cvd");
					snapshot.bidWallDistanceTicks = rs.getDouble("bidWallDistanceTicks");
					snapshot.askWallDistanceTicks = rs.getDouble("askWallDistanceTicks");
					snapshot.liquidityWallDistanceTicks = minPositive(snapshot.bidWallDistanceTicks, snapshot.askWallDistanceTicks);
					snapshot.bidStacking = rs.getDouble("bidStacking");
					snapshot.askStacking = rs.getDouble("askStacking");
					snapshot.absorption = cleanOrDefault(rs.getString("absorption"), "NONE");
					snapshot.liquidityVacuum = rs.getInt("liquidityVacuum") != 0;
					snapshot.bookFlip = cleanOrDefault(rs.getString("bookFlip"), "NONE");
					snapshot.flowState = cleanOrDefault(rs.getString("flowState"), "BALANCED");
					snapshot.source = cleanOrDefault(rs.getString("source"), "HISTORICAL_LEVEL2");
					snapshot.sourceConfidence = rs.getDouble("sourceConfidence");
					Map<LocalTime, LiveRuntimeState.OrderFlowSnapshot> byTime = snapshots.get(day);
					if (byTime == null) {
						byTime = new HashMap<LocalTime, LiveRuntimeState.OrderFlowSnapshot>();
						snapshots.put(day, byTime);
					}
					byTime.put(time, snapshot);
				}
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return snapshots;
	}

	private static double parseCsvDouble(String[] parts, int index, double defaultValue) {
		if (parts == null || index < 0 || index >= parts.length) {
			return defaultValue;
		}
		try {
			return Double.parseDouble(cleanOrDefault(parts[index], "").trim());
		} catch (Exception ignored) {
			return defaultValue;
		}
	}

	private static double minPositive(double first, double second) {
		boolean firstPositive = first > 0.0;
		boolean secondPositive = second > 0.0;
		if (firstPositive && secondPositive) {
			return Math.min(first, second);
		}
		if (firstPositive) {
			return first;
		}
		return secondPositive ? second : 0.0;
	}

	private static ZonedDateTime parseMarketTimestamp(String rawTimestamp) {
		String clean = cleanOrDefault(rawTimestamp, "").trim();
		if (clean.length() == 0) {
			return null;
		}
		try {
			if (clean.endsWith("Z") || clean.contains("+")) {
				return OffsetDateTime.parse(clean.replace("Z", "+00:00")).atZoneSameInstant(NEW_YORK_ZONE);
			}
			if (clean.indexOf(' ') > 0) {
				DateTimeFormatter formatter = clean.length() == 16 ? DISPLAY_TIME_FORMAT : SERVER_TIME_FORMAT;
				return LocalDateTime.parse(clean, formatter).atZone(NEW_YORK_ZONE);
			}
			return LocalDateTime.parse(clean).atZone(NEW_YORK_ZONE);
		} catch (Exception ignored) {
			return null;
		}
	}

	private static DataBundle loadCsv(File file, LocalDate startDate, LocalDate endDate, double scale, String source) {
		return loadCsv(file, startDate, endDate, scale, source, true);
	}

	private static DataBundle loadCsv(File file, LocalDate startDate, LocalDate endDate, double scale, String source, boolean rthOnly) {
		DataBundle bundle = new DataBundle();
		if (file == null || !file.exists()) {
			return bundle;
		}
		try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
			String header = reader.readLine();
			if (header == null) {
				return bundle;
			}
			String line;
			while ((line = reader.readLine()) != null) {
				String[] parts = line.split(",");
				if (parts.length < 6) {
					continue;
				}
				Bar bar = parseBar(parts, scale);
				if (bar == null || bar.marketDate.isBefore(startDate) || bar.marketDate.isAfter(endDate)) {
					continue;
				}
				if (rthOnly && (bar.marketTime.isBefore(RTH_START) || !bar.marketTime.isBefore(RTH_END))) {
					continue;
				}
				bundle.bars.add(bar);
			}
			bundle.source = source;
		} catch (Exception e) {
			e.printStackTrace();
		}
		return bundle;
	}

	private static Bar parseBar(String[] parts, double scale) {
		try {
			ZonedDateTime timestamp = parseMarketTimestamp(parts[0]);
			if (timestamp == null) {
				return null;
			}
			Bar bar = new Bar();
			bar.marketDate = timestamp.toLocalDate();
			bar.marketTime = timestamp.toLocalTime();
			bar.displayTime = bar.marketDate.toString() + " " + (bar.marketTime.getSecond() == 0 && bar.marketTime.getNano() == 0
				? String.format("%02d:%02d", bar.marketTime.getHour(), bar.marketTime.getMinute())
				: String.format("%02d:%02d:%02d", bar.marketTime.getHour(), bar.marketTime.getMinute(), bar.marketTime.getSecond()));
			bar.open = parseDouble(parts[1]) * scale;
			bar.high = parseDouble(parts[2]) * scale;
			bar.low = parseDouble(parts[3]) * scale;
			bar.close = parseDouble(parts[4]) * scale;
			bar.volume = parseDouble(parts[5]);
			bar.vwap = parts.length > 6 && parseDouble(parts[6]) > 0.0 ? parseDouble(parts[6]) * scale : ((bar.high + bar.low + bar.close) / 3.0);
			bar.ema9 = parts.length > 7 ? parseDouble(parts[7]) * scale : bar.close;
			bar.ema20 = parts.length > 8 ? parseDouble(parts[8]) * scale : bar.close;
			bar.ema50 = parts.length > 9 ? parseDouble(parts[9]) * scale : bar.close;
			bar.atr14 = parts.length > 10 ? parseDouble(parts[10]) * scale : 0.0;
			bar.rsi14 = parts.length > 11 ? parseDouble(parts[11]) : 50.0;
			bar.volumeSma20 = parts.length > 12 ? parseDouble(parts[12]) : 0.0;
			bar.rangeTicks = parts.length > 13 ? parseDouble(parts[13]) : 0.0;
			bar.bodyPct = parts.length > 14 ? parseDouble(parts[14]) : defaultBodyPct(bar);
			return bar;
		} catch (Exception e) {
			return null;
		}
	}

	private static List<Bar> syntheticBars(InstrumentSpec spec, LocalDate startDate, LocalDate endDate) {
		List<Bar> bars = new ArrayList<Bar>();
		Random random = new Random(spec.symbol.hashCode());
		double price = "MNQ".equals(spec.symbol) || "NQ".equals(spec.symbol)
			? 19000.0
			: ("MYM".equals(spec.symbol)
				? 39000.0
				: ("M2K".equals(spec.symbol)
					? 2200.0
					: ("MCL".equals(spec.symbol)
						? 70.0
						: ("MGC".equals(spec.symbol) || "GC".equals(spec.symbol) ? 2300.0 : 5200.0))));
		for (LocalDate day = startDate; !day.isAfter(endDate); day = day.plusDays(1)) {
			if (day.getDayOfWeek().getValue() >= 6) {
				continue;
			}
			double drift = (random.nextDouble() - 0.45) * spec.tickSize * 10.0;
			double cumulativePv = 0.0;
			double cumulativeVol = 0.0;
			for (int minute = 0; minute < 390; minute++) {
				LocalTime time = RTH_START.plusMinutes(minute);
				double open = price;
				double wave = Math.sin(minute / 19.0) * spec.tickSize * 6.0;
				double noise = (random.nextDouble() - 0.5) * spec.tickSize * 12.0;
				double close = roundToTick(spec, open + drift + wave + noise);
				double high = roundToTick(spec, Math.max(open, close) + spec.tickSize * (1.0 + random.nextInt(4)));
				double low = roundToTick(spec, Math.min(open, close) - spec.tickSize * (1.0 + random.nextInt(4)));
				double volume = 800 + random.nextInt(2400);
				cumulativePv += ((high + low + close) / 3.0) * volume;
				cumulativeVol += volume;
				Bar bar = new Bar();
				bar.marketDate = day;
				bar.marketTime = time;
				bar.displayTime = day.toString() + " " + String.format("%02d:%02d", time.getHour(), time.getMinute());
				bar.open = roundToTick(spec, open);
				bar.high = high;
				bar.low = low;
				bar.close = close;
				bar.volume = volume;
				bar.vwap = roundToTick(spec, cumulativePv / Math.max(1.0, cumulativeVol));
				bars.add(bar);
				price = close;
			}
		}
		return bars;
	}

	private static Map<LocalDate, List<Bar>> groupByDay(List<Bar> bars) {
		Map<LocalDate, List<Bar>> byDay = new HashMap<LocalDate, List<Bar>>();
		for (int index = 0; index < bars.size(); index++) {
			Bar bar = bars.get(index);
			List<Bar> dayBars = byDay.get(bar.marketDate);
			if (dayBars == null) {
				dayBars = new ArrayList<Bar>();
				byDay.put(bar.marketDate, dayBars);
			}
			dayBars.add(bar);
		}
		return byDay;
	}

	private static List<Bar> previousDayBars(Map<LocalDate, List<Bar>> byDay, List<LocalDate> days, int dayIndex) {
		if (dayIndex <= 0) {
			return new ArrayList<Bar>();
		}
		List<Bar> bars = byDay.get(days.get(dayIndex - 1));
		return bars == null ? new ArrayList<Bar>() : bars;
	}

