		specs.add(spec("MYM", "Micro E-mini Dow", "CBOT", 1.00, 0.50, 0.5, 10, 80, 1.25, "DIA", 100.0));
		specs.add(spec("ES", "E-mini S&P 500", "CME", 0.25, 12.50, 50.0, 2, 12, 1.25, "SPY", 10.0));
